const { requiredString, validUuid, validationError } = require('./validation');

function parseFeedbackInput(body = {}, projectId) {
  if (!Number.isInteger(body.rating) || body.rating < 1 || body.rating > 5) {
    validationError([{ field: 'rating', message: 'Informe uma nota inteira entre 1 e 5.' }]);
  }

  return {
    projectId: validUuid(projectId, 'projectId'),
    authorName: requiredString(body.authorName, 'authorName', 120),
    comment: requiredString(body.comment, 'comment', 2000),
    rating: body.rating,
  };
}

function toFeedbackOutput(feedback) {
  return {
    id: feedback.id,
    projectId: feedback.projectId,
    authorName: feedback.authorName,
    comment: feedback.comment,
    rating: feedback.rating,
    createdAt: feedback.createdAt,
  };
}

module.exports = { parseFeedbackInput, toFeedbackOutput };

const {
  EMAIL_PATTERN,
  optionalString,
  requiredString,
  validUrl,
  validationError,
} = require('./validation');

function parseProfileInput(body = {}) {
  const email = requiredString(body.email, 'email', 255).toLowerCase();
  if (!EMAIL_PATTERN.test(email)) {
    validationError([{ field: 'email', message: 'Informe um e-mail valido.' }]);
  }

  return {
    name: requiredString(body.name, 'name', 120),
    email,
    bio: optionalString(body.bio, 'bio', 2000),
    githubUrl: validUrl(body.githubUrl, 'githubUrl'),
  };
}

function toProfileOutput(profile) {
  return {
    id: profile.id,
    name: profile.name,
    email: profile.email,
    bio: profile.bio,
    githubUrl: profile.githubUrl,
    projects: profile.projects || [],
    createdAt: profile.createdAt,
  };
}

module.exports = { parseProfileInput, toProfileOutput };

const {
  requiredString,
  validUrl,
  validUuid,
  validationError,
} = require('./validation');

function parseProjectInput(body = {}) {
  if (!Array.isArray(body.technologyIds)) {
    validationError([{ field: 'technologyIds', message: 'Informe uma lista de UUIDs.' }]);
  }

  return {
    profileId: validUuid(body.profileId, 'profileId'),
    title: requiredString(body.title, 'title', 160),
    description: requiredString(body.description, 'description', 5000),
    repositoryUrl: validUrl(body.repositoryUrl, 'repositoryUrl'),
    demoUrl: validUrl(body.demoUrl, 'demoUrl', false),
    technologyIds: [...new Set(body.technologyIds.map((id) => validUuid(id, 'technologyIds')))],
  };
}

function toProjectOutput(project) {
  return {
    id: project.id,
    title: project.title,
    description: project.description,
    repositoryUrl: project.repositoryUrl,
    demoUrl: project.demoUrl,
    profile: project.profile,
