const AppError = require('../utils/AppError');

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validationError(details) {
  throw new AppError('Dados de entrada invalidos.', 422, details);
}

function requiredString(value, field, maxLength) {
  if (typeof value !== 'string' || value.trim() === '') {
    validationError([{ field, message: 'Campo obrigatorio.' }]);
  }

  const normalized = value.trim();
  if (maxLength && normalized.length > maxLength) {
    validationError([{ field, message: `Deve ter no maximo ${maxLength} caracteres.` }]);
  }
  return normalized;
}

function optionalString(value, field, maxLength) {
  if (value === undefined || value === null || value === '') return null;
  return requiredString(value, field, maxLength);
}

function validUrl(value, field, required = true) {
  const normalized = required
    ? requiredString(value, field)
    : optionalString(value, field);
  if (normalized === null) return null;

  try {
    const url = new URL(normalized);
    if (!['http:', 'https:'].includes(url.protocol)) throw new Error();
    return url.toString();
  } catch {
    validationError([{ field, message: 'Informe uma URL HTTP ou HTTPS valida.' }]);
  }
}

function validUuid(value, field) {
  if (typeof value !== 'string' || !UUID_PATTERN.test(value)) {
    validationError([{ field, message: 'Informe um UUID valido.' }]);
  }
  return value;
}

module.exports = {
  EMAIL_PATTERN,
  optionalString,
  requiredString,
  validUrl,
  validUuid,
  validationError,
};

function asyncHandler(handler) {
  return function wrappedHandler(req, res, next) {
    Promise.resolve(handler(req, res, next)).catch(next);
  };
}

module.exports = asyncHandler;

const AppError = require('../utils/AppError');

function notFoundHandler(req, res) {
  res.status(404).json({ error: 'Rota nao encontrada.' });
}

function errorHandler(error, req, res, next) {
  if (res.headersSent) return next(error);

  if (error instanceof AppError) {
    return res.status(error.statusCode).json({
      error: error.message,
      ...(error.details && { details: error.details }),
    });
  }

  if (error.code === '23505') {
    return res.status(409).json({ error: 'Ja existe um registro com esses dados.' });
  }

  if (error.code === '23503') {
    return res.status(422).json({ error: 'O registro relacionado nao existe.' });
  }

  console.error(error);
  return res.status(500).json({ error: 'Erro interno do servidor.' });
}

module.exports = { errorHandler, notFoundHandler };

const database = require('../config/database');

async function create(input) {
  const result = await database.query(
    `INSERT INTO feedbacks (project_id, author_name, comment, rating)
     VALUES ($1, $2, $3, $4)
     RETURNING id, project_id AS "projectId", author_name AS "authorName",
       comment, rating, created_at AS "createdAt"`,
    [input.projectId, input.authorName, input.comment, input.rating],
  );
  return result.rows[0];
}

async function findByProjectId(projectId) {
  const result = await database.query(
    `SELECT id, project_id AS "projectId", author_name AS "authorName",
       comment, rating, created_at AS "createdAt"
     FROM feedbacks WHERE project_id = $1 ORDER BY created_at DESC`,
    [projectId],
  );
  return result.rows;
}

module.exports = { create, findByProjectId };

const database = require('../config/database');

function mapProfile(row) {
  return {
    id: row.id,
    name: row.name,
    email: row.email,
    bio: row.bio,
    githubUrl: row.github_url,
    projects: row.projects || [],
    createdAt: row.created_at,
  };
}

async function create(input) {
  const result = await database.query(
    `INSERT INTO profiles (name, email, bio, github_url)
     VALUES ($1, $2, $3, $4)
     RETURNING *`,
    [input.name, input.email, input.bio, input.githubUrl],
  );
  return mapProfile(result.rows[0]);
}

async function findById(id) {
  const result = await database.query(
    `SELECT p.*,
       COALESCE(json_agg(json_build_object(
         'id', pr.id, 'title', pr.title, 'repositoryUrl', pr.repository_url
       ) ORDER BY pr.created_at DESC) FILTER (WHERE pr.id IS NOT NULL), '[]') AS projects
     FROM profiles p
     LEFT JOIN projects pr ON pr.profile_id = p.id
     WHERE p.id = $1
     GROUP BY p.id`,
    [id],
  );
  return result.rows[0] ? mapProfile(result.rows[0]) : null;
}

module.exports = { create, findById };

