const app = express();
const PORT = process.env.PORT || 3001;

// Middlewares
app.use(cors());
app.use(bodyParser.json());

// Simular banco de dados em memória
let pagamentos = [];
let instituicoes = [];

// ==========================================
// ROTAS DE PAGAMENTO
