  '/relatorio-usuarios': 'Relatório de Usuários',
  '/configuracoes': 'Configurações',
  '/configuracoes/nuvem': 'Nuvem e Sincronização'
};

function PrivateRoute({ children, requiredProfile }) {
  const { usuarioLogado, autenticacaoCarregada, registrarAcessoPagina } = useData();
  const location = useLocation();

  const isAdminDaEscola = (
    usuarioLogado?.tipo === 'master' ||
    usuarioLogado?.perfil === 'Admin' ||
    usuarioLogado?.perfil === 'AdminEscola'
  );

  const permissoesUsuario = Array.isArray(usuarioLogado?.permissoes) ? usuarioLogado.permissoes : null;

  const temPermissaoRota = () => {
    if (!usuarioLogado) {
      return false;
    }

    if (usuarioLogado.perfil === 'SuperAdmin' || isAdminDaEscola) {
      return true;
    }

    if (!permissoesUsuario || permissoesUsuario.length === 0) {
      return true; // usuários legados sem permissões explícitas
    }

    // Compatibilidade: quem já tinha acesso a empréstimos pode acessar o lote didático.
    if (
      location.pathname === '/emprestimos-didaticos-lote' &&
      permissoesUsuario.includes('/emprestimos')
    ) {
      return true;
    }

    // Compatibilidade: quem já tinha acesso a leitores pode acessar séries/turmas.
    if (
      location.pathname === '/series-turmas' &&
      permissoesUsuario.includes('/clientes')
    ) {
      return true;
    }

    // Compatibilidade: quem tem acesso a livros pode acessar etiquetas e planilha de livros.
    if (
      (location.pathname === '/etiquetas' || location.pathname === '/relatorios-livros') &&
      permissoesUsuario.includes('/livros')
    ) {
      return true;
    }

    if (
      location.pathname.startsWith('/configuracoes/') &&
      permissoesUsuario.includes('/configuracoes')
    ) {
      return true;
    }

    return location.pathname === '/' || permissoesUsuario.includes(location.pathname);
  };
  
  // Log detalhado para debug
  console.log('🔍 PrivateRoute - Verificando acesso:', {
    pathname: location.pathname,
    autenticacaoCarregada,
    usuarioLogado: usuarioLogado ? usuarioLogado.nome : 'null'
  });
  
  // Aguardar autenticação ser carregada do localStorage
  if (!autenticacaoCarregada) {
    console.log('⏳ Aguardando autenticação carregar...');
    return (
      <Box
        sx={{
          minHeight: '100vh',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)'
        }}
      >
        <Typography variant="h6" color="white">Carregando...</Typography>
      </Box>
    );
  }
  
  // Verificar se está logado
  if (!usuarioLogado) {
    // Salvar a localização de onde veio para redirecionar após login
    console.log('🔒 Usuário não autenticado, redirecionando para login');
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  if (requiredProfile && usuarioLogado.perfil !== requiredProfile) {
    console.log('⛔ Acesso negado por perfil para rota:', location.pathname);
    return <Navigate to="/" replace />;
  }
  
  // Se está logado, verificar licença
  console.log('✅ Usuário autenticado:', usuarioLogado.nome, '- Verificando licença...');

  if (!temPermissaoRota()) {
    console.log('⛔ Acesso negado por permissão para rota:', location.pathname);
    return <Navigate to="/" replace />;
  }

  React.useEffect(() => {
    if (!usuarioLogado || !autenticacaoCarregada) return;
    registrarAcessoPagina(location.pathname, ROUTE_TITLES[location.pathname] || location.pathname);
  }, [location.pathname, usuarioLogado?.id, autenticacaoCarregada, registrarAcessoPagina]);

  return <ProtectedRoute>{children}</ProtectedRoute>;
}

function AppRoutes() {
  return (
    <Routes>
      {/* Rotas públicas (sem proteção de licença) */}
      <Route path="/login" element={<LoginPage />} />
      <Route path="/ativar-licenca" element={<AtivarLicencaPage />} />
      <Route path="/termos-de-uso" element={<TermosDeUsoPage />} />
      <Route path="/cadastro-escola" element={<CadastroEscolaPage />} />
      <Route path="/pagamento" element={<PagamentoPage />} />
      <Route path="/pagamento-sucesso" element={<PagamentoSucessoPage />} />
      
      {/* Rotas privadas (requerem login + licença) */}
      <Route path="/" element={<PrivateRoute><DashboardPage /></PrivateRoute>} />
      <Route path="/gerenciar-escolas" element={<PrivateRoute><GerenciarEscolasPage /></PrivateRoute>} />
      <Route path="/configurar-planos" element={<PrivateRoute><ConfigurarPlanosPage /></PrivateRoute>} />
      <Route path="/financeiro-admin" element={<PrivateRoute><FinanceiroAdminPage /></PrivateRoute>} />
      <Route path="/financeiro" element={<PrivateRoute><FinanceiroPage /></PrivateRoute>} />
      <Route path="/livros" element={<PrivateRoute><LivrosPage /></PrivateRoute>} />
      <Route path="/patrimonio" element={<PrivateRoute><PatrimonioPage /></PrivateRoute>} />
      <Route path="/clientes" element={<PrivateRoute><LeitoresPage /></PrivateRoute>} />
      <Route path="/series-turmas" element={<PrivateRoute><SeriesTurmasPage /></PrivateRoute>} />
      <Route path="/emprestimos" element={<PrivateRoute><EmprestimosPage /></PrivateRoute>} />
      <Route path="/emprestimos-didaticos-lote" element={<PrivateRoute><EmprestimoDidaticoLotePage /></PrivateRoute>} />
      <Route path="/devolucoes" element={<PrivateRoute><DevolucaoPage /></PrivateRoute>} />
      <Route path="/relatorios" element={<PrivateRoute><RelatoriosPage /></PrivateRoute>} />
      <Route path="/busca" element={<PrivateRoute><BuscaPage /></PrivateRoute>} />
      <Route path="/diagrama-sistema" element={<PrivateRoute requiredProfile="SuperAdmin"><DiagramaSistemaPage /></PrivateRoute>} />
      <Route path="/limpar-duplicatas" element={<PrivateRoute><LimparDuplicatasPage /></PrivateRoute>} />
      <Route path="/clube-leitura" element={<PrivateRoute><ClubeDeLeituraPage /></PrivateRoute>} />
      <Route path="/relatorios-livros" element={<PrivateRoute><RelatoriosLivrosPage /></PrivateRoute>} />
      <Route path="/notas-fiscais" element={<PrivateRoute><NotaFiscalPage /></PrivateRoute>} />
      <Route path="/gerenciar-usuarios" element={<PrivateRoute><GerenciarUsuariosPage /></PrivateRoute>} />
      <Route path="/relatorio-usuarios" element={<PrivateRoute><RelatorioUsuariosPage /></PrivateRoute>} />
      <Route path="/configuracoes" element={<PrivateRoute><ConfiguracoesPage /></PrivateRoute>} />
      <Route path="/configuracoes/nuvem" element={<PrivateRoute><ConfiguracoesNuvemPage /></PrivateRoute>} />
      <Route path="/etiquetas" element={<PrivateRoute><EtiquetasPage /></PrivateRoute>} />
    </Routes>
  );
}

function App() {
  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <DataProvider>
        <LicenseProvider>
          <UpdateNotification />
          <AppRoutes />
        </LicenseProvider>
      </DataProvider>
    </ThemeProvider>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import { Alert, AlertTitle, Box, Button, Typography, Chip } from '@mui/material';
import { Warning, Error, AccessTime, DeleteForever } from '@mui/icons-material';
import { useData } from '../context/DataContext';
import { useNavigate } from 'react-router-dom';

export default function AvisoLicenca() {
  const { 
    usuarioLogado, 
    instituicoes, 
    calcularDiasRestantesLicenca,
    calcularDiasGracaRestantes 
  } = useData();
  
  const [mostrarAviso, setMostrarAviso] = useState(false);
  const [tipoAviso, setTipoAviso] = useState('');
  const [diasRestantes, setDiasRestantes] = useState(null);
  const [diasGraca, setDiasGraca] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    if (!usuarioLogado || usuarioLogado.perfil === 'SuperAdmin') {
      setMostrarAviso(false);
      return;
    }

    const instituicao = instituicoes.find(i => i.id === usuarioLogado.instituicaoId);
    console.log('⚠️ AvisoLicenca - Instituição:', instituicao);
    
    if (!instituicao) {
      setMostrarAviso(false);
      return;
    }

    console.log('⚠️ AvisoLicenca - Status:', instituicao.status);
    console.log('⚠️ AvisoLicenca - Data Expiração:', instituicao.dataExpiracao);

    // Verificar status da licença
    if (instituicao.status === 'dados_removidos') {
      setTipoAviso('dados_removidos');
      setMostrarAviso(true);
      return;
    }

    if (instituicao.status === 'expirado') {
      const diasGracaRestantes = calcularDiasGracaRestantes(instituicao.id);
      setDiasGraca(diasGracaRestantes);
      setTipoAviso('expirado');
      setMostrarAviso(true);
      return;
    }

    if (instituicao.status === 'ativo') {
      const dias = calcularDiasRestantesLicenca(instituicao.id);
      console.log('⚠️ AvisoLicenca - Dias retornados:', dias);
      setDiasRestantes(dias);
      
      if (dias !== null && dias <= 15) {
        console.log('⚠️ AvisoLicenca - Mostrando aviso! Tipo:', dias <= 7 ? 'critico' : 'aviso');
        setTipoAviso(dias <= 7 ? 'critico' : 'aviso');
        setMostrarAviso(true);
      } else {
        console.log('⚠️ AvisoLicenca - Não mostrar aviso (dias > 15)');
        setMostrarAviso(false);
      }
    }
  }, [usuarioLogado, instituicoes, calcularDiasRestantesLicenca, calcularDiasGracaRestantes]);

  if (!mostrarAviso) return null;

  // Licença dados removidos
  if (tipoAviso === 'dados_removidos') {
    return (
      <Alert 
        severity="error" 
        icon={<DeleteForever />}
        sx={{ mb: 3, borderLeft: '5px solid #d32f2f' }}
      >
        <AlertTitle><strong>⚠️ DADOS REMOVIDOS - LICENÇA EXPIRADA HÁ MAIS DE 30 DIAS</strong></AlertTitle>
        <Typography variant="body2" gutterBottom>
          Sua licença expirou há mais de 30 dias e todos os seus dados foram removidos do sistema 
          por segurança. Seus dados básicos (cadastro da escola) foram preservados.
        </Typography>
        <Typography variant="body2" gutterBottom>
          <strong>Para reativar sua conta:</strong>
        </Typography>
        <Typography variant="body2" component="ul" sx={{ pl: 2, mb: 2 }}>
          <li>Entre em contato com o administrador do sistema</li>
          <li>Renove sua licença</li>
          <li>Recadastre seus dados (livros, alunos, etc.)</li>
        </Typography>
        <Button 
          variant="contained" 
          color="error" 
          size="small"
          onClick={() => navigate('/financeiro')}
        >
          Renovar Licença
        </Button>
      </Alert>
    );
  }

  // Licença expirada (período de graça)
  if (tipoAviso === 'expirado') {
    return (
      <Alert 
        severity="error" 
        icon={<Error />}
        sx={{ mb: 3, borderLeft: '5px solid #d32f2f' }}
      >
        <AlertTitle><strong>🚨 LICENÇA EXPIRADA - PERÍODO DE GRAÇA</strong></AlertTitle>
        <Typography variant="body2" gutterBottom>
          Sua licença expirou! Você tem <Chip 
            label={`${diasGraca} dias restantes`} 
            size="small" 
            color="error"
            sx={{ fontWeight: 'bold', mx: 0.5 }}
          /> do período de graça para renovar.
        </Typography>
        <Typography variant="body2" gutterBottom>
          <strong>⚠️ ATENÇÃO:</strong> Após {diasGraca} dias, todos os seus dados (livros, alunos, 
          empréstimos, etc.) serão <strong>PERMANENTEMENTE REMOVIDOS</strong> do sistema para 
          liberar espaço.
        </Typography>
        <Typography variant="body2" sx={{ mb: 2 }}>
          Seus dados básicos (cadastro da escola) serão preservados para futuros contatos.
        </Typography>
        <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
          <Button 
            variant="contained" 
            color="error" 
            size="small"
            onClick={() => navigate('/financeiro')}
          >
            Renovar Agora
          </Button>
          <Typography variant="caption" color="error">
            <AccessTime sx={{ fontSize: 14, verticalAlign: 'middle', mr: 0.5 }} />
            Dados serão removidos em {diasGraca} dias
          </Typography>
        </Box>
      </Alert>
    );
  }

  // Licença próxima de expirar (crítico - 7 dias ou menos)
  if (tipoAviso === 'critico') {
    return (
      <Alert 
        severity="error" 
        icon={<Error />}
        sx={{ mb: 3, borderLeft: '5px solid #d32f2f' }}
      >
        <AlertTitle><strong>🚨 URGENTE: Licença expira em {diasRestantes} dias!</strong></AlertTitle>
        <Typography variant="body2" gutterBottom>
          Sua licença está prestes a expirar! Após a expiração, você terá apenas 
          <strong> 30 dias</strong> para renovar antes que seus dados sejam removidos.
        </Typography>
        <Button 
          variant="contained" 
          color="error" 
          size="small"
          onClick={() => navigate('/financeiro')}
        >
          Renovar Agora
        </Button>
      </Alert>
    );
  }

  // Licença próxima de expirar (aviso - 15 dias ou menos)
  if (tipoAviso === 'aviso') {
    return (
      <Alert 
        severity="warning" 
        icon={<Warning />}
        sx={{ mb: 3 }}
      >
        <AlertTitle><strong>⚠️ Sua licença expira em {diasRestantes} dias</strong></AlertTitle>
        <Typography variant="body2" gutterBottom>
          Renove sua licença com antecedência para evitar interrupções no serviço.
        </Typography>
        <Button 
          variant="outlined" 
          color="warning" 
          size="small"
          onClick={() => navigate('/financeiro')}
        >
          Ver Opções de Renovação
        </Button>
      </Alert>
    );
  }

  return null;
}

import React, { useState } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Box,
  Typography,
  Alert,
  CircularProgress,
  TextField,
  Grid,
  InputAdornment,
  IconButton,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  LinearProgress,
  Chip
} from '@mui/material';
import { MenuBook, Close, Search } from '@mui/icons-material';
import { buscarLivroPorISBN } from '../utils/isbnSearchService';

export default function BarcodeScannerDialog({ open, onClose, onBookFound }) {
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [isbnBuscado, setIsbnBuscado] = useState(false);
  const [mostrarCamposManual, setMostrarCamposManual] = useState(false);
  const [progressoAtual, setProgressoAtual] = useState(null); // Para mostrar progresso da busca
  const [dadosLivro, setDadosLivro] = useState({
    isbn: '',
    titulo: '',
    autor: '',
    editora: '',
    anoPublicacao: '',
    edicao: '',
    cidadeEdicao: '',
    categoria: '',
    descricao: '',
    paginas: '',
    foto: '',
    quantidade: '1',
    colecao: '',
    qtdLivrosColecao: ''
  });

  // Estados para detecção de leitor a laser
  const [bufferScanner, setBufferScanner] = useState('');
  const [ultimoCaractere, setUltimoCaractere] = useState(Date.now());
  const timeoutRef = React.useRef(null);

  // Log para confirmar que está usando o componente atualizado
  React.useEffect(() => {
    if (open) {
  console.log('📚 BarcodeScannerDialog v3.5.1 - BUSCA EXPANDIDA!');
  console.log('🔫 Leitor de código de barras com IA');
  console.log('🚀 7 fontes: Google Books (múltiplas variações) + Gemini AI + Open Library + WorldCat + Amazon BR + BuscaISBN + Advanced Search');
    }
  }, [open]);

  // Sistema de detecção de leitor a laser APRIMORADO
  React.useEffect(() => {
    if (!open) return;

    let scanBuffer = '';
    let scanTimestamp = Date.now();
    let scanTimeout = null;

    const handleKeyDown = (event) => {
      const now = Date.now();
      const timeSinceLastKey = now - scanTimestamp;
      const char = event.key;

      // Ignorar teclas especiais exceto Enter
      if (char.length > 1 && char !== 'Enter') return;

      // Se for Enter e temos um buffer válido
      if (char === 'Enter') {
        event.preventDefault();
        if (scanBuffer.length >= 10 && scanBuffer.length <= 13) {
          const isbn = scanBuffer;
          console.log('🔫 Leitor laser detectado! ISBN:', isbn);
          // Atualizar campo e buscar
          setDadosLivro(prev => ({...prev, isbn}));
          buscarLivroPorIsbn(isbn);
          scanBuffer = '';
        }
        scanBuffer = ''; // Limpar buffer após Enter
        return;
      }

      // Se for número ou letra X
      if (/^[0-9X]$/i.test(char)) {
        // Resetar buffer se passou muito tempo (> 200ms = nova leitura)
        if (timeSinceLastKey > 200) {
          scanBuffer = '';
        }

        scanBuffer += char;
        scanTimestamp = now;
        console.log('🔵 Buffer atual:', scanBuffer);

        // Limpar timeout anterior
        if (scanTimeout) clearTimeout(scanTimeout);

        // Auto-buscar após 200ms de inatividade (fim da leitura)
        scanTimeout = setTimeout(() => {
          if (scanBuffer.length >= 10 && scanBuffer.length <= 13) {
            const isbn = scanBuffer;
            console.log('🔫 Código completo capturado (timeout):', isbn);
            setDadosLivro(prev => ({...prev, isbn}));
            buscarLivroPorIsbn(isbn);
            scanBuffer = '';
          } else if (scanBuffer.length > 0) {
            console.log('⚠️ Buffer incompleto:', scanBuffer);
            scanBuffer = '';
          }
        }, 200);
      }
    };

    // Usar keydown para captura mais rápida
    document.addEventListener('keydown', handleKeyDown);
    
    // Cleanup
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
      if (scanTimeout) clearTimeout(scanTimeout);
    };
  }, [open, mostrarCamposManual]);

  // Função para buscar livro usando o novo serviço aprimorado
  const buscarLivroPorIsbn = async (isbn) => {
    // Limpar e validar ISBN
    const isbnLimpo = isbn.replace(/[^0-9X]/gi, '').toUpperCase();
    
    console.log('🔍 ISBN RECEBIDO:', isbn);
    console.log('🧹 ISBN LIMPO:', isbnLimpo);
    
    if (!isbnLimpo || (isbnLimpo.length !== 10 && isbnLimpo.length !== 13)) {
      setError('⚠️ ISBN inválido! Deve ter 10 ou 13 dígitos.');
      setDadosLivro({ ...dadosLivro, isbn: isbnLimpo });
      setMostrarCamposManual(true);
      return;
    }

    setLoading(true);
    setError('');
    setIsbnBuscado(false);
    setMostrarCamposManual(false);
    setProgressoAtual(null);
    
    // Estado para armazenar a fonte
    let fonteEncontrada = '';
    
    try {
      // Usar o novo serviço de busca aprimorado
      const resultado = await buscarLivroPorISBN(isbnLimpo, (progresso) => {
        // Atualizar progresso visual
        setProgressoAtual(progresso);
        console.log(`📊 Progresso: ${progresso.progresso}% - Tentando: ${progresso.estrategia}`);
      });
      
      if (resultado.sucesso) {
        console.log('✅ LIVRO ENCONTRADO!');
        console.log('📚 Fonte:', resultado.fonte);
        console.log('📖 Dados:', resultado.dados);
        
        fonteEncontrada = resultado.fonte;
        
        // Preencher formulário com os dados encontrados
        const dadosCompletos = {
          ...resultado.dados,
          quantidade: dadosLivro.quantidade || '1',
          colecao: dadosLivro.colecao || resultado.dados.colecao || '',
          qtdLivrosColecao: dadosLivro.qtdLivrosColecao || resultado.dados.qtdLivrosColecao || '',
          _fonte: fonteEncontrada // Armazenar fonte para exibir depois
        };
        
        setDadosLivro(dadosCompletos);
        setIsbnBuscado(true);
        setMostrarCamposManual(true);
        setError('');
        
        // PREENCHER O FORMULÁRIO PRINCIPAL AUTOMATICAMENTE
        console.log('🎯 Preenchendo formulário principal automaticamente...');
        onBookFound(dadosCompletos);
        
        // Fechar o dialog após 1 segundo para o usuário ver que encontrou
        setTimeout(() => {
          handleClose();
        }, 1000);
      } else {
        // Não encontrou em nenhuma fonte
        console.log('❌ LIVRO NÃO ENCONTRADO');
        const mensagemAmigavel = `ISBN ${isbnLimpo} não encontrado nas bases de dados.`;
        
        setError(mensagemAmigavel);
        setDadosLivro({ ...dadosLivro, isbn: isbnLimpo });
        setMostrarCamposManual(true);
        setIsbnBuscado(false);
      }
      
    } catch (err) {
      console.error('❌ Erro geral na busca:', err);
      setError('⚠️ Erro ao buscar livro. Verifique sua conexão e tente novamente.');
      setDadosLivro({ ...dadosLivro, isbn: isbnLimpo });
      setMostrarCamposManual(true);
      setIsbnBuscado(false);
    } finally {
      setLoading(false);
      setProgressoAtual(null);
    }
  };

  const handleIsbnBlur = () => {
    // Buscar apenas se ainda não foi buscado e não está mostrando campos manuais
    if (dadosLivro.isbn && dadosLivro.isbn.length >= 10 && !isbnBuscado && !mostrarCamposManual) {
      buscarLivroPorIsbn(dadosLivro.isbn);
    }
  };

  const handleSalvar = () => {
    // Validação
    if (!dadosLivro.isbn) {
      setError('⚠️ ISBN é obrigatório!');
      return;
    }
    if (!dadosLivro.titulo) {
      setError('⚠️ Título é obrigatório!');
      return;
    }

    // Enviar dados do livro
    onBookFound(dadosLivro);
    handleClose();
  };

  const handleClose = () => {
    setError('');
    setLoading(false);
    setIsbnBuscado(false);
    setMostrarCamposManual(false);
    setBufferScanner('');
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }
    setDadosLivro({
      isbn: '',
      titulo: '',
      autor: '',
      editora: '',
      anoPublicacao: '',
      categoria: '',
      descricao: '',
      paginas: '',
      foto: '',
      quantidade: '1',
      colecao: '',
      qtdLivrosColecao: ''
    });
    onClose();
  };

  return (
    <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
      <DialogTitle>
        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <MenuBook />
            <span>Cadastrar Livro</span>
          </Box>
          <Button onClick={handleClose} size="small">
            <Close />
          </Button>
        </Box>
      </DialogTitle>
      
      <DialogContent>
        <Alert severity="info" sx={{ mb: 2 }}>
          <Typography variant="body2">
            <strong>� LEITOR A LASER HABILITADO!</strong><br />
            <strong>📝 Opção 1:</strong> Use o leitor de código de barras a laser - ele detectará automaticamente<br />
            <strong>⌨️ Opção 2:</strong> Digite o ISBN manualmente e pressione Enter<br />
            <strong>🔍 Passo 2:</strong> O sistema buscará os dados automaticamente<br />
            <strong>✏️ Passo 3:</strong> Se não encontrar, preencha manualmente
          </Typography>
        </Alert>

        {bufferScanner && (
          <Alert severity="success" sx={{ mb: 2 }}>
            🔫 Lendo código de barras: {bufferScanner}...
          </Alert>
        )}

        {loading && (
          <Box sx={{ mb: 3 }}>
            <Box sx={{ textAlign: 'center', py: 2 }}>
              <CircularProgress size={60} />
              <Typography variant="h6" sx={{ mt: 2, fontWeight: 'bold' }}>
                🔍 Buscando ISBN: <Chip label={dadosLivro.isbn} color="primary" size="small" />
              </Typography>
              
              {progressoAtual && (
                <Box sx={{ mt: 2 }}>
                  <Typography variant="body2" color="primary" sx={{ mb: 1, fontWeight: 600 }}>
                    📡 {progressoAtual.estrategia}
                  </Typography>
                  <LinearProgress 
                    variant="determinate" 
                    value={progressoAtual.progresso} 
                    sx={{ height: 8, borderRadius: 4 }}
                  />
                  <Typography variant="caption" color="text.secondary" sx={{ mt: 0.5, display: 'block' }}>
                    Tentativa {progressoAtual.tentativa} de {progressoAtual.total} • {progressoAtual.progresso}%
                  </Typography>
                </Box>
              )}
            </Box>
            
            <Alert severity="info" sx={{ mt: 2 }}>
              <Typography variant="caption" component="div">
                <strong>🤖 Inteligência Artificial:</strong>
                <br />• Google Gemini AI (prioridade máxima!) ⚠️ <strong>Configure a API key gratuita!</strong>
                <br />
                <br /><strong>🇧🇷 Fontes Brasileiras:</strong>
                <br />• Editoras: FTD, Ática, Moderna, Saraiva, Scipione, SM, IBEP
                <br />• Mercado Editorial Brasileiro
                <br />
                <br /><strong>🌐 Fontes Internacionais:</strong>
                <br />• Google Books API (múltiplas estratégias)
                <br />• Open Library (biblioteca mundial)
                <br />
                <br /><Typography variant="caption" sx={{ fontStyle: 'italic', fontSize: '0.7rem' }}>
                  💡 <strong>Dica:</strong> O Gemini AI encontra QUALQUER livro! Configure a API key gratuita em ATIVAR_GEMINI_AI.md
                </Typography>
              </Typography>
            </Alert>
          </Box>
        )}

        {error && (
          <Alert severity="info" sx={{ mb: 2 }}>
            {error}
          </Alert>
        )}

        {isbnBuscado && dadosLivro.titulo && (
          <Alert severity="success" sx={{ mb: 2 }}>
            ✅ Livro encontrado! Dados preenchidos automaticamente.
            {dadosLivro._fonte && (
              <Typography variant="caption" display="block" sx={{ mt: 0.5 }}>
                📡 Fonte: <strong>{dadosLivro._fonte}</strong>
              </Typography>
            )}
          </Alert>
        )}

        {/* CAMPO ISBN - SEMPRE PRIMEIRO E OBRIGATÓRIO */}
        <TextField
          fullWidth
          required
          id="isbn-field"
          label="ISBN"
          value={dadosLivro.isbn}
          onChange={(e) => {
            const valor = e.target.value.replace(/[^0-9]/g, '');
            setDadosLivro({...dadosLivro, isbn: valor});
            setError('');
          }}
          onBlur={handleIsbnBlur}
          onKeyPress={(e) => {
            if (e.key === 'Enter' && dadosLivro.isbn) {
              buscarLivroPorIsbn(dadosLivro.isbn);
            }
          }}
          inputProps={{ 
            maxLength: 13,
            inputMode: 'numeric',
            pattern: '[0-9]*'
          }}
          InputProps={{
            endAdornment: dadosLivro.isbn && dadosLivro.isbn.length >= 10 && (
              <InputAdornment position="end">
                <IconButton 
                  onClick={() => buscarLivroPorIsbn(dadosLivro.isbn)}
                  disabled={loading}
                  edge="end"
                >
                  <Search />
                </IconButton>
              </InputAdornment>
            )
          }}
          helperText="🔫 Use o leitor laser (RECOMENDADO) | ⌨️ Digite e pressione Enter | 🇧🇷 Busca em fontes brasileiras + internacionais"
          autoFocus
          sx={{ mb: 2 }}
        />

        {/* CAMPOS DO FORMULÁRIO - APARECEM APÓS BUSCAR ISBN */}
        {mostrarCamposManual && !loading && (
          <>
            {dadosLivro.foto && (
              <Box sx={{ textAlign: 'center', mb: 2 }}>
                <img 
                  src={dadosLivro.foto} 
