                />
              </Box>
            )}

            <Grid container spacing={2}>
              <Grid item xs={12}>
                <TextField
                  fullWidth
                  required
                  id="titulo-field"
                  label="Título"
                  value={dadosLivro.titulo}
                  onChange={(e) => setDadosLivro({...dadosLivro, titulo: e.target.value})}
                  helperText="Obrigatório"
                />
              </Grid>
              
              <Grid item xs={12}>
                <TextField
                  fullWidth
                  label="Autor"
                  value={dadosLivro.autor}
                  onChange={(e) => setDadosLivro({...dadosLivro, autor: e.target.value})}
                  placeholder="Nome do autor"
                />
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Editora"
                  value={dadosLivro.editora}
                  onChange={(e) => setDadosLivro({...dadosLivro, editora: e.target.value})}
                />
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Ano de Publicação"
                  value={dadosLivro.anoPublicacao}
                  onChange={(e) => setDadosLivro({...dadosLivro, anoPublicacao: e.target.value.replace(/[^0-9]/g, '')})}
                  inputProps={{ maxLength: 4 }}
                  placeholder="2024"
                />
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Edição"
                  value={dadosLivro.edicao}
                  onChange={(e) => setDadosLivro({...dadosLivro, edicao: e.target.value})}
                  placeholder="Ex: 1ª edição, 2ª, etc."
                />
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Cidade de Edição"
                  value={dadosLivro.cidadeEdicao}
                  onChange={(e) => setDadosLivro({...dadosLivro, cidadeEdicao: e.target.value})}
                  placeholder="Ex: São Paulo, Rio de Janeiro"
                />
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <FormControl fullWidth>
                  <InputLabel>Categoria</InputLabel>
                  <Select
                    value={dadosLivro.categoria}
                    label="Categoria"
                    onChange={(e) => setDadosLivro({...dadosLivro, categoria: e.target.value})}
                  >
                    <MenuItem value="">Selecione...</MenuItem>
                    <MenuItem value="Ficção">Ficção</MenuItem>
                    <MenuItem value="Não-Ficção">Não-Ficção</MenuItem>
                    <MenuItem value="Romance">Romance</MenuItem>
                    <MenuItem value="Fantasia">Fantasia</MenuItem>
                    <MenuItem value="Aventura">Aventura</MenuItem>
                    <MenuItem value="Mistério">Mistério</MenuItem>
                    <MenuItem value="Suspense">Suspense</MenuItem>
                    <MenuItem value="Terror">Terror</MenuItem>
                    <MenuItem value="Poesia">Poesia</MenuItem>
                    <MenuItem value="Drama">Drama</MenuItem>
                    <MenuItem value="Biografia">Biografia</MenuItem>
                    <MenuItem value="História">História</MenuItem>
                    <MenuItem value="Ciência">Ciência</MenuItem>
                    <MenuItem value="Filosofia">Filosofia</MenuItem>
                    <MenuItem value="Autoajuda">Autoajuda</MenuItem>
                    <MenuItem value="Didático">Didático</MenuItem>
                    <MenuItem value="Infantil">Infantil</MenuItem>
                    <MenuItem value="Juvenil">Juvenil</MenuItem>
                    <MenuItem value="Quadrinhos">Quadrinhos</MenuItem>
                    <MenuItem value="Religião">Religião</MenuItem>
                    <MenuItem value="Gastronomia">Gastronomia</MenuItem>
                    <MenuItem value="Arte">Arte</MenuItem>
                    <MenuItem value="Técnico">Técnico</MenuItem>
                    <MenuItem value="Outro">Outro</MenuItem>
                  </Select>
                </FormControl>
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  required
                  label="Quantidade"
                  type="number"
                  value={dadosLivro.quantidade}
                  onChange={(e) => setDadosLivro({...dadosLivro, quantidade: e.target.value})}
                  inputProps={{ min: 1 }}
                  helperText="Quantos exemplares deste livro?"
                />
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Coleção"
                  value={dadosLivro.colecao}
                  onChange={(e) => setDadosLivro({...dadosLivro, colecao: e.target.value})}
                  placeholder="Ex: Harry Potter, Senhor dos Anéis..."
                  helperText="Pertence a alguma coleção?"
                />
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Qtd. Livros na Coleção"
                  type="number"
                  value={dadosLivro.qtdLivrosColecao}
                  onChange={(e) => setDadosLivro({...dadosLivro, qtdLivrosColecao: e.target.value})}
                  inputProps={{ min: 0 }}
                  placeholder="Total de livros"
                  disabled={!dadosLivro.colecao}
                  helperText="Quantos livros tem a coleção?"
                />
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Páginas"
                  value={dadosLivro.paginas}
                  onChange={(e) => setDadosLivro({...dadosLivro, paginas: e.target.value.replace(/[^0-9]/g, '')})}
                  inputProps={{ maxLength: 5 }}
                />
              </Grid>
              
              <Grid item xs={12}>
                <TextField
                  fullWidth
                  label="URL da Foto da Capa"
                  value={dadosLivro.foto}
                  onChange={(e) => setDadosLivro({...dadosLivro, foto: e.target.value})}
                  placeholder="https://exemplo.com/capa.jpg"
                  helperText="Cole o link da imagem (opcional)"
                />
              </Grid>
              
              <Grid item xs={12}>
                <TextField
                  fullWidth
                  multiline
                  rows={3}
                  label="Descrição"
                  value={dadosLivro.descricao}
                  onChange={(e) => setDadosLivro({...dadosLivro, descricao: e.target.value})}
                  placeholder="Sinopse ou descrição do livro"
                />
              </Grid>
            </Grid>
          </>
        )}
      </DialogContent>
      
      <DialogActions>
        <Button onClick={handleClose}>Cancelar</Button>
        {mostrarCamposManual && (
          <Button 
            variant="contained" 
            color="success"
            onClick={handleSalvar}
            disabled={!dadosLivro.isbn || !dadosLivro.titulo}
          >
            ✅ Salvar Livro
          </Button>
        )}
      </DialogActions>
    </Dialog>
  );
}

import React, { useState, useRef, useEffect } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Box,
  IconButton,
  Alert,
  CircularProgress,
  Slider,
  Typography
} from '@mui/material';
import {
  PhotoCamera,
  Close,
  FlipCameraAndroid,
  CheckCircle,
  ZoomIn as ZoomInIcon,
  ZoomOut as ZoomOutIcon,
  Crop as CropIcon
} from '@mui/icons-material';

/**
 * Componente para captura de foto direta da câmera
 * Permite tirar foto em tempo real sem necessidade de upload
 */
const CameraCapture = ({ open, onClose, onCapture, title = "Tirar Foto" }) => {
  const [stream, setStream] = useState(null);
  const [capturedImage, setCapturedImage] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const [facingMode, setFacingMode] = useState('environment'); // 'user' ou 'environment'
  const [zoomLevel, setZoomLevel] = useState(1); // zoom 1x a 4x
  // Crop: % a cortar de cada lado (0 = sem corte)
  const [cropBounds, setCropBounds] = useState({ top: 0, left: 0, right: 0, bottom: 0 });

  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const cropContainerRef = useRef(null);
  const draggingEdge = useRef(null);

  // Iniciar câmera quando o dialog abrir
  useEffect(() => {
    if (open && !capturedImage) {
      startCamera();
    }
    // Limpar ao fechar
    return () => { stopCamera(); };
  }, [open, facingMode]);

  // Resetar estado ao fechar
  useEffect(() => {
    if (!open) {
      setZoomLevel(1);
      setCapturedImage(null);
      setCropBounds({ top: 0, left: 0, right: 0, bottom: 0 });
      setError(null);
    }
  }, [open]);

  // Conectar o stream ao <video> assim que o elemento estiver no DOM
  // (startCamera roda enquanto loading=true, videoRef pode ser null naquele momento)
  useEffect(() => {
    if (stream && videoRef.current && !capturedImage) {
      videoRef.current.srcObject = stream;
      videoRef.current.play().catch(err => console.error('Erro ao reproduzir vídeo:', err));
    }
  }, [stream, capturedImage]);  // dispara após setLoading(false) re-renderizar o elemento

  const startCamera = async () => {
    try {
      setLoading(true);
      setError(null);

      // Verificar se o navegador suporta getUserMedia
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        throw new Error('Seu navegador não suporta acesso à câmera');
      }

      // Parar stream anterior se existir
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }

      // Solicitar acesso à câmera com resolução maior para zoom digital
      const mediaStream = await navigator.mediaDevices.getUserMedia({
        video: {
          facingMode: facingMode,
          width: { ideal: 1920 },
          height: { ideal: 1080 }
        },
        audio: false
      });

      setStream(mediaStream);
      // srcObject será atribuído pelo useEffect após setLoading(false) re-renderizar o <video>
      setLoading(false);
    } catch (err) {
      console.error('Erro ao acessar câmera:', err);
      setLoading(false);
      
      if (err.name === 'NotAllowedError') {
        setError('Acesso à câmera negado. Por favor, permita o acesso nas configurações do navegador.');
      } else if (err.name === 'NotFoundError') {
        setError('Nenhuma câmera encontrada no dispositivo.');
      } else if (err.name === 'NotReadableError') {
        setError('Câmera já está em uso por outro aplicativo.');
      } else {
        setError(err.message || 'Erro ao acessar câmera');
      }
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
  };

  const capturePhoto = () => {
    if (!videoRef.current || !canvasRef.current) return;

    const video = videoRef.current;
    const canvas = canvasRef.current;
    const fullW = video.videoWidth;
    const fullH = video.videoHeight;

    // Recortar a área central de acordo com o zoom
    const cropW = fullW / zoomLevel;
    const cropH = fullH / zoomLevel;
    const cropX = (fullW - cropW) / 2;
    const cropY = (fullH - cropH) / 2;

    canvas.width = Math.round(cropW);
    canvas.height = Math.round(cropH);

    const ctx = canvas.getContext('2d');
    if (facingMode === 'user') {
      ctx.translate(canvas.width, 0);
      ctx.scale(-1, 1);
    }
    ctx.drawImage(video, cropX, cropY, cropW, cropH, 0, 0, canvas.width, canvas.height);

    const imageData = canvas.toDataURL('image/jpeg', 0.9);
    setCapturedImage(imageData);
    setCropBounds({ top: 0, left: 0, right: 0, bottom: 0 });
    stopCamera();
  };

  const retakePhoto = () => {
    setCapturedImage(null);
    setCropBounds({ top: 0, left: 0, right: 0, bottom: 0 });
    setZoomLevel(1);
    startCamera();
  };

  const confirmPhoto = () => {
    if (!capturedImage) return;
    const { top, left, right, bottom } = cropBounds;
    // Sem recorte: enviar imagem original
    if (top === 0 && left === 0 && right === 0 && bottom === 0) {
      onCapture(capturedImage);
      handleClose();
      return;
    }
    // Aplicar recorte via canvas
    const img = new Image();
    img.onload = () => {
      const c = document.createElement('canvas');
      const srcX = Math.round(img.width * left / 100);
      const srcY = Math.round(img.height * top / 100);
      const srcW = Math.round(img.width * (100 - left - right) / 100);
      const srcH = Math.round(img.height * (100 - top - bottom) / 100);
      c.width = srcW;
      c.height = srcH;
      c.getContext('2d').drawImage(img, srcX, srcY, srcW, srcH, 0, 0, srcW, srcH);
      onCapture(c.toDataURL('image/jpeg', 0.92));
      handleClose();
    };
    img.src = capturedImage;
  };

  const toggleCamera = () => {
    setFacingMode(prev => prev === 'user' ? 'environment' : 'user');
    setCapturedImage(null);
    setZoomLevel(1);
  };

  const handleClose = () => {
    stopCamera();
    setCapturedImage(null);
    setCropBounds({ top: 0, left: 0, right: 0, bottom: 0 });
    setZoomLevel(1);
    setError(null);
    onClose();
  };

  // Drag para recorte nas 4 laterais
  const handleEdgePointerDown = (e, edge) => {
    e.preventDefault();
    e.stopPropagation();
    draggingEdge.current = edge;

    const onMove = (ev) => {
      if (!draggingEdge.current || !cropContainerRef.current) return;
      const rect = cropContainerRef.current.getBoundingClientRect();
      const x = Math.max(0, Math.min(1, (ev.clientX - rect.left) / rect.width));
      const y = Math.max(0, Math.min(1, (ev.clientY - rect.top) / rect.height));
      setCropBounds(prev => {
        const next = { ...prev };
        if (draggingEdge.current === 'top')    next.top    = Math.min(y * 100,       100 - prev.bottom - 5);
        if (draggingEdge.current === 'bottom') next.bottom = Math.min((1 - y) * 100, 100 - prev.top    - 5);
        if (draggingEdge.current === 'left')   next.left   = Math.min(x * 100,       100 - prev.right  - 5);
        if (draggingEdge.current === 'right')  next.right  = Math.min((1 - x) * 100, 100 - prev.left   - 5);
        return next;
      });
    };

    const onUp = () => {
      draggingEdge.current = null;
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup', onUp);
    };

    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
  };

  const { top, left, right, bottom } = cropBounds;
  const hasCrop = top > 0 || left > 0 || right > 0 || bottom > 0;
  const HANDLE = 28; // tamanho das alças em px

  return (
    <Dialog 
      open={open} 
      onClose={handleClose}
      maxWidth="md"
      fullWidth
      PaperProps={{
        sx: {
          backgroundColor: '#000',
          color: '#fff'
        }
      }}
    >
      <DialogTitle sx={{ 
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center',
        color: '#fff'
      }}>
        {capturedImage ? 'Ajustar Imagem' : title}
        <IconButton onClick={handleClose} sx={{ color: '#fff' }}>
          <Close />
        </IconButton>
      </DialogTitle>

      <DialogContent sx={{ p: 0, position: 'relative', minHeight: 400 }}>
        {error && (
          <Alert severity="error" sx={{ m: 2 }}>
            {error}
          </Alert>
        )}

        {loading && (
          <Box sx={{ 
            display: 'flex', 
            justifyContent: 'center', 
            alignItems: 'center',
            minHeight: 400 
          }}>
            <CircularProgress />
          </Box>
        )}

        {/* Canvas oculto para captura */}
        <canvas ref={canvasRef} style={{ display: 'none' }} />

        {!loading && !error && (
          <Box sx={{ 
            position: 'relative',
            width: '100%',
            paddingTop: '75%',
            backgroundColor: '#000',
            overflow: 'hidden'
          }}>

            {/* Vídeo sempre no DOM para que videoRef.current esteja disponível quando
                o useEffect rodar após setLoading(false) */}
            <video
              ref={videoRef}
              autoPlay
              playsInline
              muted
              onLoadedMetadata={(e) => {
                e.target.play().catch(err => console.error('Play error:', err));
              }}
              style={{
                display: capturedImage ? 'none' : 'block',
                position: 'absolute',
                top: 0, left: 0,
                width: '100%', height: '100%',
                objectFit: 'cover',
                transform: facingMode === 'user'
                  ? `scale(${zoomLevel}) scaleX(-1)`
                  : `scale(${zoomLevel})`,
                transformOrigin: 'center center',
                transition: 'transform 0.08s'
              }}
            />

            {/* ── CONTROLES CÂMERA AO VIVO ── */}
            {!capturedImage && (
              <>
                {/* Botão de trocar câmera */}
                {stream && (
                  <IconButton
                    onClick={toggleCamera}
                    sx={{
                      position: 'absolute',
                      top: 12, right: 12,
                      color: '#fff',
                      backgroundColor: 'rgba(0,0,0,0.5)',
                      '&:hover': { backgroundColor: 'rgba(0,0,0,0.7)' }
                    }}
                  >
                    <FlipCameraAndroid />
                  </IconButton>
                )}

                {/* Controle de zoom — somente quando há stream */}
                {stream && (
                  <Box sx={{
                    position: 'absolute',
                    bottom: 12, left: 12, right: 12,
                    bgcolor: 'rgba(0,0,0,0.6)',
                    borderRadius: 2,
                    p: '8px 14px',
                    display: 'flex',
                    alignItems: 'center',
                    gap: 1
                  }}>
                    <IconButton
                      size="small"
                      sx={{ color: '#fff', p: 0.5 }}
                      onClick={() => setZoomLevel(z => Math.max(1, parseFloat((z - 0.25).toFixed(2))))}
                    >
                      <ZoomOutIcon fontSize="small" />
                    </IconButton>
                    <Slider
                      value={zoomLevel}
                      min={1}
                      max={4}
                      step={0.05}
                      onChange={(_, v) => setZoomLevel(v)}
                      sx={{
                        color: '#fff',
                        flexGrow: 1,
                        '& .MuiSlider-thumb': { width: 16, height: 16 }
                      }}
                    />
                    <IconButton
                      size="small"
                      sx={{ color: '#fff', p: 0.5 }}
                      onClick={() => setZoomLevel(z => Math.min(4, parseFloat((z + 0.25).toFixed(2))))}
                    >
                      <ZoomInIcon fontSize="small" />
                    </IconButton>
                    <Typography sx={{ color: '#fff', fontSize: 13, minWidth: 34, textAlign: 'right' }}>
                      {zoomLevel.toFixed(1)}x
                    </Typography>
                  </Box>
                )}
              </>
            )}

            {/* ── IMAGEM CAPTURADA + ALÇAS DE RECORTE ── */}
            {capturedImage && (
              <>
                <img
                  src={capturedImage}
                  alt="Foto capturada"
                  style={{
                    position: 'absolute',
                    top: 0, left: 0,
                    width: '100%', height: '100%',
                    objectFit: 'contain'
                  }}
                />

                {/* Overlay de recorte */}
                <Box
                  ref={cropContainerRef}
                  sx={{ position: 'absolute', inset: 0, userSelect: 'none', touchAction: 'none' }}
                >
                  {/* Áreas escuras fora do recorte */}
                  <Box sx={{ position: 'absolute', top: 0, left: 0, right: 0, height: `${top}%`, bgcolor: 'rgba(0,0,0,0.55)' }} />
                  <Box sx={{ position: 'absolute', bottom: 0, left: 0, right: 0, height: `${bottom}%`, bgcolor: 'rgba(0,0,0,0.55)' }} />
                  <Box sx={{ position: 'absolute', top: `${top}%`, bottom: `${bottom}%`, left: 0, width: `${left}%`, bgcolor: 'rgba(0,0,0,0.55)' }} />
                  <Box sx={{ position: 'absolute', top: `${top}%`, bottom: `${bottom}%`, right: 0, width: `${right}%`, bgcolor: 'rgba(0,0,0,0.55)' }} />

                  {/* Borda do recorte */}
                  <Box sx={{
                    position: 'absolute',
                    top: `${top}%`, left: `${left}%`, right: `${right}%`, bottom: `${bottom}%`,
                    border: '2px solid rgba(255,255,255,0.9)',
                    boxSizing: 'border-box',
                    pointerEvents: 'none'
                  }} />

                  {/* Alça — Topo */}
                  <Box
                    onPointerDown={e => handleEdgePointerDown(e, 'top')}
                    sx={{
                      position: 'absolute', top: `${top}%`, left: '50%',
                      transform: 'translate(-50%, -50%)',
                      width: HANDLE, height: HANDLE,
                      bgcolor: '#fff', borderRadius: '50%',
                      border: '2.5px solid #1976d2',
                      cursor: 'ns-resize', zIndex: 10,
                      '&:hover': { bgcolor: '#bbdefb' }
                    }}
                  />

                  {/* Alça — Base */}
                  <Box
                    onPointerDown={e => handleEdgePointerDown(e, 'bottom')}
                    sx={{
                      position: 'absolute', bottom: `${bottom}%`, left: '50%',
                      transform: 'translate(-50%, 50%)',
                      width: HANDLE, height: HANDLE,
                      bgcolor: '#fff', borderRadius: '50%',
                      border: '2.5px solid #1976d2',
                      cursor: 'ns-resize', zIndex: 10,
                      '&:hover': { bgcolor: '#bbdefb' }
                    }}
                  />

                  {/* Alça — Esquerda */}
                  <Box
                    onPointerDown={e => handleEdgePointerDown(e, 'left')}
                    sx={{
                      position: 'absolute', top: '50%', left: `${left}%`,
                      transform: 'translate(-50%, -50%)',
                      width: HANDLE, height: HANDLE,
                      bgcolor: '#fff', borderRadius: '50%',
                      border: '2.5px solid #1976d2',
                      cursor: 'ew-resize', zIndex: 10,
                      '&:hover': { bgcolor: '#bbdefb' }
                    }}
                  />

                  {/* Alça — Direita */}
                  <Box
                    onPointerDown={e => handleEdgePointerDown(e, 'right')}
                    sx={{
                      position: 'absolute', top: '50%', right: `${right}%`,
                      transform: 'translate(50%, -50%)',
                      width: HANDLE, height: HANDLE,
                      bgcolor: '#fff', borderRadius: '50%',
                      border: '2.5px solid #1976d2',
                      cursor: 'ew-resize', zIndex: 10,
                      '&:hover': { bgcolor: '#bbdefb' }
                    }}
                  />
                </Box>
              </>
            )}

          </Box>
        )}

        {/* Dica de recorte */}
        {capturedImage && !loading && !error && (
          <Box sx={{ px: 2, py: 1, bgcolor: 'rgba(25,118,210,0.12)', borderTop: '1px solid rgba(255,255,255,0.08)' }}>
            <Typography variant="caption" sx={{ color: '#90caf9', display: 'flex', alignItems: 'center', gap: 0.5 }}>
              <CropIcon sx={{ fontSize: 14 }} />
              Arraste as alças brancas para ajustar cada lateral da imagem.
              {hasCrop && ` (T:${top.toFixed(0)}% B:${bottom.toFixed(0)}% E:${left.toFixed(0)}% D:${right.toFixed(0)}%)`}
            </Typography>
          </Box>
        )}
      </DialogContent>

      <DialogActions sx={{ 
        justifyContent: 'center', 
        gap: 2, 
        p: 2,
        backgroundColor: '#000'
      }}>
        {!capturedImage ? (
          <>
            <Button
              variant="outlined"
              onClick={handleClose}
              sx={{ color: '#fff', borderColor: '#fff' }}
            >
              Cancelar
            </Button>
            <Button
              variant="contained"
              startIcon={<PhotoCamera />}
              onClick={capturePhoto}
              disabled={!stream || loading || !!error}
              sx={{
                backgroundColor: '#2196f3',
                '&:hover': { backgroundColor: '#1976d2' }
              }}
            >
              Capturar
            </Button>
          </>
        ) : (
          <>
            <Button
              variant="outlined"
              onClick={retakePhoto}
              sx={{ color: '#fff', borderColor: '#fff' }}
            >
              Tirar Outra
            </Button>
            {hasCrop && (
              <Button
                variant="outlined"
                onClick={() => setCropBounds({ top: 0, left: 0, right: 0, bottom: 0 })}
                sx={{ color: '#ff9800', borderColor: '#ff9800' }}
              >
                Limpar Recorte
              </Button>
            )}
            <Button
              variant="contained"
              startIcon={<CheckCircle />}
              onClick={confirmPhoto}
              sx={{
                backgroundColor: '#4caf50',
                '&:hover': { backgroundColor: '#388e3c' }
              }}
            >
              Confirmar
            </Button>
          </>
        )}
      </DialogActions>
    </Dialog>
  );
};

export default CameraCapture;

import React, { useState, useRef, useEffect } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Box,
  Typography,
  IconButton
} from '@mui/material';
import { CheckCircle, Close, Crop as CropIcon } from '@mui/icons-material';

/**
 * Editor de corte de imagem (margens superior, inferior, esquerda e direita)
 * Props:
 *   open       - boolean
 *   imageData  - string base64 (data URL) da imagem a editar
 *   onSave     - função chamada com a imagem cortada (data URL)
 *   onClose    - função chamada ao cancelar
 *   title      - string (opcional)
 */
const ImageCropEditor = ({ open, imageData, onSave, onClose, title = 'Editar Imagem' }) => {
  const [cropBounds, setCropBounds] = useState({ top: 0, left: 0, right: 0, bottom: 0 });
  const cropContainerRef = useRef(null);
  const draggingEdge = useRef(null);

  useEffect(() => {
    if (open) setCropBounds({ top: 0, left: 0, right: 0, bottom: 0 });
  }, [open, imageData]);

  const handleEdgePointerDown = (e, edge) => {
    e.preventDefault();
    e.stopPropagation();
    draggingEdge.current = edge;

    const onMove = (ev) => {
      if (!draggingEdge.current || !cropContainerRef.current) return;
      const rect = cropContainerRef.current.getBoundingClientRect();
      const clientX = ev.touches ? ev.touches[0].clientX : ev.clientX;
      const clientY = ev.touches ? ev.touches[0].clientY : ev.clientY;
      const x = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
      const y = Math.max(0, Math.min(1, (clientY - rect.top) / rect.height));
      setCropBounds((prev) => {
        const next = { ...prev };
        if (draggingEdge.current === 'top')    next.top    = Math.min(y * 100,       100 - prev.bottom - 5);
        if (draggingEdge.current === 'bottom') next.bottom = Math.min((1 - y) * 100, 100 - prev.top    - 5);
        if (draggingEdge.current === 'left')   next.left   = Math.min(x * 100,       100 - prev.right  - 5);
        if (draggingEdge.current === 'right')  next.right  = Math.min((1 - x) * 100, 100 - prev.left   - 5);
        return next;
      });
    };

    const onUp = () => {
      draggingEdge.current = null;
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup', onUp);
      window.removeEventListener('touchmove', onMove);
      window.removeEventListener('touchend', onUp);
    };

    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
    window.addEventListener('touchmove', onMove, { passive: false });
    window.addEventListener('touchend', onUp);
  };

  const handleSave = () => {
    if (!imageData) return;
    const { top, left, right, bottom } = cropBounds;
    if (top === 0 && left === 0 && right === 0 && bottom === 0) {
      onSave(imageData);
      return;
    }
    const img = new Image();
    img.onload = () => {
      const c = document.createElement('canvas');
      const srcX = Math.round(img.width  * left   / 100);
      const srcY = Math.round(img.height * top    / 100);
      const srcW = Math.round(img.width  * (100 - left  - right)  / 100);
      const srcH = Math.round(img.height * (100 - top   - bottom) / 100);
      c.width  = srcW;
      c.height = srcH;
      c.getContext('2d').drawImage(img, srcX, srcY, srcW, srcH, 0, 0, srcW, srcH);
      onSave(c.toDataURL('image/jpeg', 0.92));
    };
    img.src = imageData;
  };

  const { top, left, right, bottom } = cropBounds;
  const hasCrop = top > 0 || left > 0 || right > 0 || bottom > 0;
  const HANDLE = 30;

  const handleStyle = (edge) => {
    const base = {
      position: 'absolute',
      width: HANDLE,
      height: HANDLE,
      bgcolor: '#fff',
      borderRadius: '50%',
      border: '2.5px solid #1976d2',
      zIndex: 10,
      touchAction: 'none',
      '&:hover': { bgcolor: '#bbdefb' },
      '&:active': { bgcolor: '#90caf9' }
    };
    if (edge === 'top')    return { ...base, top: `${top}%`,    left: '50%', transform: 'translate(-50%, -50%)', cursor: 'ns-resize' };
    if (edge === 'bottom') return { ...base, bottom: `${bottom}%`, left: '50%', transform: 'translate(-50%, 50%)', cursor: 'ns-resize' };
    if (edge === 'left')   return { ...base, top: '50%', left: `${left}%`,  transform: 'translate(-50%, -50%)', cursor: 'ew-resize' };
    if (edge === 'right')  return { ...base, top: '50%', right: `${right}%`, transform: 'translate(50%, -50%)', cursor: 'ew-resize' };
    return base;
  };

  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="md"
      fullWidth
      PaperProps={{ sx: { backgroundColor: '#111', color: '#fff' } }}
    >
      <DialogTitle sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', color: '#fff', pb: 1 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <CropIcon />
          {title}
        </Box>
        <IconButton onClick={onClose} sx={{ color: '#fff' }}>
          <Close />
        </IconButton>
      </DialogTitle>

      <DialogContent sx={{ p: 0 }}>
        {/* Área da imagem com alças de recorte */}
        <Box
          sx={{
            position: 'relative',
            width: '100%',
            paddingTop: '75%',
            backgroundColor: '#000',
            overflow: 'hidden'
          }}
        >
          {imageData && (
            <>
              <img
                src={imageData}
                alt="Editar imagem"
                style={{
                  position: 'absolute',
                  top: 0, left: 0,
                  width: '100%', height: '100%',
                  objectFit: 'contain'
                }}
              />

              {/* Overlay de recorte */}
              <Box
                ref={cropContainerRef}
                sx={{ position: 'absolute', inset: 0, userSelect: 'none', touchAction: 'none' }}
              >
                {/* Sombras nas margens cortadas */}
                <Box sx={{ position: 'absolute', top: 0, left: 0, right: 0, height: `${top}%`, bgcolor: 'rgba(0,0,0,0.6)' }} />
                <Box sx={{ position: 'absolute', bottom: 0, left: 0, right: 0, height: `${bottom}%`, bgcolor: 'rgba(0,0,0,0.6)' }} />
                <Box sx={{ position: 'absolute', top: `${top}%`, bottom: `${bottom}%`, left: 0, width: `${left}%`, bgcolor: 'rgba(0,0,0,0.6)' }} />
                <Box sx={{ position: 'absolute', top: `${top}%`, bottom: `${bottom}%`, right: 0, width: `${right}%`, bgcolor: 'rgba(0,0,0,0.6)' }} />

                {/* Borda da área selecionada */}
                <Box
                  sx={{
                    position: 'absolute',
                    top: `${top}%`, left: `${left}%`,
                    right: `${right}%`, bottom: `${bottom}%`,
                    border: '2px solid rgba(255,255,255,0.85)',
                    boxSizing: 'border-box',
                    pointerEvents: 'none'
                  }}
                />

                {/* Linhas de grade (regra dos terços) */}
                {[33, 66].map(pct => (
                  <React.Fragment key={pct}>
                    <Box sx={{
                      position: 'absolute',
                      top: `${top + (100 - top - bottom) * pct / 100}%`,
                      left: `${left}%`, right: `${right}%`,
                      height: '1px', bgcolor: 'rgba(255,255,255,0.2)',
                      pointerEvents: 'none'
                    }} />
                    <Box sx={{
                      position: 'absolute',
                      left: `${left + (100 - left - right) * pct / 100}%`,
                      top: `${top}%`, bottom: `${bottom}%`,
                      width: '1px', bgcolor: 'rgba(255,255,255,0.2)',
                      pointerEvents: 'none'
                    }} />
                  </React.Fragment>
                ))}

                {/* Alças de arrasto */}
                {['top', 'bottom', 'left', 'right'].map((edge) => (
                  <Box
                    key={edge}
                    onPointerDown={(e) => handleEdgePointerDown(e, edge)}
                    sx={handleStyle(edge)}
                  />
                ))}
              </Box>
            </>
          )}
        </Box>

        {/* Dica e valores */}
        <Box sx={{ px: 2, py: 1.5, bgcolor: 'rgba(25,118,210,0.1)', borderTop: '1px solid rgba(255,255,255,0.08)' }}>
          <Typography variant="caption" sx={{ color: '#90caf9', display: 'flex', alignItems: 'center', gap: 0.5, flexWrap: 'wrap' }}>
            <CropIcon sx={{ fontSize: 14 }} />
            Arraste as alças brancas para cortar margens (superior, inferior, esquerda, direita).
            {hasCrop && (
              <Box component="span" sx={{ ml: 1, color: '#ffcc02', fontWeight: 600 }}>
                Sup:{top.toFixed(0)}% Inf:{bottom.toFixed(0)}% Esq:{left.toFixed(0)}% Dir:{right.toFixed(0)}%
              </Box>
            )}
          </Typography>
        </Box>
      </DialogContent>

      <DialogActions sx={{ justifyContent: 'center', gap: 2, p: 2, backgroundColor: '#111' }}>
        <Button
          variant="outlined"
          onClick={onClose}
          sx={{ color: '#fff', borderColor: 'rgba(255,255,255,0.4)' }}
        >
          Cancelar
        </Button>
        {hasCrop && (
          <Button
            variant="outlined"
            onClick={() => setCropBounds({ top: 0, left: 0, right: 0, bottom: 0 })}
            sx={{ color: '#ff9800', borderColor: '#ff9800' }}
          >
            Limpar Recorte
          </Button>
        )}
        <Button
          variant="contained"
          startIcon={<CheckCircle />}
          onClick={handleSave}
          sx={{ backgroundColor: '#4caf50', '&:hover': { backgroundColor: '#388e3c' } }}
        >
          {hasCrop ? 'Salvar com Recorte' : 'Salvar Imagem'}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default ImageCropEditor;

import React, { useState, useEffect } from 'react';
import { Button, Box, Typography, Snackbar, Alert } from '@mui/material';
import GetAppIcon from '@mui/icons-material/GetApp';
import PhoneIphoneIcon from '@mui/icons-material/PhoneIphone';

export default function InstallPWA() {
  const [installable, setInstallable] = useState(false);
  const [deferredPrompt, setDeferredPrompt] = useState(null);
  const [showSuccess, setShowSuccess] = useState(false);

  useEffect(() => {
    const handler = (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
      setInstallable(true);
    };

    window.addEventListener('beforeinstallprompt', handler);

    // Verificar se já está instalado
    if (window.matchMedia('(display-mode: standalone)').matches) {
      setInstallable(false);
    }

    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  const handleInstallClick = async () => {
    if (!deferredPrompt) {
      return;
    }

    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;

    if (outcome === 'accepted') {
      setShowSuccess(true);
      setInstallable(false);
    }

    setDeferredPrompt(null);
  };

  if (!installable) {
    return null;
  }

  return (
    <>
      <Box 
        sx={{ 
          mt: 3, 
          p: 2, 
          borderRadius: 3,
          background: 'linear-gradient(135deg, rgba(102, 126, 234, 0.1) 0%, rgba(118, 75, 162, 0.1) 100%)',
          border: '2px dashed',
          borderColor: 'primary.main',
          textAlign: 'center'
        }}
      >
        <PhoneIphoneIcon sx={{ fontSize: 40, color: 'primary.main', mb: 1 }} />
        <Typography variant="body2" fontWeight="600" gutterBottom>
          Instale o CEI no seu dispositivo
        </Typography>
        <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 2 }}>
          Acesse rapidamente sem precisar abrir o navegador
        </Typography>
        <Button
          variant="contained"
          fullWidth
          startIcon={<GetAppIcon />}
          onClick={handleInstallClick}
          sx={{
            borderRadius: 2,
            py: 1,
            fontWeight: 'bold',
            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
            boxShadow: '0 4px 12px rgba(102, 126, 234, 0.3)',
            '&:hover': {
              transform: 'translateY(-2px)',
              boxShadow: '0 6px 16px rgba(102, 126, 234, 0.4)',
            }
          }}
        >
          Instalar Aplicativo
        </Button>
      </Box>

      <Snackbar
        open={showSuccess}
        autoHideDuration={4000}
        onClose={() => setShowSuccess(false)}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert 
          onClose={() => setShowSuccess(false)} 
          severity="success" 
          sx={{ width: '100%' }}
        >
          CEI instalado com sucesso! 🎉
        </Alert>
      </Snackbar>
    </>
  );
}

