import React, { useState, useRef, useEffect } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Box,
  Typography,
  Alert,
  CircularProgress,
  TextField,
  IconButton,
  Paper,
  Tab,
  Tabs
} from '@mui/material';
import { QrCodeScanner, PhotoCamera, Close, Search, Keyboard } from '@mui/icons-material';
import { buscarLivroPorISBN } from '../utils/isbnSearchService';
import { BrowserMultiFormatReader, NotFoundException } from '@zxing/library';

/**
 * Componente otimizado para leitura de códigos de barras e QR Code em dispositivos móveis
 * Suporta:
 * - Leitura por câmera (código de barras e QR Code)
 * - Entrada manual de ISBN
 * - Preenchimento automático de dados do livro
 */
export default function MobileBarcodeScanner({ open, onClose, onBookFound }) {
  const [tabIndex, setTabIndex] = useState(0);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [cameraActive, setCameraActive] = useState(false);
  const [isbn, setIsbn] = useState('');
  const [successMessage, setSuccessMessage] = useState('');
  const videoRef = useRef(null);
  const codeReaderRef = useRef(null);

  // Inicializar o leitor de código
  useEffect(() => {
    if (open && !codeReaderRef.current) {
      codeReaderRef.current = new BrowserMultiFormatReader();
    }

    return () => {
      stopCamera();
    };
  }, [open]);

  // Parar câmera ao trocar de aba
  useEffect(() => {
    if (tabIndex !== 0) {
      stopCamera();
    }
  }, [tabIndex]);

  const startCamera = async () => {
    try {
      setError('');
      setCameraActive(true);

      const constraints = {
        video: {
          facingMode: { ideal: 'environment' }, // Câmera traseira preferencial
          width: { ideal: 1920 },
          height: { ideal: 1080 },
          focusMode: { ideal: 'continuous' }, // Foco contínuo
          aspectRatio: { ideal: 1.7777777778 }, // 16:9
          zoom: { ideal: 1 }
        }
      };

      // Tentar com advanced constraints primeiro
      let stream;
      try {
        stream = await navigator.mediaDevices.getUserMedia(constraints);
      } catch (err) {
        // Fallback para constraints simples
        console.log('⚠️ Usando constraints simplificados');
        const simpleConstraints = {
          video: {
            facingMode: 'environment',
            width: { ideal: 1280 },
            height: { ideal: 720 }
          }
        };
        stream = await navigator.mediaDevices.getUserMedia(simpleConstraints);
      }

      
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        
        // Aplicar configurações avançadas de foco no track de vídeo
        const videoTrack = stream.getVideoTracks()[0];
        const capabilities = videoTrack.getCapabilities();
        
        console.log('📷 Capabilities da câmera:', capabilities);
        
        // Tentar habilitar autofocus se disponível
        if (capabilities.focusMode && capabilities.focusMode.includes('continuous')) {
          try {
            await videoTrack.applyConstraints({
              advanced: [{ focusMode: 'continuous' }]
            });
            console.log('✅ Autofocus contínuo ativado');
          } catch (e) {
            console.log('⚠️ Autofocus não suportado:', e.message);
          }
        }
        
        // Iniciar reprodução
        await videoRef.current.play();
        
        // Aguardar o vídeo estar pronto
        await new Promise(resolve => {
          videoRef.current.onloadedmetadata = resolve;
        });
        
        console.log('✅ Câmera iniciada, começando detecção...');
        
        // Iniciar detecção contínua
        detectCode();
      }
    } catch (err) {
      console.error('Erro ao iniciar câmera:', err);
      setError('Erro ao acessar câmera. Verifique as permissões.');
      setCameraActive(false);
    }
  };

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      const tracks = videoRef.current.srcObject.getTracks();
      tracks.forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    setCameraActive(false);
  };

  const detectCode = async () => {
    if (!videoRef.current || !codeReaderRef.current || !cameraActive) {
      console.log('❌ Detecção cancelada: câmera inativa');
      return;
    }

    try {
      // Usar decodeFromVideoElement para leitura contínua
      const result = await codeReaderRef.current.decodeFromVideoElement(videoRef.current);

      if (result) {
        const code = result.getText();
        console.log('📷 Código detectado:', code);
        
        // Validar se parece com ISBN
        const isbnLimpo = code.replace(/[^0-9X]/gi, '').toUpperCase();
        console.log('📋 ISBN limpo:', isbnLimpo, '(tamanho:', isbnLimpo.length, ')');
        
        if (isbnLimpo.length === 10 || isbnLimpo.length === 13) {
          console.log('✅ ISBN válido detectado!');
          setIsbn(isbnLimpo);
          stopCamera();
          
          // Buscar livro automaticamente
          await buscarLivro(isbnLimpo);
          return; // Não continuar o loop
        } else {
          console.log('⚠️ Código não é ISBN válido (tamanho incorreto)');
          setError('Código detectado não é um ISBN válido');
          // Limpar erro após 2 segundos e continuar tentando
          setTimeout(() => setError(''), 2000);
        }
      }
    } catch (err) {
      if (err instanceof NotFoundException) {
        // Nenhum código encontrado, isso é normal
        // console.log('🔍 Procurando código...');
      } else {
        console.error('❌ Erro na detecção:', err);
        // Não mostrar erro ao usuário para não atrapalhar
      }
    }
    
    // Continuar o loop se a câmera ainda estiver ativa
    if (cameraActive) {
      setTimeout(detectCode, 300); // Tentar a cada 300ms
    }
  };

  const buscarLivro = async (isbnParam) => {
    const isbnBusca = isbnParam || isbn;
    const isbnLimpo = isbnBusca.replace(/[^0-9X]/gi, '').toUpperCase();

    if (!isbnLimpo || (isbnLimpo.length !== 10 && isbnLimpo.length !== 13)) {
      setError('ISBN inválido! Deve ter 10 ou 13 dígitos.');
      return;
    }

    setLoading(true);
    setError('');
    setSuccessMessage('');

    try {
      const resultado = await buscarLivroPorISBN(isbnLimpo);

      if (resultado.sucesso) {
        setSuccessMessage(`Livro encontrado: ${resultado.dados.titulo}`);
        
        // Enviar dados para o componente pai
        onBookFound(resultado.dados);
        
        // Fechar após 1.5 segundos
        setTimeout(() => {
          handleClose();
        }, 1500);
      } else {
        setError('Livro não encontrado. Digite os dados manualmente.');
        
        // Enviar ISBN mesmo sem dados
        onBookFound({ isbn: isbnLimpo });
        
        setTimeout(() => {
          handleClose();
        }, 2000);
      }
    } catch (err) {
      console.error('Erro ao buscar livro:', err);
      setError('Erro ao buscar livro. Tente novamente.');
    } finally {
      setLoading(false);
    }
  };

  const handleManualSearch = () => {
    if (isbn.trim()) {
      buscarLivro(isbn);
    } else {
      setError('Digite um ISBN válido');
    }
  };

  const handleClose = () => {
    stopCamera();
    setError('');
    setIsbn('');
    setSuccessMessage('');
    setTabIndex(0);
    onClose();
  };

  return (
    <Dialog 
      open={open} 
      onClose={handleClose} 
      maxWidth="sm" 
      fullWidth
      fullScreen={window.innerWidth < 600}
    >
      <DialogTitle>
        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <QrCodeScanner />
            <Typography variant="h6" component="span">Escanear Código</Typography>
          </Box>
          <IconButton onClick={handleClose} size="small">
            <Close />
          </IconButton>
        </Box>
      </DialogTitle>

      <Tabs
        value={tabIndex}
        onChange={(e, newValue) => setTabIndex(newValue)}
        variant="fullWidth"
        sx={{ borderBottom: 1, borderColor: 'divider' }}
      >
        <Tab icon={<PhotoCamera />} label="Câmera" />
        <Tab icon={<Keyboard />} label="Digitar ISBN" />
      </Tabs>

      <DialogContent>
        {/* Aba da Câmera */}
        {tabIndex === 0 && (
          <Box>
            <Alert severity="info" sx={{ mb: 2 }}>
              <Typography variant="body2">
                <strong>📷 Use a câmera do celular</strong><br />
                Aponte para o código de barras ou QR Code do livro
              </Typography>
            </Alert>

            {!cameraActive ? (
              <Box sx={{ textAlign: 'center', py: 4 }}>
                <Button
                  variant="contained"
                  size="large"
                  startIcon={<PhotoCamera />}
                  onClick={startCamera}
                  fullWidth
                  sx={{ py: 2 }}
                >
                  Ativar Câmera
                </Button>
              </Box>
            ) : (
              <Paper
                elevation={3}
                sx={{
                  position: 'relative',
                  width: '100%',
                  paddingTop: '75%', // Aspect ratio 4:3
                  overflow: 'hidden',
                  borderRadius: 2
                }}
              >
                <video
                  ref={videoRef}
                  style={{
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    width: '100%',
                    height: '100%',
                    objectFit: 'cover'
                  }}
                  playsInline
                  muted
                />
                
                {/* Overlay de guia */}
                <Box
                  sx={{
                    position: 'absolute',
                    top: '50%',
                    left: '50%',
                    transform: 'translate(-50%, -50%)',
                    width: '80%',
                    height: '40%',
                    border: '3px solid #4caf50',
                    borderRadius: 2,
                    boxShadow: '0 0 0 9999px rgba(0, 0, 0, 0.5)',
                    pointerEvents: 'none'
                  }}
                />

                <Button
                  variant="contained"
                  color="error"
                  size="small"
                  onClick={stopCamera}
                  sx={{
                    position: 'absolute',
                    bottom: 16,
                    right: 16
                  }}
                >
                  Parar
                </Button>
              </Paper>
            )}
          </Box>
        )}

        {/* Aba de Entrada Manual */}
        {tabIndex === 1 && (
          <Box sx={{ mt: 2 }}>
            <Alert severity="info" sx={{ mb: 2 }}>
              <Typography variant="body2">
                <strong>⌨️ Digite o ISBN</strong><br />
                Digite o código ISBN de 10 ou 13 dígitos
              </Typography>
            </Alert>

            <TextField
              fullWidth
              label="ISBN"
              value={isbn}
              onChange={(e) => setIsbn(e.target.value)}
              placeholder="Ex: 9788535928181"
              variant="outlined"
              autoFocus
              sx={{ mb: 2 }}
              onKeyPress={(e) => {
                if (e.key === 'Enter') {
                  handleManualSearch();
                }
              }}
            />

            <Button
              variant="contained"
              fullWidth
              size="large"
              startIcon={<Search />}
              onClick={handleManualSearch}
              disabled={!isbn.trim() || loading}
              sx={{ py: 1.5 }}
            >
              Buscar Livro
            </Button>
          </Box>
        )}

        {/* Mensagens de status */}
        {loading && (
          <Box sx={{ textAlign: 'center', mt: 3 }}>
            <CircularProgress size={40} />
            <Typography variant="body2" color="text.secondary" sx={{ mt: 2 }}>
              Buscando informações do livro...
            </Typography>
          </Box>
        )}

        {error && (
          <Alert severity="error" sx={{ mt: 2 }}>
            {error}
          </Alert>
        )}

        {successMessage && (
          <Alert severity="success" sx={{ mt: 2 }}>
            {successMessage}
          </Alert>
        )}

        {isbn && !loading && !error && !successMessage && (
          <Alert severity="info" sx={{ mt: 2 }}>
            ISBN: <strong>{isbn}</strong>
          </Alert>
        )}
      </DialogContent>

      <DialogActions>
        <Button onClick={handleClose} color="inherit">
          Fechar
        </Button>
      </DialogActions>
    </Dialog>
  );
}

import React, { useEffect } from 'react';
import { Navigate, useLocation } from 'react-router-dom';
import { useLicense } from '../context/LicenseContext';
import { Box, CircularProgress, Typography, Container, Paper } from '@mui/material';
import SecurityIcon from '@mui/icons-material/Security';

/**
 * Componente para proteger rotas que requerem licença ativa
 */
export default function ProtectedRoute({ children }) {
  const { isAuthorized, isLoading, error, checkAuthorization } = useLicense();
  const location = useLocation();

  // Log detalhado para debug
  console.log('🔐 ProtectedRoute (Licença) - Verificando:', {
    pathname: location.pathname,
    isLoading,
    isAuthorized,
    error
  });

  useEffect(() => {
    // Verificar autorização ao entrar na rota
    if (!isAuthorized && !isLoading) {
      console.log('🔄 Verificando autorização de licença...');
      checkAuthorization();
    }
  }, [location.pathname]);

  // Enquanto está carregando
  if (isLoading) {
    return (
      <Box
        sx={{
          minHeight: '100vh',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)'
        }}
      >
        <Container maxWidth="sm">
          <Paper elevation={24} sx={{ p: 5, textAlign: 'center', borderRadius: 4 }}>
            <SecurityIcon sx={{ fontSize: 60, color: 'primary.main', mb: 2 }} />
            <Typography variant="h5" gutterBottom>
              Verificando Licença...
            </Typography>
            <CircularProgress sx={{ mt: 2 }} />
            <Typography variant="body2" color="text.secondary" sx={{ mt: 2 }}>
              Aguarde enquanto validamos seu acesso
            </Typography>
          </Paper>
        </Container>
      </Box>
    );
  }

  // Se não está autorizado, redirecionar para ativação
  if (!isAuthorized) {
    console.log('❌ Licença não autorizada, redirecionando para /ativar-licenca');
    return <Navigate to="/ativar-licenca" state={{ from: location }} replace />;
  }

  // Se está autorizado, mostrar conteúdo
  console.log('✅ Licença autorizada, mostrando conteúdo');
  return <>{children}</>;
}

import React, { useEffect, useMemo, useState } from 'react';
import {
  Alert,
  AppBar,
  Box,
  Button,
  Chip,
  CircularProgress,
  Dialog,
  Divider,
  IconButton,
  List,
  ListItemButton,
  ListItemText,
  MenuItem,
  Stack,
  TextField,
  Toolbar,
  Tooltip,
  Typography,
} from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';
import DownloadIcon from '@mui/icons-material/Download';
import SearchIcon from '@mui/icons-material/Search';

const ALL_AREAS = 'Todas as áreas';

function formatBytes(bytes) {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / 1024 / 1024).toFixed(2)} MB`;
}

function downloadBlob(content, fileName, type) {
  const url = URL.createObjectURL(new Blob([content], { type }));
  const link = document.createElement('a');
  link.href = url;
  link.download = fileName;
  link.click();
  URL.revokeObjectURL(url);
}

export default function SourceCodeExplorer({ open, onClose }) {
  const [catalog, setCatalog] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [query, setQuery] = useState('');
  const [area, setArea] = useState(ALL_AREAS);
  const [selectedPath, setSelectedPath] = useState('');
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    if (!open) return;

    setCatalog(null);
    setError('');
    setLoading(true);
    const cacheBust = Date.now();
    fetch(`${process.env.PUBLIC_URL || ''}/source-catalog.json?v=${cacheBust}`, { cache: 'no-store' })
      .then((response) => {
        if (!response.ok) throw new Error('Catálogo de fontes não encontrado. Execute novamente o build do sistema.');
        return response.json();
      })
      .then((data) => {
        setCatalog(data);
        setSelectedPath(data.files?.[0]?.path || '');
      })
      .catch((fetchError) => setError(fetchError.message))
      .finally(() => setLoading(false));
  }, [open]);

  const areas = useMemo(
    () => [ALL_AREAS, ...new Set((catalog?.files || []).map((file) => file.area))],
    [catalog]
  );

  const filteredFiles = useMemo(() => {
    const normalizedQuery = query.trim().toLocaleLowerCase('pt-BR');
    return (catalog?.files || []).filter((file) => {
      const matchesArea = area === ALL_AREAS || file.area === area;
      const matchesQuery = !normalizedQuery ||
        file.path.toLocaleLowerCase('pt-BR').includes(normalizedQuery) ||
        file.content.toLocaleLowerCase('pt-BR').includes(normalizedQuery);
      return matchesArea && matchesQuery;
    });
  }, [area, catalog, query]);

  const selectedFile = filteredFiles.find((file) => file.path === selectedPath) || filteredFiles[0];

  const handleCopy = async () => {
    if (!selectedFile) return;
    await navigator.clipboard.writeText(selectedFile.content);
    setCopied(true);
    window.setTimeout(() => setCopied(false), 1800);
  };

  const handleDownloadCatalog = () => {
    if (!catalog) return;
    downloadBlob(JSON.stringify(catalog, null, 2), 'codigo-fonte-cei.json', 'application/json');
  };

  return (
    <Dialog fullScreen open={open} onClose={onClose}>
      <AppBar position="static" color="primary">
        <Toolbar sx={{ gap: 1 }}>
          <Tooltip title="Fechar códigos-fonte">
            <IconButton edge="start" color="inherit" onClick={onClose} aria-label="Fechar">
              <CloseIcon />
            </IconButton>
          </Tooltip>
          <Typography variant="h6" sx={{ flexGrow: 1 }}>
            Códigos-fonte do Sistema CEI
          </Typography>
          <Tooltip title="Baixar catálogo completo em JSON">
            <span>
              <IconButton color="inherit" onClick={handleDownloadCatalog} disabled={!catalog} aria-label="Baixar catálogo">
                <DownloadIcon />
              </IconButton>
            </span>
          </Tooltip>
        </Toolbar>
      </AppBar>

      {loading && (
        <Box sx={{ flex: 1, display: 'grid', placeItems: 'center' }}>
          <Stack alignItems="center" spacing={2}>
            <CircularProgress />
            <Typography>Carregando códigos-fonte...</Typography>
          </Stack>
        </Box>
      )}

      {error && <Alert severity="error" sx={{ m: 2 }}>{error}</Alert>}

      {catalog && (
        <Box sx={{ display: 'flex', flex: 1, minHeight: 0, flexDirection: { xs: 'column', md: 'row' } }}>
          <Box sx={{ width: { xs: '100%', md: 350 }, maxHeight: { xs: '38vh', md: 'none' }, display: 'flex', flexDirection: 'column', borderRight: { md: 1 }, borderBottom: { xs: 1, md: 0 }, borderColor: 'divider' }}>
            <Box sx={{ p: 2 }}>
              <Stack direction="row" spacing={1} sx={{ mb: 2, flexWrap: 'wrap', gap: 1 }}>
                <Chip label={`${catalog.totalFiles} arquivos`} size="small" color="primary" />
                <Chip label={`${catalog.totalLines.toLocaleString('pt-BR')} linhas`} size="small" />
                <Chip label={formatBytes(catalog.totalBytes)} size="small" />
              </Stack>
              <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1.5 }}>
                Atualizado em {new Date(catalog.generatedAt).toLocaleString('pt-BR')}
              </Typography>
              <TextField
                fullWidth
                size="small"
                label="Buscar arquivo ou conteúdo"
                value={query}
                onChange={(event) => setQuery(event.target.value)}
                InputProps={{ startAdornment: <SearchIcon fontSize="small" sx={{ mr: 1, color: 'text.secondary' }} /> }}
                sx={{ mb: 1.5 }}
              />
              <TextField select fullWidth size="small" label="Área" value={area} onChange={(event) => setArea(event.target.value)}>
                {areas.map((item) => <MenuItem key={item} value={item}>{item}</MenuItem>)}
              </TextField>
            </Box>
            <Divider />
            <List dense sx={{ overflow: 'auto', flex: 1, py: 0 }}>
              {filteredFiles.map((file) => (
                <ListItemButton key={file.path} selected={file.path === selectedFile?.path} onClick={() => setSelectedPath(file.path)}>
                  <ListItemText primary={file.path} secondary={`${file.lines} linhas · ${formatBytes(file.size)}`} primaryTypographyProps={{ fontFamily: 'monospace', fontSize: 12, noWrap: true }} />
                </ListItemButton>
              ))}
              {filteredFiles.length === 0 && <Typography color="text.secondary" sx={{ p: 2 }}>Nenhum código encontrado.</Typography>}
            </List>
          </Box>

          <Box sx={{ flex: 1, minWidth: 0, minHeight: 0, display: 'flex', flexDirection: 'column', bgcolor: '#101418' }}>
            {selectedFile ? (
              <>
                <Box sx={{ px: 2, py: 1.5, display: 'flex', alignItems: 'center', gap: 1, bgcolor: '#182028', color: '#fff' }}>
                  <Typography sx={{ flexGrow: 1, fontFamily: 'monospace', fontSize: 13, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                    {selectedFile.path}
                  </Typography>
                  <Button size="small" color="inherit" startIcon={<ContentCopyIcon />} onClick={handleCopy}>
                    {copied ? 'Copiado' : 'Copiar'}
                  </Button>
                  <Tooltip title="Baixar este arquivo">
                    <IconButton color="inherit" size="small" onClick={() => downloadBlob(selectedFile.content, selectedFile.path.split('/').pop(), 'text/plain')} aria-label="Baixar arquivo">
                      <DownloadIcon fontSize="small" />
                    </IconButton>
                  </Tooltip>
                </Box>
                <Box component="pre" sx={{ m: 0, p: 2.5, flex: 1, overflow: 'auto', color: '#d6deeb', fontFamily: 'Consolas, monospace', fontSize: 13, lineHeight: 1.55, whiteSpace: 'pre', tabSize: 2 }}>
                  {selectedFile.content}
                </Box>
              </>
            ) : (
              <Box sx={{ flex: 1, display: 'grid', placeItems: 'center', color: '#fff' }}>Selecione um arquivo.</Box>
            )}
          </Box>
        </Box>
      )}
    </Dialog>
  );
}

import React, { useState, useEffect } from 'react';
import { Box, Chip, Tooltip, CircularProgress, IconButton } from '@mui/material';
import CloudDoneIcon from '@mui/icons-material/CloudDone';
import CloudOffIcon from '@mui/icons-material/CloudOff';
import CloudQueueIcon from '@mui/icons-material/CloudQueue';
import CloudSyncIcon from '@mui/icons-material/CloudSync';
import SyncIcon from '@mui/icons-material/Sync';
import RefreshIcon from '@mui/icons-material/Refresh';
import { useOnlineStatus } from '../hooks/useOnlineStatus';
import { useData } from '../context/DataContext';
import { getSyncStatus } from '../services/syncService';
import { cloudConfigScope, isCloudEnabled } from '../services/supabaseClient';

export default function SyncStatus() {
  const isOnline = useOnlineStatus();
  const { sincronizarNuvemAgora } = useData();
  const [syncing, setSyncing] = useState(false);
  const [lastSync, setLastSync] = useState(null);
  const [cloudConnected, setCloudConnected] = useState(false);
  const [cloudErrorMsg, setCloudErrorMsg] = useState('');

  const getCloudScopeHint = () => {
    if (cloudConfigScope === 'browser-local') {
      return ' Credenciais da nuvem foram salvas apenas neste navegador.';
    }

    if (cloudConfigScope === 'shared') {
      return ' Configuracao compartilhada para todos os dispositivos desta implantacao.';
    }

    return ' Dados ficam apenas neste navegador/dispositivo.';
  };

  const updateLastSync = () => {
    const lastSyncDate = localStorage.getItem('cei_last_sync');
    setLastSync(lastSyncDate ? new Date(lastSyncDate) : null);
  };

  const updateCloudStatus = async () => {
    if (!isCloudEnabled) {
      setCloudConnected(false);
      return;
    }

    try {
      const status = await getSyncStatus();
      setCloudConnected(Boolean(status?.connected));
      setCloudErrorMsg(status?.connected ? '' : (status?.message || ''));
    } catch (error) {
      setCloudConnected(false);
      setCloudErrorMsg(error.message || '');
    }
  };

  useEffect(() => {
    updateLastSync();
    updateCloudStatus();

    // Escutar eventos de sincronização
    const handleSyncStart = () => setSyncing(true);
    const handleSyncEnd = () => {
      setSyncing(false);
      updateLastSync();
      updateCloudStatus();
    };

    const interval = setInterval(() => {
      updateLastSync();
      updateCloudStatus();
    }, 10000);

    window.addEventListener('sync-start', handleSyncStart);
    window.addEventListener('sync-end', handleSyncEnd);
    window.addEventListener('online', updateCloudStatus);

    return () => {
      clearInterval(interval);
      window.removeEventListener('sync-start', handleSyncStart);
      window.removeEventListener('sync-end', handleSyncEnd);
      window.removeEventListener('online', updateCloudStatus);
    };
  }, []);

  const getStatusInfo = () => {
    if (!isCloudEnabled) {
      return {
        icon: <CloudOffIcon />,
        label: 'Somente local',
        color: 'warning',
        tooltip: `Supabase nao configurado.${getCloudScopeHint()}`
      };
    }

    if (syncing) {
      return {
        icon: <SyncIcon sx={{ animation: 'spin 1s linear infinite', '@keyframes spin': { '0%': { transform: 'rotate(0deg)' }, '100%': { transform: 'rotate(360deg)' } } }} />,
        label: 'Sincronizando...',
        color: 'info',
        tooltip: 'Sincronizando dados da escola com a nuvem'
      };
    }

    if (!isOnline) {
      return {
        icon: <CloudOffIcon />,
        label: 'Offline',
        color: 'error',
        tooltip: 'Sem conexão - os dados serão sincronizados quando a conexão for restaurada'
      };
    }

    if (!cloudConnected) {
      return {
        icon: <CloudOffIcon />,
        label: 'Nuvem indisponível',
        color: 'error',
        tooltip: `Sem conexao com Supabase — projeto deletado ou pausado. ${cloudErrorMsg ? '(' + cloudErrorMsg + ')' : ''} Acesse supabase.com e verifique o projeto, depois atualize as credenciais em Configurações → Nuvem.${getCloudScopeHint()}`
      };
    }

    if (lastSync) {
      const diffMinutes = Math.floor((new Date() - lastSync) / 60000);
      if (diffMinutes < 1) {
        return {
          icon: <CloudDoneIcon />,
          label: 'Sync OK',
          color: 'success',
          tooltip: `Nuvem conectada • Ultima sincronizacao: ${lastSync.toLocaleString('pt-BR')}.${getCloudScopeHint()}`
        };
      } else if (diffMinutes < 60) {
        return {
          icon: <CloudSyncIcon />,
          label: `Sync há ${diffMinutes}min`,
          color: 'success',
          tooltip: `Nuvem conectada • Ultima sincronizacao: ${lastSync.toLocaleString('pt-BR')}.${getCloudScopeHint()}`
        };
      } else {
        return {
          icon: <CloudQueueIcon />,
          label: 'Sync atrasado',
          color: 'warning',
          tooltip: `Nuvem conectada • Ultima sincronizacao: ${lastSync.toLocaleString('pt-BR')}.${getCloudScopeHint()}`
        };
      }
    }

    return {
      icon: <CloudQueueIcon />,
      label: 'Aguardando',
      color: 'default',
      tooltip: `Nuvem conectada • aguardando primeira sincronizacao.${getCloudScopeHint()}`
    };
  };

  const status = getStatusInfo();

  const handleManualSync = async () => {
    if (syncing || !isCloudEnabled) return;

    try {
      await sincronizarNuvemAgora();
    } finally {
      updateCloudStatus();
      updateLastSync();
    }
  };

  return (
    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
      <Tooltip title={status.tooltip} arrow>
        <Chip
          icon={syncing ? <CircularProgress size={16} color="inherit" /> : status.icon}
          label={status.label}
          size="small"
          color={status.color}
          sx={{
            fontWeight: 500,
            cursor: 'help',
            transition: 'all 0.3s',
            '&:hover': {
              transform: 'scale(1.05)',
            }
          }}
        />
      </Tooltip>

      <Tooltip title={syncing ? 'Sincronizacao em andamento' : isCloudEnabled ? 'Sincronizar agora' : 'Ative a nuvem para sincronizar entre dispositivos'} arrow>
        <span>
          <IconButton
            size="small"
            color="inherit"
            onClick={handleManualSync}
            disabled={syncing || !isCloudEnabled}
            sx={{
              color: 'white',
              background: 'rgba(255, 255, 255, 0.12)',
              '&:hover': {
                background: 'rgba(255, 255, 255, 0.22)',
              },
              '&.Mui-disabled': {
                color: 'rgba(255, 255, 255, 0.45)'
              }
            }}
          >
            <RefreshIcon fontSize="small" />
          </IconButton>
        </span>
      </Tooltip>
    </Box>
  );
}

