              <li><Typography variant="body2">Obrigação de ressarcimento do valor integral do material;</Typography></li>
              <li><Typography variant="body2">Aplicação de multa correspondente a até 2 (duas) vezes o valor do material;</Typography></li>
              <li><Typography variant="body2">Responsabilização civil e criminal nos termos da legislação vigente;</Typography></li>
              <li><Typography variant="body2">Registro em sistema de inadimplentes da instituição.</Typography></li>
            </Box>

            <Typography variant="body2" sx={{ textAlign: 'justify', mb: 1, mt: 2 }}>
              <strong>6.2. VISTORIA:</strong> O material foi vistoriado e entregue em perfeito estado de conservação, 
              conforme verificado pelo comodatário no momento da retirada.
            </Typography>

            <Typography variant="body2" sx={{ textAlign: 'justify', mb: 1 }}>
              <strong>6.3. FORO:</strong> Fica eleito o foro da comarca da instituição para dirimir quaisquer questões 
              decorrentes deste termo de empréstimo.
            </Typography>
          </Box>

          {/* DECLARAÇÃO DE CIÊNCIA */}
          <Box sx={{ mt: 3, p: 2, bgcolor: '#e3f2fd', border: '2px solid #1976d2' }}>
            <Typography variant="body1" sx={{ textAlign: 'justify', fontWeight: 'bold' }}>
              DECLARAÇÃO DE CIÊNCIA E CONCORDÂNCIA
            </Typography>
            <Typography variant="body2" sx={{ textAlign: 'justify', mt: 1 }}>
              Declaro que recebi o material descrito neste termo em perfeito estado de conservação, 
              estou ciente de todas as obrigações e responsabilidades aqui estabelecidas, bem como das 
              penalidades previstas na legislação brasileira para dano, perda ou má conservação de 
              patrimônio público. Comprometo-me a devolver o material na data estipulada e nas mesmas 
              condições em que foi recebido.
            </Typography>
          </Box>

          {/* ASSINATURAS */}
          <Box className="assinaturas">
            <Typography variant="body2" sx={{ textAlign: 'center', mb: 5 }}>
              {tipo === 'branco' ? '__________________, ____ de _____________ de ________.' : 
               `${dados?.instituicaoCidade || '________________'}, ${dataAtual}`}
            </Typography>

            <Box sx={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 4, mt: 6 }}>
              <Box>
                <Box className="assinatura-campo" sx={{ textAlign: 'center' }}>
                  <Typography variant="body2" sx={{ fontWeight: 'bold' }}>
                    {tipo === 'branco' ? '' : dados?.leitorNome}
                  </Typography>
                  <Typography variant="body2" className="assinatura-info">
                    Comodatário (Leitor)
                  </Typography>
                  <Typography variant="body2" className="assinatura-info">
                    CPF: {tipo === 'branco' ? '___________________' : dados?.leitorCPF}
                  </Typography>
                </Box>
              </Box>

              <Box>
                <Box className="assinatura-campo" sx={{ textAlign: 'center' }}>
                  <Typography variant="body2" sx={{ fontWeight: 'bold' }}>
                    {tipo === 'branco' ? '' : dados?.responsavelNome || ''}
                  </Typography>
                  <Typography variant="body2" className="assinatura-info">
                    Responsável pela Instituição
                  </Typography>
                  <Typography variant="body2" className="assinatura-info">
                    Cargo: {tipo === 'branco' ? '___________________' : dados?.responsavelCargo || 'Bibliotecário(a)'}
                  </Typography>
                </Box>
              </Box>
            </Box>

            {/* Se for menor de idade, adicionar campo para responsável legal */}
            {tipo !== 'branco' && dados?.leitorMenorIdade && (
              <Box sx={{ mt: 6 }}>
                <Typography variant="body2" sx={{ fontWeight: 'bold', mb: 2, color: '#d32f2f' }}>
                  * Por ser menor de idade, é necessária a assinatura do responsável legal:
                </Typography>
                <Box className="assinatura-campo" sx={{ maxWidth: '400px', mx: 'auto', textAlign: 'center' }}>
                  <Typography variant="body2" sx={{ fontWeight: 'bold' }}>
                    {dados?.responsavelLegalNome || ''}
                  </Typography>
                  <Typography variant="body2" className="assinatura-info">
                    Responsável Legal
                  </Typography>
                  <Typography variant="body2" className="assinatura-info">
                    CPF: {dados?.responsavelLegalCPF || '___________________'}
                  </Typography>
                </Box>
              </Box>
            )}
          </Box>

          {/* RODAPÉ */}
          <Box className="rodape">
            <Typography variant="caption">
              Este documento foi gerado eletronicamente pelo Sistema CEI - Controle Escolar Inteligente
            </Typography>
            <Typography variant="caption" display="block">
              {tipo === 'branco' ? 'Modelo de Termo de Empréstimo' : `Termo: ${dados?.codigoEmprestimo || 'N/A'}`} | 
              Data de emissão: {new Date().toLocaleDateString('pt-BR')} às {new Date().toLocaleTimeString('pt-BR')}
            </Typography>
            <Typography variant="caption" display="block" sx={{ mt: 1, fontWeight: 'bold' }}>
              ⚠️ ATENÇÃO: Este termo tem validade jurídica e deve ser arquivado pela instituição conforme 
              Lei de Arquivos (Lei 8.159/91) pelo prazo mínimo de 5 (cinco) anos.
            </Typography>
          </Box>
        </Box>
      </DialogContent>

      <DialogActions>
        <Button onClick={onClose} startIcon={<Close />}>
          Fechar
        </Button>
        <Button
          variant="contained"
          onClick={handleImprimir}
          startIcon={<Print />}
          color="primary"
        >
          Imprimir Termo
        </Button>
      </DialogActions>
        {typeof onNext === 'function' && (
          <Button
            onClick={onNext}
            variant="outlined"
            color="primary"
          >
            {nextLabel}
          </Button>
        )}
    </Dialog>
  );
}

export default TermoEmprestimo;

import React, { useState, useEffect } from 'react';
import { Alert, Snackbar, Button, Box, Typography } from '@mui/material';
import SystemUpdateIcon from '@mui/icons-material/SystemUpdate';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import { getBackupInfo } from '../utils/dataProtection';

/**
 * 🔄 Componente de Notificação de Atualização
 * 
 * Exibe notificações quando o sistema é atualizado
 * Garante que o usuário saiba que seus dados foram preservados
 */
export default function UpdateNotification() {
  const [updateAvailable, setUpdateAvailable] = useState(false);
  const [updateInstalled, setUpdateInstalled] = useState(false);
  const [backupInfo, setBackupInfo] = useState(null);

  useEffect(() => {
    // Escutar mensagens do Service Worker
    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.addEventListener('message', (event) => {
        if (event.data && event.data.type === 'SW_UPDATED') {
          console.log('🎉 [UPDATE] Atualização detectada:', event.data.version);
          setUpdateInstalled(true);
          
          // Buscar informações de backup
          const info = getBackupInfo();
          setBackupInfo(info);
          
          // Ocultar notificação após 8 segundos
          setTimeout(() => {
            setUpdateInstalled(false);
          }, 8000);
        }
      });

      // Verificar se há atualização aguardando
      navigator.serviceWorker.ready.then((registration) => {
        if (registration.waiting) {
          setUpdateAvailable(true);
        }

        registration.addEventListener('updatefound', () => {
          const newWorker = registration.installing;
          newWorker.addEventListener('statechange', () => {
            if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
              setUpdateAvailable(true);
            }
          });
        });
      });
    }
  }, []);

  const handleUpdate = () => {
    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.ready.then((registration) => {
        if (registration.waiting) {
          registration.waiting.postMessage({ type: 'SKIP_WAITING' });
        }
      });
    }
    setUpdateAvailable(false);
    window.location.reload();
  };

  const handleClose = () => {
    setUpdateInstalled(false);
  };

  return (
    <>
      {/* Notificação de atualização disponível */}
      <Snackbar
        open={updateAvailable}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert
          severity="info"
          icon={<SystemUpdateIcon />}
          action={
            <Button color="inherit" size="small" onClick={handleUpdate}>
              Atualizar
            </Button>
          }
          sx={{ minWidth: 400 }}
        >
          <Typography variant="subtitle2" fontWeight="bold">
            Nova versão disponível!
          </Typography>
          <Typography variant="body2">
            Clique em "Atualizar" para obter as últimas melhorias.
            <br />
            <strong>Seus dados serão preservados automaticamente.</strong>
          </Typography>
        </Alert>
      </Snackbar>

      {/* Notificação de atualização instalada com sucesso */}
      <Snackbar
        open={updateInstalled}
        autoHideDuration={8000}
        onClose={handleClose}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert
          severity="success"
          icon={<CheckCircleIcon />}
          onClose={handleClose}
          sx={{ minWidth: 400 }}
        >
          <Typography variant="subtitle2" fontWeight="bold">
            ✅ Sistema atualizado com sucesso!
          </Typography>
          <Typography variant="body2">
            A nova versão foi instalada e seus dados foram preservados.
          </Typography>
          {backupInfo && backupInfo.exists && (
            <Box sx={{ mt: 1, p: 1, bgcolor: 'success.light', borderRadius: 1 }}>
              <Typography variant="caption" display="block">
                🛡️ Backup de segurança criado
              </Typography>
              <Typography variant="caption" display="block">
                📅 Última atualização: {new Date(backupInfo.timestamp).toLocaleString('pt-BR')}
              </Typography>
            </Box>
          )}
        </Alert>
      </Snackbar>
    </>
  );
}

import React, { createContext, useState, useContext, useEffect } from 'react';

const DataContext = createContext();

export const useData = () => {
  const context = useContext(DataContext);
  if (!context) {
    throw new Error('useData must be used within a DataProvider');
  }
  return context;
};

export const DataProvider = ({ children }) => {
  // Usuários padrão
  const usuariosPadrao = [
    {
      id: 1,
      nome: 'Administrador',
      login: 'admin',
      senha: '[VALOR_CONFIDENCIAL_REMOVIDO]',
      perfil: 'AdminSistema'
    },
    {
      id: 2,
      nome: 'Biblioteca',
      login: 'biblioteca',
      senha: '[VALOR_CONFIDENCIAL_REMOVIDO]',
      perfil: 'AdminEscola'
    }
  ];

  // Estados
  const [livros, setLivros] = useState([]);
  const [patrimonio, setPatrimonio] = useState([]);
  const [clientes, setClientes] = useState([]);
  const [emprestimos, setEmprestimos] = useState([]);
  const [usuarios, setUsuarios] = useState(usuariosPadrao);
  const [usuarioLogado, setUsuarioLogado] = useState(null);

  // Carregar dados do localStorage ao iniciar
  useEffect(() => {
    const dadosSalvos = localStorage.getItem('cei_data');
    if (dadosSalvos) {
      const dados = JSON.parse(dadosSalvos);
      setLivros(dados.livros || []);
      setPatrimonio(dados.patrimonio || []);
      setClientes(dados.clientes || []);
      setEmprestimos(dados.emprestimos || []);
      // Sempre manter usuários padrão se não houver usuários salvos
      if (dados.usuarios && dados.usuarios.length > 0) {
        setUsuarios(dados.usuarios);
      }
    }
  }, []);

  // Salvar dados no localStorage sempre que houver mudança
  useEffect(() => {
    const dados = {
      livros,
      patrimonio,
      clientes,
      emprestimos,
      usuarios
    };
    localStorage.setItem('cei_data', JSON.stringify(dados));
  }, [livros, patrimonio, clientes, emprestimos, usuarios]);

  // Funções CRUD para Livros
  const adicionarLivro = (livro) => {
    const novoLivro = {
      ...livro,
      id: livros.length > 0 ? Math.max(...livros.map(l => l.id)) + 1 : 1,
      dataCadastro: new Date().toISOString()
    };
    setLivros([...livros, novoLivro]);
    return novoLivro;
  };

  const atualizarLivro = (id, dadosAtualizados) => {
    setLivros(livros.map(l => l.id === id ? { ...l, ...dadosAtualizados } : l));
  };

  const removerLivro = (id) => {
    setLivros(livros.filter(l => l.id !== id));
  };

  // Funções CRUD para Patrimônio
  const adicionarPatrimonio = (bem) => {
    const novoBem = {
      ...bem,
      id: patrimonio.length > 0 ? Math.max(...patrimonio.map(p => p.id)) + 1 : 1,
      dataCadastro: new Date().toISOString()
    };
    setPatrimonio([...patrimonio, novoBem]);
    return novoBem;
  };

  const atualizarPatrimonio = (id, dadosAtualizados) => {
    setPatrimonio(patrimonio.map(p => p.id === id ? { ...p, ...dadosAtualizados } : p));
  };

  const removerPatrimonio = (id) => {
    setPatrimonio(patrimonio.filter(p => p.id !== id));
  };

  // Funções CRUD para Clientes
  const adicionarCliente = (cliente) => {
    const novoCliente = {
      ...cliente,
      id: clientes.length > 0 ? Math.max(...clientes.map(c => c.id)) + 1 : 1,
      dataCadastro: new Date().toISOString()
    };
    setClientes([...clientes, novoCliente]);
    return novoCliente;
  };

  const atualizarCliente = (id, dadosAtualizados) => {
    setClientes(clientes.map(c => c.id === id ? { ...c, ...dadosAtualizados } : c));
  };

  const removerCliente = (id) => {
    setClientes(clientes.filter(c => c.id !== id));
  };

  // Funções para Empréstimos
  const adicionarEmprestimo = (emprestimoData) => {
    const novoEmprestimo = {
      ...emprestimoData,
      id: emprestimos.length > 0 ? Math.max(...emprestimos.map(e => e.id)) + 1 : 1,
      dataEmprestimo: emprestimoData.dataEmprestimo || new Date().toISOString()
    };
    setEmprestimos([...emprestimos, novoEmprestimo]);
    return novoEmprestimo;
  };

  const atualizarEmprestimo = (id, dadosAtualizados) => {
    setEmprestimos(emprestimos.map(e => e.id === id ? { ...e, ...dadosAtualizados } : e));
  };

  const realizarEmprestimo = (emprestimoData) => {
    return adicionarEmprestimo(emprestimoData);
  };

  const devolverLivro = (emprestimoId) => {
    const emprestimo = emprestimos.find(e => e.id === emprestimoId);
    if (emprestimo) {
      atualizarEmprestimo(emprestimoId, {
        dataDevolucao: new Date().toISOString(),
        dataDevolucaoReal: new Date().toISOString(),
        status: 'devolvido'
      });
    }
  };

  // Função de Login
  const login = (loginData, senha) => {
    console.log('Tentando login:', loginData, senha);
    console.log('Usuários disponíveis:', usuarios);
    const usuario = usuarios.find(u => u.login === loginData && u.senha === senha);
    if (usuario) {
      console.log('Usuário encontrado:', usuario);
      setUsuarioLogado(usuario);
      return true;
    }
    console.log('Usuário não encontrado');
    return false;
  };

  const logout = () => {
    setUsuarioLogado(null);
  };

  // Busca unificada
  const buscar = (termo) => {
    const termoLower = termo.toLowerCase();
    
    const livrosEncontrados = livros.filter(l => 
      l.titulo?.toLowerCase().includes(termoLower) ||
      l.autor?.toLowerCase().includes(termoLower) ||
      l.isbn?.includes(termo)
    );
    
    const patrimonioEncontrado = patrimonio.filter(p => 
      p.nome?.toLowerCase().includes(termoLower) ||
      p.tombamento?.includes(termo) ||
      p.localizacao?.toLowerCase().includes(termoLower)
    );
    
    const clientesEncontrados = clientes.filter(c => 
      c.nome?.toLowerCase().includes(termoLower) ||
      c.matricula?.includes(termo)
    );
    
    return {
      livros: livrosEncontrados,
      patrimonio: patrimonioEncontrado,
      clientes: clientesEncontrados
    };
  };

  const value = {
    // Estados
    livros,
    patrimonio,
    clientes,
    emprestimos,
    usuarioLogado,
    
    // Funções Livros
    adicionarLivro,
    atualizarLivro,
    removerLivro,
    
    // Funções Patrimônio
    adicionarPatrimonio,
    atualizarPatrimonio,
    removerPatrimonio,
    
    // Funções Clientes
    adicionarCliente,
    atualizarCliente,
    removerCliente,
    
    // Funções Empréstimos
    adicionarEmprestimo,
    atualizarEmprestimo,
    realizarEmprestimo,
    devolverLivro,
    
    // Autenticação
    login,
    logout,
    
    // Busca
    buscar
  };

  return <DataContext.Provider value={value}>{children}</DataContext.Provider>;
};

