export default function CadastroEscolaPage() {
  const { getPlanosAtivos } = useData();
  const navigate = useNavigate();
  const [etapa, setEtapa] = useState(0);
  const [erro, setErro] = useState('');
  const [mostrarContrato, setMostrarContrato] = useState(false);
  const [contratoAceito, setContratoAceito] = useState(null);
  const [formData, setFormData] = useState({
    // Dados da Instituição
    nomeInstituicao: '',
    cnpj: '',
    inep: '',
    telefone: '',
    email: '',
    endereco: '',
    cidade: '',
    estado: '',
    cep: '',
    planoId: '',
    
    // Dados do Responsável
    nomeResponsavel: '',
    cpfResponsavel: '',
    telefoneResponsavel: '',
    emailResponsavel: '',
    cargoResponsavel: '',
    
    // Dados de Acesso
    loginAdmin: '',
    senhaAdmin: '',
    confirmarSenha: ''
  });

  const planosDisponiveis = getPlanosAtivos();
  const etapas = ['Dados da Instituição', 'Responsável', 'Criar Acesso'];

  // Funções de máscara
  const aplicarMascaraCPF = (valor) => {
    valor = valor.replace(/\D/g, '');
    if (valor.length <= 11) {
      valor = valor.replace(/(\d{3})(\d)/, '$1.$2');
      valor = valor.replace(/(\d{3})(\d)/, '$1.$2');
      valor = valor.replace(/(\d{3})(\d{1,2})$/, '$1-$2');
    }
    return valor;
  };

  const aplicarMascaraCNPJ = (valor) => {
    valor = valor.replace(/\D/g, '');
    if (valor.length <= 14) {
      valor = valor.replace(/^(\d{2})(\d)/, '$1.$2');
      valor = valor.replace(/^(\d{2})\.(\d{3})(\d)/, '$1.$2.$3');
      valor = valor.replace(/\.(\d{3})(\d)/, '.$1/$2');
      valor = valor.replace(/(\d{4})(\d)/, '$1-$2');
    }
    return valor;
  };

  const aplicarMascaraCelular = (valor) => {
    valor = valor.replace(/\D/g, '');
    if (valor.length <= 11) {
      valor = valor.replace(/^(\d{2})(\d)/, '($1) $2');
      valor = valor.replace(/(\d{5})(\d)/, '$1-$2');
    }
    return valor;
  };

  const aplicarMascaraTelefone = (valor) => {
    valor = valor.replace(/\D/g, '');
    if (valor.length <= 10) {
      valor = valor.replace(/^(\d{2})(\d)/, '($1) $2');
      valor = valor.replace(/(\d{4})(\d)/, '$1-$2');
    } else {
      return aplicarMascaraCelular(valor);
    }
    return valor;
  };

  const aplicarMascaraCEP = (valor) => {
    valor = valor.replace(/\D/g, '');
    if (valor.length <= 8) {
      valor = valor.replace(/^(\d{5})(\d)/, '$1-$2');
    }
    return valor;
  };

  const validarCPF = (cpf) => {
    cpf = cpf.replace(/\D/g, '');
    if (cpf.length !== 11) return false;
    if (/^(\d)\1+$/.test(cpf)) return false;
    
    let soma = 0;
    for (let i = 0; i < 9; i++) {
      soma += parseInt(cpf.charAt(i)) * (10 - i);
    }
    let resto = 11 - (soma % 11);
    let digito1 = resto > 9 ? 0 : resto;
    
    soma = 0;
    for (let i = 0; i < 10; i++) {
      soma += parseInt(cpf.charAt(i)) * (11 - i);
    }
    resto = 11 - (soma % 11);
    let digito2 = resto > 9 ? 0 : resto;
    
    return digito1 === parseInt(cpf.charAt(9)) && digito2 === parseInt(cpf.charAt(10));
  };

  const validarCNPJ = (cnpj) => {
    cnpj = cnpj.replace(/\D/g, '');
    if (cnpj.length !== 14) return false;
    if (/^(\d)\1+$/.test(cnpj)) return false;
    
    let tamanho = cnpj.length - 2;
    let numeros = cnpj.substring(0, tamanho);
    let digitos = cnpj.substring(tamanho);
    let soma = 0;
    let pos = tamanho - 7;
    
    for (let i = tamanho; i >= 1; i--) {
      soma += numeros.charAt(tamanho - i) * pos--;
      if (pos < 2) pos = 9;
    }
    
    let resultado = soma % 11 < 2 ? 0 : 11 - (soma % 11);
    if (resultado != digitos.charAt(0)) return false;
    
    tamanho = tamanho + 1;
    numeros = cnpj.substring(0, tamanho);
    soma = 0;
    pos = tamanho - 7;
    
    for (let i = tamanho; i >= 1; i--) {
      soma += numeros.charAt(tamanho - i) * pos--;
      if (pos < 2) pos = 9;
    }
    
    resultado = soma % 11 < 2 ? 0 : 11 - (soma % 11);
    return resultado == digitos.charAt(1);
  };

  const validarEmail = (email) => {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return re.test(email);
  };

  const handleChange = (campo) => (e) => {
    let valor = e.target.value;
    
    // Aplicar máscaras específicas
    if (campo === 'cpfResponsavel') {
      valor = aplicarMascaraCPF(valor);
    } else if (campo === 'cnpj') {
      valor = aplicarMascaraCNPJ(valor);
    } else if (campo === 'telefoneResponsavel' || campo === 'telefone') {
      valor = aplicarMascaraTelefone(valor);
    } else if (campo === 'cep') {
      valor = aplicarMascaraCEP(valor);
    }
    
    setFormData({ ...formData, [campo]: valor });
  };

  const handleProximo = () => {
    if (etapa === 0 && !validarDadosInstituicao()) return;
    if (etapa === 1 && !validarDadosResponsavel()) return;
    
    if (etapa < 2) {
      setEtapa(etapa + 1);
    } else {
      handleSubmit();
    }
  };

  const validarDadosInstituicao = () => {
    // Validar campos obrigatórios
    if (!formData.nomeInstituicao.trim()) {
      setErro('Nome da instituição é obrigatório');
      return false;
    }
    
    if (!formData.cnpj.trim()) {
      setErro('CNPJ é obrigatório');
      return false;
    }
    
    if (!validarCNPJ(formData.cnpj)) {
      setErro('CNPJ inválido');
      return false;
    }
    
    if (!formData.telefone.trim()) {
      setErro('Telefone é obrigatório');
      return false;
    }
    
    const telefoneNumeros = formData.telefone.replace(/\D/g, '');
    if (telefoneNumeros.length < 10) {
      setErro('Telefone inválido. Use o formato (99) 9999-9999 ou (99) 9 9999-9999');
      return false;
    }
    
    if (!formData.email.trim()) {
      setErro('Email é obrigatório');
      return false;
    }
    
    if (!validarEmail(formData.email)) {
      setErro('Email inválido');
      return false;
    }
    
    if (!formData.endereco.trim()) {
      setErro('Endereço é obrigatório');
      return false;
    }
    
    if (!formData.cidade.trim()) {
      setErro('Cidade é obrigatória');
      return false;
    }
    
    if (!formData.estado.trim()) {
      setErro('Estado é obrigatório');
      return false;
    }
    
    if (!formData.cep.trim()) {
      setErro('CEP é obrigatório');
      return false;
    }
    
    const cepNumeros = formData.cep.replace(/\D/g, '');
    if (cepNumeros.length !== 8) {
      setErro('CEP inválido. Use o formato 99999-999');
      return false;
    }
    
    if (!formData.planoId) {
      setErro('Selecione um plano');
      return false;
    }
    
    setErro('');
    return true;
  };

  const validarDadosResponsavel = () => {
    if (!formData.nomeResponsavel.trim()) {
      setErro('Nome do responsável é obrigatório');
      return false;
    }
    
    if (!formData.cpfResponsavel.trim()) {
      setErro('CPF do responsável é obrigatório');
      return false;
    }
    
    if (!validarCPF(formData.cpfResponsavel)) {
      setErro('CPF inválido');
      return false;
    }
    
    if (!formData.telefoneResponsavel.trim()) {
      setErro('Telefone do responsável é obrigatório');
      return false;
    }
    
    const telefoneNumeros = formData.telefoneResponsavel.replace(/\D/g, '');
    if (telefoneNumeros.length < 10) {
      setErro('Telefone inválido');
      return false;
    }
    
    if (!formData.emailResponsavel.trim()) {
      setErro('Email do responsável é obrigatório');
      return false;
    }
    
    if (!validarEmail(formData.emailResponsavel)) {
      setErro('Email do responsável inválido');
      return false;
    }
    
    if (!formData.cargoResponsavel.trim()) {
      setErro('Cargo do responsável é obrigatório');
      return false;
    }
    
    setErro('');
    return true;
  };

  const handleSubmit = () => {
    if (!formData.loginAdmin.trim()) {
      setErro('Login é obrigatório');
      return;
    }
    
    if (formData.loginAdmin.length < 4) {
      setErro('Login deve ter no mínimo 4 caracteres');
      return;
    }
    
    if (!formData.senhaAdmin.trim()) {
      setErro('Senha é obrigatória');
      return;
    }

    if (formData.senhaAdmin.length < 6) {
      setErro('A senha deve ter no mínimo 8 caracteres');
      return;
    }

    if (!/[A-Z]/.test(formData.senhaAdmin)) {
      setErro('A senha deve conter pelo menos 1 letra maiúscula');
      return;
    }

    if (!/[a-z]/.test(formData.senhaAdmin)) {
      setErro('A senha deve conter pelo menos 1 letra minúscula');
      return;
    }

    if (!/[0-9]/.test(formData.senhaAdmin)) {
      setErro('A senha deve conter pelo menos 1 número');
      return;
    }

    if (!/[^A-Za-z0-9]/.test(formData.senhaAdmin)) {
      setErro('A senha deve conter pelo menos 1 caractere especial');
      return;
    }
    
    if (!formData.confirmarSenha.trim()) {
      setErro('Confirme a senha');
      return;
    }

    if (formData.senhaAdmin !== formData.confirmarSenha) {
      setErro('As senhas não conferem');
      return;
    }

    // Abrir modal de contrato
    setErro('');
    setMostrarContrato(true);
  };

  const handleContratoAceito = (dadosAceite) => {
    setContratoAceito(dadosAceite);
    setMostrarContrato(false);

    try {
      const planoSelecionado = planosDisponiveis.find(p => p.id === parseInt(formData.planoId));
      
      // Redirecionar para a página de pagamento com dados do contrato
      navigate('/pagamento', {
        state: {
          dadosCadastro: formData,
          planoSelecionado: planoSelecionado,
          contratoAceito: dadosAceite
        }
      });
    } catch (error) {
      setErro('Erro ao processar. Tente novamente.');
    }
  };

  return (
    <Container maxWidth="md">
      <Box sx={{ minHeight: '100vh', py: 4 }}>
        <Paper elevation={3} sx={{ p: 4 }}>
          <Box sx={{ textAlign: 'center', mb: 3 }}>
            <SchoolIcon sx={{ fontSize: 60, color: 'primary.main', mb: 2 }} />
            <Typography variant="h4" gutterBottom>
              Cadastro de Nova Instituição
            </Typography>
            <Typography variant="subtitle1" color="text.secondary">
              Sistema CEI - Controle Escolar Inteligente - Gerenciamento de Biblioteca
            </Typography>
          </Box>

          <Stepper activeStep={etapa} sx={{ mb: 4 }}>
            {etapas.map((label) => (
              <Step key={label}>
                <StepLabel>{label}</StepLabel>
              </Step>
            ))}
          </Stepper>

          {erro && (
            <Alert severity="error" sx={{ mb: 2 }} onClose={() => setErro('')}>
              {erro}
            </Alert>
          )}

          {/* ETAPA 0 - Dados da Instituição */}
          {etapa === 0 && (
            <Grid container spacing={2}>
              <Grid item xs={12}>
                <TextField
                  label="Nome da Instituição *"
                  fullWidth
                  required
                  value={formData.nomeInstituicao}
                  onChange={handleChange('nomeInstituicao')}
                  placeholder="Ex: Escola Municipal João Silva"
                />
              </Grid>
              <Grid item xs={12} sm={6}>
                <TextField
                  label="CNPJ *"
                  fullWidth
                  required
                  value={formData.cnpj}
                  onChange={handleChange('cnpj')}
                  placeholder="99.999.999/9999-99"
                  helperText="Formato: 99.999.999/9999-99"
                  inputProps={{ maxLength: 18 }}
                />
              </Grid>
              <Grid item xs={12} sm={6}>
                <TextField
                  label="Código INEP"
                  fullWidth
                  value={formData.inep}
                  onChange={handleChange('inep')}
                  placeholder="12345678"
                  helperText="Código de 8 dígitos (opcional)"
                  inputProps={{ maxLength: 8 }}
                />
              </Grid>
              <Grid item xs={12} sm={6}>
                <TextField
                  label="Telefone/Celular *"
                  fullWidth
                  required
                  value={formData.telefone}
                  onChange={handleChange('telefone')}
                  placeholder="(99) 9 9999-9999"
                  helperText="Formato: (99) 9 9999-9999"
                  inputProps={{ maxLength: 16 }}
                />
              </Grid>
              <Grid item xs={12}>
                <TextField
                  label="Email Institucional *"
                  type="email"
                  fullWidth
                  required
                  value={formData.email}
                  onChange={handleChange('email')}
                  placeholder="contato@escola.com.br"
                />
              </Grid>
              <Grid item xs={12}>
                <TextField
                  label="Endereço *"
                  fullWidth
                  required
                  value={formData.endereco}
                  onChange={handleChange('endereco')}
                  placeholder="Rua, número, complemento"
                />
              </Grid>
              <Grid item xs={12} sm={5}>
                <TextField
                  label="Cidade *"
                  fullWidth
                  required
                  value={formData.cidade}
                  onChange={handleChange('cidade')}
                />
              </Grid>
              <Grid item xs={12} sm={4}>
                <TextField
                  label="Estado *"
                  fullWidth
                  required
                  value={formData.estado}
                  onChange={handleChange('estado')}
                  placeholder="Ex: SP, RJ, MG"
                  inputProps={{ maxLength: 2, style: { textTransform: 'uppercase' } }}
                />
              </Grid>
              <Grid item xs={12} sm={3}>
                <TextField
                  label="CEP *"
                  fullWidth
                  required
                  value={formData.cep}
                  onChange={handleChange('cep')}
                  placeholder="99999-999"
                  helperText="Formato: 99999-999"
                  inputProps={{ maxLength: 9 }}
                />
              </Grid>
              
              <Grid item xs={12}>
                <TextField
                  select
                  label="Escolha seu Plano *"
                  fullWidth
                  required
                  value={formData.planoId}
                  onChange={handleChange('planoId')}
                  helperText="Selecione a duração da sua assinatura"
                >
                  {planosDisponiveis.length === 0 ? (
                    <MenuItem value="" disabled>
                      Nenhum plano disponível no momento
                    </MenuItem>
                  ) : (
                    planosDisponiveis.map((plano) => (
                      <MenuItem key={plano.id} value={plano.id}>
                        {plano.nome} - R$ {plano.valor.toFixed(2)} ({plano.dias} dias)
                      </MenuItem>
                    ))
                  )}
                </TextField>
                {formData.planoId && planosDisponiveis.find(p => p.id === parseInt(formData.planoId)) && (
                  <FormHelperText>
                    Valor por dia: R$ {(planosDisponiveis.find(p => p.id === parseInt(formData.planoId)).valor / 
                      planosDisponiveis.find(p => p.id === parseInt(formData.planoId)).dias).toFixed(2)}
                  </FormHelperText>
                )}
              </Grid>
            </Grid>
          )}

          {/* ETAPA 1 - Dados do Responsável */}
          {etapa === 1 && (
            <Grid container spacing={2}>
              <Grid item xs={12}>
                <TextField
                  label="Nome Completo do Responsável *"
                  fullWidth
                  required
                  value={formData.nomeResponsavel}
                  onChange={handleChange('nomeResponsavel')}
                />
              </Grid>
              <Grid item xs={12} sm={6}>
                <TextField
                  label="CPF *"
                  fullWidth
                  required
                  value={formData.cpfResponsavel}
                  onChange={handleChange('cpfResponsavel')}
                  placeholder="999.999.999-99"
                  helperText="Formato: 999.999.999-99"
                  inputProps={{ maxLength: 14 }}
                />
              </Grid>
              <Grid item xs={12} sm={6}>
                <TextField
                  label="Telefone/Celular *"
                  fullWidth
                  required
                  value={formData.telefoneResponsavel}
                  onChange={handleChange('telefoneResponsavel')}
                  placeholder="(99) 9 9999-9999"
                  helperText="Formato: (99) 9 9999-9999"
                  inputProps={{ maxLength: 16 }}
                />
              </Grid>
              <Grid item xs={12}>
                <TextField
                  label="Email *"
                  type="email"
                  fullWidth
                  required
                  value={formData.emailResponsavel}
                  onChange={handleChange('emailResponsavel')}
                  placeholder="responsavel@email.com"
                />
              </Grid>
              <Grid item xs={12}>
                <TextField
                  label="Cargo/Função *"
                  fullWidth
                  required
                  value={formData.cargoResponsavel}
                  onChange={handleChange('cargoResponsavel')}
                  placeholder="Ex: Diretor, Coordenador Pedagógico"
                />
              </Grid>
            </Grid>
          )}

          {/* ETAPA 2 - Criar Acesso */}
          {etapa === 2 && (
            <Grid container spacing={2}>
              <Grid item xs={12}>
                <Alert severity="info" sx={{ mb: 2 }}>
                  Crie seu login e senha para acessar o sistema após a aprovação
                </Alert>
              </Grid>
              <Grid item xs={12}>
                <TextField
                  label="Login de Acesso *"
                  fullWidth
                  required
                  value={formData.loginAdmin}
                  onChange={handleChange('loginAdmin')}
                  helperText="Mínimo 4 caracteres. Sem espaços."
                  inputProps={{ minLength: 4 }}
                  autoComplete="username"
                />
              </Grid>
              <Grid item xs={12}>
                <TextField
                  label="Senha *"
                  type="password"
                  fullWidth
                  required
                  value={formData.senhaAdmin}
                  onChange={handleChange('senhaAdmin')}
                  helperText="Mínimo 6 caracteres"
                  inputProps={{ minLength: 6 }}
                  autoComplete="new-password"
                />
              </Grid>
              <Grid item xs={12}>
                <TextField
                  label="Confirmar Senha *"
                  type="password"
                  fullWidth
                  required
                  value={formData.confirmarSenha}
                  onChange={handleChange('confirmarSenha')}
                  helperText="Digite a mesma senha novamente"
                  autoComplete="new-password"
                />
              </Grid>
            </Grid>
          )}

          <Box sx={{ display: 'flex', justifyContent: 'space-between', mt: 4 }}>
            <Button
              disabled={etapa === 0}
              onClick={() => setEtapa(etapa - 1)}
            >
              Voltar
            </Button>
            <Box>
              <Button onClick={() => navigate('/login')} sx={{ mr: 1 }}>
                Cancelar
              </Button>
              <Button
                variant="contained"
                onClick={handleProximo}
              >
                {etapa === 2 ? 'Finalizar Cadastro' : 'Próximo'}
              </Button>
            </Box>
          </Box>
          
          {/* Marca Registrada no rodapé do formulário */}
          <Box sx={{ mt: 4, pt: 3, borderTop: 1, borderColor: 'divider', textAlign: 'center' }}>
            <Typography variant="caption" color="text.secondary" display="block">
              © {new Date().getFullYear()} CEI - Controle Escolar Inteligente - Gerenciamento de Biblioteca
            </Typography>
            <Typography variant="caption" color="text.secondary" display="block">
              Sistema desenvolvido por <strong>Wander Pires Silva Coelho</strong> ®
            </Typography>
          </Box>
        </Paper>

        {/* Modal de Contrato */}
        <ContratoModal
          open={mostrarContrato}
          onClose={() => setMostrarContrato(false)}
          onAceitar={handleContratoAceito}
          dadosInstituicao={{
            nome: formData.nomeInstituicao,
            cnpj: formData.cnpj,
            responsavel: formData.nomeResponsavel,
            plano: planosDisponiveis.find(p => p.id === parseInt(formData.planoId))?.nome || 'Não selecionado'
          }}
        />
      </Box>
    </Container>
  );
}

import React, { useState, useRef } from 'react';
import Layout from '../components/Layout';
import { useData } from '../context/DataContext';
import CameraCapture from '../components/CameraCapture';
import ImageCropEditor from '../components/ImageCropEditor';
import Autocomplete from '@mui/material/Autocomplete';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Button,
  TextField,
  Grid,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Avatar,
  Chip,
  Rating,
  Alert,
  IconButton,
  Tabs,
  Tab,
  InputAdornment,
  useMediaQuery,
  useTheme
} from '@mui/material';
import {
  EmojiEvents,
  Add,
  CameraAlt,
  MenuBook,
  Person,
  CheckCircle,
  DocumentScanner,
  Search,
  ZoomIn,
  Upload,
  DeleteForever
} from '@mui/icons-material';

export default function ClubeDeLeituraPage() {
  const { instituicaoLogada, livros, clientes } = useData();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const [dialogOpen, setDialogOpen] = useState(false);
  const [tabValue, setTabValue] = useState(0);
  const [fotoAluno, setFotoAluno] = useState(null);
  const [resumo, setResumo] = useState({
    clienteId: '',
    livroId: '',
    resumoTexto: '',
    pergunta1: '', // Qual foi a parte mais interessante?
    pergunta2: '', // O que você aprendeu?
    pergunta3: '', // Recomendaria para um amigo?
    nota: 0
  });
  const [resumos, setResumos] = useState(() => {
    const salvos = localStorage.getItem('cei_resumos_livros');
    return salvos ? JSON.parse(salvos) : [];
  });
  const [cameraOpen, setCameraOpen] = useState(false);
  const [cameraDocumentoOpen, setCameraDocumentoOpen] = useState(false);
  const [documentoEscaneado, setDocumentoEscaneado] = useState(null);
  const [buscaDocAluno, setBuscaDocAluno] = useState('');
  const [buscaDocLivro, setBuscaDocLivro] = useState('');
  const [docVisualizarOpen, setDocVisualizarOpen] = useState(false);
  const [docSelecionado, setDocSelecionado] = useState(null);
  const [clienteSelecionado, setClienteSelecionado] = useState(null);
  const [buscaAluno, setBuscaAluno] = useState('');
  const fileInputDocRef = useRef(null);
  // Editor de recorte para imagens carregadas por upload
  const [imagemParaEditar, setImagemParaEditar] = useState(null);
  const [imageEditorOpen, setImageEditorOpen] = useState(false);
  // OCR — extração de texto do documento escaneado
  const [ocrText, setOcrText] = useState('');
  const [ocrLoading, setOcrLoading] = useState(false);

  const salvarResumo = () => {
    if (!resumo.clienteId || !resumo.livroId || !resumo.resumoTexto) {
      alert('Preencha todos os campos obrigatórios!');
      return;
    }

    const clienteSelecionado = clientes.find((cliente) => String(cliente.id) === String(resumo.clienteId));

    const novoResumo = {
      ...resumo,
      id: Date.now(),
      data: new Date().toISOString(),
      foto: fotoAluno,
      documentoEscaneado: documentoEscaneado,
      clienteNome: clienteSelecionado?.nome || 'Leitor',
      status: 'aprovado'
    };

    const novosResumos = [...resumos, novoResumo];
    setResumos(novosResumos);
    localStorage.setItem('cei_resumos_livros', JSON.stringify(novosResumos));

    // Reset
    setResumo({
      clienteId: '',
      livroId: '',
      resumoTexto: '',
      pergunta1: '',
      pergunta2: '',
      pergunta3: '',
      nota: 0
    });
    setClienteSelecionado(null);
    setBuscaAluno('');
    setFotoAluno(null);
    setDocumentoEscaneado(null);
    setDialogOpen(false);
    alert('✅ Resumo cadastrado com sucesso! Leitor adicionado ao ranking.');
  };

  const handleFotoCapture = (imageData) => {
    setFotoAluno(imageData);
    setCameraOpen(false);
  };

  const handleDocumentoCapture = (imageData) => {
    setDocumentoEscaneado(imageData);
    setCameraDocumentoOpen(false);
  };

  const handleDocumentoUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    // Zera o valor para permitir re-seleção do mesmo arquivo
    e.target.value = '';
    const reader = new FileReader();
    reader.onloadend = () => {
      setImagemParaEditar(reader.result);
      setImageEditorOpen(true);
    };
    reader.readAsDataURL(file);
  };

  const handleExtractText = async () => {
    if (!docSelecionado?.documentoEscaneado) return;
    setOcrLoading(true);
    setOcrText('');
    try {
      const { createWorker } = await import('tesseract.js');
      const worker = await createWorker('por', 1, {
        workerPath: 'https://unpkg.com/tesseract.js@5/dist/worker.min.js',
        corePath: 'https://unpkg.com/tesseract.js-core@5/tesseract-core-simd-lstm.wasm.js',
        langPath: 'https://tessdata.projectnaptha.com/4.0.0'
      });
      const { data: { text } } = await worker.recognize(docSelecionado.documentoEscaneado);
      await worker.terminate();
      setOcrText(text.trim() || '(Nenhum texto detectado na imagem)');
    } catch (err) {
      setOcrText('Erro ao extrair texto: ' + (err.message || String(err)));
    }
    setOcrLoading(false);
  };

  const resumosComDocumento = resumos.filter(r => r.documentoEscaneado).filter(r => {
    const nomeAluno = (clientes.find(c => String(c.id) === String(r.clienteId))?.nome || r.clienteNome || '').toLowerCase();
    const tituloLivro = (livros.find(l => String(l.id) === String(r.livroId))?.titulo || '').toLowerCase();
    const ba = buscaDocAluno.toLowerCase();
    const bl = buscaDocLivro.toLowerCase();
    return (!ba || nomeAluno.includes(ba)) && (!bl || tituloLivro.includes(bl));
  });

  const getNomeClienteResumo = (resumoItem) => {
    const cliente = clientes.find((item) => String(item.id) === String(resumoItem?.clienteId));
    return cliente?.nome || resumoItem?.clienteNome || 'Leitor';
  };

  const getRankingLeitores = () => {
    const contagem = {};
    resumos.forEach(r => {
      if (!contagem[r.clienteId]) {
        contagem[r.clienteId] = { total: 0, notaMedia: 0, resumos: [] };
      }
      contagem[r.clienteId].total++;
      contagem[r.clienteId].resumos.push(r);
    });

    Object.keys(contagem).forEach(id => {
      const notas = contagem[id].resumos.map(r => r.nota);
      contagem[id].notaMedia = notas.reduce((a, b) => a + b, 0) / notas.length;
    });

    return Object.entries(contagem)
      .map(([clienteId, data]) => ({
        cliente: clientes.find((c) => String(c.id) === String(clienteId)),
        clienteNome: data.resumos.find((resumoItem) => resumoItem?.clienteNome)?.clienteNome || 'Leitor',
        ...data
      }))
      .sort((a, b) => b.total - a.total);
  };

  const ranking = getRankingLeitores();

  return (
    <Layout title="🏆 Clube de Leitura">
      <Box sx={{ mb: 3 }}>
        <Alert severity="info" sx={{ mb: 2 }}>
          <Typography variant="body2">
            <strong>Sistema de Premiação:</strong> Alunos que comprovarem leitura através de resumos
            e respostas ganham pontos no ranking! 📚🏆
          </Typography>
        </Alert>

        <Button
          variant="contained"
          startIcon={<Add />}
          onClick={() => setDialogOpen(true)}
        >
          Registrar Nova Leitura
        </Button>
      </Box>

      <Tabs value={tabValue} onChange={(e, v) => setTabValue(v)} sx={{ mb: 3 }}>
        <Tab label="🏆 Ranking de Leitores" />
        <Tab label="📖 Resumos Cadastrados" />
        <Tab label="📄 Documentos Escaneados" />
      </Tabs>

      {/* TAB 1: RANKING */}
      {tabValue === 0 && (
        <Grid container spacing={3}>
          {ranking.slice(0, 3).map((item, index) => (
            <Grid item xs={12} md={4} key={index}>
              <Card sx={{ 
                bgcolor: index === 0 ? '#ffd700' : index === 1 ? '#c0c0c0' : '#cd7f32',
                textAlign: 'center'
              }}>
                <CardContent>
                  <EmojiEvents sx={{ fontSize: 60, mb: 2 }} />
                  <Typography variant="h4">
                    {index === 0 ? '🥇' : index === 1 ? '🥈' : '🥉'} {index + 1}º Lugar
                  </Typography>
                  <Avatar
                    src={item.resumos[item.resumos.length - 1]?.foto}
                    sx={{ width: 100, height: 100, margin: '20px auto' }}
                    imgProps={{ style: { objectFit: 'contain' } }}
                  >
                    <Person sx={{ fontSize: 50 }} />
                  </Avatar>
                  <Typography variant="h5" gutterBottom>
                    {item.cliente?.nome || item.clienteNome || 'Leitor'}
                  </Typography>
                  <Typography variant="h6" color="text.secondary">
                    <MenuBook sx={{ verticalAlign: 'middle', mr: 1 }} />
                    {item.total} {item.total === 1 ? 'livro lido' : 'livros lidos'}
                  </Typography>
                  <Rating value={item.notaMedia} readOnly sx={{ mt: 1 }} />
                </CardContent>
              </Card>
            </Grid>
          ))}

          {ranking.length > 3 && (
            <Grid item xs={12}>
              <Card>
                <CardContent>
                  <Typography variant="h6" gutterBottom>
                    Demais Leitores
                  </Typography>
                  <TableContainer>
                    <Table>
                      <TableHead>
                        <TableRow>
                          <TableCell>Posição</TableCell>
                          <TableCell>Nome</TableCell>
                          <TableCell align="center">Livros Lidos</TableCell>
                          <TableCell align="center">Nota Média</TableCell>
                        </TableRow>
                      </TableHead>
                      <TableBody>
                        {ranking.slice(3).map((item, index) => (
                          <TableRow key={index}>
                            <TableCell>{index + 4}º</TableCell>
                            <TableCell>{item.cliente?.nome || item.clienteNome || 'Leitor'}</TableCell>
                            <TableCell align="center">{item.total}</TableCell>
                            <TableCell align="center">
                              <Rating value={item.notaMedia} readOnly size="small" />
                            </TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </TableContainer>
                </CardContent>
              </Card>
            </Grid>
          )}
        </Grid>
      )}

      {/* TAB 2: RESUMOS */}
      {tabValue === 1 && (
        <TableContainer component={Paper}>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>Data</TableCell>
                <TableCell>Leitor</TableCell>
                <TableCell>Livro</TableCell>
                <TableCell>Nota</TableCell>
                <TableCell>Status</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {resumos.map((r) => (
                <TableRow key={r.id}>
                  <TableCell>{new Date(r.data).toLocaleDateString('pt-BR')}</TableCell>
                  <TableCell>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                      <Avatar src={r.foto} sx={{ width: 32, height: 32 }} imgProps={{ style: { objectFit: 'contain' } }}>
                        <Person />
                      </Avatar>
                      {getNomeClienteResumo(r)}
                    </Box>
                  </TableCell>
                  <TableCell>
                    {livros.find(l => l.id === parseInt(r.livroId))?.titulo || 'Livro'}
                  </TableCell>
                  <TableCell>
                    <Rating value={r.nota} readOnly size="small" />
                  </TableCell>
                  <TableCell>
                    <Chip 
                      label="Aprovado" 
                      color="success" 
                      size="small" 
                      icon={<CheckCircle />}
                    />
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}

      {/* TAB 3: DOCUMENTOS ESCANEADOS */}
      {tabValue === 2 && (
        <Box>
          {/* Barra de busca */}
          <Box sx={{ display: 'flex', gap: 2, mb: 3, flexWrap: 'wrap' }}>
            <TextField
              size="small"
              label="Buscar por aluno"
              value={buscaDocAluno}
              onChange={e => setBuscaDocAluno(e.target.value)}
              InputProps={{ startAdornment: <Search sx={{ mr: 1, color: 'text.secondary' }} /> }}
              sx={{ minWidth: 220 }}
            />
            <TextField
              size="small"
              label="Buscar por livro"
              value={buscaDocLivro}
              onChange={e => setBuscaDocLivro(e.target.value)}
              InputProps={{ startAdornment: <Search sx={{ mr: 1, color: 'text.secondary' }} /> }}
              sx={{ minWidth: 220 }}
            />
          </Box>

          {resumosComDocumento.length === 0 ? (
            <Alert severity="info">
              {resumos.filter(r => r.documentoEscaneado).length === 0
                ? 'Nenhum documento escaneado ainda. Ao registrar uma leitura, escaneie o resumo físico do aluno.'
                : 'Nenhum documento encontrado para os filtros informados.'}
            </Alert>
          ) : (
            <TableContainer component={Paper}>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>Data</TableCell>
                    <TableCell>Aluno</TableCell>
                    <TableCell>Livro</TableCell>
                    <TableCell>Nota</TableCell>
                    <TableCell align="center">Documento</TableCell>
                    <TableCell align="center">Ver</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {resumosComDocumento.map(r => (
                    <TableRow key={r.id} hover>
                      <TableCell>{new Date(r.data).toLocaleDateString('pt-BR')}</TableCell>
                      <TableCell>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                          <Avatar src={r.foto} sx={{ width: 28, height: 28 }}><Person /></Avatar>
                          {getNomeClienteResumo(r)}
                        </Box>
                      </TableCell>
                      <TableCell>{livros.find(l => String(l.id) === String(r.livroId))?.titulo || 'Livro'}</TableCell>
                      <TableCell><Rating value={r.nota} readOnly size="small" /></TableCell>
                      <TableCell align="center">
                        <Box
                          component="img"
                          src={r.documentoEscaneado}
                          alt="Resumo escaneado"
                          sx={{ width: 60, height: 60, objectFit: 'cover', borderRadius: 1, border: '1px solid #ccc', cursor: 'pointer' }}
                          onClick={() => { setDocSelecionado(r); setDocVisualizarOpen(true); }}
                        />
                      </TableCell>
                      <TableCell align="center">
                        <IconButton
                          color="primary"
                          onClick={() => { setDocSelecionado(r); setDocVisualizarOpen(true); }}
                          title="Ver documento"
                        >
                          <ZoomIn />
                        </IconButton>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          )}
        </Box>
      )}

      {/* DIALOG: CADASTRAR RESUMO */}
      <Dialog
        open={dialogOpen}
        onClose={() => setDialogOpen(false)}
        maxWidth="md"
        fullWidth
        fullScreen={isMobile}
        PaperProps={isMobile ? {} : { sx: { maxWidth: '900px' } }}
      >
        <DialogTitle>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <MenuBook />
            <Typography variant="h6" component="span">
              Registrar Leitura Completa
            </Typography>
          </Box>
        </DialogTitle>
        <DialogContent>
          {/* Box column layout garante 100% de largura em qualquer versão do MUI Grid */}
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 1 }}>
            <Box sx={{ width: '100%' }}>
              <Autocomplete
                options={clientes.filter(c => c.nome)}
                getOptionLabel={(option) => option.nome || ''}
                value={clienteSelecionado}
                onChange={(e, newValue) => {
                  setClienteSelecionado(newValue);
                  setResumo({ ...resumo, clienteId: newValue?.id || '' });
                }}
                inputValue={buscaAluno}
                onInputChange={(e, newInputValue) => setBuscaAluno(newInputValue)}
                disablePortal
                fullWidth
                sx={{ width: '100%' }}
                componentsProps={{
                  paper: { sx: { minWidth: 320 } }
                }}
                filterOptions={(options, { inputValue }) => {
                  if (!inputValue.trim()) return options;
                  const termo = inputValue.toLowerCase();
                  return options.filter(
                    (c) =>
                      c.nome?.toLowerCase().includes(termo) ||
                      c.turma?.toLowerCase().includes(termo) ||
                      c.serie?.toLowerCase().includes(termo) ||
                      c.matricula?.toLowerCase?.().includes(termo) ||
                      String(c.matricula || '').includes(termo)
                  );
                }}
                renderOption={(props, option) => {
                  const { key, ...liProps } = props;
                  return (
                    <Box
                      component="li"
                      key={key}
                      {...liProps}
                      sx={{
                        display: 'flex',
                        alignItems: 'center',
                        gap: 1.5,
                        py: 1,
                        px: 1.5,
                        width: '100%',
                        boxSizing: 'border-box'
                      }}
                    >
                      <Avatar sx={{ width: 34, height: 34, fontSize: 14, bgcolor: 'primary.main', flexShrink: 0 }}>
                        {option.nome?.charAt(0)?.toUpperCase()}
                      </Avatar>
                      <Box sx={{ flex: 1, overflow: 'hidden' }}>
                        <Typography
                          variant="body2"
                          fontWeight={600}
                          sx={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}
                          title={option.nome}
                        >
                          {option.nome}
                        </Typography>
                        {(option.turma || option.serie || option.matricula) && (
                          <Typography variant="caption" color="text.secondary" sx={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', display: 'block' }}>
                            {[option.serie, option.turma, option.matricula ? `Matr: ${option.matricula}` : ''].filter(Boolean).join(' — ')}
                          </Typography>
                        )}
                      </Box>
                    </Box>
                  );
                }}
                renderInput={(params) => (
                  <TextField
                    {...params}
                    label="🔍 Buscar Leitor"
                    placeholder="Digite nome, turma ou série..."
                    fullWidth
                    size="medium"
                    sx={{
                      width: '100%',
                      '& .MuiInputBase-root': {
                        fontSize: '1.08rem',
                        minHeight: 62,
                        borderRadius: 2,
                        bgcolor: '#f0f7ff',
                        width: '100%'
                      },
                      '& .MuiInputBase-input': { py: 1.5 },
                      '& .MuiInputLabel-root': { fontSize: '1.05rem' }
                    }}
                    InputProps={{
                      ...params.InputProps,
                      startAdornment: (
                        <>
                          <InputAdornment position="start">
                            <Search sx={{ color: 'primary.main', fontSize: 22 }} />
                          </InputAdornment>
                          {params.InputProps.startAdornment}
                        </>
                      )
                    }}
                  />
                )}
                noOptionsText="Nenhum aluno encontrado"
                clearText="Limpar"
                openText="Abrir"
                closeText="Fechar"
                fullWidth
              />
            </Box>

            <Box sx={{ width: '100%' }}>
              <TextField
                select
                fullWidth
                label="Livro Lido"
                value={resumo.livroId}
                onChange={(e) => setResumo({ ...resumo, livroId: e.target.value })}
                SelectProps={{ native: true }}
                InputLabelProps={{ shrink: true }}
              >
                <option value="">Selecione...</option>
                {livros.map(l => (
                  <option key={l.id} value={l.id}>{l.titulo}</option>
                ))}
              </TextField>
            </Box>

            <Box sx={{ width: '100%' }}>
              <Box sx={{ textAlign: 'center', mb: 2 }}>
                <Box sx={{ display: 'flex', gap: 1, justifyContent: 'center', flexWrap: 'wrap' }}>
                  <Button
                    variant="outlined"
                    startIcon={<CameraAlt />}
                    onClick={() => setCameraOpen(true)}
                  >
                    {fotoAluno ? 'Alterar Foto' : 'Tirar Foto do Leitor'}
                  </Button>
                  {fotoAluno && (
                    <Button
                      variant="outlined"
                      color="error"
                      startIcon={<DeleteForever />}
                      onClick={() => setFotoAluno(null)}
                    >
                      Excluir Foto
                    </Button>
                  )}
                </Box>
                {fotoAluno && (
                  <Avatar src={fotoAluno} sx={{ width: 100, height: 100, margin: '10px auto' }} imgProps={{ style: { objectFit: 'contain' } }} />
                )}
              </Box>
            </Box>

            {/* ESCANEAR RESUMO FÍSICO */}
            <Box sx={{ width: '100%' }}>
              <Box sx={{ p: 2, border: '1px dashed #1976d2', borderRadius: 2, bgcolor: '#f0f7ff' }}>
                <Typography variant="subtitle2" gutterBottom sx={{ color: '#1565c0', fontWeight: 'bold' }}>
                  <DocumentScanner sx={{ verticalAlign: 'middle', mr: 1 }} />
                  Escanear Resumo Físico (opcional)
                </Typography>
                <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>
                  Fotografe ou faça upload do resumo escrito a mão pelo aluno.
                </Typography>
                <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                  <Button
                    variant="outlined"
                    size="small"
                    startIcon={<CameraAlt />}
                    onClick={() => setCameraDocumentoOpen(true)}
                  >
                    Fotografar Documento
                  </Button>
                  <Button
                    variant="outlined"
                    size="small"
                    startIcon={<Upload />}
                    onClick={() => fileInputDocRef.current?.click()}
                  >
                    Upload de Imagem
                  </Button>
                  <input
                    type="file"
                    accept="image/*"
                    ref={fileInputDocRef}
                    style={{ display: 'none' }}
                    onChange={handleDocumentoUpload}
                  />
                  {documentoEscaneado && (
                    <Button size="small" color="error" onClick={() => setDocumentoEscaneado(null)}>Remover</Button>
                  )}
                </Box>
                {documentoEscaneado && (
                  <Box sx={{ mt: 1 }}>
                    <Box
                      component="img"
                      src={documentoEscaneado}
                      alt="Documento escaneado"
                      sx={{ maxWidth: '100%', maxHeight: 200, borderRadius: 1, border: '1px solid #90caf9', mt: 1 }}
                    />
                    <Chip label="✅ Documento pronto" color="success" size="small" sx={{ mt: 1, display: 'block', width: 'fit-content' }} />
                  </Box>
                )}
              </Box>
            </Box>

            <Box sx={{ width: '100%' }}>
              <TextField
                fullWidth
                multiline
                rows={3}
                label="Resumo do Livro *"
                value={resumo.resumoTexto}
                onChange={(e) => setResumo({ ...resumo, resumoTexto: e.target.value })}
                placeholder="Escreva um breve resumo do que você leu..."
              />
            </Box>

            <Box sx={{ width: '100%' }}>
              <Typography variant="subtitle2" gutterBottom sx={{ mt: 2, mb: 1 }}>
                📝 Perguntas de Comprovação:
              </Typography>
            </Box>

            <Box sx={{ width: '100%' }}>
              <TextField
                fullWidth
                multiline
                rows={2}
                label="1. Qual foi a parte mais interessante do livro?"
                value={resumo.pergunta1}
                onChange={(e) => setResumo({ ...resumo, pergunta1: e.target.value })}
              />
            </Box>

            <Box sx={{ width: '100%' }}>
              <TextField
                fullWidth
                multiline
                rows={2}
                label="2. O que você aprendeu com essa leitura?"
                value={resumo.pergunta2}
                onChange={(e) => setResumo({ ...resumo, pergunta2: e.target.value })}
              />
            </Box>

            <Box sx={{ width: '100%' }}>
              <TextField
                fullWidth
                multiline
                rows={2}
                label="3. Você recomendaria esse livro? Por quê?"
                value={resumo.pergunta3}
                onChange={(e) => setResumo({ ...resumo, pergunta3: e.target.value })}
              />
            </Box>

            <Box sx={{ width: '100%' }}>
              <Typography variant="body2" gutterBottom>
                Avalie o livro:
              </Typography>
              <Rating
                value={resumo.nota}
                onChange={(e, newValue) => setResumo({ ...resumo, nota: newValue })}
                size="large"
              />
            </Box>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDialogOpen(false)}>Cancelar</Button>
          <Button variant="contained" onClick={salvarResumo}>
            Salvar Resumo
          </Button>
        </DialogActions>
      </Dialog>

      {/* Editor de recorte para imagens carregadas por upload */}
      <ImageCropEditor
        open={imageEditorOpen}
        imageData={imagemParaEditar}
        title="Editar Documento — Cortar Margens"
        onClose={() => { setImageEditorOpen(false); setImagemParaEditar(null); }}
        onSave={(img) => { setDocumentoEscaneado(img); setImageEditorOpen(false); setImagemParaEditar(null); }}
      />

      {/* Dialog de Captura de Câmera - Foto do Leitor */}
      <CameraCapture
        open={cameraOpen}
        onClose={() => setCameraOpen(false)}
        onCapture={handleFotoCapture}
        title="Tirar Foto do Leitor"
      />

      {/* Dialog de Captura - Documento/Resumo Físico */}
      <CameraCapture
        open={cameraDocumentoOpen}
        onClose={() => setCameraDocumentoOpen(false)}
        onCapture={handleDocumentoCapture}
        title="Fotografar Resumo Físico do Aluno"
      />

      {/* Dialog de Visualização do Documento */}
      <Dialog
        open={docVisualizarOpen}
        onClose={() => { setDocVisualizarOpen(false); setOcrText(''); }}
        maxWidth="md"
        fullWidth
        fullScreen={isMobile}
      >
        <DialogTitle>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <DocumentScanner />
            <Typography variant="h6" component="span">
              Resumo Escrito — {docSelecionado && getNomeClienteResumo(docSelecionado)}
            </Typography>
          </Box>
        </DialogTitle>
        <DialogContent sx={{ p: { xs: 1, sm: 2 } }}>
          {docSelecionado && (
            <Box>
              <Box sx={{ display: 'flex', gap: 1, mb: 2, flexWrap: 'wrap' }}>
                <Chip label={`Aluno: ${getNomeClienteResumo(docSelecionado)}`} />
                <Chip label={`Livro: ${livros.find(l => String(l.id) === String(docSelecionado.livroId))?.titulo || 'Livro'}`} color="primary" />
                <Chip label={`Data: ${new Date(docSelecionado.data).toLocaleDateString('pt-BR')}`} variant="outlined" />
              </Box>

              {/* Imagem do documento com visualizador de zoom CSS */}
              <Box
                sx={{
                  overflow: 'auto',
                  maxHeight: { xs: 320, sm: 480 },
                  border: '1px solid #e0e0e0',
                  borderRadius: 2,
                  bgcolor: '#f9f9f9',
                  mb: 2,
                  textAlign: 'center',
                  cursor: 'zoom-in',
                }}
              >
                <Box
                  component="img"
                  src={docSelecionado.documentoEscaneado}
                  alt="Resumo escaneado"
                  sx={{
                    maxWidth: '100%',
                    display: 'block',
                    margin: '0 auto',
                    transition: 'transform 0.2s',
                    '&:hover': { transform: 'scale(1.6)', transformOrigin: 'center top', cursor: 'zoom-in' }
                  }}
                />
              </Box>

              {/* Painel de texto extraído por OCR */}
              <Box sx={{ border: '1px dashed #1976d2', borderRadius: 2, p: 2, bgcolor: '#f0f7ff' }}>
                <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 1, flexWrap: 'wrap', gap: 1 }}>
                  <Typography variant="subtitle2" sx={{ color: '#1565c0', fontWeight: 'bold', display: 'flex', alignItems: 'center', gap: 0.5 }}>
                    📄 Texto Extraído do Documento
                  </Typography>
                  <Button
                    variant="contained"
                    size="small"
                    onClick={handleExtractText}
                    disabled={ocrLoading}
                    startIcon={ocrLoading ? null : <DocumentScanner />}
                    sx={{ bgcolor: '#1976d2' }}
                  >
                    {ocrLoading ? 'Extraindo texto...' : 'Extrair Texto (OCR)'}
                  </Button>
                </Box>
                {ocrLoading && (
                  <Alert severity="info" sx={{ mb: 1 }}>
                    Processando imagem com OCR... Isso pode levar alguns segundos.
                  </Alert>
                )}
                {ocrText ? (
                  <TextField
                    multiline
                    fullWidth
                    rows={8}
                    value={ocrText}
                    onChange={(e) => setOcrText(e.target.value)}
                    placeholder="Texto extraído aparecerá aqui..."
                    variant="outlined"
                    sx={{
                      '& .MuiInputBase-root': { fontFamily: 'monospace', fontSize: '0.93rem', bgcolor: '#fff' }
                    }}
                    helperText="Texto gerado automaticamente por OCR. Pode conter erros — você pode editar aqui."
                  />
                ) : (
                  !ocrLoading && (
                    <Typography variant="caption" color="text.secondary">
                      Clique em "Extrair Texto (OCR)" para tentar ler automaticamente o conteúdo escrito no documento.
                      A precisão varia conforme a qualidade da imagem e caligrafia.
                    </Typography>
                  )
                )}
              </Box>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => { setDocVisualizarOpen(false); setOcrText(''); }}>Fechar</Button>
        </DialogActions>
      </Dialog>
    </Layout>
  );
}

