import React, { useEffect, useState } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Button,
  Alert,
  CircularProgress,
  Grid,
  Chip,
  Paper,
  Divider,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Switch,
  FormControlLabel
} from '@mui/material';
import {
  Backup,
  CheckCircle,
  CloudDone,
  CloudOff,
  Launch,
  Security,
  Speed,
  Storage,
  Sync,
  Warning
} from '@mui/icons-material';
import Layout from '../components/Layout';
import { useData } from '../context/DataContext';
import { getSyncStatus } from '../services/syncService';
import { cloudConfigScope, cloudConfigSource, isCloudEnabled } from '../services/supabaseClient';

const ConfiguracoesNuvemPage = () => {
  const {
    livros,
    clientes,
    emprestimos,
    patrimonio,
    instituicoes,
    instituicaoAtiva,
    sincronizarNuvemAgora
  } = useData();

  const [cloudStatus, setCloudStatus] = useState(null);
  const [loading, setLoading] = useState(true);
  const [syncing, setSyncing] = useState(false);
  const [lastSync, setLastSync] = useState(null);

  const currentInstituicao = instituicoes.find(
    (instituicao) => Number(instituicao?.id) === Number(instituicaoAtiva)
  ) || null;
  const publicBasePath = process.env.PUBLIC_URL || '';
  const browserConfigUrl = `${publicBasePath}/configurar-supabase.html`;

  useEffect(() => {
    checkCloudStatus();

    const interval = setInterval(checkCloudStatus, 30000);
    return () => clearInterval(interval);
  }, []);

  const checkCloudStatus = async () => {
    setLoading(true);
    try {
      const status = await getSyncStatus();
      setCloudStatus(status);

      const lastSyncTime = localStorage.getItem('cei_last_sync');
      if (lastSyncTime) {
        setLastSync(new Date(lastSyncTime));
      }
    } catch (error) {
      console.error('Erro ao verificar status da nuvem:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleSync = async () => {
    setSyncing(true);
    try {
      await sincronizarNuvemAgora();
      localStorage.setItem('cei_last_sync', new Date().toISOString());
      setLastSync(new Date());
      await checkCloudStatus();
      alert('✅ Sincronizacao concluida com sucesso!');
    } catch (error) {
      alert(`❌ Erro ao sincronizar: ${error.message}`);
    } finally {
      setSyncing(false);
    }
  };

  const handleDownloadFromCloud = async () => {
    if (!window.confirm('Deseja baixar e mesclar os dados da nuvem com este dispositivo?')) {
      return;
    }

    setSyncing(true);
    try {
      await sincronizarNuvemAgora({ somenteBaixar: true });
      localStorage.setItem('cei_last_sync', new Date().toISOString());
      setLastSync(new Date());
      await checkCloudStatus();
      alert('✅ Dados da nuvem baixados e mesclados com sucesso!');
    } catch (error) {
      alert(`❌ Erro ao baixar dados da nuvem: ${error.message}`);
    } finally {
      setSyncing(false);
    }
  };

  const getStatusColor = () => {
    if (!cloudStatus) return 'default';
    if (cloudStatus.connected) return 'success';
    if (cloudStatus.enabled) return 'warning';
    return 'default';
  };

  const getStatusIcon = () => {
    if (!cloudStatus) return <CloudOff />;
    if (cloudStatus.connected) return <CloudDone />;
    if (cloudStatus.enabled) return <Warning />;
    return <CloudOff />;
  };

  const getStatusText = () => {
    if (!cloudStatus) return 'Verificando...';
    if (cloudStatus.connected) return 'Conectado';
    if (cloudStatus.enabled) return 'Configurado sem conexao';
    return 'Nao configurado';
  };

  const getConfigSourceLabel = () => {
    if (cloudConfigSource === 'runtime-file') {
      return 'Arquivo compartilhado do deploy';
    }

    if (cloudConfigSource === 'env') {
      return 'Variaveis de ambiente';
    }

    if (cloudConfigSource === 'localStorage') {
      return 'Somente este navegador';
    }

    return 'Nao configurado';
  };

  const totalRecords = livros.length + clientes.length + emprestimos.length + patrimonio.length;

  return (
    <Layout title="Configuracoes de Nuvem">
      <Box sx={{ p: 3 }}>
        <Card sx={{ mb: 3 }}>
          <CardContent>
            <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
              {getStatusIcon()}
              <Typography variant="h5" sx={{ ml: 2, flexGrow: 1 }}>
                Status da Nuvem
              </Typography>
              <Chip label={getStatusText()} color={getStatusColor()} icon={getStatusIcon()} />
            </Box>

            <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mb: 2 }}>
              <Chip label={`Fonte: ${getConfigSourceLabel()}`} variant="outlined" />
              {currentInstituicao && (
                <Chip
                  label={`Instituicao: ${currentInstituicao.nomeInstituicao || currentInstituicao.nome || currentInstituicao.id}`}
                  variant="outlined"
                />
              )}
              <Chip
                label={
                  cloudConfigScope === 'shared'
                    ? 'Compartilhada entre dispositivos'
                    : cloudConfigScope === 'browser-local'
                      ? 'Configuracao local deste navegador'
                      : 'Sem configuracao de nuvem'
                }
                color={
                  cloudConfigScope === 'shared'
                    ? 'success'
                    : cloudConfigScope === 'browser-local'
                      ? 'warning'
                      : 'default'
                }
                variant="outlined"
              />
            </Box>

            {loading ? (
              <Box sx={{ display: 'flex', justifyContent: 'center', p: 3 }}>
                <CircularProgress />
              </Box>
            ) : (
              <>
                {!isCloudEnabled && (
                  <Alert severity="warning" sx={{ mb: 2 }}>
                    <Typography variant="body2" sx={{ fontWeight: 'bold', mb: 1 }}>
                      Dados apenas neste navegador
                    </Typography>
                    <Typography variant="body2" sx={{ mb: 2 }}>
                      Sem Supabase configurado, os dados ficam somente neste aparelho. Por isso um dispositivo pode ter registros e outro abrir vazio.
                    </Typography>
                    <ol style={{ margin: 0, paddingLeft: 20 }}>
                      <li>Crie ou use seu projeto em <a href="https://supabase.com" target="_blank" rel="noopener noreferrer">supabase.com</a></li>
                      <li>Preencha <code>public/supabase-runtime-config.js</code> no deploy para valer em todos os dispositivos</li>
                      <li>Ou configure <code>.env.local</code> antes do build</li>
                      <li>Se quiser testar so neste aparelho, use o configurador deste navegador</li>
                    </ol>
                  </Alert>
                )}

                {cloudConfigSource === 'localStorage' && (
                  <Alert severity="warning" sx={{ mb: 2 }}>
                    A nuvem foi configurada apenas neste navegador. Outros dispositivos so acessarao os mesmos dados se a configuracao for movida para <code>public/supabase-runtime-config.js</code> ou para as variaveis de ambiente do build.
                  </Alert>
                )}

                {cloudStatus?.connected && (
                  <Alert severity="success" sx={{ mb: 2 }}>
                    Supabase conectado. Sincronizacao automatica ativa.
                  </Alert>
                )}

                {cloudStatus?.enabled && !cloudStatus?.connected && (
                  <Alert severity="warning" sx={{ mb: 2 }}>
                    Supabase configurado, mas sem conexao. Verifique internet, URL e chave.
                  </Alert>
                )}

                <Grid container spacing={2} sx={{ mt: 2 }}>
                  <Grid item xs={12} sm={6} md={3}>
                    <Paper sx={{ p: 2, textAlign: 'center' }}>
                      <Storage sx={{ fontSize: 40, color: 'primary.main', mb: 1 }} />
                      <Typography variant="h4">{totalRecords}</Typography>
                      <Typography variant="body2" color="text.secondary">
                        Registros totais
                      </Typography>
                    </Paper>
                  </Grid>

                  <Grid item xs={12} sm={6} md={3}>
                    <Paper sx={{ p: 2, textAlign: 'center' }}>
                      <Speed sx={{ fontSize: 40, color: 'success.main', mb: 1 }} />
                      <Typography variant="h4">{livros.length}</Typography>
                      <Typography variant="body2" color="text.secondary">
                        Livros
                      </Typography>
                    </Paper>
                  </Grid>

                  <Grid item xs={12} sm={6} md={3}>
                    <Paper sx={{ p: 2, textAlign: 'center' }}>
                      <Security sx={{ fontSize: 40, color: 'info.main', mb: 1 }} />
                      <Typography variant="h4">{clientes.length}</Typography>
                      <Typography variant="body2" color="text.secondary">
                        Leitores
                      </Typography>
                    </Paper>
                  </Grid>

                  <Grid item xs={12} sm={6} md={3}>
                    <Paper sx={{ p: 2, textAlign: 'center' }}>
                      <Backup sx={{ fontSize: 40, color: 'warning.main', mb: 1 }} />
                      <Typography variant="h4">{emprestimos.length}</Typography>
                      <Typography variant="body2" color="text.secondary">
                        Emprestimos
                      </Typography>
                    </Paper>
                  </Grid>
                </Grid>

                {lastSync && (
                  <Box sx={{ mt: 3, p: 2, bgcolor: 'background.default', borderRadius: 1 }}>
                    <Typography variant="body2" color="text.secondary">
                      Ultima sincronizacao: {lastSync.toLocaleString('pt-BR')}
                    </Typography>
                  </Box>
                )}

                <Box sx={{ mt: 3, display: 'flex', gap: 2, flexWrap: 'wrap' }}>
                  <Button
                    variant="contained"
                    startIcon={syncing ? <CircularProgress size={20} /> : <Sync />}
                    onClick={handleSync}
                    disabled={syncing || !currentInstituicao}
                  >
                    {syncing ? 'Sincronizando...' : 'Sincronizar agora'}
                  </Button>

                  <Button
                    variant="outlined"
                    startIcon={<CloudDone />}
                    onClick={handleDownloadFromCloud}
                    disabled={syncing || !isCloudEnabled || !currentInstituicao}
                  >
                    Baixar da nuvem
                  </Button>

                  <Button
                    variant="outlined"
                    startIcon={<Launch />}
                    component="a"
                    href={browserConfigUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                  >
                    Configurar neste navegador
                  </Button>

                  <Button
                    variant="outlined"
                    startIcon={<Backup />}
                    onClick={() => window.open('https://supabase.com/dashboard', '_blank')}
                  >
                    Abrir dashboard
                  </Button>
                </Box>

                <Paper sx={{ mt: 3, p: 2, bgcolor: 'background.default' }}>
                  <Typography variant="subtitle2" sx={{ mb: 1 }}>
                    Ativacao para qualquer dispositivo
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    Para os dados aparecerem de qualquer lugar, a configuracao da nuvem precisa estar compartilhada no deploy. O arquivo indicado e <code>public/supabase-runtime-config.js</code>. Salvar credenciais no localStorage resolve apenas neste navegador.
                  </Typography>
                </Paper>

                <Divider sx={{ my: 3 }} />

                <Typography variant="h6" sx={{ mb: 2 }}>
                  Configuracoes de sincronizacao
                </Typography>

                <FormControlLabel
                  control={<Switch checked disabled />}
                  label="Sincronizacao automatica habilitada pelo sistema"
                />

                <Divider sx={{ my: 3 }} />

                <Typography variant="h6" sx={{ mb: 2 }}>
                  Beneficios da nuvem Supabase
                </Typography>

                <List>
                  <ListItem>
                    <ListItemIcon>
                      <CheckCircle color="success" />
                    </ListItemIcon>
                    <ListItemText
                      primary="Acesso multi-dispositivo"
                      secondary="Acesse seus dados de qualquer lugar"
                    />
                  </ListItem>
                  <ListItem>
                    <ListItemIcon>
                      <CheckCircle color="success" />
                    </ListItemIcon>
                    <ListItemText
                      primary="Backup automatico"
                      secondary="Persistencia em nuvem para evitar perda por dispositivo"
                    />
                  </ListItem>
                  <ListItem>
                    <ListItemIcon>
                      <CheckCircle color="success" />
                    </ListItemIcon>
                    <ListItemText
                      primary="Seguranca SSL/TLS"
                      secondary="Criptografia nas conexoes com a nuvem"
                    />
                  </ListItem>
                  <ListItem>
                    <ListItemIcon>
                      <CheckCircle color="success" />
                    </ListItemIcon>
                    <ListItemText
                      primary="Sincronizacao entre aparelhos"
                      secondary="Um cadastro feito em um dispositivo pode aparecer nos demais"
                    />
                  </ListItem>
                </List>
              </>
            )}
          </CardContent>
        </Card>
      </Box>
    </Layout>
  );
};

export default ConfiguracoesNuvemPage;

import React, { useState, useRef, useEffect } from 'react';
import { Link as RouterLink } from 'react-router-dom';
import Layout from '../components/Layout';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Button,
  TextField,
  Grid,
  Avatar,
  Divider,
  Alert,
  Paper,
  IconButton,
  Chip
} from '@mui/material';
import {
  Settings,
  Save,
  Image as ImageIcon,
  Delete,
  School,
  CheckCircle,
  Cloud
} from '@mui/icons-material';
import { useData } from '../context/DataContext';
import { isCloudEnabled } from '../services/supabaseClient';

export default function ConfiguracoesPage() {
  const { 
    instituicoes,
    usuarioLogado,
    instituicaoAtiva,
    atualizarInstituicao
  } = useData();

  const [sucesso, setSucesso] = useState(false);
  const [erro, setErro] = useState('');
  const [configs, setConfigs] = useState({
    // Configurações de Cabeçalho
    tituloCabecalho: '',
    subtituloCabecalho: '',
    logoCabecalho: '',
    corCabecalho: '#667eea',
    
    // Configurações de Emblema/Logo
    logoEscola: '',
    descricaoLogo: '',
    
    // Configurações de Rodapé
    textoRodape: '',
    enderecoRodape: '',
    telefoneRodape: '',
    emailRodape: '',
    siteRodape: '',
    redesSociais: {
      facebook: '',
      instagram: '',
      twitter: ''
    }
  });

  const logoInputRef = useRef(null);
  const emblemaInputRef = useRef(null);
  const instituicaoCarregadaRef = useRef(null);

  // Carregar configurações salvas da instituição apenas uma vez por instituição
  // (não re-executar quando instituicoes atualiza via sync para evitar reset do formulário)
  // Porém, se a instituição ainda não tem mídia reidratada, não travar o ref
  useEffect(() => {
    if (instituicaoCarregadaRef.current === instituicaoAtiva) return;
    const instituicao = instituicoes.find(i => i.id === instituicaoAtiva);
    if (instituicao) {
      setConfigs({
        tituloCabecalho: instituicao.tituloCabecalho || instituicao.nomeInstituicao || '',
        subtituloCabecalho: instituicao.subtituloCabecalho || `${instituicao.cidade || ''}, ${instituicao.estado || ''}`,
        logoCabecalho: instituicao.logoCabecalho || '',
        corCabecalho: instituicao.corCabecalho || '#667eea',
        logoEscola: instituicao.logoEscola || '',
        descricaoLogo: instituicao.descricaoLogo || '',
        textoRodape: instituicao.textoRodape || `© ${new Date().getFullYear()} ${instituicao.nomeInstituicao || 'Escola'}. Todos os direitos reservados.`,
        enderecoRodape: instituicao.enderecoRodape || instituicao.endereco || '',
        telefoneRodape: instituicao.telefoneRodape || instituicao.telefone || '',
        emailRodape: instituicao.emailRodape || instituicao.email || '',
        siteRodape: instituicao.siteRodape || '',
        redesSociais: instituicao.redesSociais || {
          facebook: '',
          instagram: '',
          twitter: ''
        }
      });
      // Só travar o ref quando a mídia já estiver reidratada (logo presente)
      // ou quando realmente não existe mídia salva
      const mediaSalva = localStorage.getItem('cei_institution_media_v1');
      const temMediaSalva = mediaSalva && mediaSalva !== '{}';
      const midiaCarregada = !temMediaSalva || instituicao.logoEscola || instituicao.logoCabecalho;
      if (midiaCarregada) {
        instituicaoCarregadaRef.current = instituicaoAtiva;
      }
    }
  }, [instituicaoAtiva, instituicoes]);

  const handleImagemUpload = (e, tipo) => {
    const file = e.target.files[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) { // 2MB
        setErro('A imagem deve ter no máximo 2MB');
        return;
      }

      const reader = new FileReader();
      reader.onloadend = () => {
        if (tipo === 'logo') {
          setConfigs(prev => ({ ...prev, logoCabecalho: reader.result, logoEscola: reader.result }));
        } else if (tipo === 'emblema') {
          setConfigs(prev => ({ ...prev, logoEscola: reader.result, logoCabecalho: reader.result }));
        }
        setErro('');
      };
      reader.readAsDataURL(file);
    }
  };

  const handleRemoverImagem = (tipo) => {
    if (tipo === 'logo') {
      setConfigs(prev => ({ ...prev, logoCabecalho: '' }));
    } else if (tipo === 'emblema') {
      setConfigs(prev => ({ ...prev, logoEscola: '' }));
    }
  };

  const handleSalvar = () => {
    try {
      const instituicao = instituicoes.find(i => i.id === instituicaoAtiva);
      if (!instituicao) {
        setErro('Instituição não encontrada');
        return;
      }

      // Atualizar instituição com as novas configurações
      const instituicaoAtualizada = {
        ...instituicao,
        ...configs,
        // Manter compatibilidade com sistema de relatórios
        configRelatorios: {
          titulo: configs.tituloCabecalho,
          subtitulo: configs.subtituloCabecalho,
          logoUrl: configs.logoCabecalho || configs.logoEscola
        }
      };

      atualizarInstituicao(instituicao.id, instituicaoAtualizada);
      setSucesso(true);
      setErro('');

      setTimeout(() => {
        setSucesso(false);
      }, 3000);

    } catch (error) {
      setErro('Erro ao salvar configurações');
      console.error(error);
    }
  };

  return (
    <Layout title="Configurações da Escola">
      <Box sx={{ mb: 3, display: 'flex', alignItems: 'center', gap: 2 }}>
        <Settings sx={{ fontSize: 40, color: 'primary.main' }} />
        <Box>
          <Typography variant="h4" gutterBottom>
            Configurações da Escola
          </Typography>
          <Typography variant="body2" color="text.secondary">
            Personalize cabeçalho, emblema e rodapé dos documentos
          </Typography>
        </Box>
      </Box>

      {sucesso && (
        <Alert severity="success" sx={{ mb: 3 }} icon={<CheckCircle />}>
          Configurações salvas com sucesso!
        </Alert>
      )}

      {erro && (
        <Alert severity="error" sx={{ mb: 3 }}>
          {erro}
        </Alert>
      )}

{!isCloudEnabled && (
      <Alert
        severity="info"
        sx={{ mb: 3 }}
        action={
          <Button component={RouterLink} to="/configuracoes/nuvem" color="inherit" size="small" startIcon={<Cloud />}>
            Abrir Nuvem
          </Button>
        }
      >
        Acesso multi-dispositivo depende da configuracao da nuvem. Use a area "Nuvem" para verificar se os dados estao sincronizando entre aparelhos.
      </Alert>
      )}

      <Grid container spacing={3}>
        {/* Dados da Escola - Cabeçalho e Emblema unificados */}
        <Grid item xs={12}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <School color="primary" />
                Dados da Escola
              </Typography>
              <Divider sx={{ mb: 3 }} />

              <Grid container spacing={2}>
                <Grid item xs={12} md={8}>
                  <TextField
                    label="Nome da Escola (Título Principal)"
                    fullWidth
                    value={configs.tituloCabecalho}
                    onChange={(e) => setConfigs({ ...configs, tituloCabecalho: e.target.value })}
                    placeholder="Nome da instituição"
                    sx={{ mb: 2 }}
                  />

                  <TextField
                    label="Subtítulo (Slogan / Lema)"
                    fullWidth
                    value={configs.subtituloCabecalho}
                    onChange={(e) => setConfigs({ ...configs, subtituloCabecalho: e.target.value })}
                    placeholder="Slogan da escola, lema, etc."
                    sx={{ mb: 2 }}
                  />

                  <TextField
                    label="Descrição da Escola"
                    fullWidth
                    multiline
                    rows={2}
                    value={configs.descricaoLogo}
                    onChange={(e) => setConfigs({ ...configs, descricaoLogo: e.target.value })}
                    placeholder="Breve descrição sobre a escola"
                    sx={{ mb: 2 }}
                  />

                  <TextField
                    label="Cor Institucional"
                    type="color"
                    fullWidth
                    value={configs.corCabecalho}
                    onChange={(e) => setConfigs({ ...configs, corCabecalho: e.target.value })}
                  />
                </Grid>

                <Grid item xs={12} md={4}>
                  <Typography variant="subtitle2" gutterBottom>
                    Emblema / Logo da Escola
                  </Typography>
                  
                  {(configs.logoEscola || configs.logoCabecalho) ? (
                    <Box sx={{ textAlign: 'center' }}>
                      <Avatar
                        src={configs.logoEscola || configs.logoCabecalho}
                        alt="Emblema"
                        sx={{ width: 150, height: 150, mx: 'auto', mb: 1, border: '2px solid #eee' }}
                        imgProps={{ style: { objectFit: 'contain' } }}
                      />
                      <Button
                        size="small"
                        color="error"
                        startIcon={<Delete />}
                        onClick={() => {
                          setConfigs(prev => ({ ...prev, logoEscola: '', logoCabecalho: '' }));
                        }}
                      >
                        Remover
                      </Button>
                    </Box>
                  ) : (
                    <Box
                      sx={{
                        border: '2px dashed #ccc',
                        borderRadius: 1,
                        p: 3,
                        textAlign: 'center',
                        cursor: 'pointer',
                        '&:hover': { borderColor: 'primary.main' }
                      }}
                      onClick={() => emblemaInputRef.current?.click()}
                    >
                      <School sx={{ fontSize: 60, color: 'text.secondary', mb: 1 }} />
                      <Typography variant="body2" color="text.secondary">
                        Clique para adicionar emblema
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        (máx. 2MB)
                      </Typography>
                    </Box>
                  )}
                  <input
                    ref={emblemaInputRef}
                    type="file"
                    accept="image/*"
