import React, { useState } from 'react';
import Layout from '../components/Layout';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  IconButton,
  Chip,
  Grid,
  InputAdornment,
  Alert
} from '@mui/material';
import {
  Add,
  Edit,
  Delete,
  CheckCircle,
  Cancel,
  AttachMoney
} from '@mui/icons-material';
import { useData } from '../context/DataContext';

function ConfigurarPlanosPage() {
  const { planos, adicionarPlano, atualizarPlano, removerPlano } = useData();
  
  const [dialogAberto, setDialogAberto] = useState(false);
  const [planoEditando, setPlanoEditando] = useState(null);
  const [formData, setFormData] = useState({
    nome: '',
    dias: '',
    valor: ''
  });
  const [erro, setErro] = useState('');

  const handleAbrirDialog = (plano = null) => {
    if (plano) {
      setPlanoEditando(plano);
      setFormData({
        nome: plano.nome,
        dias: plano.dias.toString(),
        valor: plano.valor.toFixed(2)
      });
    } else {
      setPlanoEditando(null);
      setFormData({
        nome: '',
        dias: '',
        valor: ''
      });
    }
    setErro('');
    setDialogAberto(true);
  };

  const handleFecharDialog = () => {
    setDialogAberto(false);
    setPlanoEditando(null);
    setFormData({ nome: '', dias: '', valor: '' });
    setErro('');
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const validarFormulario = () => {
    if (!formData.nome.trim()) {
      setErro('Nome do plano é obrigatório');
      return false;
    }
    if (!formData.dias || parseInt(formData.dias) <= 0) {
      setErro('Quantidade de dias deve ser maior que zero');
      return false;
    }
    if (!formData.valor || parseFloat(formData.valor) <= 0) {
      setErro('Valor deve ser maior que zero');
      return false;
    }
    return true;
  };

  const handleSalvar = () => {
    if (!validarFormulario()) return;

    const dadosPlano = {
      nome: formData.nome.trim(),
      dias: parseInt(formData.dias),
      valor: parseFloat(formData.valor)
    };

    if (planoEditando) {
      atualizarPlano(planoEditando.id, dadosPlano);
    } else {
      adicionarPlano(dadosPlano);
    }

    handleFecharDialog();
  };

  const handleToggleAtivo = (plano) => {
    atualizarPlano(plano.id, { ativo: !plano.ativo });
  };

  const handleRemover = (id) => {
    if (window.confirm('Deseja realmente remover este plano? Esta ação não pode ser desfeita.')) {
      removerPlano(id);
    }
  };

  const calcularMeses = (dias) => {
    const meses = Math.floor(dias / 30);
    const diasRestantes = dias % 30;
    if (meses === 0) return `${dias} dias`;
    if (diasRestantes === 0) return `${meses} ${meses === 1 ? 'mês' : 'meses'}`;
    return `${meses} ${meses === 1 ? 'mês' : 'meses'} e ${diasRestantes} dias`;
  };

  const calcularValorDiario = (valor, dias) => {
    return (valor / dias).toFixed(2);
  };

  return (
    <Layout title="Configurar Planos">
      <Box sx={{ mb: 3 }}>
        <Grid container spacing={2} alignItems="center">
          <Grid item xs={12} md={8}>
            <Alert severity="info">
              Configure os planos que estarão disponíveis para as escolas escolherem durante o cadastro.
            </Alert>
          </Grid>
          <Grid item xs={12} md={4} textAlign="right">
            <Button
              variant="contained"
              startIcon={<Add />}
              onClick={() => handleAbrirDialog()}
            >
              Adicionar Plano
            </Button>
          </Grid>
        </Grid>
      </Box>

      <Card>
        <CardContent>
          <Typography variant="h6" gutterBottom>
            Planos Cadastrados
          </Typography>

          <TableContainer component={Paper} variant="outlined">
            <Table>
              <TableHead>
                <TableRow sx={{ bgcolor: 'primary.main' }}>
                  <TableCell sx={{ color: 'white', fontWeight: 'bold' }}>Nome do Plano</TableCell>
                  <TableCell sx={{ color: 'white', fontWeight: 'bold' }}>Duração</TableCell>
                  <TableCell sx={{ color: 'white', fontWeight: 'bold' }}>Dias</TableCell>
                  <TableCell sx={{ color: 'white', fontWeight: 'bold' }}>Valor Total</TableCell>
                  <TableCell sx={{ color: 'white', fontWeight: 'bold' }}>Valor/Dia</TableCell>
                  <TableCell sx={{ color: 'white', fontWeight: 'bold' }}>Status</TableCell>
                  <TableCell sx={{ color: 'white', fontWeight: 'bold' }} align="center">Ações</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {planos.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={7} align="center">
                      <Typography color="textSecondary">
                        Nenhum plano cadastrado. Clique em "Adicionar Plano" para começar.
                      </Typography>
                    </TableCell>
                  </TableRow>
                ) : (
                  planos.map((plano) => (
                    <TableRow key={plano.id} hover>
                      <TableCell>
                        <Typography fontWeight="bold">{plano.nome}</Typography>
                      </TableCell>
                      <TableCell>{calcularMeses(plano.dias)}</TableCell>
                      <TableCell>{plano.dias} dias</TableCell>
                      <TableCell>
                        <Typography color="primary" fontWeight="bold">
                          R$ {plano.valor.toFixed(2)}
                        </Typography>
                      </TableCell>
                      <TableCell>
                        <Typography variant="body2" color="textSecondary">
                          R$ {calcularValorDiario(plano.valor, plano.dias)}
                        </Typography>
                      </TableCell>
                      <TableCell>
                        {plano.ativo ? (
                          <Chip
                            icon={<CheckCircle />}
                            label="Ativo"
                            color="success"
                            size="small"
                          />
                        ) : (
                          <Chip
                            icon={<Cancel />}
                            label="Inativo"
                            color="default"
                            size="small"
                          />
                        )}
                      </TableCell>
                      <TableCell align="center">
                        <Box sx={{ display: 'flex', gap: 1, justifyContent: 'center' }}>
                          <IconButton
                            size="small"
                            color="primary"
                            onClick={() => handleAbrirDialog(plano)}
                            title="Editar"
                          >
                            <Edit />
                          </IconButton>
                          <IconButton
                            size="small"
                            color={plano.ativo ? 'warning' : 'success'}
                            onClick={() => handleToggleAtivo(plano)}
                            title={plano.ativo ? 'Desativar' : 'Ativar'}
                          >
                            {plano.ativo ? <Cancel /> : <CheckCircle />}
                          </IconButton>
                          <IconButton
                            size="small"
                            color="error"
                            onClick={() => handleRemover(plano.id)}
                            title="Remover"
                          >
                            <Delete />
                          </IconButton>
                        </Box>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </TableContainer>

          {planos.length > 0 && (
            <Box sx={{ mt: 2 }}>
              <Typography variant="caption" color="textSecondary">
                Total de planos: {planos.length} | Ativos: {planos.filter(p => p.ativo).length}
              </Typography>
            </Box>
          )}
        </CardContent>
      </Card>

      {/* Dialog de Adicionar/Editar Plano */}
      <Dialog open={dialogAberto} onClose={handleFecharDialog} maxWidth="sm" fullWidth>
        <DialogTitle>
          {planoEditando ? 'Editar Plano' : 'Adicionar Novo Plano'}
        </DialogTitle>
        <DialogContent>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 1 }}>
            {erro && (
              <Alert severity="error" onClose={() => setErro('')}>
                {erro}
              </Alert>
            )}

            <TextField
              label="Nome do Plano"
              name="nome"
              value={formData.nome}
              onChange={handleChange}
              fullWidth
              required
              placeholder="Ex: 1 Mês (30 dias), 6 Meses, Anual"
              helperText="Nome que será exibido para os clientes"
            />

            <TextField
              label="Quantidade de Dias"
              name="dias"
              type="number"
              value={formData.dias}
              onChange={handleChange}
              fullWidth
              required
              inputProps={{ min: 1 }}
              helperText={formData.dias ? `Equivale a: ${calcularMeses(parseInt(formData.dias))}` : 'Duração do plano em dias'}
            />

            <TextField
              label="Valor do Plano"
              name="valor"
              type="number"
              value={formData.valor}
              onChange={handleChange}
              fullWidth
              required
              inputProps={{ min: 0.01, step: 0.01 }}
              InputProps={{
                startAdornment: <InputAdornment position="start">R$</InputAdornment>,
              }}
              helperText={formData.valor && formData.dias 
                ? `Valor por dia: R$ ${calcularValorDiario(parseFloat(formData.valor), parseInt(formData.dias))}`
                : 'Valor total do plano'
              }
            />

            {formData.valor && formData.dias && (
              <Paper sx={{ p: 2, bgcolor: 'primary.light', color: 'white' }}>
                <Typography variant="subtitle2" gutterBottom>
                  Resumo do Plano:
                </Typography>
                <Typography variant="body2">
                  • Duração: {calcularMeses(parseInt(formData.dias))} ({formData.dias} dias)
                </Typography>
                <Typography variant="body2">
                  • Valor Total: R$ {parseFloat(formData.valor).toFixed(2)}
                </Typography>
                <Typography variant="body2">
                  • Valor Diário: R$ {calcularValorDiario(parseFloat(formData.valor), parseInt(formData.dias))}
                </Typography>
              </Paper>
            )}
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleFecharDialog}>Cancelar</Button>
          <Button onClick={handleSalvar} variant="contained">
            {planoEditando ? 'Salvar Alterações' : 'Adicionar Plano'}
          </Button>
        </DialogActions>
      </Dialog>
    </Layout>
  );
}

export default ConfigurarPlanosPage;

import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import Layout from '../components/Layout';
import { 
  Card, 
  CardContent, 
  Typography, 
  Grid, 
  Box,
  Chip,
  Alert,
  Snackbar,
  Button,
  Tooltip
} from '@mui/material';
import { 
  MenuBook, 
  Inventory, 
  People, 
  Assignment,
  Warning,
  Error,
  Assessment,
  Search,
  EmojiEvents,
  AccountBalanceWallet,
  LibraryBooks,
  AssignmentReturn,
  Description,
  Receipt,
  ContentCopy,
  PrintOutlined,
  Backup,
  CloudDownload,
  CloudUpload
} from '@mui/icons-material';
import { useData } from '../context/DataContext';
import TermoEmprestimo from '../components/TermoEmprestimo';

const DEMO_DEVICE_ID_KEY = 'cei_demo_device_id';

const formatarIdentificadorDemo = (deviceId) => {
  if (!deviceId) return 'Não disponível';
  const partes = deviceId.split('-');
  const base = (partes[partes.length - 1] || deviceId).slice(0, 6).toUpperCase();
  return `DEMO-${base}`;
};

function DashboardPage() {
  const DATA_LANCAMENTO_TESTE_EMAIL = new Date('2026-02-14T00:00:00');
  const DIAS_DESTAQUE_NOVO = 30;

  const navigate = useNavigate();
  const { 
    livros, 
    patrimonio, 
    clientes, 
    emprestimos, 
    usuarioLogado, 
    instituicoes, 
    instituicaoAtiva,
    sincronizando,
    sincronizarNuvemAgora,
    calcularProximoVencimento,
    exportarDados,
    importarDados
  } = useData();
  const [alertaFinanceiro, setAlertaFinanceiro] = useState(null);
  const [termoOpen, setTermoOpen] = useState(false);
  const [tipoTermo, setTipoTermo] = useState('branco');
  const [snackbar, setSnackbar] = useState({ open: false, mensagem: '', tipo: 'info' });
  const [ultimaAtualizacaoDados, setUltimaAtualizacaoDados] = useState(null);

  const diasDesdeLancamento = Math.floor((Date.now() - DATA_LANCAMENTO_TESTE_EMAIL.getTime()) / (1000 * 60 * 60 * 24));
  const exibirBadgeNovoTesteEmail = diasDesdeLancamento >= 0 && diasDesdeLancamento <= DIAS_DESTAQUE_NOVO;
  const exibirInfoSessaoDemo = Boolean(usuarioLogado?.contaTeste);
  const identificadorDemo = formatarIdentificadorDemo(localStorage.getItem(DEMO_DEVICE_ID_KEY));

  const handleCopiarIdentificadorDemo = async () => {
    try {
      await navigator.clipboard.writeText(identificadorDemo);
      setSnackbar({
        open: true,
        mensagem: `Identificador copiado: ${identificadorDemo}`,
        tipo: 'success'
      });
    } catch (error) {
      console.error('Erro ao copiar identificador demo:', error);
      setSnackbar({
        open: true,
        mensagem: `Não foi possível copiar automaticamente. ID: ${identificadorDemo}`,
        tipo: 'warning'
      });
    }
  };

  const fecharSnackbar = (_, reason) => {
    if (reason === 'clickaway') return;
    setSnackbar(prev => ({ ...prev, open: false }));
  };
  
  // Funções de backup
  const handleExportarDados = () => {
    const resultado = exportarDados();
    if (resultado.sucesso) {
      setSnackbar({
        open: true,
        mensagem: resultado.mensagem,
        tipo: 'success'
      });
    } else {
      setSnackbar({
        open: true,
        mensagem: resultado.mensagem,
        tipo: 'error'
      });
    }
  };
  
  const handleImportarDados = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json';
    input.onchange = async (e) => {
      const file = e.target.files[0];
      if (file) {
        try {
          const resultado = await importarDados(file);
          setSnackbar({
            open: true,
            mensagem: resultado.mensagem,
            tipo: 'success'
          });
          setUltimaAtualizacaoDados(new Date());
        } catch (error) {
          setSnackbar({
            open: true,
            mensagem: error?.mensagem || 'Erro ao importar dados.',
            tipo: 'error'
          });
        }
      }
    };
    input.click();
  };

  // Buscar informações da instituição ativa
  const instituicaoInfo = instituicoes.find(i => i.id === instituicaoAtiva);

  // Verificar situação financeira
  useEffect(() => {
    if (instituicaoInfo && usuarioLogado?.perfil !== 'SuperAdmin') {
      const statusFinanceiro = instituicaoInfo.statusFinanceiro || 'em_dia';
      
      if (statusFinanceiro === 'bloqueado_financeiro') {
        setAlertaFinanceiro({
          tipo: 'error',
          titulo: 'Conta Bloqueada por Inadimplência',
          mensagem: 'Seu acesso está bloqueado. Entre em contato com o administrador.'
        });
      } else if (statusFinanceiro === 'atrasado') {
        setAlertaFinanceiro({
          tipo: 'error',
          titulo: 'Pagamento em Atraso',
          mensagem: 'Seu pagamento está atrasado. Regularize o quanto antes para evitar bloqueio.'
        });
      } else {
        // Verificar dias para vencimento
        const proximoVencimento = calcularProximoVencimento(instituicaoInfo.id);
        if (proximoVencimento) {
          const hoje = new Date();
          const diffTime = proximoVencimento - hoje;
          const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
          
          if (diffDays <= 5 && diffDays > 0) {
            setAlertaFinanceiro({
              tipo: 'warning',
              titulo: 'Vencimento Próximo',
              mensagem: `Seu pagamento vence em ${diffDays} dia${diffDays !== 1 ? 's' : ''}. Fique atento!`
            });
          } else if (diffDays <= 0) {
            setAlertaFinanceiro({
              tipo: 'error',
              titulo: 'Pagamento Vencido',
              mensagem: 'Seu pagamento está vencido. Regularize o quanto antes.'
            });
          }
        }
      }
    }
  }, [instituicaoInfo, usuarioLogado]);

  const emprestimosAtivos = emprestimos.filter(e => e.status === 'ativo').length;

  const resumoAcervo = useMemo(() => {
    const ativosMap = new Map();
    emprestimos
      .filter(e => String(e.status || '').toLowerCase() === 'ativo')
      .forEach(e => {
        const lid = String(e.livroId || '');
        if (lid) ativosMap.set(lid, (ativosMap.get(lid) || 0) + 1);
      });
    let totalExemplares = 0;
    let disponiveis = 0;
    livros.forEach(livro => {
      if (livro.baixa) return;
      const qtd = Math.max(Number(livro.quantidade) || 0, 0);
      totalExemplares += qtd;
      disponiveis += Math.max(qtd - (ativosMap.get(String(livro.id)) || 0), 0);
    });
    return { totalExemplares, emprestados: emprestimosAtivos, disponiveis };
  }, [livros, emprestimos, emprestimosAtivos]);

  const emprestimosVencidos = emprestimos.filter(e => {
    if (e.status !== 'ativo') return false;
    const hoje = new Date();
    const dataDevolucao = new Date(e.dataDevolucao);
    return dataDevolucao < hoje;
