                    <Stack spacing={1}>
                      <Chip label="SSL/TLS (HTTPS)" color="error" size="small" />
                      <Chip label="Row Level Security (RLS)" color="error" size="small" />
                      <Chip label="Supabase Auth" color="error" size="small" />
