const formatDateForInput = (date) => {
  const yyyy = date.getFullYear();
  const mm = String(date.getMonth() + 1).padStart(2, '0');
  const dd = String(date.getDate()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}`;
};

const normalizarTexto = (valor) => {
  return String(valor || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[º°]/g, 'o')
    .replace(/[ª]/g, 'a')
    .replace(/[^a-z0-9\s-]/g, ' ')
    .replace(/\s+/g, ' ');
};

const compactarTexto = (valor) => normalizarTexto(valor).replace(/[^a-z0-9]/g, '');

const tokenizarTexto = (...valores) => {
  const texto = normalizarTexto(valores.filter(Boolean).join(' '));
  if (!texto) return [];
  return texto.split(/[^a-z0-9]+/).filter(Boolean);
};

const extrairNumeroSerie = (valor) => {
  const texto = normalizarTexto(valor);
  if (!texto) return '';

  const match = texto.match(/(\d{1,2})\s*(?:a|o)?\s*(?:serie|ano)?/);
  return match ? match[1] : '';
};

const extrairSalaTurma = (valor) => {
  const texto = normalizarTexto(valor).toUpperCase();
  if (!texto) return '';

  const padraoIB = texto.match(/\b[IA]\s*-\s*([A-Z])\b/);
  if (padraoIB) {
    return padraoIB[1];
  }

  const inicio = texto.match(/^([A-Z])\b/);
  if (inicio) {
    return inicio[1];
  }

  const final = texto.match(/\b([A-Z])\b$/);
  if (final) {
    return final[1];
  }

  return '';
};

const extrairCursoAcademico = (...valores) => {
  const tokens = tokenizarTexto(...valores);
  if (tokens.length === 0) return '';

  const tokenSet = new Set(tokens);
  const textoCompacto = tokens.join('');

  if (tokens.some((token) => token.includes('farm'))) return 'farm';
  if (tokens.some((token) => token.includes('mark')) || tokenSet.has('dig')) return 'mark';
  if (tokens.some((token) => token.includes('emp'))) return 'emp';
  if (tokens.some((token) => token.includes('prop')) || tokens.some((token) => token.includes('admi'))) return 'prop';

  const temDs = tokenSet.has('ds')
    || (tokenSet.has('d') && tokenSet.has('s'))
    || tokens.some((token) => token.includes('des'))
    || tokens.some((token) => token === 'sis');

  if (temDs || textoCompacto.includes('dessis')) return 'ds';
  if (tokenSet.has('int')) return 'int';

  return '';
};

const buildLegacyTurmaKey = (serieNome, turmaNome) => {
  return `legacy:${normalizarTexto(serieNome)}|${normalizarTexto(turmaNome)}`;
};

const extrairSerieTurmaCombinada = (valor) => {
  const textoNormalizado = String(valor || '')
    .replace(/[–—]/g, ' - ')
    .replace(/\s+/g, ' ')
    .trim();

  if (!textoNormalizado) {
    return { serie: '', turma: '' };
  }

  const partes = textoNormalizado
    .split(' - ')
    .map((item) => item.trim())
    .filter(Boolean);

  if (partes.length >= 2) {
    return {
      serie: partes.slice(0, -1).join(' - ').trim(),
      turma: partes[partes.length - 1].trim()
    };
  }

  const tokens = textoNormalizado.split(' ').map((token) => token.trim()).filter(Boolean);
  if (tokens.length >= 2) {
    const turmaSuffix = tokens[tokens.length - 1];
    const serieBase = tokens.slice(0, -1).join(' ').trim();
    const serieBaseNormalizada = normalizarTexto(serieBase);
    const pareceSufixoTurma = /^[IVXLCDM]{1,4}-[A-Z]$/i.test(turmaSuffix) || /^[A-Z]$/i.test(turmaSuffix);
    const pareceSerieAcademica = /\d/.test(serieBase)
      || serieBaseNormalizada.includes('ano')
      || serieBaseNormalizada.includes('serie');

    if (pareceSufixoTurma && pareceSerieAcademica) {
      return {
        serie: serieBase,
        turma: turmaSuffix.toUpperCase()
      };
    }
  }

  return { serie: textoNormalizado, turma: '' };
};

const obterTurmaSerieTextoAluno = (aluno) => {
  const turmaDireta = String(aluno?.turma || aluno?.nomeTurma || '').trim();
  const serieDireta = String(aluno?.serie || aluno?.nomeSerie || '').trim();
  const serieDiretaExtraida = serieDireta
    ? extrairSerieTurmaCombinada(serieDireta)
    : { serie: '', turma: '' };
  const serieDiretaTemTurma = Boolean(serieDiretaExtraida.turma);
  const turmaDiretaConfereComSerie = serieDiretaTemTurma
    && normalizarTexto(turmaDireta) === normalizarTexto(serieDiretaExtraida.turma);

  if (turmaDireta || serieDireta) {
    return {
      turma: turmaDireta || serieDiretaExtraida.turma || '',
      serie: serieDiretaTemTurma && (!turmaDireta || turmaDiretaConfereComSerie)
        ? serieDiretaExtraida.serie
        : serieDireta
    };
  }

  const campoCombinado = String(
    aluno?.anoSerieTurma
    || aluno?.serieTurma
    || aluno?.turmaSerie
    || aluno?.serie_turma
    || ''
  ).trim();

  if (!campoCombinado) {
    return { turma: '', serie: '' };
  }

  const extraido = extrairSerieTurmaCombinada(campoCombinado);
  return {
    turma: String(extraido?.turma || '').trim(),
    serie: String(extraido?.serie || '').trim()
  };
};

const seriesSaoCompativeis = (serieA, serieB) => {
  const serieANormalizada = normalizarTexto(serieA);
  const serieBNormalizada = normalizarTexto(serieB);
  const serieACompacta = compactarTexto(serieA);
  const serieBCompacta = compactarTexto(serieB);
  const numeroSerieA = extrairNumeroSerie(serieA);
  const numeroSerieB = extrairNumeroSerie(serieB);

  if (!serieANormalizada || !serieBNormalizada) {
    return true;
  }

  return (
    serieANormalizada === serieBNormalizada
    || (serieACompacta.length > 0 && serieBCompacta === serieACompacta)
    || (serieACompacta.length > 0 && serieBCompacta.includes(serieACompacta))
    || (serieACompacta.length > 0 && serieACompacta.includes(serieBCompacta))
    || (numeroSerieA && numeroSerieB && numeroSerieA === numeroSerieB)
  );
};

const turmasSaoCompativeis = (turmaA, turmaB) => {
  const nomeTurmaA = String(turmaA?.nomeTurma || '').trim();
  const nomeTurmaB = String(turmaB?.nomeTurma || '').trim();
  const nomeSerieA = String(turmaA?.nomeSerie || '').trim();
  const nomeSerieB = String(turmaB?.nomeSerie || '').trim();

  const nomeTurmaANormalizado = normalizarTexto(nomeTurmaA);
  const nomeTurmaBNormalizado = normalizarTexto(nomeTurmaB);
  const nomeTurmaACompacto = compactarTexto(nomeTurmaA);
  const nomeTurmaBCompacto = compactarTexto(nomeTurmaB);

  const porNomeDireto =
    (nomeTurmaANormalizado && nomeTurmaANormalizado === nomeTurmaBNormalizado)
    || (nomeTurmaACompacto && nomeTurmaACompacto === nomeTurmaBCompacto)
    || (nomeTurmaACompacto && nomeTurmaBCompacto && (
      nomeTurmaACompacto.includes(nomeTurmaBCompacto)
      || nomeTurmaBCompacto.includes(nomeTurmaACompacto)
    ));

  if (porNomeDireto && seriesSaoCompativeis(nomeSerieA, nomeSerieB)) {
    return true;
  }

  const salaA = extrairSalaTurma(nomeTurmaA);
  const salaB = extrairSalaTurma(nomeTurmaB);
  const cursoA = extrairCursoAcademico(nomeTurmaA, nomeSerieA);
  const cursoB = extrairCursoAcademico(nomeTurmaB, nomeSerieB);

  const porAssinatura =
    Boolean(salaA)
    && Boolean(salaB)
    && salaA === salaB
    && (!cursoA || !cursoB || cursoA === cursoB)
    && seriesSaoCompativeis(nomeSerieA, nomeSerieB);

  return porAssinatura;
};

const isAlunoDaTurmaSelecionada = (aluno, turmaSelecionadaInfo, turmasAcademicasMap) => {
  if (!turmaSelecionadaInfo) {
    return true;
  }

  const chaveSelecionada = String(turmaSelecionadaInfo.key || '').trim();
  const turmaSelecionadaAcademica = turmasAcademicasMap.has(chaveSelecionada)
    ? turmasAcademicasMap.get(chaveSelecionada)
    : null;

  const turmaAlunoResolvida = localizarTurmaAcademicaDoAluno(aluno, turmasAcademicasMap);
  if (turmaAlunoResolvida?.id !== undefined && turmaAlunoResolvida?.id !== null) {
    if (String(turmaAlunoResolvida.id) === chaveSelecionada) {
      return true;
    }

    if (turmaSelecionadaAcademica) {
      return turmasSaoCompativeis(turmaAlunoResolvida, turmaSelecionadaAcademica);
    }

    const chaveLegacyResolvida = buildLegacyTurmaKey(
      turmaAlunoResolvida.nomeSerie,
      turmaAlunoResolvida.nomeTurma
    );

    if (chaveLegacyResolvida === chaveSelecionada) {
      return true;
    }
  }

  const turmaSerieAluno = obterTurmaSerieTextoAluno(aluno);
  const turmaNomeAluno = String(turmaSerieAluno.turma || '').trim();
  const serieNomeAluno = String(turmaSerieAluno.serie || '').trim();
  const chaveLegacyAluno = buildLegacyTurmaKey(serieNomeAluno, turmaNomeAluno);
  const turmaNomeSelecionada = String(
    turmaSelecionadaAcademica?.nomeTurma || turmaSelecionadaInfo?.nomeTurma || ''
  ).trim();
  const serieNomeSelecionada = String(
    turmaSelecionadaAcademica?.nomeSerie || turmaSelecionadaInfo?.nomeSerie || ''
  ).trim();

  if (chaveLegacyAluno === chaveSelecionada) {
    return true;
  }

  if (!turmaNomeAluno || !turmaNomeSelecionada) {
    return false;
  }

  return turmasSaoCompativeis(
    { nomeTurma: turmaNomeAluno, nomeSerie: serieNomeAluno },
    { nomeTurma: turmaNomeSelecionada, nomeSerie: serieNomeSelecionada }
  );
};

const localizarTurmaAcademicaDoAluno = (aluno, turmasAcademicasMap) => {
  const turmaId = String(aluno?.turmaId || '').trim();
  if (turmaId && turmasAcademicasMap.has(turmaId)) {
    return turmasAcademicasMap.get(turmaId);
  }

  const turmaSerieAluno = obterTurmaSerieTextoAluno(aluno);
  const turmaNomeAluno = String(turmaSerieAluno.turma || '').trim();
  if (!turmaNomeAluno) {
    return null;
  }

  const serieNomeAluno = String(turmaSerieAluno.serie || '').trim();
  const serieIdAluno = String(aluno?.serieId || '').trim();

  const turmaNomeNormalizado = normalizarTexto(turmaNomeAluno);
  const turmaNomeCompacto = compactarTexto(turmaNomeAluno);
  const serieNomeNormalizado = normalizarTexto(serieNomeAluno);
  const serieNomeCompacto = compactarTexto(serieNomeAluno);
  const numeroSerieAluno = extrairNumeroSerie(serieNomeAluno);
  const salaAluno = extrairSalaTurma(turmaNomeAluno);
  const cursoAluno = extrairCursoAcademico(turmaNomeAluno, serieNomeAluno);

  let melhorPorNome = null;
  let melhorPorAssinatura = null;

  for (const turma of turmasAcademicasMap.values()) {
    const nomeTurma = String(turma?.nomeTurma || '').trim();
    if (!nomeTurma) continue;

    const nomeSerie = String(turma?.nomeSerie || '').trim();
    const turmaSerieId = String(turma?.serieId || '').trim();
    const nomeTurmaNormalizado = normalizarTexto(nomeTurma);
    const nomeTurmaCompacto = compactarTexto(nomeTurma);
    const nomeSerieNormalizado = normalizarTexto(nomeSerie);
    const nomeSerieCompacto = compactarTexto(nomeSerie);
    const numeroSerieTurma = extrairNumeroSerie(nomeSerie);
    const salaTurma = extrairSalaTurma(nomeTurma);
    const cursoTurma = extrairCursoAcademico(nomeTurma, nomeSerie);

    const serieCompativel =
      !serieNomeNormalizado
      || !nomeSerieNormalizado
      || nomeSerieNormalizado === serieNomeNormalizado
      || (serieNomeCompacto.length > 0 && nomeSerieCompacto === serieNomeCompacto)
      || (serieNomeCompacto.length > 0 && nomeSerieCompacto.includes(serieNomeCompacto))
      || (serieNomeCompacto.length > 0 && serieNomeCompacto.includes(nomeSerieCompacto))
      || (numeroSerieAluno && numeroSerieTurma && numeroSerieAluno === numeroSerieTurma)
      || (serieIdAluno && turmaSerieId && serieIdAluno === turmaSerieId);

    const nomeCompativel =
      (turmaNomeNormalizado.length > 0 && nomeTurmaNormalizado === turmaNomeNormalizado)
      || (turmaNomeCompacto.length > 0 && nomeTurmaCompacto === turmaNomeCompacto);

    if (nomeCompativel && serieCompativel) {
      return turma;
    }

    if (!melhorPorNome && nomeCompativel) {
      melhorPorNome = turma;
    }

    const cursoCompativel = cursoAluno ? (!cursoTurma || cursoAluno === cursoTurma) : !cursoTurma;
    const porAssinatura =
      Boolean(salaAluno)
      && Boolean(salaTurma)
      && salaAluno === salaTurma
      && cursoCompativel
      && (!numeroSerieAluno || !numeroSerieTurma || numeroSerieAluno === numeroSerieTurma);

    if (!melhorPorAssinatura && porAssinatura && serieCompativel) {
      melhorPorAssinatura = turma;
    }
  }

  return melhorPorNome || melhorPorAssinatura || null;
};

const isTipoDidatico = (tipoLivro) => {
  const tipoNormalizado = normalizarTexto(tipoLivro);
  return (
    tipoNormalizado === 'didatico'
    || tipoNormalizado === 'didaticos'
    || tipoNormalizado === 'livro didatico'
  );
};

const isTipoParadidatico = (tipoLivro) => {
  const tipoNormalizado = normalizarTexto(tipoLivro);
  return (
    tipoNormalizado === ''
    || tipoNormalizado === 'paradidatico'
    || tipoNormalizado === 'paradidaticos'
    || tipoNormalizado === 'livro paradidatico'
  );
};

const isTipoLivroProfessor = (tipoLivro) => {
  const tipoNormalizado = normalizarTexto(tipoLivro);
  return (
    tipoNormalizado === 'livro do professor'
    || tipoNormalizado === 'livro professor'
    || tipoNormalizado === 'material do professor'
    || tipoNormalizado === 'professor'
  );
};

const isAlunoLote = (cliente) => {
  const tipoNormalizado = normalizarTexto(cliente?.tipo);
  const categoriaNormalizada = normalizarTexto(cliente?.categoria);
  const turmaSerieAluno = obterTurmaSerieTextoAluno(cliente);
  const possuiCampoCombinado = String(
    cliente?.anoSerieTurma
    || cliente?.serieTurma
    || cliente?.turmaSerie
    || cliente?.serie_turma
    || ''
  ).trim().length > 0;

  const possuiVinculoAcademico =
    String(cliente?.turmaId || '').trim().length > 0
    || String(cliente?.serieId || '').trim().length > 0
    || normalizarTexto(turmaSerieAluno.turma).length > 0
    || normalizarTexto(turmaSerieAluno.serie).length > 0
    || possuiCampoCombinado;

  const perfisNaoAluno = [
    'professor',
    'funcionario',
    'funcionario administrativo',
    'bibliotecario',
    'coordenador',
    'diretor',
    'gestor',
    'servidor',
    'admin',
    'administrador',
    'comunidade'
  ];

  if (tipoNormalizado === 'aluno' || categoriaNormalizada === 'estudante') {
    return true;
  }

  if (tipoNormalizado === 'leitor') {
    return possuiVinculoAcademico;
  }

  if (possuiVinculoAcademico) {
    return !perfisNaoAluno.includes(tipoNormalizado) && !perfisNaoAluno.includes(categoriaNormalizada);
  }

  return false;
};

const obterChaveTurmaAluno = (aluno, turmasAcademicasMap) => {
  const turmaAssociada = localizarTurmaAcademicaDoAluno(aluno, turmasAcademicasMap);
  if (turmaAssociada?.id !== undefined && turmaAssociada?.id !== null) {
    return String(turmaAssociada.id);
  }

  const turmaSerieAluno = obterTurmaSerieTextoAluno(aluno);
  const turmaNome = String(turmaSerieAluno.turma || '').trim();
  if (!turmaNome) {
    return '';
  }

  const serieNome = String(turmaSerieAluno.serie || '').trim();
  return buildLegacyTurmaKey(serieNome, turmaNome);
};

const obterRotuloTurmaAluno = (aluno, turmasAcademicasMap) => {
  const turmaAssociada = localizarTurmaAcademicaDoAluno(aluno, turmasAcademicasMap);

  if (turmaAssociada) {
    const turma = turmaAssociada;
    const nomeTurma = String(turma?.nomeTurma || '').trim();
    const nomeSerie = String(turma?.nomeSerie || '').trim();
    return nomeSerie ? `${nomeSerie} - ${nomeTurma}` : nomeTurma;
  }

  const turmaSerieAluno = obterTurmaSerieTextoAluno(aluno);
  const nomeTurmaLegacy = String(turmaSerieAluno.turma || '').trim();
  const nomeSerieLegacy = String(turmaSerieAluno.serie || '').trim();
  if (!nomeTurmaLegacy) {
    return 'Sem turma';
  }

  return nomeSerieLegacy ? `${nomeSerieLegacy} - ${nomeTurmaLegacy}` : nomeTurmaLegacy;
};

const campoPadraoSx = {
  '& .MuiOutlinedInput-root': {
    minHeight: 56
  }
};

const cartaoResumoSx = {
  p: 2,
  minHeight: 92,
  height: '100%',
  display: 'flex',
  flexDirection: 'column',
  justifyContent: 'center'
};

const botaoAcaoSx = {
  minHeight: 42,
  minWidth: { xs: '100%', sm: 180 }
};

export default function EmprestimoDidaticoLotePage() {
  const navigate = useNavigate();

  const {
    clientes,
    livros,
    emprestimos,
    adicionarEmprestimo,
    devolverLivro,
    adicionarCliente,
    turmasAcademicas
  } = useData();

  const [turmaSelecionada, setTurmaSelecionada] = useState('');
  const [modoSelecaoAlunos, setModoSelecaoAlunos] = useState('turma');
  const [tipoAcervoSelecionado, setTipoAcervoSelecionado] = useState('todos');
  const [livrosSelecionados, setLivrosSelecionados] = useState([]);
  const [alunosSelecionadosMapa, setAlunosSelecionadosMapa] = useState({});
  const [dataDevolucaoPrevista, setDataDevolucaoPrevista] = useState(() => {
    const data = new Date();
    data.setDate(data.getDate() + 30);
    return formatDateForInput(data);
  });
  const [selecoes, setSelecoes] = useState({});
  const [processando, setProcessando] = useState(false);
  const [resultadoAplicacao, setResultadoAplicacao] = useState(null);
  const [confirmacaoAberta, setConfirmacaoAberta] = useState(false);
  const [resumoConfirmacao, setResumoConfirmacao] = useState(null);
  const [termosLote, setTermosLote] = useState([]);
  const [indiceTermoLote, setIndiceTermoLote] = useState(0);
  const [termoLoteOpen, setTermoLoteOpen] = useState(false);
  const [buscaLeitorLote, setBuscaLeitorLote] = useState('');
  const [cadastroLeitorLoteOpen, setCadastroLeitorLoteOpen] = useState(false);
  const [novoLeitorLote, setNovoLeitorLote] = useState({
    nome: '',
    cpf: '',
    telefone: '',
    email: '',
    endereco: '',
    tipo: 'Aluno',
    categoria: 'Estudante',
    matricula: '',
    serie: '',
    serieId: '',
    turma: '',
    turmaId: '',
    ativo: true
  });

  const observacaoPadraoAplicada = 'Empréstimo em lote por turma';

  const isEmprestimoAtivo = (status) => {
    const statusNormalizado = String(status || '').toLowerCase();
    return statusNormalizado === 'ativo' || statusNormalizado === 'emprestado';
  };

  const turmasAcademicasMap = useMemo(() => {
    const map = new Map();
    turmasAcademicas.forEach((turma) => {
      map.set(String(turma.id), turma);
    });
    return map;
  }, [turmasAcademicas]);

  const turmasDisponiveis = useMemo(() => {
    const mapaTurmas = new Map();

    turmasAcademicas.forEach((turma) => {
      const nomeTurma = String(turma.nomeTurma || '').trim();
      if (!nomeTurma) return;

      const nomeSerie = String(turma.nomeSerie || '').trim();
      const chave = String(turma.id);

      mapaTurmas.set(chave, {
        key: chave,
        nomeTurma,
        nomeSerie,
        rotulo: nomeSerie ? `${nomeSerie} - ${nomeTurma}` : nomeTurma
      });
    });

    clientes
      .filter((cliente) => isAlunoLote(cliente))
      .forEach((cliente) => {
        const turmaSerieAluno = obterTurmaSerieTextoAluno(cliente);
        const turmaNome = String(turmaSerieAluno.turma || '').trim();
        if (!turmaNome) return;

        const turmaAssociada = localizarTurmaAcademicaDoAluno(cliente, turmasAcademicasMap);
        if (turmaAssociada?.id !== undefined && turmaAssociada?.id !== null) {
          return;
        }

        const serieNome = String(turmaSerieAluno.serie || '').trim();
        const chave = buildLegacyTurmaKey(serieNome, turmaNome);

        if (!mapaTurmas.has(chave)) {
          mapaTurmas.set(chave, {
            key: chave,
            nomeTurma: turmaNome,
            nomeSerie: serieNome,
            rotulo: serieNome ? `${serieNome} - ${turmaNome}` : turmaNome
          });
        }
      });

    return Array.from(mapaTurmas.values()).sort((a, b) => a.rotulo.localeCompare(b.rotulo, 'pt-BR'));
  }, [clientes, turmasAcademicas, turmasAcademicasMap]);

  const turmaSelecionadaInfo = useMemo(() => {
    return turmasDisponiveis.find((item) => item.key === turmaSelecionada) || null;
  }, [turmasDisponiveis, turmaSelecionada]);

  const livrosDidaticos = useMemo(() => {
    return livros
      .filter((livro) => {
        if (livro.baixa) return false;

        const didatico = isTipoDidatico(livro.tipo);
        const paradidatico = isTipoParadidatico(livro.tipo);
        const livroProfessor = isTipoLivroProfessor(livro.tipo);

        if (!didatico && !paradidatico && !livroProfessor) {
          return false;
        }

        if (tipoAcervoSelecionado === 'didatico') {
          return didatico;
        }

        if (tipoAcervoSelecionado === 'paradidatico') {
          return paradidatico;
        }

        if (tipoAcervoSelecionado === 'professor') {
          return livroProfessor;
        }

        return didatico || paradidatico || livroProfessor;
      })
      .sort((a, b) => String(a.titulo || '').localeCompare(String(b.titulo || ''), 'pt-BR'));
  }, [livros, tipoAcervoSelecionado]);

  const livrosDidaticosMap = useMemo(() => {
    const map = new Map();
    livrosDidaticos.forEach((livro) => {
      map.set(String(livro.id), livro);
    });
    return map;
  }, [livrosDidaticos]);

  const livrosSelecionadosDados = useMemo(() => {
    return livrosSelecionados
      .map((id) => livrosDidaticosMap.get(String(id)))
      .filter(Boolean);
  }, [livrosSelecionados, livrosDidaticosMap]);

  const emprestimosAtivos = useMemo(() => {
    return emprestimos.filter((emp) => isEmprestimoAtivo(emp.status));
  }, [emprestimos]);

  const emprestimoAtivoPorPar = useMemo(() => {
    const map = new Map();

    emprestimosAtivos.forEach((emp) => {
      const clienteId = emp.clienteId ?? emp.leitorId;
      const livroId = emp.livroId;
      if (clienteId === undefined || clienteId === null || livroId === undefined || livroId === null) {
        return;
      }

      const livroIdNormalizado = String(livroId);
      if (!livrosDidaticosMap.has(livroIdNormalizado)) {
        return;
      }

      const chave = `${clienteId}-${livroId}`;
      if (!map.has(chave)) {
        map.set(chave, emp);
      }
    });

    return map;
  }, [emprestimosAtivos, livrosDidaticosMap]);

  const alunosDisponiveisParaSelecao = useMemo(() => {
    const alunosAtivos = clientes
      .filter((cliente) => {
        if (!isAlunoLote(cliente)) return false;
        return cliente.ativo !== false;
      })
      .sort((a, b) => String(a.nome || '').localeCompare(String(b.nome || ''), 'pt-BR'));

    if (modoSelecaoAlunos === 'turma') {
      if (!turmaSelecionadaInfo) return [];
      return alunosAtivos.filter((aluno) => (
        isAlunoDaTurmaSelecionada(aluno, turmaSelecionadaInfo, turmasAcademicasMap)
      ));
    }

    if (!turmaSelecionadaInfo) {
      return alunosAtivos;
    }

    return alunosAtivos.filter((aluno) => (
      isAlunoDaTurmaSelecionada(aluno, turmaSelecionadaInfo, turmasAcademicasMap)
    ));
  }, [clientes, modoSelecaoAlunos, turmaSelecionadaInfo, turmasAcademicasMap]);

  const alunosFiltrados = alunosDisponiveisParaSelecao;

  const alunosSelecionados = useMemo(() => {
    return alunosDisponiveisParaSelecao.filter((aluno) => Boolean(alunosSelecionadosMapa[String(aluno.id)]));
  }, [alunosDisponiveisParaSelecao, alunosSelecionadosMapa]);

  const resumoSelecaoFiltro = useMemo(() => {
    const totalFiltrados = alunosFiltrados.length;
    let selecionadosFiltrados = 0;

    alunosFiltrados.forEach((aluno) => {
      if (Boolean(alunosSelecionadosMapa[String(aluno.id)])) {
        selecionadosFiltrados += 1;
      }
    });

    return {
      totalFiltrados,
      selecionadosFiltrados,
      todosFiltradosSelecionados: totalFiltrados > 0 && selecionadosFiltrados === totalFiltrados,
      parcialmenteSelecionados: selecionadosFiltrados > 0 && selecionadosFiltrados < totalFiltrados
    };
  }, [alunosFiltrados, alunosSelecionadosMapa]);

  const prepararLeitorLoteInicial = (termoBusca = '') => {
    const termoLimpo = String(termoBusca || '').trim();
    const termoDigitos = termoLimpo.replace(/\D/g, '');

    const turmaAcademicaSelecionada = turmaSelecionadaInfo && turmasAcademicasMap.has(String(turmaSelecionadaInfo.key))
      ? turmasAcademicasMap.get(String(turmaSelecionadaInfo.key))
      : null;

    const nomeTurmaPadrao = turmaAcademicaSelecionada?.nomeTurma || turmaSelecionadaInfo?.nomeTurma || '';
    const nomeSeriePadrao = turmaAcademicaSelecionada?.nomeSerie || turmaSelecionadaInfo?.nomeSerie || '';

    return {
      nome: termoDigitos.length >= 11 ? '' : termoLimpo,
      cpf: termoDigitos.length >= 11 ? termoDigitos.slice(0, 11) : '',
      telefone: '',
      email: '',
      endereco: '',
      tipo: 'Aluno',
      categoria: 'Estudante',
      matricula: '',
      serie: nomeSeriePadrao,
      serieId: turmaAcademicaSelecionada?.serieId ? String(turmaAcademicaSelecionada.serieId) : '',
      turma: nomeTurmaPadrao,
      turmaId: turmaAcademicaSelecionada?.id ? String(turmaAcademicaSelecionada.id) : '',
      ativo: true
    };
  };

  const localizarLeitoresPorTermo = (termo) => {
    const termoLimpo = String(termo || '').trim();
    if (!termoLimpo) return [];

    const termoNormalizado = normalizarTexto(termoLimpo);
    const termoDigitos = termoLimpo.replace(/\D/g, '');

    return clientes.filter((cliente) => {
      if (cliente?.ativo === false) return false;

      const nomeNormalizado = normalizarTexto(cliente?.nome);
      const cpfDigitos = String(cliente?.cpf || '').replace(/\D/g, '');
      const matriculaNormalizada = normalizarTexto(cliente?.matricula);

      const porNome = nomeNormalizado.includes(termoNormalizado);
      const porCpf = termoDigitos.length > 0 && cpfDigitos.includes(termoDigitos);
      const porMatricula = matriculaNormalizada.includes(termoNormalizado);

      return porNome || porCpf || porMatricula;
    });
  };

  const abrirCadastroLeitorLote = (termoBusca = '') => {
    setNovoLeitorLote(prepararLeitorLoteInicial(termoBusca));
    setCadastroLeitorLoteOpen(true);
  };

  const handleBuscarLeitorLote = () => {
    const termo = String(buscaLeitorLote || '').trim();
    if (!termo) {
      alert('Digite o nome, CPF ou matrícula para buscar o leitor.');
      return;
    }

    const encontrados = localizarLeitoresPorTermo(termo);

    if (encontrados.length === 0) {
      const confirmarCadastro = window.confirm(
        `Leitor não encontrado para "${termo}".\n\nDeseja cadastrá-lo agora?`
      );

      if (confirmarCadastro) {
        abrirCadastroLeitorLote(termo);
      }
      return;
    }

    if (encontrados.length > 1) {
      alert(`Foram encontrados ${encontrados.length} leitores. Refine a busca para selecionar apenas um.`);
      return;
    }

    const leitorEncontrado = encontrados[0];
    const leitorEstaNoFiltroAtual = alunosDisponiveisParaSelecao.some(
      (aluno) => String(aluno.id) === String(leitorEncontrado.id)
    );

    if (!leitorEstaNoFiltroAtual) {
      const confirmarMudancaModo = window.confirm(
        `O leitor "${leitorEncontrado.nome}" existe, mas não aparece no filtro atual.\n\nDeseja mudar para o modo individual para incluí-lo no lote?`
      );

      if (!confirmarMudancaModo) {
        return;
      }

      setModoSelecaoAlunos('individual');
      setTurmaSelecionada('');
    }

    setAlunosSelecionadosMapa((prev) => ({
      ...prev,
      [String(leitorEncontrado.id)]: true
    }));
    setResultadoAplicacao(null);
    alert(`✅ Leitor "${leitorEncontrado.nome}" selecionado para o lote.`);
  };

  const handleCadastrarLeitorLote = () => {
    if (!novoLeitorLote.nome || !novoLeitorLote.cpf) {
      alert('Nome e CPF são obrigatórios para cadastrar o leitor.');
      return;
    }

    const cpfNovo = String(novoLeitorLote.cpf || '').replace(/\D/g, '');
    const leitorExistenteCpf = clientes.find(
      (cliente) => String(cliente?.cpf || '').replace(/\D/g, '') === cpfNovo
    );

    if (leitorExistenteCpf) {
      const usarLeitorExistente = window.confirm(
        `Já existe um leitor cadastrado com este CPF:\n\n${leitorExistenteCpf.nome}\n\nDeseja utilizá-lo no lote?`
      );

      if (usarLeitorExistente) {
        setAlunosSelecionadosMapa((prev) => ({
          ...prev,
          [String(leitorExistenteCpf.id)]: true
        }));
        setCadastroLeitorLoteOpen(false);
      }

      return;
    }

    const leitorCadastrado = adicionarCliente({
      ...novoLeitorLote,
      ativo: true
    });

    if (!leitorCadastrado) {
      return;
    }

    setAlunosSelecionadosMapa((prev) => ({
      ...prev,
      [String(leitorCadastrado.id)]: true
    }));
    setCadastroLeitorLoteOpen(false);
    setBuscaLeitorLote('');
    setResultadoAplicacao(null);
    alert(`✅ Leitor "${leitorCadastrado.nome}" cadastrado e selecionado no lote.`);
  };

  useEffect(() => {
    const idsDisponiveis = new Set(alunosDisponiveisParaSelecao.map((aluno) => String(aluno.id)));

    setAlunosSelecionadosMapa((prev) => {
      const proximo = {};

      Object.entries(prev).forEach(([id, marcado]) => {
        if (marcado && idsDisponiveis.has(String(id))) {
          proximo[String(id)] = true;
        }
      });

      if (modoSelecaoAlunos === 'turma' && turmaSelecionada) {
        alunosDisponiveisParaSelecao.forEach((aluno) => {
          proximo[String(aluno.id)] = true;
        });
      }

      return proximo;
    });
  }, [alunosDisponiveisParaSelecao, modoSelecaoAlunos, turmaSelecionada]);

  const montarEstadoAtual = () => {
    const estado = {};

    alunosSelecionados.forEach((aluno) => {
      livrosSelecionadosDados.forEach((livro) => {
        const chave = `${aluno.id}-${livro.id}`;
        // No lote, por padrão marcamos todos os pares selecionados para facilitar
        // o cenário comum de emprestar todos os livros para todos os alunos.
        estado[chave] = true;
      });
    });

    return estado;
  };

  useEffect(() => {
    if (livrosSelecionadosDados.length === 0 || alunosSelecionados.length === 0) {
      setSelecoes({});
      return;
    }

    setSelecoes(montarEstadoAtual());
  }, [livrosSelecionadosDados, alunosSelecionados, emprestimoAtivoPorPar]);

  const disponibilidadePorLivro = useMemo(() => {
    const ativosPorLivro = {};

    emprestimosAtivos.forEach((emp) => {
      const livroId = String(emp.livroId || '');
      ativosPorLivro[livroId] = (ativosPorLivro[livroId] || 0) + 1;
    });

    const disponibilidade = {};
    livrosSelecionadosDados.forEach((livro) => {
      const livroId = String(livro.id);
      const total = Number(livro.quantidade) || 0;
      const ativos = ativosPorLivro[livroId] || 0;
      disponibilidade[livroId] = {
        total,
        ativos,
        disponiveis: Math.max(total - ativos, 0)
      };
    });

    return disponibilidade;
  }, [emprestimosAtivos, livrosSelecionadosDados]);

  const atualizarSelecao = (alunoId, livroId, marcado) => {
    const chave = `${alunoId}-${livroId}`;
    setSelecoes((prev) => ({
      ...prev,
      [chave]: marcado
    }));
  };

  const atualizarSelecaoAluno = (alunoId, marcado) => {
    setAlunosSelecionadosMapa((prev) => ({
      ...prev,
      [String(alunoId)]: marcado
    }));
    setResultadoAplicacao(null);
  };

  const selecionarTodosAlunosVisiveis = (marcado) => {
    setAlunosSelecionadosMapa((prev) => {
      const proximo = { ...prev };
      alunosFiltrados.forEach((aluno) => {
        proximo[String(aluno.id)] = marcado;
      });
      return proximo;
    });
    setResultadoAplicacao(null);
  };

  const selecionarTurmaInteira = (marcado) => {
    setAlunosSelecionadosMapa((prev) => {
      const proximo = { ...prev };
      alunosDisponiveisParaSelecao.forEach((aluno) => {
        proximo[String(aluno.id)] = marcado;
      });
      return proximo;
    });
    setResultadoAplicacao(null);
  };

  const limparSelecaoAlunos = () => {
    setAlunosSelecionadosMapa({});
    setResultadoAplicacao(null);
  };

  const marcarTodosLivrosParaTodosAlunos = (marcado) => {
    setSelecoes((prev) => {
      const proximo = { ...prev };

      alunosSelecionados.forEach((aluno) => {
        livrosSelecionadosDados.forEach((livro) => {
          proximo[`${aluno.id}-${livro.id}`] = marcado;
        });
      });

      return proximo;
    });
  };

  const marcarLivroParaTodosAlunos = (livroId, marcado) => {
    setSelecoes((prev) => {
      const proximo = { ...prev };

      alunosSelecionados.forEach((aluno) => {
        proximo[`${aluno.id}-${livroId}`] = marcado;
      });

      return proximo;
    });
  };

  const getResumoMarcacaoLivro = (livroId) => {
    const total = alunosSelecionados.length;
    if (total === 0) return { todos: false, parcial: false };

    let marcados = 0;
    alunosSelecionados.forEach((aluno) => {
      if (selecoes[`${aluno.id}-${livroId}`]) {
        marcados += 1;
      }
    });

    return {
      todos: marcados === total,
      parcial: marcados > 0 && marcados < total
    };
  };

  const resumoPainel = useMemo(() => {
    const totalPares = alunosSelecionados.length * livrosSelecionadosDados.length;
    let marcados = 0;

    alunosSelecionados.forEach((aluno) => {
      livrosSelecionadosDados.forEach((livro) => {
        if (selecoes[`${aluno.id}-${livro.id}`]) {
          marcados += 1;
        }
      });
    });

    return {
      totalPares,
      marcados,
      desmarcados: Math.max(totalPares - marcados, 0)
    };
  }, [alunosSelecionados, livrosSelecionadosDados, selecoes]);

  const obterPlanoAlteracoes = () => {
    const criarSolicitacoes = [];
    const devolverSolicitacoes = [];

    alunosSelecionados.forEach((aluno) => {
      livrosSelecionadosDados.forEach((livro) => {
        const chave = `${aluno.id}-${livro.id}`;
        const desejaMarcado = Boolean(selecoes[chave]);
        const emprestimoAtivo = emprestimoAtivoPorPar.get(chave);
        const estaMarcadoNoSistema = Boolean(emprestimoAtivo);

        if (desejaMarcado && !estaMarcadoNoSistema) {
          criarSolicitacoes.push({ aluno, livro });
        }

        if (!desejaMarcado && estaMarcadoNoSistema) {
          devolverSolicitacoes.push(emprestimoAtivo);
        }
      });
    });

    return { criarSolicitacoes, devolverSolicitacoes };
  };

  const resumoOperacaoLote = useMemo(() => {
    const { criarSolicitacoes, devolverSolicitacoes } = obterPlanoAlteracoes();
    const criacoesPorLivro = {};
    const devolucoesPorLivro = {};

    criarSolicitacoes.forEach(({ livro }) => {
      const livroId = String(livro.id);
      criacoesPorLivro[livroId] = (criacoesPorLivro[livroId] || 0) + 1;
    });

    devolverSolicitacoes.forEach((emprestimo) => {
      const livroId = String(emprestimo.livroId || '');
      devolucoesPorLivro[livroId] = (devolucoesPorLivro[livroId] || 0) + 1;
    });

    const totalExemplaresSelecionados = livrosSelecionadosDados.reduce((sum, livro) => {
      return sum + (Number(livro.quantidade) || 0);
    }, 0);

    const emprestadosAtualmente = livrosSelecionadosDados.reduce((sum, livro) => {
      return sum + (disponibilidadePorLivro[String(livro.id)]?.ativos || 0);
    }, 0);

    const estoqueDisponivelAtual = livrosSelecionadosDados.reduce((sum, livro) => {
      return sum + (disponibilidadePorLivro[String(livro.id)]?.disponiveis || 0);
    }, 0);

    const estoqueRestanteProjetado = livrosSelecionadosDados.reduce((sum, livro) => {
      const livroId = String(livro.id);
      const disponibilidadeAtual = disponibilidadePorLivro[livroId] || { disponiveis: 0 };
      const devolucoes = devolucoesPorLivro[livroId] || 0;
      const criacoes = criacoesPorLivro[livroId] || 0;

      return sum + Math.max(disponibilidadeAtual.disponiveis + devolucoes - criacoes, 0);
    }, 0);

    return {
      titulosSelecionados: livrosSelecionadosDados.length,
      exemplaresSelecionados: totalExemplaresSelecionados,
      quantidadeEmprestada: emprestadosAtualmente,
      quantidadePrevista: criarSolicitacoes.length,
      devolucoesPrevistas: devolverSolicitacoes.length,
      estoqueDisponivelAtual,
      estoqueRestanteProjetado
    };
  }, [disponibilidadePorLivro, livrosSelecionadosDados, selecoes, alunosSelecionados, emprestimoAtivoPorPar]);

  const abrirConfirmacaoEmprestimo = () => {
    if (modoSelecaoAlunos === 'turma' && !turmaSelecionada) {
      alert('Selecione uma turma para continuar.');
      return;
    }

    if (alunosSelecionados.length === 0) {
      alert('Selecione pelo menos um aluno para receber os livros.');
      return;
    }

    if (livrosSelecionadosDados.length === 0) {
      alert('Selecione pelo menos um livro para o lote.');
      return;
    }

    if (!dataDevolucaoPrevista) {
      alert('Informe a data de devolução prevista.');
      return;
    }

    const { criarSolicitacoes, devolverSolicitacoes } = obterPlanoAlteracoes();

    if (criarSolicitacoes.length === 0 && devolverSolicitacoes.length === 0) {
      alert('Nenhuma alteração para aplicar.');
      return;
    }

    setResumoConfirmacao({
      alunos: alunosSelecionados.length,
      livros: livrosSelecionadosDados.length,
      criar: criarSolicitacoes.length,
      devolver: devolverSolicitacoes.length,
      dataDevolucaoPrevista,
      turma: turmaSelecionadaInfo?.rotulo || (modoSelecaoAlunos === 'individual' ? 'Múltiplas turmas' : 'Sem turma')
    });
    setConfirmacaoAberta(true);
  };

  const confirmarEmprestimo = async () => {
    setConfirmacaoAberta(false);
    await aplicarAlteracoes();
  };

  const aplicarAlteracoes = async () => {
    if (modoSelecaoAlunos === 'turma' && !turmaSelecionada) {
      alert('Selecione uma turma para continuar.');
      return;
    }

    if (alunosSelecionados.length === 0) {
      alert('Selecione pelo menos um aluno para receber os livros.');
      return;
    }

    if (livrosSelecionadosDados.length === 0) {
      alert('Selecione pelo menos um livro para o lote.');
      return;
    }

    if (!dataDevolucaoPrevista) {
      alert('Informe a data de devolução prevista.');
      return;
    }

    const { criarSolicitacoes, devolverSolicitacoes } = obterPlanoAlteracoes();

    if (criarSolicitacoes.length === 0 && devolverSolicitacoes.length === 0) {
      alert('Nenhuma alteração para aplicar.');
      return;
    }

    setProcessando(true);
    try {
      const emprestimosCriadosAgora = [];
      const devolucoesPorLivro = {};
      devolverSolicitacoes.forEach((emp) => {
        const livroId = String(emp.livroId);
        devolucoesPorLivro[livroId] = (devolucoesPorLivro[livroId] || 0) + 1;
      });

      const ativosAtuaisPorLivro = {};
      emprestimosAtivos.forEach((emp) => {
        const livroId = String(emp.livroId);
        if (livrosDidaticosMap.has(livroId)) {
          ativosAtuaisPorLivro[livroId] = (ativosAtuaisPorLivro[livroId] || 0) + 1;
        }
      });

      const criarPorLivro = {};
      criarSolicitacoes.forEach((item) => {
        const livroId = String(item.livro.id);
        if (!criarPorLivro[livroId]) {
          criarPorLivro[livroId] = [];
        }
        criarPorLivro[livroId].push(item);
      });

      const criacoesPermitidas = [];
      const criacoesBloqueadas = [];

      Object.entries(criarPorLivro).forEach(([livroId, solicitacoesLivro]) => {
        const livro = livrosDidaticosMap.get(livroId);
        const total = Number(livro?.quantidade) || 0;
        const ativos = ativosAtuaisPorLivro[livroId] || 0;
        const devolvendo = devolucoesPorLivro[livroId] || 0;
        const disponiveisAposDevolucao = Math.max(total - ativos + devolvendo, 0);

        solicitacoesLivro.forEach((solicitacao, index) => {
          if (index < disponiveisAposDevolucao) {
            criacoesPermitidas.push(solicitacao);
          } else {
            criacoesBloqueadas.push(solicitacao);
          }
        });
      });

      devolverSolicitacoes.forEach((emprestimo) => {
        devolverLivro(emprestimo.id);
      });

      criacoesPermitidas.forEach((solicitacao) => {
        const turmaChaveAluno = obterChaveTurmaAluno(solicitacao.aluno, turmasAcademicasMap);
        const turmaRelacao = turmaChaveAluno && turmasAcademicasMap.has(String(turmaChaveAluno))
          ? turmasAcademicasMap.get(String(turmaChaveAluno))
          : null;
        const turmaTexto = obterRotuloTurmaAluno(solicitacao.aluno, turmasAcademicasMap)
          || turmaSelecionadaInfo?.rotulo
          || turmaSelecionada;

        const emprestimoCriado = adicionarEmprestimo({
          clienteId: solicitacao.aluno.id,
          livroId: solicitacao.livro.id,
          clienteNome: solicitacao.aluno.nome,
          livroTitulo: solicitacao.livro.titulo,
          turmaId: turmaRelacao?.id || solicitacao.aluno.turmaId || null,
          turmaNome: turmaRelacao?.nomeTurma || solicitacao.aluno.turma || solicitacao.aluno.nomeTurma || '',
          serieNome: turmaRelacao?.nomeSerie || solicitacao.aluno.serie || solicitacao.aluno.nomeSerie || '',
          origemLoteDidatico: true,
          modoSelecaoLote: modoSelecaoAlunos,
          status: 'ativo',
          dataEmprestimo: new Date().toISOString(),
          dataDevolucaoPrevista,
          dataDevolucao: dataDevolucaoPrevista,
          observacoes: `${observacaoPadraoAplicada} | Turma: ${turmaTexto}`
        });

        if (emprestimoCriado) {
          emprestimosCriadosAgora.push(emprestimoCriado);
        }
      });

      if (criacoesBloqueadas.length > 0) {
        setSelecoes((prev) => {
          const proximo = { ...prev };
          criacoesBloqueadas.forEach((solicitacao) => {
            proximo[`${solicitacao.aluno.id}-${solicitacao.livro.id}`] = false;
          });
          return proximo;
        });
      }

      const detalhesBloqueio = criacoesBloqueadas.slice(0, 12).map((item) => (
        `${item.aluno.nome} -> ${item.livro.titulo}`
      ));

      setResultadoAplicacao({
        devolvidos: devolverSolicitacoes.length,
        criados: criacoesPermitidas.length,
        bloqueados: criacoesBloqueadas.length,
        detalhesBloqueio,
        excessoBloqueio: Math.max(criacoesBloqueadas.length - detalhesBloqueio.length, 0)
      });

      setTermosLote(emprestimosCriadosAgora.filter((emp) => emp?.dadosTermoEmprestimo));
      setIndiceTermoLote(0);
    } finally {
      setProcessando(false);
    }
  };

  const abrirTermosLote = () => {
    if (termosLote.length === 0) {
      alert('Não há termos de empréstimo gerados neste lote.');
      return;
    }

    setIndiceTermoLote(0);
    setTermoLoteOpen(true);
  };

  const abrirProximoTermoLote = () => {
    if (indiceTermoLote >= termosLote.length - 1) {
      setTermoLoteOpen(false);
      return;
    }

    setIndiceTermoLote((prev) => prev + 1);
  };

  const semDadosParaMatriz = livrosSelecionadosDados.length === 0 || alunosSelecionados.length === 0;

  return (
    <Layout title="Empréstimos em Lote">
      {livrosDidaticos.length === 0 && (
        <Alert severity="warning" sx={{ mb: 2 }}>
          Nenhum livro compatível com o filtro selecionado foi encontrado. Cadastre livros do tipo <strong>Didático</strong>, <strong>Paradidático</strong> ou <strong>Livro do Professor</strong> para usar esta funcionalidade.
        </Alert>
      )}
      {turmasDisponiveis.length === 0 && (
        <Alert severity="info" sx={{ mb: 2 }}>
          Nenhuma turma cadastrada. Acesse <strong>Séries/Turmas</strong> e cadastre as turmas da escola.
        </Alert>
      )}
      <Card sx={{ mb: 2 }}>
        <CardContent>
          <Typography variant="h6" gutterBottom>
            Etapa 1 — Configuração do Lote
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            Defina o modo de seleção, turma, tipo de acervo, data de devolução e escolha os livros.
          </Typography>
          <Grid container spacing={2}>
            <Grid item xs={12} md={3}>
              <FormControl fullWidth sx={campoPadraoSx}>
                <InputLabel>Modo de seleção</InputLabel>
                <Select
                  value={modoSelecaoAlunos}
                  label="Modo de seleção"
                  onChange={(e) => {
                    setModoSelecaoAlunos(e.target.value);
                    setAlunosSelecionadosMapa({});
                    setResultadoAplicacao(null);
                  }}
                >
                  <MenuItem value="turma">Por série/turma (lote)</MenuItem>
                  <MenuItem value="individual">Por aluno(s) individualmente</MenuItem>
                </Select>
              </FormControl>
            </Grid>

            <Grid item xs={12} md={3}>
              <FormControl fullWidth sx={campoPadraoSx}>
                <InputLabel>{modoSelecaoAlunos === 'turma' ? 'Série/Turma' : 'Filtrar série/turma (opcional)'}</InputLabel>
                <Select
                  value={turmaSelecionada}
                  label={modoSelecaoAlunos === 'turma' ? 'Série/Turma' : 'Filtrar série/turma (opcional)'}
                  onChange={(e) => {
                    setTurmaSelecionada(e.target.value);
                    setAlunosSelecionadosMapa({});
                    setResultadoAplicacao(null);
                  }}
                >
                  <MenuItem value="">
                    {modoSelecaoAlunos === 'turma' ? 'Selecione uma turma' : 'Todas as turmas'}
                  </MenuItem>
                  {turmasDisponiveis.map((turma) => (
                    <MenuItem key={turma.key} value={turma.key}>{turma.rotulo}</MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>

            <Grid item xs={12} md={3}>
              <FormControl fullWidth sx={campoPadraoSx}>
                <InputLabel>Tipo do Acervo</InputLabel>
                <Select
                  value={tipoAcervoSelecionado}
                  label="Tipo do Acervo"
                  onChange={(e) => {
                    setTipoAcervoSelecionado(e.target.value);
                    setLivrosSelecionados([]);
                    setResultadoAplicacao(null);
                  }}
                >
                  <MenuItem value="todos">Didáticos, paradidáticos e livro do professor</MenuItem>
                  <MenuItem value="didatico">Somente didáticos</MenuItem>
                  <MenuItem value="paradidatico">Somente paradidáticos</MenuItem>
                  <MenuItem value="professor">Somente livro do professor</MenuItem>
                </Select>
              </FormControl>
            </Grid>

            <Grid item xs={12} md={3}>
              <TextField
                fullWidth
                type="date"
                label="Devolução Prevista"
                value={dataDevolucaoPrevista}
                onChange={(e) => setDataDevolucaoPrevista(e.target.value)}
                InputLabelProps={{ shrink: true }}
                sx={campoPadraoSx}
              />
            </Grid>

            <Grid item xs={12} md={12}>
              <FormControl fullWidth sx={campoPadraoSx}>
                <InputLabel>Livros do Lote</InputLabel>
                <Select
                  multiple
                  value={livrosSelecionados}
                  label="Livros do Lote"
                  onChange={(e) => {
                    const value = e.target.value;
                    setLivrosSelecionados(typeof value === 'string' ? value.split(',') : value);
                    setResultadoAplicacao(null);
                  }}
                  renderValue={(selected) => `${selected.length} livro(s) selecionado(s)`}
                >
                  {livrosDidaticos.map((livro) => (
                    <MenuItem key={livro.id} value={String(livro.id)}>
                      <Checkbox checked={livrosSelecionados.includes(String(livro.id))} />
                      <ListItemText
                        primary={livro.titulo}
                        secondary={`${livro.tipo || 'Paradidático'} | Qtd: ${Number(livro.quantidade) || 0}`}
                      />
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
          </Grid>

          <Divider sx={{ my: 2 }} />
          <Typography variant="h6" gutterBottom>
            Etapa 2 — Selecionar Alunos
          </Typography>
          <Box sx={{ mt: 1 }}>
            <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>
              {modoSelecaoAlunos === 'turma'
                ? 'Selecione a turma e marque alunos específicos ou a turma inteira para receber os livros.'
                : 'Busque e marque alunos individualmente. Você pode filtrar por turma quando necessário.'}
            </Typography>

            <Box sx={{ display: 'flex', gap: 1, mb: 1, flexWrap: 'wrap' }}>
              <TextField
                size="small"
                fullWidth
                label="Buscar leitor por nome, CPF ou matrícula"
                value={buscaLeitorLote}
                onChange={(e) => setBuscaLeitorLote(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    handleBuscarLeitorLote();
                  }
                }}
                placeholder="Ex: João da Silva, 12345678901, MAT2026..."
                sx={{ flex: 1, minWidth: 260 }}
              />
              <Button variant="outlined" onClick={handleBuscarLeitorLote}>
                Localizar / Cadastrar
              </Button>
            </Box>

            <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mb: 1 }}>
              <Button
                variant="outlined"
                size="small"
                onClick={() => selecionarTodosAlunosVisiveis(true)}
                disabled={alunosFiltrados.length === 0 || processando}
              >
                Selecionar todos
              </Button>
              <Button
                variant="outlined"
                size="small"
                color="inherit"
                onClick={() => selecionarTodosAlunosVisiveis(false)}
                disabled={alunosFiltrados.length === 0 || processando}
              >
                Desmarcar todos
              </Button>
              {modoSelecaoAlunos === 'turma' && (
                <Button
                  variant="outlined"
                  size="small"
                  onClick={() => selecionarTurmaInteira(true)}
                  disabled={alunosDisponiveisParaSelecao.length === 0 || processando}
                >
                  Selecionar todos da turma
                </Button>
              )}
              <Button
                variant="outlined"
                size="small"
                color="inherit"
                onClick={limparSelecaoAlunos}
                disabled={alunosSelecionados.length === 0 || processando}
              >
                Limpar seleção de alunos
              </Button>
            </Box>

            <TableContainer component={Paper} variant="outlined" sx={{ maxHeight: 260 }}>
              <Table size="small" stickyHeader>
                <TableHead>
                  <TableRow>
                    <TableCell align="center" sx={{ width: 92 }}>
                      <Checkbox
                        checked={resumoSelecaoFiltro.todosFiltradosSelecionados}
                        indeterminate={resumoSelecaoFiltro.parcialmenteSelecionados}
                        onChange={(e) => selecionarTodosAlunosVisiveis(e.target.checked)}
                        disabled={alunosFiltrados.length === 0 || processando}
                        inputProps={{ 'aria-label': 'Selecionar todos os alunos visíveis' }}
                      />
                    </TableCell>
                    <TableCell>Aluno</TableCell>
                    <TableCell>Matrícula</TableCell>
                    <TableCell>Turma</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {alunosFiltrados.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={4} align="center">
                        <Typography variant="body2" color="text.secondary">
                          {modoSelecaoAlunos === 'turma' && turmaSelecionada
                            ? 'Nenhum aluno leitor associado à turma selecionada. Verifique os vínculos em Leitores (série/turma).'
                            : 'Nenhum aluno encontrado para os filtros atuais.'}
                        </Typography>
                      </TableCell>
                    </TableRow>
                  ) : (
                    alunosFiltrados.map((aluno) => (
                      <TableRow key={aluno.id} hover>
                        <TableCell align="center">
                          <Checkbox
                            checked={Boolean(alunosSelecionadosMapa[String(aluno.id)])}
                            onChange={(e) => atualizarSelecaoAluno(aluno.id, e.target.checked)}
                            disabled={processando}
                          />
                        </TableCell>
                        <TableCell>
                          <Typography variant="body2" fontWeight="bold">{aluno.nome}</Typography>
                        </TableCell>
                        <TableCell>{aluno.matricula || '-'}</TableCell>
                        <TableCell>
                          <Chip size="small" label={obterRotuloTurmaAluno(aluno, turmasAcademicasMap)} />
                        </TableCell>
                      </TableRow>
                    ))
                  )}
                </TableBody>
              </Table>
            </TableContainer>
          </Box>

          <Divider sx={{ my: 2 }} />
          <Typography variant="h6" gutterBottom>
            Etapa 3 — Confirmar e Aplicar
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
            Marque ou desmarque na matriz abaixo quais livros cada aluno irá receber. Depois clique em <strong>Confirmar empréstimo</strong>.
          </Typography>
          <Box sx={{ mt: 2, display: 'flex', gap: 1, flexWrap: 'wrap' }}>
            <Button
              variant="outlined"
              startIcon={<AssignmentTurnedIn />}
              onClick={() => marcarTodosLivrosParaTodosAlunos(true)}
              disabled={semDadosParaMatriz || processando}
              sx={botaoAcaoSx}
            >
              Marcar todos
            </Button>
            <Button
              variant="outlined"
              color="warning"
              startIcon={<Undo />}
              onClick={() => marcarTodosLivrosParaTodosAlunos(false)}
              disabled={semDadosParaMatriz || processando}
              sx={botaoAcaoSx}
            >
              Desmarcar todos
            </Button>
            <Button
              variant="contained"
              startIcon={processando ? <CircularProgress size={18} color="inherit" /> : <Save />}
              onClick={abrirConfirmacaoEmprestimo}
              disabled={processando}
              sx={botaoAcaoSx}
            >
              Confirmar empréstimo
            </Button>
          </Box>
        </CardContent>
      </Card>

      <Grid container spacing={2} sx={{ mb: 2 }}>
        <Grid item xs={12} sm={4}>
          <Paper sx={cartaoResumoSx}>
            <Typography variant="caption" color="text.secondary">Alunos selecionados</Typography>
            <Typography variant="h6">
              <Groups sx={{ mr: 0.5, verticalAlign: 'middle' }} />
              {alunosSelecionados.length} / {alunosDisponiveisParaSelecao.length}
            </Typography>
          </Paper>
        </Grid>
        <Grid item xs={12} sm={4}>
          <Paper sx={cartaoResumoSx}>
            <Typography variant="caption" color="text.secondary">Pares marcados</Typography>
            <Typography variant="h6"><AssignmentTurnedIn sx={{ mr: 0.5, verticalAlign: 'middle' }} />{resumoPainel.marcados}</Typography>
          </Paper>
        </Grid>
        <Grid item xs={12} sm={4}>
          <Paper sx={cartaoResumoSx}>
            <Typography variant="caption" color="text.secondary">Pares desmarcados</Typography>
            <Typography variant="h6"><LibraryBooks sx={{ mr: 0.5, verticalAlign: 'middle' }} />{resumoPainel.desmarcados}</Typography>
          </Paper>
        </Grid>
      </Grid>

      <Card sx={{ mb: 2, border: '1px solid', borderColor: 'divider' }}>
        <CardContent>
          <Typography variant="subtitle1" fontWeight="bold" sx={{ mb: 0.5 }}>
            📊 Resumo do Lote
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            {turmaSelecionadaInfo?.rotulo
              ? `Resumo operacional para ${turmaSelecionadaInfo.rotulo}.`
              : 'Resumo operacional para os livros e alunos atualmente selecionados.'}
          </Typography>

          <Grid container spacing={2}>
            <Grid item xs={12} sm={6} md={2.4}>
              <Paper variant="outlined" sx={cartaoResumoSx}>
                <Typography variant="caption" color="text.secondary">Títulos selecionados</Typography>
                <Typography variant="h6">{resumoOperacaoLote.titulosSelecionados}</Typography>
              </Paper>
            </Grid>
            <Grid item xs={12} sm={6} md={2.4}>
              <Paper variant="outlined" sx={cartaoResumoSx}>
                <Typography variant="caption" color="text.secondary">Quantidade emprestada</Typography>
                <Typography variant="h6">{resumoOperacaoLote.quantidadeEmprestada}</Typography>
              </Paper>
            </Grid>
            <Grid item xs={12} sm={6} md={2.4}>
              <Paper variant="outlined" sx={cartaoResumoSx}>
                <Typography variant="caption" color="text.secondary">Empréstimos previstos</Typography>
                <Typography variant="h6">{resumoOperacaoLote.quantidadePrevista}</Typography>
              </Paper>
            </Grid>
            <Grid item xs={12} sm={6} md={2.4}>
              <Paper variant="outlined" sx={cartaoResumoSx}>
                <Typography variant="caption" color="text.secondary">Estoque disponível agora</Typography>
                <Typography variant="h6">{resumoOperacaoLote.estoqueDisponivelAtual}</Typography>
              </Paper>
            </Grid>
            <Grid item xs={12} sm={6} md={2.4}>
              <Paper variant="outlined" sx={cartaoResumoSx}>
                <Typography variant="caption" color="text.secondary">Estoque restante projetado</Typography>
                <Typography variant="h6">{resumoOperacaoLote.estoqueRestanteProjetado}</Typography>
              </Paper>
            </Grid>
          </Grid>

          <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 2 }}>
            Exemplares nos títulos selecionados: {resumoOperacaoLote.exemplaresSelecionados} | Devoluções previstas: {resumoOperacaoLote.devolucoesPrevistas}
          </Typography>
        </CardContent>
      </Card>

      <Dialog
        open={confirmacaoAberta}
        onClose={() => {
          if (!processando) {
            setConfirmacaoAberta(false);
          }
        }}
        fullWidth
        maxWidth="sm"
      >
        <DialogTitle>Confirmar empréstimo em lote</DialogTitle>
        <DialogContent dividers>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            Revise os dados antes de efetivar o lote de empréstimos.
          </Typography>
          <Grid container spacing={2}>
            <Grid item xs={6}>
              <Paper variant="outlined" sx={cartaoResumoSx}>
                <Typography variant="caption" color="text.secondary">Alunos</Typography>
                <Typography variant="h6">{resumoConfirmacao?.alunos || 0}</Typography>
              </Paper>
            </Grid>
            <Grid item xs={6}>
              <Paper variant="outlined" sx={cartaoResumoSx}>
                <Typography variant="caption" color="text.secondary">Livros</Typography>
                <Typography variant="h6">{resumoConfirmacao?.livros || 0}</Typography>
              </Paper>
            </Grid>
            <Grid item xs={6}>
              <Paper variant="outlined" sx={cartaoResumoSx}>
                <Typography variant="caption" color="text.secondary">Novos empréstimos</Typography>
                <Typography variant="h6">{resumoConfirmacao?.criar || 0}</Typography>
              </Paper>
            </Grid>
            <Grid item xs={6}>
              <Paper variant="outlined" sx={cartaoResumoSx}>
                <Typography variant="caption" color="text.secondary">Devoluções</Typography>
                <Typography variant="h6">{resumoConfirmacao?.devolver || 0}</Typography>
              </Paper>
            </Grid>
          </Grid>

          <Box sx={{ mt: 2 }}>
            <Typography variant="body2"><strong>Turma/filtro:</strong> {resumoConfirmacao?.turma || '-'}</Typography>
            <Typography variant="body2"><strong>Devolução prevista:</strong> {resumoConfirmacao?.dataDevolucaoPrevista || '-'}</Typography>
          </Box>

          <Alert severity="info" sx={{ mt: 2 }}>
            Ao confirmar, o sistema cria os novos empréstimos marcados e processa as devoluções dos itens desmarcados.
          </Alert>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setConfirmacaoAberta(false)} disabled={processando}>
            Cancelar
          </Button>
          <Button
            variant="contained"
            onClick={confirmarEmprestimo}
            disabled={processando}
            startIcon={processando ? <CircularProgress size={18} color="inherit" /> : <Save />}
          >
            Aplicar agora
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={cadastroLeitorLoteOpen}
        onClose={() => setCadastroLeitorLoteOpen(false)}
        fullWidth
        maxWidth="sm"
      >
        <DialogTitle>Cadastrar novo leitor para o lote</DialogTitle>
        <DialogContent dividers>
          <Alert severity="info" sx={{ mb: 2 }}>
            O leitor será inserido no sistema e poderá receber os empréstimos do lote atual.
          </Alert>

          <Grid container spacing={2}>
            <Grid item xs={12}>
              <TextField
                label="Nome Completo"
                fullWidth
                required
                value={novoLeitorLote.nome}
                onChange={(e) => setNovoLeitorLote((prev) => ({ ...prev, nome: e.target.value }))}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                label="CPF"
                fullWidth
                required
                value={novoLeitorLote.cpf}
                onChange={(e) => setNovoLeitorLote((prev) => ({ ...prev, cpf: e.target.value }))}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                label="Matrícula"
                fullWidth
                value={novoLeitorLote.matricula}
                onChange={(e) => setNovoLeitorLote((prev) => ({ ...prev, matricula: e.target.value }))}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                label="Tipo"
                fullWidth
                select
                value={novoLeitorLote.tipo}
                onChange={(e) => setNovoLeitorLote((prev) => ({ ...prev, tipo: e.target.value }))}
              >
                {['Aluno', 'Professor', 'Funcionário', 'Visitante'].map((tipo) => (
                  <MenuItem key={tipo} value={tipo}>{tipo}</MenuItem>
                ))}
              </TextField>
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                label="Categoria"
                fullWidth
                select
                value={novoLeitorLote.categoria}
                onChange={(e) => setNovoLeitorLote((prev) => ({ ...prev, categoria: e.target.value }))}
              >
                <MenuItem value="">— Não informado —</MenuItem>
                {['Estudante', 'Professor', 'Funcionário', 'Comunidade'].map((cat) => (
                  <MenuItem key={cat} value={cat}>{cat}</MenuItem>
                ))}
              </TextField>
            </Grid>
            {novoLeitorLote.tipo === 'Aluno' && (
              <>
                <Grid item xs={12} sm={6}>
                  <TextField
                    label="Série/Ano"
                    fullWidth
                    value={novoLeitorLote.serie}
                    onChange={(e) => setNovoLeitorLote((prev) => ({ ...prev, serie: e.target.value }))}
                  />
                </Grid>
                <Grid item xs={12} sm={6}>
                  <TextField
                    label="Turma"
                    fullWidth
                    value={novoLeitorLote.turma}
                    onChange={(e) => setNovoLeitorLote((prev) => ({ ...prev, turma: e.target.value }))}
                  />
                </Grid>
              </>
            )}
            <Grid item xs={12} sm={6}>
              <TextField
                label="Telefone"
                fullWidth
                value={novoLeitorLote.telefone}
                onChange={(e) => setNovoLeitorLote((prev) => ({ ...prev, telefone: e.target.value }))}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                label="Email"
                fullWidth
                type="email"
                value={novoLeitorLote.email}
                onChange={(e) => setNovoLeitorLote((prev) => ({ ...prev, email: e.target.value }))}
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                label="Endereço"
                fullWidth
                value={novoLeitorLote.endereco}
                onChange={(e) => setNovoLeitorLote((prev) => ({ ...prev, endereco: e.target.value }))}
              />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setCadastroLeitorLoteOpen(false)}>
            Cancelar
          </Button>
          <Button variant="contained" onClick={handleCadastrarLeitorLote}>
            Cadastrar leitor
          </Button>
        </DialogActions>
      </Dialog>

      {resultadoAplicacao && (
        <Alert
          severity={resultadoAplicacao.bloqueados > 0 ? 'warning' : 'success'}
          sx={{ mb: 2 }}
        >
          <Typography variant="body2" sx={{ mb: resultadoAplicacao.bloqueados > 0 ? 1 : 0 }}>
            Resultado: {resultadoAplicacao.criados} empréstimo(s) criado(s), {resultadoAplicacao.devolvidos} devolução(ões) processada(s)
            {resultadoAplicacao.bloqueados > 0 ? `, ${resultadoAplicacao.bloqueados} bloqueado(s) por falta de estoque.` : '.'}
          </Typography>
          {resultadoAplicacao.bloqueados > 0 && (
            <Box>
              {resultadoAplicacao.detalhesBloqueio.map((detalhe) => (
                <Typography key={detalhe} variant="caption" display="block">• {detalhe}</Typography>
              ))}
              {resultadoAplicacao.excessoBloqueio > 0 && (
                <Typography variant="caption" display="block">
                  • ... e mais {resultadoAplicacao.excessoBloqueio} bloqueio(s)
                </Typography>
              )}
            </Box>
          )}

          {resultadoAplicacao.criados > 0 && (
            <Box sx={{ mt: 1.5, display: 'flex', gap: 1, flexWrap: 'wrap' }}>
              <Button
                size="small"
                variant="outlined"
                color="success"
                startIcon={<Description />}
                onClick={abrirTermosLote}
              >
                Gerar termos do lote ({termosLote.length})
              </Button>
              <Button
                size="small"
                variant="outlined"
                color="primary"
                startIcon={<Print />}
                onClick={() => navigate('/relatorios-livros')}
              >
                Ver estoque disponível
              </Button>
            </Box>
          )}
        </Alert>
      )}

      {semDadosParaMatriz ? (
        <Alert severity="info">
          Selecione ao menos um aluno e um livro para exibir a matriz de marcação.
        </Alert>
      ) : (
        <TableContainer component={Paper} sx={{ maxHeight: '70vh' }}>
          <Table size="small" stickyHeader>
            <TableHead>
              <TableRow>
                <TableCell sx={{ minWidth: 220 }}>Aluno</TableCell>
                <TableCell sx={{ minWidth: 120 }}>Matrícula</TableCell>
                {livrosSelecionadosDados.map((livro) => {
                  const disp = disponibilidadePorLivro[String(livro.id)] || { total: 0, ativos: 0, disponiveis: 0 };
                  const estadoMarcacao = getResumoMarcacaoLivro(livro.id);

                  return (
                    <TableCell key={livro.id} align="center" sx={{ minWidth: 220 }}>
                      <Typography variant="caption" fontWeight="bold" display="block">
                        {livro.titulo}
                      </Typography>
                      <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 0.5 }}>
                        Disp.: {disp.disponiveis} / {disp.total}
                      </Typography>
                      <Checkbox
                        size="small"
                        indeterminate={estadoMarcacao.parcial}
                        checked={estadoMarcacao.todos}
                        onChange={(e) => marcarLivroParaTodosAlunos(livro.id, e.target.checked)}
                        disabled={processando}
                      />
                    </TableCell>
                  );
                })}
              </TableRow>
            </TableHead>
            <TableBody>
              {alunosSelecionados.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={2 + livrosSelecionadosDados.length} align="center">
                    <Typography color="text.secondary">Nenhum aluno selecionado para o lote.</Typography>
                  </TableCell>
                </TableRow>
              ) : (
                alunosSelecionados.map((aluno) => (
                  <TableRow key={aluno.id} hover>
                    <TableCell>
                      <Typography variant="body2" fontWeight="bold">{aluno.nome}</Typography>
                      <Chip
                        size="small"
                        label={obterRotuloTurmaAluno(aluno, turmasAcademicasMap)}
                        sx={{ mt: 0.5 }}
                      />
                    </TableCell>
                    <TableCell>{aluno.matricula || '-'}</TableCell>
                    {livrosSelecionadosDados.map((livro) => {
                      const chave = `${aluno.id}-${livro.id}`;
                      const checked = Boolean(selecoes[chave]);

                      return (
                        <TableCell key={chave} align="center">
                          <Checkbox
                            checked={checked}
                            onChange={(e) => atualizarSelecao(aluno.id, livro.id, e.target.checked)}
                            disabled={processando}
                          />
                        </TableCell>
                      );
                    })}
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </TableContainer>
      )}

      <Box sx={{ mt: 2 }}>
        <Divider sx={{ mb: 1 }} />
        <Typography variant="caption" color="text.secondary">
          💡 Dica: Na Etapa 3, marcar um checkbox gera o empréstimo; desmarcar processa a devolução automaticamente ao confirmar.
        </Typography>
      </Box>

      <TermoEmprestimo
        open={termoLoteOpen}
        onClose={() => setTermoLoteOpen(false)}
        dados={termosLote[indiceTermoLote]?.dadosTermoEmprestimo || null}
        tipo="preenchido"
        onNext={indiceTermoLote < termosLote.length - 1 ? abrirProximoTermoLote : null}
        nextLabel={`Próximo termo (${indiceTermoLote + 2}/${termosLote.length})`}
      />
    </Layout>
  );
}

import React, { useMemo, useState } from 'react';
import Layout from '../components/Layout';
import {
  Box,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  Chip,
  Typography,
  MenuItem,
  Autocomplete,
  Alert,
  Card,
  CardContent,
  Grid,
  InputAdornment,
  Divider,
  FormControl,
  FormLabel,
  RadioGroup,
  FormControlLabel,
  Radio
} from '@mui/material';
import { Add, Edit, AssignmentReturn, Search, PersonAdd, CheckCircle, Print, Description, PrintOutlined } from '@mui/icons-material';
import { useData } from '../context/DataContext';
import TermoEmprestimo from '../components/TermoEmprestimo';
import { useNavigate } from 'react-router-dom';

function EmprestimosPage() {
  const navigate = useNavigate();

  const { 
    emprestimos, 
    adicionarEmprestimo, 
    atualizarEmprestimo,
    livros,
    clientes,
    turmasAcademicas,
    adicionarCliente,
    adicionarLivro
  } = useData();
  const [open, setOpen] = useState(false);
  const [busca, setBusca] = useState('');

  // Estados para o fluxo de empréstimo
  const [isbnBusca, setIsbnBusca] = useState('');
  const [livroSelecionado, setLivroSelecionado] = useState(null);
  const [etapaAtual, setEtapaAtual] = useState(1); // 1: buscar livro, 2: selecionar/cadastrar leitor
  const [mostrarCadastroLivro, setMostrarCadastroLivro] = useState(false);
  const [buscaLeitor, setBuscaLeitor] = useState('');
  const [mostrarCadastroLeitor, setMostrarCadastroLeitor] = useState(false);
  
  // Estados para termos de empréstimo
  const [termoOpen, setTermoOpen] = useState(false);
  const [termoSelecionado, setTermoSelecionado] = useState(null);
  const [tipoTermo, setTipoTermo] = useState('preenchido'); // 'preenchido' ou 'branco'
  
  const [formData, setFormData] = useState({
    clienteId: '',
    livroId: '',
    dataEmprestimo: new Date().toISOString().split('T')[0],
    dataDevolucaoPrevista: '',
    observacoes: '',
    categoriaLeitor: ''
  });
  
  // Dados para cadastro rápido de leitor
  const [novoLeitor, setNovoLeitor] = useState({
    nome: '',
    cpf: '',
    email: '',
    telefone: '',
    endereco: ''
  });

  const [novoLivro, setNovoLivro] = useState({
    titulo: '',
    autor: '',
    isbn: '',
    editora: '',
    categoria: '',
    quantidade: 1,
    localizacao: '',
    tipo: 'Paradidático',
    anoPublicacao: '',
    anoVigencia: ''
  });

  const normalizarIsbn = (valor) => String(valor || '').replace(/[^0-9Xx]/g, '').toUpperCase();

  const resumoEstoqueEmprestimos = useMemo(() => {
    const emprestimosAtivos = emprestimos.filter((emp) => String(emp?.status || '').toLowerCase() === 'ativo');

    const ativosPorLivro = new Map();
    emprestimosAtivos.forEach((emp) => {
      const livroId = String(emp?.livroId || '');
      if (!livroId) return;
      ativosPorLivro.set(livroId, (ativosPorLivro.get(livroId) || 0) + 1);
    });

    let totalExemplares = 0;
    let disponiveis = 0;

    livros.forEach((livro) => {
      if (livro?.baixa) return;
      const quantidade = Math.max(Number(livro?.quantidade) || 0, 0);
      totalExemplares += quantidade;

      const ativos = ativosPorLivro.get(String(livro.id)) || 0;
      disponiveis += Math.max(quantidade - ativos, 0);
    });

    return {
      totalExemplares,
      emprestados: emprestimosAtivos.length,
      disponiveis
    };
  }, [livros, emprestimos]);

  const leitoresFiltrados = useMemo(() => {
    const termo = buscaLeitor.trim();
    if (!termo) return [];

    const termoLower = termo.toLowerCase();
    const termoCpf = termo.replace(/\D/g, '');

    return clientes.filter((c) => {
      if (!c?.ativo) return false;

      const nome = String(c?.nome || '').toLowerCase();
      const cpf = String(c?.cpf || '').replace(/\D/g, '');

      const nomeConfere = nome.includes(termoLower);
      const cpfConfere = termoCpf.length > 0 && cpf.includes(termoCpf);

      return nomeConfere || cpfConfere;
    });
  }, [buscaLeitor, clientes]);

  const selecionarLivroParaEmprestimo = (livro) => {
    if (!livro) return false;

    const emprestimosAtivosDoLivro = emprestimos.filter(
      (emp) => emp.livroId === livro.id && emp.status === 'ativo'
    ).length;

    const quantidadeDisponivel = (Number(livro.quantidade) || 1) - emprestimosAtivosDoLivro;

    if (quantidadeDisponivel <= 0) {
      alert(`❌ Livro indisponível!\n\nTodos os ${livro.quantidade} exemplar(es) estão emprestados.\nAguarde a devolução de algum exemplar.`);
      return false;
    }

    setLivroSelecionado({ ...livro, quantidadeDisponivel });
    setFormData((prev) => ({ ...prev, livroId: livro.id }));
    setEtapaAtual(2);
    setMostrarCadastroLivro(false);
    return true;
  };

  const handleOpen = () => {
    setIsbnBusca('');
    setLivroSelecionado(null);
    setEtapaAtual(1);
    setMostrarCadastroLivro(false);
    setBuscaLeitor('');
    setMostrarCadastroLeitor(false);
    setNovoLeitor({
      nome: '',
      cpf: '',
      email: '',
      telefone: '',
      endereco: ''
    });
    setNovoLivro({
      titulo: '',
      autor: '',
      isbn: '',
      editora: '',
      categoria: '',
      quantidade: 1,
      localizacao: '',
      tipo: 'Paradidático',
      anoPublicacao: '',
      anoVigencia: ''
    });
    setFormData({
      clienteId: '',
      livroId: '',
      dataEmprestimo: new Date().toISOString().split('T')[0],
      dataDevolucaoPrevista: '',
      observacoes: ''
    });
    setOpen(true);
  };

  const handleClose = () => {
    setOpen(false);
  };

  const buscarLivroPorISBN = () => {
    const isbnNormalizado = normalizarIsbn(isbnBusca);

    if (!isbnNormalizado) {
      alert('Digite o ISBN do livro');
      return;
    }
    
    const livro = livros.find((l) => normalizarIsbn(l.isbn) === isbnNormalizado);
    
    if (livro) {
      selecionarLivroParaEmprestimo(livro);
    } else {
      const confirmarCadastro = window.confirm(
        `❌ Livro não encontrado com ISBN ${isbnNormalizado}.\n\nDeseja cadastrar um novo livro agora?`
      );

      if (confirmarCadastro) {
        setNovoLivro((prev) => ({
          ...prev,
          isbn: isbnNormalizado
        }));
        setMostrarCadastroLivro(true);
      }
    }
  };

  const handleCancelarCadastroLivro = () => {
    setMostrarCadastroLivro(false);
    setNovoLivro((prev) => ({
      ...prev,
      isbn: normalizarIsbn(isbnBusca)
    }));
  };

  const handleCadastrarLivroEContinuar = () => {
    const isbnNormalizado = normalizarIsbn(novoLivro.isbn || isbnBusca);

    if (!novoLivro.titulo || !novoLivro.autor) {
      alert('Título e autor são obrigatórios para cadastrar o livro.');
      return;
    }

    if (!isbnNormalizado) {
      alert('Informe um ISBN válido para continuar.');
      return;
    }

    const livroExistente = livros.find((l) => normalizarIsbn(l.isbn) === isbnNormalizado);
    if (livroExistente) {
      const usarExistente = window.confirm(
        `Já existe um livro cadastrado com esse ISBN:\n\n${livroExistente.titulo}\n\nDeseja usá-lo neste empréstimo?`
      );

      if (usarExistente) {
        selecionarLivroParaEmprestimo(livroExistente);
      }
      return;
    }

    const numeroSequencial = (livros.length + 1).toString().padStart(6, '0');
    const livroCadastrado = adicionarLivro({
      ...novoLivro,
      isbn: isbnNormalizado,
      quantidade: Math.max(Number(novoLivro.quantidade) || 1, 1),
      codigoIdentificacao: `LIV${numeroSequencial}`,
      anoVigencia: novoLivro.tipo === 'Didático' ? novoLivro.anoVigencia : ''
    });

    if (!livroCadastrado) {
      return;
    }

    setIsbnBusca(isbnNormalizado);
    selecionarLivroParaEmprestimo(livroCadastrado);
    alert('✅ Livro cadastrado e selecionado para o empréstimo!');
  };

  const handleSelecionarLeitor = (leitor) => {
    console.log('🎯 handleSelecionarLeitor chamado:', leitor);
    const cat = (leitor.categoria || leitor.tipo || '').toLowerCase();
    let categoriaAuto = '';
    if (/professor/.test(cat)) categoriaAuto = 'professor';
    else if (/aluno|estudante/.test(cat)) categoriaAuto = 'estudante';
    else if (/funcion|servidor|bibliotec|coordenador|diretor|gestor|admin/.test(cat)) categoriaAuto = 'funcionario';
    else if (/comunidade/.test(cat)) categoriaAuto = 'comunidade';
    setFormData(prev => {
      const newFormData = { ...prev, clienteId: leitor.id, categoriaLeitor: categoriaAuto || prev.categoriaLeitor };
      console.log('📝 Novo formData:', newFormData);
      return newFormData;
    });
    setMostrarCadastroLeitor(false);
    setBuscaLeitor(''); // Limpar busca após seleção
    console.log('✅ Leitor selecionado:', leitor.nome);
  };

  const handleCadastrarLeitor = () => {
    if (!novoLeitor.nome || !novoLeitor.cpf) {
      alert('Nome e CPF são obrigatórios!');
      return;
    }
    
    // Cadastrar novo leitor
    const leitorCadastrado = adicionarCliente({
      ...novoLeitor,
      ativo: true,
      dataCadastro: new Date().toISOString()
    });

    if (!leitorCadastrado) {
      return;
    }
    
    // Selecionar o leitor recém-cadastrado
    setFormData(prev => ({ ...prev, clienteId: leitorCadastrado.id }));
    setMostrarCadastroLeitor(false);
    alert('✅ Leitor cadastrado com sucesso!');
  };

  const perguntarCadastroLeitor = () => {
    const termoBusca = String(buscaLeitor || '').trim();
    if (!termoBusca) {
      alert('Digite o nome, CPF ou matrícula do leitor para buscar.');
      return;
    }

    const confirmarCadastro = window.confirm(
      `Leitor não encontrado para "${termoBusca}".\n\nDeseja cadastrá-lo agora?`
    );

    if (!confirmarCadastro) {
      return;
    }

    const termoSomenteDigitos = termoBusca.replace(/\D/g, '');
    setNovoLeitor((prev) => ({
      ...prev,
      nome: termoSomenteDigitos.length >= 11 ? prev.nome : termoBusca,
      cpf: termoSomenteDigitos.length >= 11 ? termoSomenteDigitos.slice(0, 11) : prev.cpf
    }));
    setMostrarCadastroLeitor(true);
  };

  const handleBuscarLeitor = () => {
    if (!buscaLeitor.trim()) {
      alert('Digite o nome, CPF ou matrícula do leitor para buscar.');
      return;
    }

    if (leitoresFiltrados.length === 1) {
      handleSelecionarLeitor(leitoresFiltrados[0]);
      return;
    }

    if (leitoresFiltrados.length === 0) {
      perguntarCadastroLeitor();
    }
  };

  const handleSubmit = () => {
    const cliente = clientes.find(c => c.id === formData.clienteId);
    const livro = livros.find(l => l.id === formData.livroId);
    
    if (!cliente || !livro) {
      alert('Cliente ou livro não encontrado!');
      return;
    }
    
    if (!formData.dataDevolucaoPrevista) {
      alert('Data de devolução prevista é obrigatória!');
      return;
    }

    adicionarEmprestimo({
      ...formData,
      clienteNome: cliente.nome,
      livroTitulo: livro.titulo,
      status: 'ativo',
      dataDevolucao: formData.dataDevolucaoPrevista
    });
    handleClose();
  };

  const handleDevolucao = (id) => {
    if (window.confirm('Confirmar devolução deste empréstimo?')) {
      atualizarEmprestimo(id, {
        status: 'devolvido',
        dataDevolucaoReal: new Date().toISOString().split('T')[0]
      });
    }
  };

  const montarDadosTermoEmprestimo = (emprestimo) => {
    const dados = emprestimo?.dadosTermoEmprestimo || {};
    const livro = livros.find((item) => String(item?.id) === String(emprestimo?.livroId));
    const leitor = clientes.find((item) => String(item?.id) === String(emprestimo?.clienteId));

    return {
      ...dados,
      codigoEmprestimo: dados.codigoEmprestimo || emprestimo?.codigoEmprestimo,
      dataEmprestimo: dados.dataEmprestimo || emprestimo?.dataEmprestimo,
      dataDevolucao: dados.dataDevolucao || emprestimo?.dataDevolucao,
      livroCodigo: dados.livroCodigo || livro?.codigoIdentificacao || 'N/A',
      livroTitulo: dados.livroTitulo || emprestimo?.livroTitulo || livro?.titulo || 'N/A',
      livroAutor: dados.livroAutor || livro?.autor || 'N/A',
      livroISBN: dados.livroISBN || livro?.isbn || 'N/A',
      livroEditora: dados.livroEditora || livro?.editora || 'N/A',
      livroTipo: dados.livroTipo || livro?.tipo || 'N/A',
      leitorCodigo: dados.leitorCodigo || leitor?.codigoIdentificacao || 'N/A',
      leitorNome: dados.leitorNome || emprestimo?.clienteNome || leitor?.nome || 'N/A',
      leitorCPF: dados.leitorCPF || leitor?.cpf || 'N/A',
      leitorTelefone: dados.leitorTelefone || leitor?.telefone || 'N/A',
      leitorEmail: dados.leitorEmail || leitor?.email || 'N/A',
      leitorEndereco: dados.leitorEndereco || leitor?.endereco || 'N/A',
      leitorMatricula: dados.leitorMatricula || leitor?.matricula || '',
      leitorTurma: dados.leitorTurma || emprestimo?.turmaNome || leitor?.turma || leitor?.nomeTurma || 'N/A',
      leitorSerie: dados.leitorSerie || emprestimo?.serieNome || leitor?.serie || leitor?.nomeSerie || 'N/A'
    };
  };
  
  const handleAbrirTermo = (emprestimo) => {
    setTermoSelecionado(montarDadosTermoEmprestimo(emprestimo));
    setTipoTermo('preenchido');
    setTermoOpen(true);
  };
  
  const handleAbrirTermoBranco = () => {
    setTermoSelecionado(null);
    setTipoTermo('branco');
    setTermoOpen(true);
  };
  
  const handleImprimirLote = () => {
    const emprestimosAtivos = emprestimos.filter(e => e.status === 'ativo');
    if (emprestimosAtivos.length === 0) {
      alert('Não há empréstimos ativos para imprimir!');
      return;
    }
    
    alert('✅ Preparado ' + emprestimosAtivos.length + ' termo(s) para impressão em lote!\n\nClique em OK para imprimir cada termo individualmente.');
    
    // Imprimir cada termo com um pequeno delay
    emprestimosAtivos.forEach((emp, index) => {
      setTimeout(() => {
        handleAbrirTermo(emp);
      }, index * 500);
    });
  };

  const getStatusColor = (emprestimo) => {
    if (emprestimo.status === 'devolvido') return 'success';
    const hoje = new Date();
    const dataDev = new Date(emprestimo.dataDevolucao);
    if (dataDev < hoje) return 'error';
    return 'primary';
  };

  const getStatusLabel = (emprestimo) => {
    if (emprestimo.status === 'devolvido') return 'Devolvido';
    const hoje = new Date();
    const dataDev = new Date(emprestimo.dataDevolucao);
    if (dataDev < hoje) return 'Atrasado';
    return 'Ativo';
  };

  const emprestimosComDetalhes = useMemo(() => {
    const livrosPorId = new Map(livros.map((livro) => [String(livro.id), livro]));
    const leitoresPorId = new Map(clientes.map((cliente) => [String(cliente.id), cliente]));
    const turmasPorId = new Map(turmasAcademicas.map((turma) => [String(turma.id), turma]));

    return emprestimos.map((emprestimo) => {
      const livro = livrosPorId.get(String(emprestimo.livroId)) || {};
      const leitorId = emprestimo.clienteId ?? emprestimo.leitorId;
      const leitor = leitoresPorId.get(String(leitorId)) || {};
      const turma = turmasPorId.get(String(leitor.turmaId ?? emprestimo.turmaId)) || {};
      const dadosHistoricos = emprestimo.dadosTermoEmprestimo || {};

      const serie = String(
        turma.nomeSerie
        || leitor.serie
        || leitor.nomeSerie
        || emprestimo.serieNome
        || dadosHistoricos.leitorSerie
        || ''
      ).trim();
      const nomeTurma = String(
        turma.nomeTurma
        || leitor.turma
        || leitor.nomeTurma
        || emprestimo.turmaNome
        || dadosHistoricos.leitorTurma
        || ''
      ).trim();
      const anoSerieDireto = String(
        leitor.anoSerieTurma
        || leitor.serieTurma
        || leitor.turmaSerie
        || leitor.serie_turma
        || ''
      ).trim();

      return {
        ...emprestimo,
        detalhes: {
          leitorNome: leitor.nome || emprestimo.clienteNome || dadosHistoricos.leitorNome || 'Leitor não encontrado',
          anoSerie: anoSerieDireto || [serie, nomeTurma].filter((valor) => valor && valor !== 'N/A').join(' - ') || 'Não informado',
          livroTitulo: livro.titulo || emprestimo.livroTitulo || dadosHistoricos.livroTitulo || 'Livro não encontrado',
          livroAutor: livro.autor || dadosHistoricos.livroAutor || 'Não informado',
          livroIsbn: livro.isbn || dadosHistoricos.livroISBN || 'Não informado'
        }
      };
    });
  }, [emprestimos, livros, clientes, turmasAcademicas]);

  const emprestimosFiltrados = useMemo(() => {
    const termo = busca.trim().toLowerCase();
    if (!termo) return emprestimosComDetalhes;
    return emprestimosComDetalhes.filter((emp) => {
      const codigo = String(emp.codigoEmprestimo || `EMP${String(emp.id).padStart(6, '0')}`).toLowerCase();
      const leitor = String(emp.detalhes.leitorNome).toLowerCase();
      const livro = String(emp.detalhes.livroTitulo).toLowerCase();
      const autor = String(emp.detalhes.livroAutor).toLowerCase();
      const isbn = String(emp.detalhes.livroIsbn).toLowerCase();
      const anoSerie = String(emp.detalhes.anoSerie).toLowerCase();
      const status = getStatusLabel(emp).toLowerCase();
      return [codigo, leitor, livro, autor, isbn, anoSerie, status].some((valor) => valor.includes(termo));
    });
  }, [emprestimosComDetalhes, busca]);

  return (
    <Layout title="Empréstimos">
      <Grid container spacing={2} sx={{ mb: 2 }}>
        <Grid item xs={12} md={3}>
          <Card>
            <CardContent>
              <Typography variant="caption" color="text.secondary">Exemplares no acervo</Typography>
              <Typography variant="h5" fontWeight={700}>{resumoEstoqueEmprestimos.totalExemplares}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={3}>
          <Card>
            <CardContent>
              <Typography variant="caption" color="text.secondary">Empréstimos ativos</Typography>
              <Typography variant="h5" fontWeight={700}>{resumoEstoqueEmprestimos.emprestados}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={3}>
          <Card>
            <CardContent>
              <Typography variant="caption" color="text.secondary">Estoque disponível</Typography>
              <Typography variant="h5" fontWeight={700} color="success.main">{resumoEstoqueEmprestimos.disponiveis}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={3}>
          <Card>
            <CardContent>
              <Typography variant="caption" color="text.secondary">Acesso rápido</Typography>
              <Button
                sx={{ mt: 1 }}
                fullWidth
                variant="outlined"
                onClick={() => navigate('/relatorios-livros')}
              >
                Ver estoque disponível
              </Button>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      <Box sx={{ mb: 2, display: 'flex', justifyContent: 'space-between', flexWrap: 'wrap', gap: 1 }}>
        <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
          <Button
            variant="outlined"
            startIcon={<Description />}
            onClick={handleAbrirTermoBranco}
            color="secondary"
          >
            Termo em Branco
          </Button>
          <Button
            variant="outlined"
            startIcon={<PrintOutlined />}
            onClick={handleImprimirLote}
            color="info"
          >
            Imprimir em Lote
          </Button>
        </Box>
        <Button
          variant="contained"
          startIcon={<Add />}
          onClick={handleOpen}
        >
          Novo Empréstimo
        </Button>
      </Box>

      <Box sx={{ mb: 2 }}>
        <TextField
          fullWidth
          size="small"
          placeholder="Buscar por leitor, ano/série, livro, autor, ISBN, código ou status..."
          value={busca}
          onChange={(e) => setBusca(e.target.value)}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <Search fontSize="small" sx={{ color: 'text.secondary' }} />
              </InputAdornment>
            )
          }}
        />
      </Box>

      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Código</TableCell>
              <TableCell>Leitor</TableCell>
              <TableCell>Ano/Série</TableCell>
              <TableCell>Nome do Livro</TableCell>
              <TableCell>Autor</TableCell>
              <TableCell>Código ISBN</TableCell>
              <TableCell>Data Empréstimo</TableCell>
              <TableCell>Data Devolução</TableCell>
              <TableCell>Status</TableCell>
              <TableCell>Ações</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {emprestimos.length === 0 ? (
              <TableRow>
                <TableCell colSpan={10} align="center">
                  <Typography color="text.secondary">
                    Nenhum empréstimo registrado
                  </Typography>
                </TableCell>
              </TableRow>
            ) : emprestimosFiltrados.length === 0 ? (
              <TableRow>
                <TableCell colSpan={10} align="center">
                  <Typography color="text.secondary">
                    Nenhum empréstimo encontrado para "{busca}"
                  </Typography>
                </TableCell>
              </TableRow>
            ) : (
              emprestimosFiltrados.map((emprestimo) => (
                <TableRow key={emprestimo.id}>
                  <TableCell>
                    <Chip 
                      label={emprestimo.codigoEmprestimo || `EMP${emprestimo.id.toString().padStart(6, '0')}`}
                      size="small"
                      color="default"
                      variant="outlined"
                    />
                  </TableCell>
                  <TableCell>{emprestimo.detalhes.leitorNome}</TableCell>
                  <TableCell>{emprestimo.detalhes.anoSerie}</TableCell>
                  <TableCell>{emprestimo.detalhes.livroTitulo}</TableCell>
                  <TableCell>{emprestimo.detalhes.livroAutor}</TableCell>
                  <TableCell sx={{ whiteSpace: 'nowrap' }}>{emprestimo.detalhes.livroIsbn}</TableCell>
                  <TableCell>
                    {new Date(emprestimo.dataEmprestimo).toLocaleDateString('pt-BR')}
                  </TableCell>
                  <TableCell>
                    {new Date(emprestimo.dataDevolucao).toLocaleDateString('pt-BR')}
                  </TableCell>
                  <TableCell>
                    <Chip 
                      label={getStatusLabel(emprestimo)} 
                      size="small" 
                      color={getStatusColor(emprestimo)}
                    />
                  </TableCell>
                  <TableCell>
                    <Box sx={{ display: 'flex', gap: 0.5 }}>
                      <IconButton 
                        onClick={() => handleAbrirTermo(emprestimo)} 
                        size="small"
                        color="info"
                        title="Imprimir Termo"
                      >
                        <Print />
                      </IconButton>
                      {emprestimo.status === 'ativo' && (
                        <IconButton 
                          onClick={() => handleDevolucao(emprestimo.id)} 
                          size="small"
                          color="primary"
                          title="Devolver Livro"
                        >
                          <AssignmentReturn />
                        </IconButton>
                      )}
                    </Box>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </TableContainer>

      <Dialog open={open} onClose={handleClose} maxWidth="md" fullWidth>
        <DialogTitle>
          Novo Empréstimo
          <Typography variant="body2" color="text.secondary">
            {etapaAtual === 1 ? '📚 Etapa 1: Buscar Livro por ISBN' : '👤 Etapa 2: Selecionar Leitor'}
          </Typography>
        </DialogTitle>
        <DialogContent>
          <Box sx={{ mt: 2 }}>
            {/* ETAPA 1: BUSCAR LIVRO POR ISBN */}
            {etapaAtual === 1 && (
              <Box>
                {!mostrarCadastroLivro ? (
                  <>
                    <Alert severity="info" sx={{ mb: 3 }}>
                      Digite o ISBN do livro que será emprestado
                    </Alert>

                    <Box sx={{ display: 'flex', gap: 2, mb: 3 }}>
                      <TextField
                        label="ISBN"
                        fullWidth
                        required
                        value={isbnBusca}
                        onChange={(e) => setIsbnBusca(e.target.value)}
                        onKeyDown={(e) => {
                          if (e.key === 'Enter') {
                            buscarLivroPorISBN();
                          }
                        }}
                        placeholder="Digite o ISBN e pressione Enter"
                        autoFocus
                        InputProps={{
                          endAdornment: (
                            <InputAdornment position="end">
                              <IconButton onClick={buscarLivroPorISBN} edge="end">
                                <Search />
                              </IconButton>
                            </InputAdornment>
                          )
                        }}
                      />
                      <Button
                        variant="contained"
                        startIcon={<Search />}
                        onClick={buscarLivroPorISBN}
                        sx={{ minWidth: 120 }}
                      >
                        Buscar
                      </Button>
                    </Box>
                  </>
                ) : (
                  <>
                    <Alert severity="warning" sx={{ mb: 2 }}>
                      ISBN não encontrado. Cadastre o novo livro para continuar o empréstimo.
                    </Alert>

                    <Grid container spacing={2}>
                      <Grid item xs={12}>
                        <TextField
                          label="ISBN"
                          fullWidth
                          required
                          value={novoLivro.isbn}
                          onChange={(e) => setNovoLivro((prev) => ({ ...prev, isbn: e.target.value }))}
                        />
                      </Grid>
                      <Grid item xs={12}>
                        <TextField
                          label="Título"
                          fullWidth
                          required
                          value={novoLivro.titulo}
                          onChange={(e) => setNovoLivro((prev) => ({ ...prev, titulo: e.target.value }))}
                        />
                      </Grid>
                      <Grid item xs={12}>
                        <TextField
                          label="Autor"
                          fullWidth
                          required
                          value={novoLivro.autor}
                          onChange={(e) => setNovoLivro((prev) => ({ ...prev, autor: e.target.value }))}
                        />
                      </Grid>
                      <Grid item xs={12} sm={6}>
                        <TextField
                          label="Tipo de Livro"
                          fullWidth
                          select
                          value={novoLivro.tipo}
                          onChange={(e) => setNovoLivro((prev) => ({
                            ...prev,
                            tipo: e.target.value,
                            anoVigencia: e.target.value === 'Didático' ? prev.anoVigencia : ''
                          }))}
                        >
                          <MenuItem value="Didático">Didático</MenuItem>
                          <MenuItem value="Paradidático">Paradidático</MenuItem>
                          <MenuItem value="Livro do Professor">Livro do Professor</MenuItem>
                        </TextField>
                      </Grid>
                      <Grid item xs={12} sm={6}>
                        <TextField
                          label="Quantidade"
                          fullWidth
                          type="number"
