                      </Grid>
                      {novoLivro.tipo === 'Didático' && (
                        <Grid item xs={12} sm={6}>
                          <TextField
                            label="Ano de Vigência"
                            fullWidth
                            type="number"
                            value={novoLivro.anoVigencia}
