                        variant="contained"
                        startIcon={<Add />}
                        onClick={handleCadastrarLivroEContinuar}
                        fullWidth
                      >
                        Cadastrar e continuar
                      </Button>
                    </Box>
                  </>
                )}
              </Box>
            )}

            {/* ETAPA 2: SELECIONAR OU CADASTRAR LEITOR */}
            {etapaAtual === 2 && (
              <Box>
