                    {/* Busca de leitor */}
                    <TextField
                      label="Buscar Leitor"
                      fullWidth
                      value={buscaLeitor}
                      onChange={(e) => setBuscaLeitor(e.target.value)}
                      onKeyDown={(e) => {
