                            <Box sx={{ mt: 1 }}>
                              <Button size="small" variant="contained" onClick={perguntarCadastroLeitor}>
                                Cadastrar novo leitor
                              </Button>
                            </Box>
                          </Alert>
                        )}
                      </Box>
                    )}

                    <Button
                      variant="outlined"
                      startIcon={<PersonAdd />}
                      fullWidth
                      onClick={() => setMostrarCadastroLeitor(true)}
                      sx={{ mb: 2 }}
                    >
                      Cadastrar Novo Leitor
                    </Button>

                    <Divider sx={{ my: 2 }} />

                    {/* Campos de empréstimo */}
                    <Grid container spacing={2}>
                      <Grid item xs={12}>
                        <FormControl component="fieldset" required>
                          <FormLabel component="legend">Categoria do Leitor</FormLabel>
                          <RadioGroup
                            row
                            value={formData.categoriaLeitor}
                            onChange={(e) => setFormData(prev => ({ ...prev, categoriaLeitor: e.target.value }))}
                          >
                            <FormControlLabel value="estudante" control={<Radio size="small" />} label="Estudante" />
                            <FormControlLabel value="professor" control={<Radio size="small" />} label="Professor" />
                            <FormControlLabel value="funcionario" control={<Radio size="small" />} label="Funcionário" />
                            <FormControlLabel value="comunidade" control={<Radio size="small" />} label="Comunidade" />
                          </RadioGroup>
                        </FormControl>
                      </Grid>
                      <Grid item xs={12} sm={6}>
                        <TextField
                          label="Data do Empréstimo"
                          fullWidth
                          type="date"
                          required
                          InputLabelProps={{ shrink: true }}
                          value={formData.dataEmprestimo}
                          onChange={(e) => setFormData(prev => ({ ...prev, dataEmprestimo: e.target.value }))}
                        />
                      </Grid>
                      <Grid item xs={12} sm={6}>
                        <TextField
                          label="Data de Devolução Prevista"
                          fullWidth
                          type="date"
                          required
                          InputLabelProps={{ shrink: true }}
                          value={formData.dataDevolucaoPrevista}
                          onChange={(e) => setFormData(prev => ({ ...prev, dataDevolucaoPrevista: e.target.value }))}
                        />
                      </Grid>
                      <Grid item xs={12}>
                        <TextField
                          label="Observações"
                          fullWidth
                          multiline
                          rows={2}
                          value={formData.observacoes}
                          onChange={(e) => setFormData(prev => ({ ...prev, observacoes: e.target.value }))}
                        />
                      </Grid>
                    </Grid>
                  </>
                ) : (
                  <>
                    <Alert severity="warning" sx={{ mb: 2 }}>
                      Preencha os dados do novo leitor. Ele será cadastrado automaticamente.
                    </Alert>
                    
                    <Grid container spacing={2}>
                      <Grid item xs={12}>
                        <TextField
                          label="Nome Completo"
                          fullWidth
                          required
                          value={novoLeitor.nome}
                          onChange={(e) => setNovoLeitor({ ...novoLeitor, nome: e.target.value })}
                        />
                      </Grid>
                      <Grid item xs={12} sm={6}>
                        <TextField
                          label="CPF"
                          fullWidth
                          required
                          value={novoLeitor.cpf}
                          onChange={(e) => setNovoLeitor({ ...novoLeitor, cpf: e.target.value })}
                        />
                      </Grid>
                      <Grid item xs={12} sm={6}>
                        <TextField
                          label="Telefone"
                          fullWidth
                          value={novoLeitor.telefone}
                          onChange={(e) => setNovoLeitor({ ...novoLeitor, telefone: e.target.value })}
                        />
                      </Grid>
                      <Grid item xs={12}>
                        <TextField
                          label="Email"
                          fullWidth
                          type="email"
                          value={novoLeitor.email}
                          onChange={(e) => setNovoLeitor({ ...novoLeitor, email: e.target.value })}
                        />
                      </Grid>
                      <Grid item xs={12}>
                        <TextField
                          label="Endereço"
                          fullWidth
                          value={novoLeitor.endereco}
                          onChange={(e) => setNovoLeitor({ ...novoLeitor, endereco: e.target.value })}
                        />
                      </Grid>
                    </Grid>

                    <Box sx={{ mt: 2, display: 'flex', gap: 2 }}>
                      <Button
                        variant="outlined"
                        onClick={() => setMostrarCadastroLeitor(false)}
                        fullWidth
                      >
                        Cancelar
                      </Button>
                      <Button
                        variant="contained"
                        startIcon={<PersonAdd />}
                        onClick={handleCadastrarLeitor}
                        fullWidth
                      >
                        Cadastrar e Continuar
                      </Button>
                    </Box>
                  </>
                )}
              </Box>
            )}
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClose}>Cancelar</Button>
          {etapaAtual === 2 && !mostrarCadastroLeitor && (
            <Button 
              onClick={handleSubmit} 
              variant="contained"
              disabled={!formData.clienteId || !formData.dataDevolucaoPrevista}
            >
              Registrar Empréstimo
            </Button>
          )}
        </DialogActions>
      </Dialog>

      {/* Dialog do Termo de Empréstimo */}
      <TermoEmprestimo
        open={termoOpen}
        onClose={() => setTermoOpen(false)}
        dados={termoSelecionado}
        tipo={tipoTermo}
      />
    </Layout>
  );
}

export default EmprestimosPage;

import React, { useState, useMemo } from 'react';
import Layout from '../components/Layout';
import { useData } from '../context/DataContext';
import {
  Box,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
  Button,
  Checkbox,
  TextField,
  Grid,
  Card,
  CardContent,
  Chip,
  Alert,
  FormControlLabel,
  Switch,
  Divider,
  IconButton,
  Tooltip
} from '@mui/material';
import { Print, SelectAll, Search, Label } from '@mui/icons-material';

function gerarCodigosUnitarios(item, tipo) {
  const codigos = [];
  const quantidade = Number(item.quantidade) || 1;
  const codigoBase = tipo === 'livro'
    ? (item.codigoIdentificacao || `LIV${String(item.id).slice(0, 6)}`)
    : (item.numeroPatrimonio || `PAT${String(item.id).slice(0, 6)}`);

  for (let i = 1; i <= quantidade; i++) {
    codigos.push({
      codigoUnitario: `${codigoBase}-${String(i).padStart(2, '0')}`,
      codigoBase,
      exemplar: i,
      totalExemplares: quantidade,
      titulo: tipo === 'livro' ? item.titulo : item.descricao,
      autor: tipo === 'livro' ? (item.autor || '') : '',
      isbn: tipo === 'livro' ? (item.isbn || '') : '',
      tipoItem: tipo === 'livro' ? (item.tipo || 'Livro') : 'Patrimônio',
      categoria: tipo === 'livro' ? (item.categoria || '') : (item.categoria || ''),
      localizacao: item.localizacao || '',
      itemId: item.id
    });
  }
  return codigos;
}

export default function EtiquetasPage() {
  const { livros, patrimonio } = useData();
  const [busca, setBusca] = useState('');
  const [selecionados, setSelecionados] = useState(new Set());
  const [incluirPatrimonio, setIncluirPatrimonio] = useState(false);
  const [tamanhoEtiqueta, setTamanhoEtiqueta] = useState('molde'); // molde, pequena, media, grande

  const todosOsCodigos = useMemo(() => {
    const codigos = [];

    livros.filter(l => !l.baixa).forEach(livro => {
      codigos.push(...gerarCodigosUnitarios(livro, 'livro'));
    });

    if (incluirPatrimonio) {
      patrimonio.forEach(bem => {
        codigos.push(...gerarCodigosUnitarios(bem, 'patrimonio'));
      });
    }

    return codigos;
  }, [livros, patrimonio, incluirPatrimonio]);

  const codigosFiltrados = useMemo(() => {
    if (!busca.trim()) return todosOsCodigos;
    const termo = busca.toLowerCase();
    return todosOsCodigos.filter(c =>
      c.codigoUnitario.toLowerCase().includes(termo) ||
      c.titulo.toLowerCase().includes(termo) ||
      c.autor.toLowerCase().includes(termo) ||
      c.isbn.toLowerCase().includes(termo) ||
      c.codigoBase.toLowerCase().includes(termo)
    );
  }, [todosOsCodigos, busca]);

  const toggleSelecionado = (codigo) => {
    setSelecionados(prev => {
      const next = new Set(prev);
      if (next.has(codigo)) {
        next.delete(codigo);
      } else {
        next.add(codigo);
      }
      return next;
    });
  };

  const selecionarTodos = () => {
    if (selecionados.size === codigosFiltrados.length) {
      setSelecionados(new Set());
    } else {
      setSelecionados(new Set(codigosFiltrados.map(c => c.codigoUnitario)));
    }
  };

  const TIPOS_PADRAO = ['Didático', 'Paradidático', 'Livro do Professor'];

  const selecionarPorTipo = (tipo) => {
    const codigosDoTipo = codigosFiltrados.filter(c =>
      c.tipoItem.toLowerCase() === tipo.toLowerCase()
    );
    const todosSelecionados = codigosDoTipo.length > 0 &&
      codigosDoTipo.every(c => selecionados.has(c.codigoUnitario));

    setSelecionados(prev => {
      const next = new Set(prev);
      codigosDoTipo.forEach(c => {
        if (todosSelecionados) {
          next.delete(c.codigoUnitario);
        } else {
          next.add(c.codigoUnitario);
        }
      });
      return next;
    });
  };

  const selecionarPorItem = (itemId) => {
    const codigosDoItem = codigosFiltrados.filter(c => c.itemId === itemId);
    const todosJaSelecionados = codigosDoItem.every(c => selecionados.has(c.codigoUnitario));

    setSelecionados(prev => {
      const next = new Set(prev);
      codigosDoItem.forEach(c => {
        if (todosJaSelecionados) {
          next.delete(c.codigoUnitario);
        } else {
          next.add(c.codigoUnitario);
        }
      });
      return next;
    });
  };

  const etiquetasSelecionadas = codigosFiltrados.filter(c => selecionados.has(c.codigoUnitario));

  const dimensoes = {
    molde: { w: 23, h: 15, fontSize: 4, titleSize: 4, codeSize: 6,
      cols: 7, rows: 18, colGap: 6, rowGap: 0,
      marginTop: 13, marginLeft: 5 },
    pequena: { w: 50, h: 25, fontSize: 7, titleSize: 6, codeSize: 9 },
    media: { w: 70, h: 35, fontSize: 8, titleSize: 7, codeSize: 11 },
    grande: { w: 90, h: 45, fontSize: 9, titleSize: 8, codeSize: 13 }
  };

  const handleImprimirEtiquetas = () => {
    const items = etiquetasSelecionadas.length > 0 ? etiquetasSelecionadas : codigosFiltrados;
    if (items.length === 0) {
      alert('Nenhuma etiqueta para imprimir.');
      return;
    }

    const dim = dimensoes[tamanhoEtiqueta];

    const win = window.open('', '_blank');
    if (!win) {
      alert('Popup bloqueado. Permita popups para imprimir etiquetas.');
      return;
    }

    if (tamanhoEtiqueta === 'molde') {
      // Layout exato para o molde: 7 colunas × 18 linhas, 23×15mm por etiqueta
      const etiquetasHtml = items.map(item => {
        const titulo = item.titulo.length > 18 ? item.titulo.substring(0, 16) + '..' : item.titulo;
        const autor = item.autor ? (item.autor.split(' ').pop() || item.autor).substring(0, 10) : '';
        return `<div class="etiqueta"><div class="codigo">${item.codigoUnitario}</div><div class="titulo">${titulo}</div>${autor ? `<div class="autor">${autor}</div>` : ''}</div>`;
      }).join('');

      win.document.write(`<!DOCTYPE html>
<html><head><title>Etiquetas - CEI Biblioteca</title>
<style>
  @page { size: A4; margin: 0; }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { font-family: Arial, Helvetica, sans-serif; width: 210mm; }
  .container {
    margin-top: ${dim.marginTop}mm;
    margin-left: ${dim.marginLeft}mm;
    display: grid;
    grid-template-columns: repeat(${dim.cols}, ${dim.w}mm);
