    line-height: 1.1; max-height: ${dim.h * 0.3}mm;
    overflow: hidden;
  }
  .autor {
    font-size: ${dim.fontSize - 1}pt; color: #555;
    line-height: 1; margin-top: 0.5mm;
  }
  .codigo {
    font-size: ${dim.codeSize}pt; font-weight: bold;
    font-family: 'Courier New', monospace;
    margin-top: 1mm; letter-spacing: 0.5px;
    border: 1px solid #333; padding: 0.5mm 2mm;
    border-radius: 2px; background: #f9f9f9;
  }
  .tipo {
    font-size: ${dim.fontSize - 2}pt; color: #777;
    margin-top: 0.5mm;
  }
  @media print {
    .etiqueta { border-color: #ccc; }
  }
</style>
</head><body>
<div class="container">${etiquetasHtml}</div>
</body></html>`);
    }

    win.document.close();
    setTimeout(() => win.print(), 300);
  };

  // Group by item for display
  const itensPorId = useMemo(() => {
    const map = new Map();
    codigosFiltrados.forEach(c => {
      if (!map.has(c.itemId)) {
        map.set(c.itemId, {
          titulo: c.titulo,
          codigoBase: c.codigoBase,
          autor: c.autor,
          tipoItem: c.tipoItem,
          isbn: c.isbn,
          codigos: []
        });
      }
      map.get(c.itemId).codigos.push(c);
    });
    return Array.from(map.values());
  }, [codigosFiltrados]);

  const totalLivros = livros.filter(l => !l.baixa).length;
  const totalExemplares = livros.filter(l => !l.baixa).reduce((sum, l) => sum + (Number(l.quantidade) || 1), 0);
  const totalPatrimonio = patrimonio.length;

  return (
    <Layout title="Etiquetas e Códigos Unitários">
      <Grid container spacing={2} sx={{ mb: 2 }}>
        <Grid item xs={6} sm={3}>
          <Card>
            <CardContent sx={{ py: 1 }}>
              <Typography variant="caption" color="text.secondary">Títulos</Typography>
              <Typography variant="h5" fontWeight={700}>{totalLivros}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={6} sm={3}>
          <Card>
            <CardContent sx={{ py: 1 }}>
              <Typography variant="caption" color="text.secondary">Exemplares</Typography>
              <Typography variant="h5" fontWeight={700}>{totalExemplares}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={6} sm={3}>
          <Card>
            <CardContent sx={{ py: 1 }}>
              <Typography variant="caption" color="text.secondary">Etiquetas Geradas</Typography>
              <Typography variant="h5" fontWeight={700}>{todosOsCodigos.length}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={6} sm={3}>
          <Card sx={{ bgcolor: 'primary.main', color: 'white' }}>
            <CardContent sx={{ py: 1 }}>
              <Typography variant="caption" sx={{ opacity: 0.8 }}>Selecionadas</Typography>
              <Typography variant="h5" fontWeight={700}>{selecionados.size}</Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      <Alert severity="info" sx={{ mb: 2 }}>
        Cada exemplar recebe um código unitário único (ex: <strong>LIV000001-01</strong>, <strong>LIV000001-02</strong>).
        Selecione as etiquetas e clique em "Imprimir Etiquetas" para gerar folha pronta para impressão.
      </Alert>

      {/* Controles */}
      <Box sx={{ display: 'flex', gap: 2, mb: 2, flexWrap: 'wrap', alignItems: 'center' }}>
        <TextField
          placeholder="Buscar por título, autor, ISBN ou código..."
          variant="outlined"
          size="small"
          value={busca}
          onChange={(e) => setBusca(e.target.value)}
          InputProps={{ startAdornment: <Search sx={{ mr: 1, color: 'text.secondary' }} /> }}
          sx={{ flexGrow: 1, minWidth: 200 }}
        />
        <FormControlLabel
          control={<Switch checked={incluirPatrimonio} onChange={(e) => setIncluirPatrimonio(e.target.checked)} size="small" />}
          label="Incluir Patrimônio"
        />
        <TextField
          select
          size="small"
          label="Tamanho"
          value={tamanhoEtiqueta}
          onChange={(e) => setTamanhoEtiqueta(e.target.value)}
          SelectProps={{ native: true }}
          sx={{ minWidth: 120 }}
        >
          <option value="molde">Molde PDF (23×15mm — 7 col × 18 lin)</option>
          <option value="pequena">Pequena (50×25mm)</option>
          <option value="media">Média (70×35mm)</option>
          <option value="grande">Grande (90×45mm)</option>
        </TextField>
        <Button variant="outlined" startIcon={<SelectAll />} onClick={selecionarTodos} size="small">
          {selecionados.size === codigosFiltrados.length ? 'Desmarcar Todos' : 'Selecionar Todos'}
        </Button>
        {TIPOS_PADRAO.map(tipo => {
          const codigosDoTipo = codigosFiltrados.filter(c => c.tipoItem === tipo);
          if (codigosDoTipo.length === 0) return null;
          const todosSel = codigosDoTipo.every(c => selecionados.has(c.codigoUnitario));
          return (
            <Button
              key={tipo}
              variant={todosSel ? 'contained' : 'outlined'}
              color="secondary"
              size="small"
              onClick={() => selecionarPorTipo(tipo)}
            >
              {tipo} ({codigosDoTipo.length})
            </Button>
          );
        })}
        <Button
          variant="contained"
          startIcon={<Print />}
          onClick={handleImprimirEtiquetas}
          disabled={codigosFiltrados.length === 0}
        >
          Imprimir Etiquetas {selecionados.size > 0 ? `(${selecionados.size})` : `(${codigosFiltrados.length})`}
        </Button>
      </Box>

      <Divider sx={{ mb: 2 }} />

      {/* Tabela agrupada por item */}
      {itensPorId.map((item, idx) => (
        <Paper key={idx} sx={{ mb: 2, overflow: 'hidden' }}>
          <Box sx={{
            display: 'flex', alignItems: 'center', gap: 2,
            p: 1.5, bgcolor: 'grey.100', cursor: 'pointer'
          }}
            onClick={() => selecionarPorItem(item.codigos[0]?.itemId)}
          >
            <Checkbox
              checked={item.codigos.every(c => selecionados.has(c.codigoUnitario))}
              indeterminate={item.codigos.some(c => selecionados.has(c.codigoUnitario)) && !item.codigos.every(c => selecionados.has(c.codigoUnitario))}
              size="small"
            />
            <Label fontSize="small" color="action" />
            <Box sx={{ flexGrow: 1 }}>
              <Typography variant="subtitle2" fontWeight={700}>
                {item.titulo}
                {item.autor && <Typography component="span" variant="body2" color="text.secondary"> — {item.autor}</Typography>}
              </Typography>
              <Typography variant="caption" color="text.secondary">
                Código: {item.codigoBase} | Tipo: {item.tipoItem}
                {item.isbn && ` | ISBN: ${item.isbn}`}
                {' | '}{item.codigos.length} exemplar(es)
              </Typography>
            </Box>
            <Chip label={`${item.codigos.length} etiqueta(s)`} size="small" color="primary" variant="outlined" />
          </Box>
          <TableContainer>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell padding="checkbox" />
                  <TableCell>Código Unitário</TableCell>
                  <TableCell>Exemplar</TableCell>
                  <TableCell>Tipo</TableCell>
                  <TableCell>Categoria</TableCell>
                  <TableCell>Localização</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {item.codigos.map((c) => (
                  <TableRow
                    key={c.codigoUnitario}
                    hover
                    selected={selecionados.has(c.codigoUnitario)}
                    onClick={() => toggleSelecionado(c.codigoUnitario)}
                    sx={{ cursor: 'pointer' }}
                  >
                    <TableCell padding="checkbox">
                      <Checkbox checked={selecionados.has(c.codigoUnitario)} size="small" />
                    </TableCell>
                    <TableCell>
                      <Chip
                        label={c.codigoUnitario}
                        size="small"
                        color="primary"
                        variant={selecionados.has(c.codigoUnitario) ? 'filled' : 'outlined'}
                        sx={{ fontFamily: 'monospace', fontWeight: 700 }}
                      />
                    </TableCell>
                    <TableCell>{c.exemplar} de {c.totalExemplares}</TableCell>
                    <TableCell>{c.tipoItem}</TableCell>
                    <TableCell>{c.categoria || '-'}</TableCell>
                    <TableCell>{c.localizacao || '-'}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>
      ))}

      {codigosFiltrados.length === 0 && (
        <Alert severity="warning">
          Nenhum item encontrado. Cadastre livros ou patrimônio para gerar etiquetas.
        </Alert>
      )}
    </Layout>
  );
}

import React, { useState } from 'react';
import Layout from '../components/Layout';
import { useData } from '../context/DataContext';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Button,
  Chip,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Grid,
  Alert,
  IconButton,
  Tooltip,
  MenuItem
} from '@mui/material';
import AttachMoneyIcon from '@mui/icons-material/AttachMoney';
import WarningIcon from '@mui/icons-material/Warning';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import BlockIcon from '@mui/icons-material/Block';
import ReceiptIcon from '@mui/icons-material/Receipt';
import NotificationsIcon from '@mui/icons-material/Notifications';
import FilterListIcon from '@mui/icons-material/FilterList';
import RefreshIcon from '@mui/icons-material/Refresh';

export default function FinanceiroAdminPage() {
  const { 
    instituicoes, 
    registrarPagamento, 
    verificarInadimplencia,
    calcularProximoVencimento,
    obterHistoricoPagamentos 
  } = useData();

  const [dialogPagamento, setDialogPagamento] = useState(false);
  const [dialogHistorico, setDialogHistorico] = useState(false);
  const [instituicaoSelecionada, setInstituicaoSelecionada] = useState(null);
  const [valorPagamento, setValorPagamento] = useState('');
  const [metodoPagamento, setMetodoPagamento] = useState('manual');
  const [filtroStatus, setFiltroStatus] = useState('todos');

  const instituicoesAtivas = instituicoes.filter(i => i.status !== 'pendente');

  const getStatusFinanceiroChip = (status) => {
    const configs = {
      em_dia: { label: 'Em Dia', color: 'success', icon: <CheckCircleIcon /> },
      pendente: { label: 'Pendente', color: 'warning', icon: <WarningIcon /> },
      atrasado: { label: 'Atrasado', color: 'error', icon: <WarningIcon /> },
      bloqueado_financeiro: { label: 'Bloqueado', color: 'error', icon: <BlockIcon /> }
    };
    
    const config = configs[status] || configs.em_dia;
    return <Chip icon={config.icon} label={config.label} color={config.color} size="small" />;
  };

  const calcularDiasParaVencimento = (instituicao) => {
    const proximoVencimento = calcularProximoVencimento(instituicao.id);
    if (!proximoVencimento) return null;
    
    const hoje = new Date();
    const diffTime = proximoVencimento - hoje;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    
    return diffDays;
  };

  const handleRegistrarPagamento = () => {
    if (!instituicaoSelecionada || !valorPagamento) {
      alert('Preencha todos os campos');
      return;
    }

    registrarPagamento(
      instituicaoSelecionada.id,
      parseFloat(valorPagamento),
      metodoPagamento
    );

    setDialogPagamento(false);
    setInstituicaoSelecionada(null);
    setValorPagamento('');
  };

  const handleVerHistorico = (instituicao) => {
    setInstituicaoSelecionada(instituicao);
    setDialogHistorico(true);
  };

  const handleAbrirPagamento = (instituicao) => {
    setInstituicaoSelecionada(instituicao);
    setValorPagamento(instituicao.valorMensal?.toString() ?? '97.00');
    setDialogPagamento(true);
  };

  const calcularReceitaMensal = () => {
    return instituicoesAtivas.reduce((total, inst) => {
      return total + (inst.valorMensal ?? 97.00);
    }, 0);
  };

  const contarInadimplentes = () => {
    return instituicoesAtivas.filter(i => 
      i.statusFinanceiro === 'atrasado' || i.statusFinanceiro === 'bloqueado_financeiro'
    ).length;
  };

  const handleFiltrar = () => {
    // Função para atualizar a lista conforme filtro
  };

  const handleAtualizar = () => {
    // Força re-render para atualizar dados
    setFiltroStatus('todos');
  };

  const instituicoesFiltradas = instituicoesAtivas.filter(inst => {
    if (filtroStatus === 'todos') return true;
    if (filtroStatus === 'em_dia') return inst.statusFinanceiro === 'em_dia';
    if (filtroStatus === 'inadimplentes') return inst.statusFinanceiro === 'atrasado' || inst.statusFinanceiro === 'bloqueado_financeiro';
    if (filtroStatus === 'bloqueados') return inst.statusFinanceiro === 'bloqueado_financeiro';
    return true;
  });

  return (
    <Layout title="Gestão Financeira">
      {/* Painel de Botões */}
      <Box sx={{ mb: 3, display: 'flex', gap: 2, flexWrap: 'wrap' }}>
        <TextField
          select
          size="small"
          value={filtroStatus}
          onChange={(e) => setFiltroStatus(e.target.value)}
          sx={{ minWidth: 200 }}
          InputProps={{
            startAdornment: <FilterListIcon sx={{ mr: 1, color: 'text.secondary' }} />
          }}
        >
          <MenuItem value="todos">Todas as Escolas</MenuItem>
          <MenuItem value="em_dia">Adimplentes</MenuItem>
          <MenuItem value="inadimplentes">Inadimplentes</MenuItem>
          <MenuItem value="bloqueados">Bloqueados</MenuItem>
        </TextField>

        <Button
          variant="outlined"
          startIcon={<RefreshIcon />}
          onClick={handleAtualizar}
        >
          Atualizar
        </Button>

        <Box sx={{ flex: 1 }} />

        <Tooltip title="Total de escolas filtradas">
          <Chip 
            label={`${instituicoesFiltradas.length} escola(s)`} 
            color="primary"
            variant="outlined"
          />
        </Tooltip>
      </Box>

      {/* Cards Resumo */}
      <Grid container spacing={3} sx={{ mb: 3 }}>
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                Receita Mensal Prevista
              </Typography>
              <Typography variant="h4">
                R$ {calcularReceitaMensal().toFixed(2)}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                Instituições Ativas
              </Typography>
              <Typography variant="h4" color="success.main">
                {instituicoesAtivas.length}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                Inadimplentes
              </Typography>
              <Typography variant="h4" color="error.main">
                {contarInadimplentes()}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                Em Dia
              </Typography>
              <Typography variant="h4" color="success.main">
                {instituicoesAtivas.filter(i => i.statusFinanceiro === 'em_dia').length}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Tabela de Instituições */}
      <Card>
        <CardContent>
          <Typography variant="h6" gutterBottom>
            Controle de Pagamentos por Instituição
          </Typography>
          
          <TableContainer component={Paper} sx={{ mt: 2 }}>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>Instituição</TableCell>
                  <TableCell>Valor Mensal</TableCell>
                  <TableCell>Vencimento</TableCell>
                  <TableCell>Último Pagamento</TableCell>
                  <TableCell>Status</TableCell>
                  <TableCell align="center">Ações</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {instituicoesFiltradas.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={6} align="center">
                      <Typography color="text.secondary">
                        {filtroStatus === 'todos' 
                          ? 'Nenhuma instituição cadastrada'
                          : `Nenhuma instituição ${filtroStatus === 'em_dia' ? 'adimplente' : filtroStatus === 'bloqueados' ? 'bloqueada' : 'inadimplente'}`
                        }
                      </Typography>
                    </TableCell>
                  </TableRow>
                ) : (
                  instituicoesFiltradas.map((instituicao) => {
                  const diasVencimento = calcularDiasParaVencimento(instituicao);
                  const historico = obterHistoricoPagamentos(instituicao.id);
                  
                  return (
                    <TableRow key={instituicao.id}>
                      <TableCell>
                        <Typography variant="body1" fontWeight="bold">
                          {instituicao.nomeInstituicao}
                        </Typography>
                        <Typography variant="caption" color="textSecondary">
                          {instituicao.cnpj}
                        </Typography>
                      </TableCell>
                      
                      <TableCell>
                        <Typography variant="body1">
                          R$ {(instituicao.valorMensal ?? 97.00).toFixed(2)}
                        </Typography>
                      </TableCell>
                      
                      <TableCell>
                        <Typography>Dia {instituicao.diaVencimento || 10}</Typography>
                        {diasVencimento !== null && (
                          <Typography variant="caption" color={diasVencimento < 5 ? 'error' : 'textSecondary'}>
                            {diasVencimento > 0 
                              ? `${diasVencimento} dias` 
                              : `Vencido há ${Math.abs(diasVencimento)} dias`}
                          </Typography>
                        )}
                      </TableCell>
                      
                      <TableCell>
                        {instituicao.ultimoPagamento ? (
                          <Typography variant="caption">
                            {new Date(instituicao.ultimoPagamento).toLocaleDateString('pt-BR')}
                          </Typography>
                        ) : (
                          <Typography variant="caption" color="textSecondary">
                            Nenhum pagamento
                          </Typography>
                        )}
                      </TableCell>
                      
                      <TableCell>
                        {getStatusFinanceiroChip(instituicao.statusFinanceiro || 'em_dia')}
                      </TableCell>
                      
                      <TableCell align="center">
                        <Tooltip title="Registrar Pagamento">
                          <IconButton
                            color="primary"
                            size="small"
                            onClick={() => handleAbrirPagamento(instituicao)}
                          >
                            <AttachMoneyIcon />
                          </IconButton>
                        </Tooltip>
                        
                        <Tooltip title="Ver Histórico">
                          <IconButton
                            color="info"
                            size="small"
                            onClick={() => handleVerHistorico(instituicao)}
                          >
                            <ReceiptIcon />
                          </IconButton>
                        </Tooltip>
                        
                        {diasVencimento !== null && diasVencimento < 5 && diasVencimento > 0 && (
                          <Tooltip title="Enviar Lembrete">
                            <IconButton
                              color="warning"
                              size="small"
                            >
                              <NotificationsIcon />
                            </IconButton>
                          </Tooltip>
                        )}
                      </TableCell>
                    </TableRow>
                  );
                }))
                }
              </TableBody>
            </Table>
          </TableContainer>
        </CardContent>
      </Card>

      {/* Dialog Registrar Pagamento */}
      <Dialog open={dialogPagamento} onClose={() => setDialogPagamento(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Registrar Pagamento</DialogTitle>
        <DialogContent>
          {instituicaoSelecionada && (
            <>
              <Alert severity="info" sx={{ mb: 2 }}>
                <strong>{instituicaoSelecionada.nomeInstituicao}</strong>
              </Alert>
              
              <TextField
                fullWidth
                label="Valor do Pagamento"
                type="number"
                value={valorPagamento}
                onChange={(e) => setValorPagamento(e.target.value)}
                sx={{ mb: 2, mt: 1 }}
                InputProps={{
                  startAdornment: <Typography sx={{ mr: 1 }}>R$</Typography>
                }}
              />
              
              <TextField
                fullWidth
                select
                label="Método de Pagamento"
                value={metodoPagamento}
                onChange={(e) => setMetodoPagamento(e.target.value)}
                SelectProps={{ native: true }}
              >
                <option value="manual">Confirmação Manual</option>
                <option value="pix">PIX</option>
                <option value="boleto">Boleto</option>
                <option value="cartao">Cartão de Crédito</option>
                <option value="transferencia">Transferência Bancária</option>
              </TextField>
            </>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDialogPagamento(false)}>
            Cancelar
          </Button>
          <Button onClick={handleRegistrarPagamento} variant="contained" color="primary">
            Confirmar Pagamento
          </Button>
        </DialogActions>
      </Dialog>

      {/* Dialog Histórico */}
      <Dialog open={dialogHistorico} onClose={() => setDialogHistorico(false)} maxWidth="md" fullWidth>
        <DialogTitle>Histórico de Pagamentos</DialogTitle>
        <DialogContent>
          {instituicaoSelecionada && (
            <>
              <Alert severity="info" sx={{ mb: 2 }}>
                <strong>{instituicaoSelecionada.nomeInstituicao}</strong>
              </Alert>
              
              <TableContainer component={Paper}>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableCell>Data</TableCell>
                      <TableCell>Referência</TableCell>
                      <TableCell>Valor</TableCell>
                      <TableCell>Método</TableCell>
                      <TableCell>Status</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {obterHistoricoPagamentos(instituicaoSelecionada.id).length > 0 ? (
                      obterHistoricoPagamentos(instituicaoSelecionada.id)
                        .sort((a, b) => new Date(b.dataPagamento) - new Date(a.dataPagamento))
                        .map((pag) => (
                          <TableRow key={pag.id}>
                            <TableCell>
                              {new Date(pag.dataPagamento).toLocaleDateString('pt-BR')}
                            </TableCell>
                            <TableCell>{pag.referenciaMes}</TableCell>
                            <TableCell>R$ {pag.valor.toFixed(2)}</TableCell>
                            <TableCell sx={{ textTransform: 'capitalize' }}>
                              {pag.metodoPagamento}
                            </TableCell>
                            <TableCell>
                              <Chip label={pag.status} color="success" size="small" />
                            </TableCell>
                          </TableRow>
                        ))
                    ) : (
                      <TableRow>
                        <TableCell colSpan={5} align="center">
                          <Typography color="textSecondary">
                            Nenhum pagamento registrado
                          </Typography>
                        </TableCell>
                      </TableRow>
                    )}
                  </TableBody>
                </Table>
              </TableContainer>
            </>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDialogHistorico(false)}>
            Fechar
          </Button>
        </DialogActions>
      </Dialog>
    </Layout>
  );
}

import React, { useState, useEffect } from 'react';
import { useData } from '../context/DataContext';
import Layout from '../components/Layout';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Chip,
  Alert,
  Grid,
  Button
} from '@mui/material';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import WarningIcon from '@mui/icons-material/Warning';
import ErrorIcon from '@mui/icons-material/Error';
import ReceiptLongIcon from '@mui/icons-material/ReceiptLong';
import CalendarMonthIcon from '@mui/icons-material/CalendarMonth';

export default function FinanceiroPage() {
  const { 
    usuarioLogado,
    instituicoes,
    calcularProximoVencimento,
    obterHistoricoPagamentos
  } = useData();

  const [instituicao, setInstituicao] = useState(null);
  const [proximoVencimento, setProximoVencimento] = useState(null);
  const [diasParaVencimento, setDiasParaVencimento] = useState(null);

  useEffect(() => {
    if (usuarioLogado?.instituicaoId) {
      const inst = instituicoes.find(i => i.id === usuarioLogado.instituicaoId);
      setInstituicao(inst);
      
      if (inst) {
        const vencimento = calcularProximoVencimento(inst.id);
        setProximoVencimento(vencimento);
        
        if (vencimento) {
          const hoje = new Date();
          const diffTime = vencimento - hoje;
          const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
          setDiasParaVencimento(diffDays);
        }
      }
    }
  }, [usuarioLogado, instituicoes]);

  if (!instituicao) {
    return (
      <Layout>
        <Alert severity="error">
          Instituição não encontrada.
        </Alert>
      </Layout>
    );
  }

  const historico = obterHistoricoPagamentos(instituicao.id);
  const statusFinanceiro = instituicao.statusFinanceiro || 'em_dia';

  const getStatusAlert = () => {
    if (statusFinanceiro === 'bloqueado_financeiro') {
      return (
        <Alert severity="error" icon={<ErrorIcon />} sx={{ mb: 3 }}>
          <Typography variant="h6">Sua conta está bloqueada por inadimplência</Typography>
          <Typography>
            Entre em contato com o administrador para regularizar sua situação.
          </Typography>
        </Alert>
      );
    }
    
    if (statusFinanceiro === 'atrasado' || (diasParaVencimento !== null && diasParaVencimento < 0)) {
      return (
        <Alert severity="error" icon={<WarningIcon />} sx={{ mb: 3 }}>
          <Typography variant="h6">Pagamento em Atraso</Typography>
          <Typography>
            Seu pagamento está atrasado. Regularize o quanto antes para evitar bloqueio.
          </Typography>
        </Alert>
      );
    }
    
    if (diasParaVencimento !== null && diasParaVencimento <= 5 && diasParaVencimento > 0) {
      return (
        <Alert severity="warning" icon={<WarningIcon />} sx={{ mb: 3 }}>
          <Typography variant="h6">Vencimento Próximo</Typography>
          <Typography>
            Seu pagamento vence em {diasParaVencimento} dia{diasParaVencimento !== 1 ? 's' : ''}. 
            Fique atento!
          </Typography>
        </Alert>
      );
    }
    
    return (
      <Alert severity="success" icon={<CheckCircleIcon />} sx={{ mb: 3 }}>
        <Typography variant="h6">Pagamento em Dia</Typography>
        <Typography>
          Sua situação financeira está regularizada. Obrigado!
        </Typography>
      </Alert>
    );
  };

  return (
    <Layout>
      <Box>
        <Typography variant="h4" gutterBottom>
          💰 Financeiro
        </Typography>

        {getStatusAlert()}

      {/* Cards Informações */}
      <Grid container spacing={3} sx={{ mb: 3 }}>
        <Grid item xs={12} md={4}>
          <Card>
            <CardContent>
              <Box display="flex" alignItems="center" mb={1}>
                <ReceiptLongIcon color="primary" sx={{ mr: 1 }} />
                <Typography color="textSecondary">
                  Valor Mensal
                </Typography>
              </Box>
              <Typography variant="h4">
                R$ {(instituicao.valorMensal ?? 97.00).toFixed(2)}
              </Typography>
              <Typography variant="caption" color="textSecondary">
                Plano: {instituicao.plano || 'Mensal'}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        
        <Grid item xs={12} md={4}>
          <Card>
            <CardContent>
              <Box display="flex" alignItems="center" mb={1}>
                <CalendarMonthIcon color="primary" sx={{ mr: 1 }} />
                <Typography color="textSecondary">
                  Próximo Vencimento
                </Typography>
              </Box>
              <Typography variant="h5">
                {proximoVencimento 
                  ? proximoVencimento.toLocaleDateString('pt-BR')
                  : 'N/A'}
              </Typography>
              <Typography variant="caption" color="textSecondary">
                {instituicao.diasLicenca >= 180 || 
                 instituicao.plano?.includes('Ano') || 
                 instituicao.plano?.includes('ano') ||
                 instituicao.plano?.includes('Semestral')
                  ? `Plano: ${instituicao.plano || 'Anual'}`
                  : `Dia ${instituicao.diaVencimento || 10} de cada mês`}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        
        <Grid item xs={12} md={4}>
          <Card>
            <CardContent>
              <Box display="flex" alignItems="center" mb={1}>
                {statusFinanceiro === 'em_dia' ? (
                  <CheckCircleIcon color="success" sx={{ mr: 1 }} />
                ) : (
                  <WarningIcon color="error" sx={{ mr: 1 }} />
                )}
                <Typography color="textSecondary">
                  Status
                </Typography>
              </Box>
              <Typography variant="h5" sx={{ textTransform: 'capitalize' }}>
                {statusFinanceiro.replace('_', ' ')}
              </Typography>
              {diasParaVencimento !== null && diasParaVencimento > 0 && (
                <Typography variant="caption" color="textSecondary">
                  Faltam {diasParaVencimento} dias
                </Typography>
              )}
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Informações de Pagamento */}
      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Typography variant="h6" gutterBottom>
            Formas de Pagamento
          </Typography>
          
          <Box sx={{ mt: 2 }}>
            <Typography variant="body2" paragraph>
              <strong>PIX:</strong> Entre em contato com o administrador para obter a chave PIX
            </Typography>
            <Typography variant="body2" paragraph>
              <strong>Boleto:</strong> Solicite ao administrador
            </Typography>
            <Typography variant="body2" paragraph>
              <strong>Transferência Bancária:</strong> Entre em contato para dados bancários
            </Typography>
          </Box>
          
          <Alert severity="info" sx={{ mt: 2 }}>
            Após realizar o pagamento, envie o comprovante para o administrador confirmar.
          </Alert>
        </CardContent>
      </Card>

      {/* Histórico de Pagamentos */}
      <Card>
        <CardContent>
          <Typography variant="h6" gutterBottom>
            Histórico de Pagamentos
          </Typography>
          
          <TableContainer component={Paper} sx={{ mt: 2 }}>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>Data do Pagamento</TableCell>
                  <TableCell>Referência</TableCell>
                  <TableCell>Valor</TableCell>
                  <TableCell>Método</TableCell>
                  <TableCell>Status</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {historico.length > 0 ? (
                  historico
                    .sort((a, b) => new Date(b.dataPagamento) - new Date(a.dataPagamento))
                    .map((pag) => (
                      <TableRow key={pag.id}>
                        <TableCell>
                          {new Date(pag.dataPagamento).toLocaleDateString('pt-BR')}
                        </TableCell>
                        <TableCell>{pag.referenciaMes}</TableCell>
                        <TableCell>
                          <strong>R$ {pag.valor.toFixed(2)}</strong>
                        </TableCell>
                        <TableCell sx={{ textTransform: 'capitalize' }}>
                          {pag.metodoPagamento}
                        </TableCell>
                        <TableCell>
                          <Chip 
                            label={pag.status} 
                            color="success" 
                            size="small"
                            icon={<CheckCircleIcon />}
                          />
                        </TableCell>
                      </TableRow>
                    ))
                ) : (
                  <TableRow>
                    <TableCell colSpan={5} align="center">
                      <Typography color="textSecondary" py={3}>
                        Nenhum pagamento registrado ainda
                      </Typography>
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </TableContainer>
        </CardContent>
      </Card>
      </Box>
    </Layout>
  );
}

import React, { useEffect, useState } from 'react';
import Layout from '../components/Layout';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  Chip,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  MenuItem,
  Grid,
  Alert,
  Checkbox,
  FormControlLabel
} from '@mui/material';
import {
  CheckCircle,
  Block,
  Delete,
  DeleteForever,
  Info,
  VpnKey,
  CalendarToday,
  Add,
  School,
  Edit,
  Print,
  Analytics
} from '@mui/icons-material';
import { useData } from '../context/DataContext';
import { imprimirEscopo } from '../utils/printUtils';

export default function GerenciarEscolasPage() {
  const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:3001';
  const { 
    instituicoes, 
    ativarInstituicao, 
    bloquearInstituicao, 
    removerInstituicao,
    removerTodasInstituicoes,
    adicionarInstituicao,
    atualizarInstituicao,
    usuarioLogado 
  } = useData();
  
  const [dialogOpen, setDialogOpen] = useState(false);
  const [cadastroDialogOpen, setCadastroDialogOpen] = useState(false);
  const [edicaoDialogOpen, setEdicaoDialogOpen] = useState(false);
  const [modoEdicao, setModoEdicao] = useState(false);
  const [instituicaoSelecionada, setInstituicaoSelecionada] = useState(null);
  const [acao, setAcao] = useState('');
  const [diasValidade, setDiasValidade] = useState(365);
  const [motivoBloqueio, setMotivoBloqueio] = useState('');
  const [excluirTodasOpen, setExcluirTodasOpen] = useState(false);
  const [analiseOpen, setAnaliseOpen] = useState(false);
  const [filtroExclusao, setFiltroExclusao] = useState('pendentes');
  const [usarExclusaoExataTeste, setUsarExclusaoExataTeste] = useState(false);
  const [demoLeads, setDemoLeads] = useState([]);
  const [carregandoDemoLeads, setCarregandoDemoLeads] = useState(false);
  const [erroDemoLeads, setErroDemoLeads] = useState('');
  const [idsExclusaoSelecionados, setIdsExclusaoSelecionados] = useState(new Set());

  // Estado para cadastro manual
  const [formCadastro, setFormCadastro] = useState({
    nomeInstituicao: '',
    cnpj: '',
    endereco: '',
    cidade: '',
    estado: '',
    cep: '',
    telefone: '',
    email: '',
    nomeResponsavel: '',
    cargoResponsavel: '',
    emailResponsavel: '',
    telefoneResponsavel: '',
    nomeEscola: '',
    loginAdmin: '',
    senhaAdmin: '',
    horarioFuncionamento: '',
    diasLicenca: 365,
    plano: '1 Ano (365 dias)',
    valorMensal: 97.00
  });

  // Verificar se é super admin
  if (usuarioLogado?.perfil !== 'SuperAdmin') {
    return (
      <Layout title="Gerenciar Escolas">
        <Alert severity="error">
          Acesso negado. Apenas o Super Administrador pode acessar esta página.
        </Alert>
      </Layout>
    );
  }

  const handleAbrirDialog = (instituicao, tipoAcao) => {
    setInstituicaoSelecionada(instituicao);
    setAcao(tipoAcao);
    // Usar os dias do plano contratado como padrão
    if (tipoAcao === 'ativar' && instituicao.diasLicenca) {
      setDiasValidade(instituicao.diasLicenca);
    }
    setDialogOpen(true);
  };

  const handleFecharDialog = () => {
    setDialogOpen(false);
    setInstituicaoSelecionada(null);
    setAcao('');
    setDiasValidade(365);
    setMotivoBloqueio('');
  };

  const handleImprimirDetalhes = () => {
    imprimirEscopo();
  };

  const handleConfirmarAcao = () => {
    if (!instituicaoSelecionada) return;

    switch (acao) {
      case 'ativar':
        ativarInstituicao(instituicaoSelecionada.id, diasValidade);
        break;
      case 'bloquear':
        bloquearInstituicao(instituicaoSelecionada.id, motivoBloqueio);
        break;
      case 'remover':
        removerInstituicao(instituicaoSelecionada.id);
        break;
      default:
        break;
    }

    handleFecharDialog();
  };

  const handleAbrirCadastro = () => {
    setCadastroDialogOpen(true);
  };

  const handleFecharCadastro = () => {
    setCadastroDialogOpen(false);
    setModoEdicao(false);
    setFormCadastro({
      nomeInstituicao: '',
      cnpj: '',
      endereco: '',
      cidade: '',
      estado: '',
      cep: '',
      telefone: '',
      email: '',
      nomeResponsavel: '',
      cargoResponsavel: '',
      emailResponsavel: '',
      telefoneResponsavel: '',
      nomeEscola: '',
      loginAdmin: '',
      senhaAdmin: '',
      horarioFuncionamento: '',
      diasLicenca: 365,
      plano: '1 Ano (365 dias)',
      valorMensal: 97.00
    });
  };

  const handleAbrirEdicao = (instituicao) => {
    setFormCadastro({
      ...instituicao,
      senhaAdmin: '********' // Não mostrar senha real
    });
    setModoEdicao(true);
    setCadastroDialogOpen(true);
  };

  const handleChangeCadastro = (campo, valor) => {
    setFormCadastro(prev => ({
      ...prev,
      [campo]: valor
    }));
  };

  const handleConfirmarCadastro = () => {
    // Validações básicas
    if (!formCadastro.nomeInstituicao || !formCadastro.email || !formCadastro.loginAdmin) {
      alert('Preencha todos os campos obrigatórios: Nome da Instituição, Email, Login');
      return;
    }

    // Modo edição
    if (modoEdicao) {
      // Atualizar instituição existente
      const dadosAtualizados = {
        ...formCadastro,
        dataAtualizacao: new Date().toISOString()
      };
      
      // Se senha foi alterada (não é ********), incluir no update
      if (formCadastro.senhaAdmin !== '********') {
        if (formCadastro.senhaAdmin.length < 8) {
          alert('A senha deve ter no mínimo 8 caracteres.');
          return;
        }
        if (!/[A-Z]/.test(formCadastro.senhaAdmin)) {
          alert('A senha deve conter pelo menos 1 letra maiúscula.');
          return;
        }
        if (!/[a-z]/.test(formCadastro.senhaAdmin)) {
          alert('A senha deve conter pelo menos 1 letra minúscula.');
          return;
        }
        if (!/[0-9]/.test(formCadastro.senhaAdmin)) {
          alert('A senha deve conter pelo menos 1 número.');
          return;
        }
        if (!/[^A-Za-z0-9]/.test(formCadastro.senhaAdmin)) {
          alert('A senha deve conter pelo menos 1 caractere especial.');
          return;
        }
        dadosAtualizados.senhaAdmin = formCadastro.senhaAdmin;
      } else {
        delete dadosAtualizados.senhaAdmin; // Não alterar senha
      }
      
      atualizarInstituicao(formCadastro.id, dadosAtualizados);
      alert(`✅ Instituição atualizada com sucesso!\n\nNome: ${formCadastro.nomeInstituicao}`);
      handleFecharCadastro();
      return;
    }

    // Modo cadastro (validar senha obrigatória)
    if (!formCadastro.senhaAdmin) {
      alert('Senha do Admin é obrigatória para novo cadastro');
      return;
    }

    if (formCadastro.senhaAdmin.length < 8) {
      alert('A senha deve ter no mínimo 8 caracteres.');
      return;
    }
    if (!/[A-Z]/.test(formCadastro.senhaAdmin)) {
      alert('A senha deve conter pelo menos 1 letra maiúscula.');
      return;
    }
    if (!/[a-z]/.test(formCadastro.senhaAdmin)) {
      alert('A senha deve conter pelo menos 1 letra minúscula.');
      return;
    }
    if (!/[0-9]/.test(formCadastro.senhaAdmin)) {
      alert('A senha deve conter pelo menos 1 número.');
      return;
    }
    if (!/[^A-Za-z0-9]/.test(formCadastro.senhaAdmin)) {
      alert('A senha deve conter pelo menos 1 caractere especial.');
      return;
    }

    // Calcular data de expiração
    const dataExpiracao = new Date();
    dataExpiracao.setDate(dataExpiracao.getDate() + formCadastro.diasLicenca);

    // Preparar dados para cadastro
    const novaInstituicao = {
      ...formCadastro,
      pagamentoConfirmado: true, // Marcado como pago (cadastro manual pelo admin)
      status: 'ativo', // Já vem ativo
      dataCadastro: new Date().toISOString(),
      dataAtivacao: new Date().toISOString(),
      dataExpiracao: dataExpiracao.toISOString(),
      dataPagamento: new Date().toISOString(),
      ultimoPagamento: new Date().toISOString(),
      metodoPagamento: 'Manual (Admin)',
      cadastroManual: true, // Flag para identificar que foi cadastro manual
      historicoLicencas: [{
        dataAtivacao: new Date().toISOString(),
        dataExpiracao: dataExpiracao.toISOString(),
        diasValidade: formCadastro.diasLicenca,
        renovacao: false
      }]
    };

    // Adicionar instituição
    const instituicaoAdicionada = adicionarInstituicao(novaInstituicao);
    
    if (instituicaoAdicionada) {
      alert(`✅ Instituição cadastrada com sucesso!\n\nNome: ${formCadastro.nomeInstituicao}\nLogin: ${formCadastro.loginAdmin}\nSenha: ${formCadastro.senhaAdmin}\nLicença: ${formCadastro.diasLicenca} dias\n\nA instituição já está ATIVA e pode fazer login.`);
      handleFecharCadastro();
    } else {
      alert('❌ Erro ao cadastrar instituição. Verifique se o CNPJ, Email ou Login já não estão cadastrados.');
    }
  };

  // ──────────────────── ANÁLISE: TESTE vs COMPRADOR ────────────────────
  const classificarInstituicao = (inst) => {
    const nome = String(inst.nomeInstituicao || '').toLowerCase();
    const email = String(inst.email || inst.emailResponsavel || '').toLowerCase();
    const cnpj = String(inst.cnpj || '').replace(/\D/g, '');
    const login = String(inst.loginAdmin || '').toLowerCase();

    const sinaisTeste = [];
    const sinaisComprador = [];

    // Palavras-chave de teste
    const palavrasTeste = ['teste', 'test', 'demo', 'exemplo', 'sample', 'prova', 'experimento', 'fake', 'lixo', 'aaa', 'bbb', 'xxx', 'zzz', 'abc'];
    if (palavrasTeste.some(p => nome.includes(p))) sinaisTeste.push('Nome sugere teste');
    if (palavrasTeste.some(p => email.includes(p))) sinaisTeste.push('Email sugere teste');
    if (palavrasTeste.some(p => login.includes(p))) sinaisTeste.push('Login sugere teste');

    // CNPJ inválido/fictício
    if (cnpj.length === 14) {
      const todosIguais = cnpj.split('').every(c => c === cnpj[0]);
      if (todosIguais || cnpj === '00000000000000') sinaisTeste.push('CNPJ fictício');
    } else if (!cnpj) {
      sinaisTeste.push('Sem CNPJ');
    }

    // Nunca pagou e nunca ativou com data de cadastro antiga
    const diasSinceCadastro = inst.dataCadastro
      ? Math.floor((Date.now() - new Date(inst.dataCadastro)) / 86400000)
      : 0;
    if (inst.status === 'pendente' && diasSinceCadastro > 30) sinaisTeste.push('Pendente há +30 dias');
    if (inst.status === 'pendente' && diasSinceCadastro <= 7) sinaisComprador.push('Cadastro recente (≤7 dias)');

    // Sinais de comprador real
    if (inst.telefone && inst.telefone.replace(/\D/g, '').length >= 10) sinaisComprador.push('Telefone válido');
    if (inst.cidade && inst.estado) sinaisComprador.push('Localização informada');
    if (inst.nomeResponsavel && inst.nomeResponsavel.split(' ').length >= 2) sinaisComprador.push('Nome completo do responsável');
    if (inst.status === 'ativo') sinaisComprador.push('Escola ativa (pagou)');
    if (inst.pagamentoConfirmado) sinaisComprador.push('Pagamento confirmado');
    if (inst.cadastroManual) sinaisComprador.push('Cadastro manual pelo admin');

    const pontosTeste = sinaisTeste.length;
    const pontosComprador = sinaisComprador.length;

    let classificacao = 'indefinido';
    if (pontosTeste >= 2 && pontosTeste > pontosComprador) classificacao = 'teste';
    else if (pontosComprador >= 2 && pontosComprador > pontosTeste) classificacao = 'comprador';

    return { classificacao, sinaisTeste, sinaisComprador };
  };

  const analise = instituicoes.map((inst) => ({
    ...inst,
    ...classificarInstituicao(inst)
  }));

  const isCadastroTesteExato = (inst) => {
    const licenca = String(inst?.licenca || '').toUpperCase();
    const loginAdmin = String(inst?.loginAdmin || '').toLowerCase();
    const email = String(inst?.email || inst?.emailResponsavel || '').toLowerCase();
    const statusFinanceiro = String(inst?.statusFinanceiro || '').toLowerCase();
    const origemCadastro = String(inst?.origemCadastro || '').toLowerCase();

    return (
      Boolean(inst?.contaTeste) ||
      statusFinanceiro === 'teste' ||
      origemCadastro === 'demo_login' ||
      licenca.includes('DEMO') ||
      loginAdmin === 'demo' ||
      loginAdmin.startsWith('demo_') ||
      email.endsWith('@cei-demo.com.br')
    );
  };

  const totalTeste = analise.filter(a => a.classificacao === 'teste').length;
  const totalTesteExato = instituicoes.filter(isCadastroTesteExato).length;
  const totalTesteOuPendente = instituicoes.filter((inst) => {
    const ehTeste = usarExclusaoExataTeste
      ? isCadastroTesteExato(inst)
      : analise.some((a) => a.id === inst.id && a.classificacao === 'teste');
    return ehTeste || inst.status === 'pendente';
  }).length;
  const totalComprador = analise.filter(a => a.classificacao === 'comprador').length;
  const totalIndefinido = analise.filter(a => a.classificacao === 'indefinido').length;

  // ──────────────────── EXCLUIR EM LOTE ────────────────────
  const getInstituicoesFiltradas = () => {
    const testesSelecionados = usarExclusaoExataTeste
      ? instituicoes.filter(isCadastroTesteExato)
      : analise.filter(a => a.classificacao === 'teste');

    if (filtroExclusao === 'pendentes') {
      return instituicoes.filter(i => i.status === 'pendente');
    }
    if (filtroExclusao === 'testes') {
      return testesSelecionados;
    }
    if (filtroExclusao === 'testes_e_pendentes') {
      return instituicoes.filter((inst) => {
        const ehTeste = usarExclusaoExataTeste
          ? isCadastroTesteExato(inst)
          : analise.some((a) => a.id === inst.id && a.classificacao === 'teste');
        return ehTeste || inst.status === 'pendente';
      });
    }
    if (filtroExclusao === 'todas') {
      return [...instituicoes];
    }
    return [];
  };

  const getIdsParaExcluir = () => {
    return Array.from(idsExclusaoSelecionados);
  };

  // Atualizar seleção quando filtro muda
  const atualizarSelecaoPorFiltro = (novoFiltro) => {
    setFiltroExclusao(novoFiltro);
  };

  // Recomputar lista filtrada e sincronizar seleção
  const instituicoesFiltradas = getInstituicoesFiltradas();

  // Efeito para resetar seleção quando filtro ou checkbox exata muda
  React.useEffect(() => {
    const filtradas = getInstituicoesFiltradas();
    setIdsExclusaoSelecionados(new Set(filtradas.map(i => i.id)));
  }, [filtroExclusao, usarExclusaoExataTeste, instituicoes.length]); // eslint-disable-line

  const toggleExclusaoId = (id) => {
    setIdsExclusaoSelecionados(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const toggleTodosExclusao = (marcar) => {
    if (marcar) {
      setIdsExclusaoSelecionados(new Set(instituicoesFiltradas.map(i => i.id)));
    } else {
      setIdsExclusaoSelecionados(new Set());
    }
  };

  const handleConfirmarExclusaoLote = () => {
    const ids = getIdsParaExcluir();
    if (ids.length === 0) {
      alert('Nenhuma instituição encontrada com o critério selecionado.');
      return;
    }
    const confirmacao = window.confirm(
      `⚠️ CONFIRMAR EXCLUSÃO EM LOTE\n\n` +
      `Serão excluídas ${ids.length} instituições e todos os seus dados.\n\n` +
      `Esta ação é IRREVERSÍVEL.\n\nDeseja confirmar?`
    );
    if (confirmacao) {
      removerTodasInstituicoes(ids);
      setExcluirTodasOpen(false);
      alert(`✅ ${ids.length} instituição(ões) excluída(s) com sucesso.`);
    }
  };

  const getStatusColor = (status) => {
    const cores = {
      'pendente': 'warning',
      'ativo': 'success',
      'bloqueado': 'error',
      'expirado': 'error',
      'dados_removidos': 'default'
    };
    return cores[status] || 'default';
  };

  const getStatusLabel = (status) => {
    const labels = {
      'pendente': 'PENDENTE',
      'ativo': 'ATIVO',
      'bloqueado': 'BLOQUEADO',
      'expirado': 'EXPIRADO',
      'dados_removidos': 'DADOS REMOVIDOS'
    };
    return labels[status] || status.toUpperCase();
  };

  const formatarData = (dataISO) => {
    if (!dataISO) return '-';
    return new Date(dataISO).toLocaleDateString('pt-BR');
  };

  const formatarDataHora = (dataISO) => {
    if (!dataISO) return '-';
    const data = new Date(dataISO);
    if (Number.isNaN(data.getTime())) return '-';
    return data.toLocaleString('pt-BR');
  };

  const carregarDemoLeads = async () => {
    setCarregandoDemoLeads(true);
    setErroDemoLeads('');
    try {
      const response = await fetch(`${API_URL}/api/demo-leads?limit=200`);
      const data = await response.json();
      if (!response.ok || !data?.success) {
        throw new Error(data?.error || 'Falha ao carregar leads demo.');
      }

      setDemoLeads(Array.isArray(data.leads) ? data.leads : []);
    } catch (error) {
      setErroDemoLeads(error.message || 'Falha ao carregar leads demo.');
    } finally {
      setCarregandoDemoLeads(false);
    }
  };

  useEffect(() => {
    carregarDemoLeads();
  }, []);

  const calcularDiasRestantes = (dataExpiracao) => {
    if (!dataExpiracao) return null;
    const hoje = new Date();
    const expira = new Date(dataExpiracao);
    const diff = Math.ceil((expira - hoje) / (1000 * 60 * 60 * 24));
    return diff > 0 ? diff : 0;
  };

  const instituicoesPendentes = instituicoes.filter(i => i.status === 'pendente');
  const instituicoesAtivas = instituicoes.filter(i => i.status === 'ativo');
  const instituicoesBloqueadas = instituicoes.filter(i => i.status === 'bloqueado');
  const instituicoesExpiradas = instituicoes.filter(i => i.status === 'expirado');
  const instituicoesDadosRemovidos = instituicoes.filter(i => i.status === 'dados_removidos');

  return (
    <Layout title="Gerenciar Instituições">
      {/* Botões de Ação */}
      <Box sx={{ mb: 3, display: 'flex', gap: 2, flexWrap: 'wrap', alignItems: 'center' }}>
        <Button
          variant="contained"
          color="primary"
          startIcon={<Add />}
          onClick={handleAbrirCadastro}
          size="large"
        >
          Cadastrar Escola Manualmente
        </Button>
        <Button
          variant="outlined"
          color="info"
          startIcon={<Analytics />}
          onClick={() => setAnaliseOpen(true)}
          size="large"
        >
          Analisar Registros
        </Button>
        <Button
          variant="outlined"
          color="error"
          startIcon={<DeleteForever />}
          onClick={() => setExcluirTodasOpen(true)}
          size="large"
        >
          Excluir em Lote
        </Button>
        <Typography variant="caption" display="block" sx={{ width: '100%', color: 'text.secondary' }}>
          Cadastre uma nova instituição e forneça licença sem necessidade de pagamento
        </Typography>
      </Box>

      {/* Cards de Resumo */}
      <Grid container spacing={2} sx={{ mb: 4 }}>
        <Grid item xs={12} sm={6} md={2.4}>
          <Card sx={{ bgcolor: '#fff3e0' }}>
            <CardContent>
              <Typography color="text.secondary" gutterBottom sx={{ fontSize: '0.875rem' }}>
                Aguardando Aprovação
              </Typography>
              <Typography variant="h3" color="warning.main">
                {instituicoesPendentes.length}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={2.4}>
          <Card sx={{ bgcolor: '#e8f5e9' }}>
            <CardContent>
              <Typography color="text.secondary" gutterBottom sx={{ fontSize: '0.875rem' }}>
                Instituições Ativas
              </Typography>
              <Typography variant="h3" color="success.main">
                {instituicoesAtivas.length}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={2.4}>
          <Card sx={{ bgcolor: '#ffebee' }}>
            <CardContent>
              <Typography color="text.secondary" gutterBottom sx={{ fontSize: '0.875rem' }}>
                Bloqueadas
              </Typography>
              <Typography variant="h3" color="error.main">
                {instituicoesBloqueadas.length}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={2.4}>
          <Card sx={{ bgcolor: '#fff9c4' }}>
            <CardContent>
              <Typography color="text.secondary" gutterBottom sx={{ fontSize: '0.875rem' }}>
                Expiradas (Período de Graça)
              </Typography>
              <Typography variant="h3" color="error.main">
                {instituicoesExpiradas.length}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={2.4}>
          <Card sx={{ bgcolor: '#f5f5f5' }}>
            <CardContent>
              <Typography color="text.secondary" gutterBottom sx={{ fontSize: '0.875rem' }}>
                Dados Removidos
              </Typography>
              <Typography variant="h3" color="text.secondary">
                {instituicoesDadosRemovidos.length}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 1, flexWrap: 'wrap', mb: 1.5 }}>
            <Typography variant="h6">Novos Clientes DEMO (Backend)</Typography>
            <Button
              variant="outlined"
              size="small"
              onClick={carregarDemoLeads}
              disabled={carregandoDemoLeads}
            >
              {carregandoDemoLeads ? 'Atualizando...' : 'Atualizar Leads'}
            </Button>
          </Box>

          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            Lista de contatos capturados no login demo para retorno comercial.
          </Typography>

          {erroDemoLeads && (
            <Alert severity="warning" sx={{ mb: 2 }}>
              {erroDemoLeads}
            </Alert>
          )}

          <TableContainer component={Paper} variant="outlined">
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Atualizado em</TableCell>
                  <TableCell>Responsável</TableCell>
                  <TableCell>Contato</TableCell>
                  <TableCell>Cidade/UF</TableCell>
                  <TableCell>Origem</TableCell>
                  <TableCell>Acessos DEMO</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {demoLeads.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={6} align="center">
                      <Typography color="text.secondary">
                        {carregandoDemoLeads
                          ? 'Carregando leads...'
                          : 'Nenhum lead demo registrado no backend.'}
                      </Typography>
                    </TableCell>
                  </TableRow>
                ) : (
                  demoLeads.map((lead) => (
                    <TableRow key={lead.id} hover>
                      <TableCell>{formatarDataHora(lead.atualizadoEm || lead.capturadoEm)}</TableCell>
                      <TableCell>
                        <Typography variant="body2" fontWeight="bold">{lead.nomeResponsavel || '-'}</Typography>
                        <Typography variant="caption" color="text.secondary">{lead.demoDeviceId || '-'}</Typography>
                      </TableCell>
                      <TableCell>
                        <Typography variant="body2">{lead.telefoneCelular || '-'}</Typography>
                        <Typography variant="caption" color="text.secondary">{lead.email || '-'}</Typography>
                      </TableCell>
                      <TableCell>{`${lead.cidade || '-'} / ${lead.estado || '-'}`}</TableCell>
                      <TableCell>
                        <Chip size="small" label={lead.origemEvento || 'login_demo'} color="secondary" variant="outlined" />
                      </TableCell>
                      <TableCell>{Number(lead.acessosDemo || 0)}</TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </TableContainer>
        </CardContent>
      </Card>

      {/* Tabela de Instituições */}
      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Instituição</TableCell>
              <TableCell>Responsável</TableCell>
              <TableCell>Contato</TableCell>
              <TableCell>Plano Contratado</TableCell>
              <TableCell>Status</TableCell>
              <TableCell>Cadastro</TableCell>
              <TableCell>Validade</TableCell>
              <TableCell>Licença</TableCell>
              <TableCell>Ações</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {instituicoes.length === 0 ? (
              <TableRow>
                <TableCell colSpan={9} align="center">
                  <Typography color="text.secondary">
                    Nenhuma instituição cadastrada
                  </Typography>
                </TableCell>
              </TableRow>
            ) : (
              instituicoes.map((instituicao) => {
                const diasRestantes = calcularDiasRestantes(instituicao.dataExpiracao);
                return (
                  <TableRow key={instituicao.id}>
                    <TableCell>
                      <Typography variant="body2" fontWeight="bold">
                        {instituicao.nomeInstituicao}
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        {instituicao.cidade}, {instituicao.estado}
                      </Typography>
                      {instituicao.origemCadastro === 'demo_login' && (
                        <Chip
                          label="Origem: Demo (Login)"
                          size="small"
                          color="secondary"
                          variant="outlined"
                          sx={{ mt: 0.5 }}
                        />
                      )}
                    </TableCell>
                    <TableCell>
                      <Typography variant="body2">
                        {instituicao.nomeResponsavel}
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        {instituicao.cargoResponsavel}
                      </Typography>
                    </TableCell>
                    <TableCell>
                      <Typography variant="caption" display="block">
                        {instituicao.telefone}
                      </Typography>
                      <Typography variant="caption" display="block">
                        {instituicao.email}
                      </Typography>
                    </TableCell>
                    <TableCell>
                      <Typography variant="body2" fontWeight="bold">
                        {instituicao.plano || 'Não especificado'}
                      </Typography>
                      <Typography variant="caption" display="block" color="text.secondary">
                        {instituicao.diasLicenca ? `${instituicao.diasLicenca} dias` : '-'}
                      </Typography>
                      <Typography variant="caption" display="block" color="primary">
                        R$ {(instituicao.valorMensal || 0).toFixed(2)}/mês
                      </Typography>
                    </TableCell>
                    <TableCell>
                      <Chip 
                        label={getStatusLabel(instituicao.status)} 
                        size="small" 
                        color={getStatusColor(instituicao.status)}
                      />
                      {instituicao.status === 'expirado' && (
                        <Chip 
                          label="30 dias para renovar" 
                          size="small" 
                          color="warning"
                          sx={{ ml: 0.5 }}
                        />
                      )}
                      {instituicao.status === 'dados_removidos' && (
                        <Chip 
                          label="Renovar para restaurar" 
                          size="small" 
                          color="default"
                          sx={{ ml: 0.5 }}
                        />
                      )}
                    </TableCell>
                    <TableCell>
                      {formatarData(instituicao.dataCadastro)}
                    </TableCell>
                    <TableCell>
                      {instituicao.status === 'ativo' ? (
                        <>
                          {formatarData(instituicao.dataExpiracao)}
                          <br />
                          <Chip 
                            label={`${diasRestantes} dias`} 
                            size="small"
                            color={diasRestantes < 30 ? 'error' : 'success'}
                            sx={{ mt: 0.5 }}
                          />
                        </>
                      ) : instituicao.status === 'expirado' ? (
                        <>
                          <Typography variant="caption" color="error" display="block">
                            {formatarData(instituicao.dataExpiracaoReal || instituicao.dataExpiracao)}
                          </Typography>
                          <Chip 
                            label={`${calcularDiasGracaRestantes(instituicao.id)} dias de graça`}
                            size="small"
                            color="warning"
                            sx={{ mt: 0.5 }}
                          />
                        </>
                      ) : instituicao.status === 'dados_removidos' ? (
                        <Typography variant="caption" color="text.secondary">
                          Dados removidos
                        </Typography>
                      ) : '-'}
                    </TableCell>
                    <TableCell>
                      <Typography variant="caption" sx={{ fontFamily: 'monospace' }}>
                        {instituicao.licenca}
                      </Typography>
                    </TableCell>
                    <TableCell>
                      <Box sx={{ display: 'flex', gap: 0.5 }}>
                        {/* Botão Editar - sempre disponível */}
                        <IconButton
                          size="small"
                          color="info"
                          onClick={() => handleAbrirEdicao(instituicao)}
                          title="Editar"
                        >
                          <Edit />
                        </IconButton>
                        
                        {instituicao.status === 'pendente' && (
                          <IconButton
                            size="small"
                            color="success"
                            onClick={() => handleAbrirDialog(instituicao, 'ativar')}
                            title="Ativar"
                          >
                            <CheckCircle />
                          </IconButton>
                        )}
                        {instituicao.status === 'ativo' && (
                          <>
                            <IconButton
                              size="small"
                              color="primary"
                              onClick={() => handleAbrirDialog(instituicao, 'ativar')}
                              title="Renovar"
                            >
                              <CalendarToday />
                            </IconButton>
                            <IconButton
                              size="small"
                              color="error"
                              onClick={() => handleAbrirDialog(instituicao, 'bloquear')}
                              title="Bloquear"
                            >
                              <Block />
                            </IconButton>
                          </>
                        )}
                        {(instituicao.status === 'expirado' || instituicao.status === 'dados_removidos') && (
                          <IconButton
                            size="small"
                            color="success"
                            onClick={() => handleAbrirDialog(instituicao, 'ativar')}
                            title="Renovar Licença"
                          >
                            <CheckCircle />
                          </IconButton>
                        )}
                        {instituicao.status === 'bloqueado' && (
                          <IconButton
                            size="small"
                            color="success"
                            onClick={() => handleAbrirDialog(instituicao, 'ativar')}
                            title="Desbloquear"
                          >
                            <CheckCircle />
                          </IconButton>
                        )}
                        <IconButton
                          size="small"
                          color="error"
                          onClick={() => handleAbrirDialog(instituicao, 'remover')}
                          title="Remover"
                        >
                          <Delete />
                        </IconButton>
                        <IconButton
                          size="small"
                          onClick={() => handleAbrirDialog(instituicao, 'info')}
                          title="Detalhes"
                        >
                          <Info />
                        </IconButton>
                      </Box>
                    </TableCell>
                  </TableRow>
                );
              })
            )}
          </TableBody>
        </Table>
      </TableContainer>

      {/* ── Dialog: Análise de Registros ── */}
      <Dialog open={analiseOpen} onClose={() => setAnaliseOpen(false)} maxWidth="md" fullWidth>
        <DialogTitle>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <Analytics color="info" />
            Análise de Registros — {instituicoes.length} instituições
          </Box>
        </DialogTitle>
        <DialogContent>
          <Grid container spacing={2} sx={{ mb: 3 }}>
            <Grid item xs={4}>
              <Paper elevation={0} sx={{ p: 2, bgcolor: '#ffebee', textAlign: 'center' }}>
                <Typography variant="h4" color="error.main" fontWeight="bold">{totalTeste}</Typography>
                <Typography variant="body2">Prováveis Testes</Typography>
              </Paper>
            </Grid>
            <Grid item xs={4}>
              <Paper elevation={0} sx={{ p: 2, bgcolor: '#e8f5e9', textAlign: 'center' }}>
                <Typography variant="h4" color="success.main" fontWeight="bold">{totalComprador}</Typography>
                <Typography variant="body2">Prováveis Compradores</Typography>
              </Paper>
            </Grid>
            <Grid item xs={4}>
              <Paper elevation={0} sx={{ p: 2, bgcolor: '#fff3e0', textAlign: 'center' }}>
                <Typography variant="h4" color="warning.main" fontWeight="bold">{totalIndefinido}</Typography>
                <Typography variant="body2">Indefinidos</Typography>
              </Paper>
            </Grid>
          </Grid>

          <Alert severity="info" sx={{ mb: 2 }}>
            A classificação é automática e baseada em: nome/email/login com palavras-chave de teste, CNPJ fictício, tempo sem ativação, telefone válido, localização e status de pagamento.
          </Alert>

          <TableContainer component={Paper} variant="outlined" sx={{ maxHeight: 400 }}>
            <Table size="small" stickyHeader>
              <TableHead>
                <TableRow>
                  <TableCell>Instituição</TableCell>
                  <TableCell>Status</TableCell>
                  <TableCell>Classificação</TableCell>
                  <TableCell>Evidências</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {analise.map((inst) => (
                  <TableRow key={inst.id} sx={{
                    bgcolor: inst.classificacao === 'teste' ? '#fff5f5' :
                             inst.classificacao === 'comprador' ? '#f5fff5' : 'inherit'
                  }}>
                    <TableCell>
                      <Typography variant="body2" fontWeight="bold">{inst.nomeInstituicao}</Typography>
                      <Typography variant="caption" color="text.secondary">{inst.email || inst.emailResponsavel}</Typography>
                    </TableCell>
                    <TableCell>
                      <Chip label={getStatusLabel(inst.status)} size="small" color={getStatusColor(inst.status)} />
                    </TableCell>
                    <TableCell>
                      <Chip
                        label={inst.classificacao === 'teste' ? '🧪 Teste' : inst.classificacao === 'comprador' ? '💰 Comprador' : '❓ Indefinido'}
                        size="small"
                        color={inst.classificacao === 'teste' ? 'error' : inst.classificacao === 'comprador' ? 'success' : 'warning'}
                      />
                    </TableCell>
                    <TableCell>
                      {inst.sinaisTeste.length > 0 && (
                        <Typography variant="caption" color="error.main" display="block">
                          ⚠️ {inst.sinaisTeste.join('; ')}
                        </Typography>
                      )}
                      {inst.sinaisComprador.length > 0 && (
                        <Typography variant="caption" color="success.main" display="block">
                          ✅ {inst.sinaisComprador.join('; ')}
                        </Typography>
                      )}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setAnaliseOpen(false)}>Fechar</Button>
        </DialogActions>
      </Dialog>

      {/* ── Dialog: Excluir em Lote ── */}
      <Dialog open={excluirTodasOpen} onClose={() => setExcluirTodasOpen(false)} maxWidth="md" fullWidth>
        <DialogTitle>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <DeleteForever color="error" />
            Excluir Instituições em Lote
          </Box>
        </DialogTitle>
        <DialogContent>
          <Alert severity="error" sx={{ mb: 3 }}>
            <strong>ATENÇÃO:</strong> A exclusão é permanente e irá remover todos os dados relacionados (livros, alunos, empréstimos, etc.).
          </Alert>
          <TextField
            select
            fullWidth
            label="O que deseja excluir?"
            value={filtroExclusao}
            onChange={(e) => atualizarSelecaoPorFiltro(e.target.value)}
          >
            <MenuItem value="pendentes">
              Apenas pendentes ({instituicoes.filter(i => i.status === 'pendente').length})
            </MenuItem>
            <MenuItem value="testes">
              Apenas testes ({usarExclusaoExataTeste ? totalTesteExato : totalTeste})
            </MenuItem>
            <MenuItem value="testes_e_pendentes">
              Testes + Pendentes ({totalTesteOuPendente})
            </MenuItem>
            <MenuItem value="todas">
              TODAS as instituições ({instituicoes.length}) ⚠️
            </MenuItem>
          </TextField>
          {(filtroExclusao === 'testes' || filtroExclusao === 'testes_e_pendentes') && (
            <FormControlLabel
              sx={{ mt: 1 }}
              control={
                <Checkbox
                  checked={usarExclusaoExataTeste}
                  onChange={(e) => setUsarExclusaoExataTeste(e.target.checked)}
                />
              }
              label="Exclusão exata dos cadastros teste (somente registros marcados como teste/demo)"
            />
          )}

          {/* Lista de instituições com checkboxes individuais */}
          {instituicoesFiltradas.length > 0 && (
            <Box sx={{ mt: 2, border: '1px solid #ddd', borderRadius: 1, maxHeight: 320, overflow: 'auto' }}>
              <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', px: 2, py: 1, bgcolor: '#f5f5f5', borderBottom: '1px solid #ddd', position: 'sticky', top: 0, zIndex: 1 }}>
                <FormControlLabel
                  control={
                    <Checkbox
                      checked={idsExclusaoSelecionados.size === instituicoesFiltradas.length && instituicoesFiltradas.length > 0}
                      indeterminate={idsExclusaoSelecionados.size > 0 && idsExclusaoSelecionados.size < instituicoesFiltradas.length}
                      onChange={(e) => toggleTodosExclusao(e.target.checked)}
                      size="small"
                    />
                  }
                  label={<Typography variant="body2" fontWeight="bold">Selecionar todas ({instituicoesFiltradas.length})</Typography>}
                />
                <Typography variant="caption" color="text.secondary">
                  {idsExclusaoSelecionados.size} selecionada(s)
                </Typography>
              </Box>
              {instituicoesFiltradas.map((inst) => {
                const infoAnalise = analise.find(a => a.id === inst.id);
                return (
                  <Box
                    key={inst.id}
                    sx={{
                      display: 'flex', alignItems: 'center', px: 2, py: 0.5,
                      borderBottom: '1px solid #eee',
                      bgcolor: idsExclusaoSelecionados.has(inst.id) ? '#fff3f3' : 'transparent',
                      '&:hover': { bgcolor: '#f9f9f9' }
                    }}
                  >
                    <Checkbox
                      checked={idsExclusaoSelecionados.has(inst.id)}
                      onChange={() => toggleExclusaoId(inst.id)}
                      size="small"
                    />
                    <Box sx={{ flex: 1, ml: 1, minWidth: 0 }}>
                      <Typography variant="body2" noWrap fontWeight={500}>
                        {inst.nomeInstituicao || inst.nomeEscola || 'Sem nome'}
                      </Typography>
                      <Typography variant="caption" color="text.secondary" noWrap>
                        {inst.loginAdmin && `Login: ${inst.loginAdmin}`}
                        {inst.email && ` • ${inst.email}`}
                        {inst.cidade && inst.estado && ` • ${inst.cidade}/${inst.estado}`}
                      </Typography>
                    </Box>
                    <Chip
                      label={inst.status?.toUpperCase() || 'N/A'}
                      size="small"
                      color={getStatusColor(inst.status)}
                      sx={{ ml: 1, minWidth: 80 }}
                    />
                    {infoAnalise && (
                      <Chip
                        label={infoAnalise.classificacao === 'teste' ? 'TESTE' : infoAnalise.classificacao === 'comprador' ? 'COMPRADOR' : '?'}
                        size="small"
                        variant="outlined"
                        color={infoAnalise.classificacao === 'teste' ? 'error' : infoAnalise.classificacao === 'comprador' ? 'success' : 'default'}
                        sx={{ ml: 0.5, minWidth: 70 }}
                      />
                    )}
                  </Box>
                );
              })}
            </Box>
          )}

          <Typography variant="body2" color="text.secondary" sx={{ mt: 2 }}>
            Serão excluídas: <strong>{idsExclusaoSelecionados.size} instituição(ões)</strong>
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setExcluirTodasOpen(false)}>Cancelar</Button>
          <Button
            variant="contained"
            color="error"
            startIcon={<DeleteForever />}
            onClick={handleConfirmarExclusaoLote}
            disabled={idsExclusaoSelecionados.size === 0}
          >
            Excluir {idsExclusaoSelecionados.size} Instituição(ões)
          </Button>
        </DialogActions>
      </Dialog>

      {/* Dialog de Ações */}
      <Dialog open={dialogOpen} onClose={handleFecharDialog} maxWidth="sm" fullWidth>
        <DialogTitle>
          {acao === 'ativar' && 'Ativar/Renovar Instituição'}
          {acao === 'bloquear' && 'Bloquear Instituição'}
          {acao === 'remover' && 'Remover Instituição'}
          {acao === 'info' && 'Detalhes da Instituição'}
        </DialogTitle>
        <DialogContent>
          {instituicaoSelecionada && (
            <Box sx={{ mt: 2 }}>
              {acao === 'ativar' && (
                <>
                  <Typography variant="body2" sx={{ mb: 2 }}>
                    Ativar acesso para: <strong>{instituicaoSelecionada.nomeInstituicao}</strong>
                  </Typography>
                  <TextField
                    label="Dias de Validade"
                    type="number"
                    fullWidth
                    value={diasValidade}
                    onChange={(e) => setDiasValidade(parseInt(e.target.value))}
                    select
                  >
                    <MenuItem value={30}>30 dias (1 mês)</MenuItem>
                    <MenuItem value={90}>90 dias (3 meses)</MenuItem>
                    <MenuItem value={180}>180 dias (6 meses)</MenuItem>
                    <MenuItem value={365}>365 dias (1 ano)</MenuItem>
                    <MenuItem value={730}>730 dias (2 anos)</MenuItem>
                  </TextField>
                </>
              )}

              {acao === 'bloquear' && (
                <>
                  <Alert severity="warning" sx={{ mb: 2 }}>
                    A instituição <strong>{instituicaoSelecionada.nomeInstituicao}</strong> será bloqueada 
                    e não poderá mais acessar o sistema.
                  </Alert>
                  <TextField
                    label="Motivo do Bloqueio"
                    fullWidth
                    multiline
                    rows={3}
                    value={motivoBloqueio}
                    onChange={(e) => setMotivoBloqueio(e.target.value)}
                  />
                </>
              )}

              {acao === 'remover' && (
                <Alert severity="error">
                  <Typography variant="body2" gutterBottom>
                    <strong>ATENÇÃO:</strong> Esta ação é irreversível!
                  </Typography>
                  <Typography variant="body2">
                    Todos os dados da instituição <strong>{instituicaoSelecionada.nomeInstituicao}</strong> serão 
                    permanentemente removidos, incluindo livros, patrimônio, clientes e empréstimos.
                  </Typography>
                </Alert>
              )}

              {acao === 'info' && (
                <Box className="print-scope">
                  <Typography className="print-only" variant="h6" fontWeight="bold" sx={{ mb: 1 }}>
                    Detalhes da Instituição
                  </Typography>
                  <Typography className="print-only" variant="body2" sx={{ mb: 2 }}>
                    Emitido em: {new Date().toLocaleString('pt-BR')}
                  </Typography>
                  <Typography variant="body2"><strong>Instituição:</strong> {instituicaoSelecionada.nomeInstituicao}</Typography>
                  <Typography variant="body2"><strong>CNPJ:</strong> {instituicaoSelecionada.cnpj || '-'}</Typography>
                  <Typography variant="body2"><strong>Endereço:</strong> {instituicaoSelecionada.endereco}</Typography>
                  <Typography variant="body2"><strong>Cidade/Estado:</strong> {instituicaoSelecionada.cidade}, {instituicaoSelecionada.estado}</Typography>
                  <Typography variant="body2"><strong>CEP:</strong> {instituicaoSelecionada.cep}</Typography>
                  <Typography variant="body2" sx={{ mt: 2 }}><strong>Responsável:</strong> {instituicaoSelecionada.nomeResponsavel}</Typography>
                  <Typography variant="body2"><strong>Cargo:</strong> {instituicaoSelecionada.cargoResponsavel}</Typography>
                  <Typography variant="body2"><strong>Email:</strong> {instituicaoSelecionada.emailResponsavel}</Typography>
                  <Typography variant="body2"><strong>Telefone:</strong> {instituicaoSelecionada.telefoneResponsavel}</Typography>
                  <Typography variant="body2" sx={{ mt: 2 }}><strong>Código de Licença:</strong> {instituicaoSelecionada.licenca}</Typography>
                  <Typography variant="body2"><strong>Status:</strong> {instituicaoSelecionada.status}</Typography>
                  <Typography variant="body2"><strong>Data Cadastro:</strong> {formatarData(instituicaoSelecionada.dataCadastro)}</Typography>
                  {instituicaoSelecionada.dataExpiracao && (
                    <Typography variant="body2"><strong>Data Expiração:</strong> {formatarData(instituicaoSelecionada.dataExpiracao)}</Typography>
                  )}
                </Box>
              )}
            </Box>
          )}
        </DialogContent>
        <DialogActions className="no-print">
          {acao === 'info' && (
            <Button variant="outlined" startIcon={<Print />} onClick={handleImprimirDetalhes}>
              Imprimir Detalhes
            </Button>
          )}
          <Button onClick={handleFecharDialog}>
            {acao === 'info' ? 'Fechar' : 'Cancelar'}
          </Button>
          {acao !== 'info' && (
            <Button
              variant="contained"
              onClick={handleConfirmarAcao}
              color={acao === 'remover' || acao === 'bloquear' ? 'error' : 'primary'}
            >
              Confirmar
            </Button>
          )}
        </DialogActions>
      </Dialog>

      {/* Dialog de Cadastro Manual */}
      <Dialog open={cadastroDialogOpen} onClose={handleFecharCadastro} maxWidth="md" fullWidth>
        <DialogTitle>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <School color="primary" />
            {modoEdicao ? 'Editar Instituição' : 'Cadastrar Escola Manualmente'}
          </Box>
        </DialogTitle>
        <DialogContent>
          {!modoEdicao && (
            <Alert severity="info" sx={{ mt: 2, mb: 3 }}>
              <Typography variant="body2">
                <strong>Cadastro pelo Administrador:</strong> A escola será cadastrada diretamente 
                com status ATIVO e licença fornecida automaticamente, sem necessidade de pagamento.
              </Typography>
            </Alert>
          )}
          {modoEdicao && (
            <Alert severity="warning" sx={{ mt: 2, mb: 3 }}>
              <Typography variant="body2">
                <strong>Modo Edição:</strong> Altere os dados da instituição. A senha só será alterada se você digitar uma nova.
              </Typography>
            </Alert>
          )}

          <Grid container spacing={2}>
            {/* Dados da Instituição */}
            <Grid item xs={12}>
              <Typography variant="subtitle1" color="primary" gutterBottom sx={{ mt: 2 }}>
                📋 Dados da Instituição
              </Typography>
            </Grid>

            <Grid item xs={12} sm={8}>
              <TextField
                label="Nome da Instituição *"
                fullWidth
                value={formCadastro.nomeInstituicao}
                onChange={(e) => handleChangeCadastro('nomeInstituicao', e.target.value)}
                placeholder="Ex: Escola Municipal João da Silva"
              />
            </Grid>

            <Grid item xs={12} sm={4}>
              <TextField
                label="CNPJ"
                fullWidth
                value={formCadastro.cnpj}
                onChange={(e) => handleChangeCadastro('cnpj', e.target.value)}
                placeholder="00.000.000/0001-00"
              />
            </Grid>

            <Grid item xs={12}>
              <TextField
                label="Endereço"
                fullWidth
                value={formCadastro.endereco}
                onChange={(e) => handleChangeCadastro('endereco', e.target.value)}
                placeholder="Rua, número, bairro"
              />
            </Grid>

            <Grid item xs={12} sm={5}>
              <TextField
                label="Cidade"
                fullWidth
                value={formCadastro.cidade}
                onChange={(e) => handleChangeCadastro('cidade', e.target.value)}
              />
            </Grid>

            <Grid item xs={12} sm={3}>
              <TextField
                label="Estado"
                fullWidth
                value={formCadastro.estado}
                onChange={(e) => handleChangeCadastro('estado', e.target.value)}
                placeholder="UF"
                inputProps={{ maxLength: 2, style: { textTransform: 'uppercase' } }}
              />
            </Grid>

            <Grid item xs={12} sm={4}>
              <TextField
                label="CEP"
                fullWidth
                value={formCadastro.cep}
                onChange={(e) => handleChangeCadastro('cep', e.target.value)}
                placeholder="00000-000"
              />
            </Grid>

            <Grid item xs={12} sm={6}>
              <TextField
                label="Telefone"
                fullWidth
                value={formCadastro.telefone}
                onChange={(e) => handleChangeCadastro('telefone', e.target.value)}
                placeholder="(00) 0000-0000"
              />
            </Grid>

            <Grid item xs={12} sm={6}>
              <TextField
                label="Email da Instituição *"
                fullWidth
                type="email"
                value={formCadastro.email}
                onChange={(e) => handleChangeCadastro('email', e.target.value)}
                placeholder="contato@escola.com.br"
              />
            </Grid>

            <Grid item xs={12} sm={6}>
              <TextField
                label="Horário de Funcionamento"
                fullWidth
                value={formCadastro.horarioFuncionamento}
                onChange={(e) => handleChangeCadastro('horarioFuncionamento', e.target.value)}
                placeholder="Ex: 7h às 17h"
              />
            </Grid>

            {/* Dados do Responsável */}
            <Grid item xs={12}>
              <Typography variant="subtitle1" color="primary" gutterBottom sx={{ mt: 2 }}>
                👤 Dados do Responsável
              </Typography>
            </Grid>

            <Grid item xs={12} sm={6}>
              <TextField
                label="Nome do Responsável"
                fullWidth
                value={formCadastro.nomeResponsavel}
                onChange={(e) => handleChangeCadastro('nomeResponsavel', e.target.value)}
              />
            </Grid>

            <Grid item xs={12} sm={6}>
              <TextField
                label="Cargo"
                fullWidth
                value={formCadastro.cargoResponsavel}
                onChange={(e) => handleChangeCadastro('cargoResponsavel', e.target.value)}
                placeholder="Ex: Diretor(a)"
              />
            </Grid>

            <Grid item xs={12} sm={6}>
              <TextField
                label="Email do Responsável"
                fullWidth
                type="email"
                value={formCadastro.emailResponsavel}
                onChange={(e) => handleChangeCadastro('emailResponsavel', e.target.value)}
              />
            </Grid>

            <Grid item xs={12} sm={6}>
              <TextField
                label="Telefone do Responsável"
                fullWidth
                value={formCadastro.telefoneResponsavel}
                onChange={(e) => handleChangeCadastro('telefoneResponsavel', e.target.value)}
              />
            </Grid>

            {/* Dados de Acesso */}
            <Grid item xs={12}>
              <Typography variant="subtitle1" color="primary" gutterBottom sx={{ mt: 2 }}>
                🔐 Dados de Acesso ao Sistema
              </Typography>
            </Grid>

            <Grid item xs={12} sm={6}>
              <TextField
                label="Login do Administrador *"
                fullWidth
                value={formCadastro.loginAdmin}
                onChange={(e) => handleChangeCadastro('loginAdmin', e.target.value)}
                placeholder="usuario.admin"
                helperText="Login que a escola usará para acessar o sistema"
              />
            </Grid>

            <Grid item xs={12} sm={6}>
              <TextField
                label="Senha do Administrador *"
                fullWidth
                type="text"
                value={formCadastro.senhaAdmin}
                onChange={(e) => handleChangeCadastro('senhaAdmin', e.target.value)}
                placeholder="Senha inicial"
                helperText="A escola poderá alterar depois"
              />
            </Grid>

            {/* Configurações de Licença */}
            <Grid item xs={12}>
              <Typography variant="subtitle1" color="primary" gutterBottom sx={{ mt: 2 }}>
                📅 Configurações de Licença
              </Typography>
            </Grid>

            <Grid item xs={12} sm={4}>
              <TextField
                label="Plano"
                fullWidth
                select
                value={formCadastro.plano}
                onChange={(e) => {
                  const plano = e.target.value;
                  handleChangeCadastro('plano', plano);
                  // Atualizar dias e valor baseado no plano
                  const planosMap = {
                    '1 Mês (30 dias)': { dias: 30, valor: 97.00 },
                    '3 Meses (90 dias)': { dias: 90, valor: 270.00 },
                    '6 Meses (180 dias)': { dias: 180, valor: 520.00 },
                    '1 Ano (365 dias)': { dias: 365, valor: 970.00 },
                    '2 Anos (730 dias)': { dias: 730, valor: 1800.00 }
                  };
                  if (planosMap[plano]) {
                    handleChangeCadastro('diasLicenca', planosMap[plano].dias);
                    handleChangeCadastro('valorMensal', planosMap[plano].valor);
                  }
                }}
              >
                <MenuItem value="1 Mês (30 dias)">1 Mês (30 dias)</MenuItem>
                <MenuItem value="3 Meses (90 dias)">3 Meses (90 dias)</MenuItem>
                <MenuItem value="6 Meses (180 dias)">6 Meses (180 dias)</MenuItem>
                <MenuItem value="1 Ano (365 dias)">1 Ano (365 dias)</MenuItem>
                <MenuItem value="2 Anos (730 dias)">2 Anos (730 dias)</MenuItem>
              </TextField>
            </Grid>

            <Grid item xs={12} sm={4}>
              <TextField
                label="Dias de Licença *"
                fullWidth
                type="number"
                value={formCadastro.diasLicenca}
                onChange={(e) => handleChangeCadastro('diasLicenca', parseInt(e.target.value) || 0)}
                inputProps={{ min: 1 }}
                helperText="Validade da licença em dias"
              />
            </Grid>

            <Grid item xs={12} sm={4}>
              <TextField
                label="Valor (R$)"
                fullWidth
                type="number"
                value={formCadastro.valorMensal}
                onChange={(e) => handleChangeCadastro('valorMensal', parseFloat(e.target.value) || 0)}
                inputProps={{ step: 0.01, min: 0 }}
                helperText="Apenas para registro"
              />
            </Grid>

            <Grid item xs={12}>
              <Alert severity="success" sx={{ mt: 2 }}>
                <Typography variant="body2">
                  ✅ A instituição será cadastrada com status <strong>ATIVO</strong> e poderá 
                  fazer login imediatamente com as credenciais fornecidas.
                </Typography>
              </Alert>
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleFecharCadastro}>Cancelar</Button>
          <Button
            variant="contained"
            onClick={handleConfirmarCadastro}
            startIcon={modoEdicao ? <Edit /> : <Add />}
          >
            {modoEdicao ? 'Salvar Alterações' : 'Cadastrar e Ativar'}
          </Button>
        </DialogActions>
      </Dialog>
    </Layout>
  );
}

import React, { useState } from 'react';
import Layout from '../components/Layout';
import { useData } from '../context/DataContext';
import {
  Box,
  Button,
  Card,
  CardContent,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Typography,
  IconButton,
  Chip,
  Alert,
  Grid,
  Avatar,
  FormGroup,
  FormControlLabel,
  Checkbox,
  InputAdornment
} from '@mui/material';
import {
  Add,
  Edit,
  Delete,
  PersonAdd,
  VpnKey,
  AdminPanelSettings,
  Person,
  Visibility,
  VisibilityOff
} from '@mui/icons-material';

const PERMISSOES_DISPONIVEIS = [
  { path: '/configuracoes', label: 'Configurações' },
  { path: '/financeiro', label: 'Financeiro' },
  { path: '/livros', label: 'Livros' },
  { path: '/relatorios-livros', label: 'Relatórios de Livros' },
  { path: '/patrimonio', label: 'Patrimônio' },
  { path: '/clientes', label: 'Leitores' },
  { path: '/series-turmas', label: 'Séries e Turmas' },
  { path: '/emprestimos', label: 'Empréstimos' },
  { path: '/emprestimos-didaticos-lote', label: 'Empréstimos em Lote' },
  { path: '/devolucoes', label: 'Devoluções' },
  { path: '/clube-leitura', label: 'Clube de Leitura' },
  { path: '/busca', label: 'Busca' },
  { path: '/relatorios', label: 'Relatórios' }
];

const obterLabelPermissao = (path) => {
  const permissao = PERMISSOES_DISPONIVEIS.find(item => item.path === path);
  return permissao?.label || path;
};

const validarSenhaForte = (senha) => {
  if (!senha || senha.length < 8) {
    return 'A senha deve ter no mínimo 8 caracteres.';
  }
  if (!/[A-Z]/.test(senha)) {
    return 'A senha deve conter pelo menos 1 letra maiúscula.';
  }
  if (!/[a-z]/.test(senha)) {
    return 'A senha deve conter pelo menos 1 letra minúscula.';
  }
  if (!/[0-9]/.test(senha)) {
    return 'A senha deve conter pelo menos 1 número.';
  }
  if (!/[^A-Za-z0-9]/.test(senha)) {
    return 'A senha deve conter pelo menos 1 caractere especial.';
  }
  return '';
};

export default function GerenciarUsuariosPage() {
  const { 
    usuarioLogado, 
    instituicaoAtiva,
    usuarios,
    adicionarUsuario,
    editarUsuario,
    excluirUsuario
  } = useData();

  const [dialogOpen, setDialogOpen] = useState(false);
  const [dialogSenhaOpen, setDialogSenhaOpen] = useState(false);
  const [editando, setEditando] = useState(false);
  const [usuarioEditando, setUsuarioEditando] = useState(null);
  const [usuarioSenhaAlvo, setUsuarioSenhaAlvo] = useState(null);
  const [mostrarSenha, setMostrarSenha] = useState(false);
  const [mostrarSenhaAtual, setMostrarSenhaAtual] = useState(false);
  const [mostrarNovaSenha, setMostrarNovaSenha] = useState(false);
  const [mostrarConfirmarSenha, setMostrarConfirmarSenha] = useState(false);
  
  const [formData, setFormData] = useState({
    nome: '',
    login: '',
    senha: '',
    email: '',
    cargo: '',
    observacoes: '',
    permissoes: PERMISSOES_DISPONIVEIS.map(item => item.path)
  });

  const [senhaFormData, setSenhaFormData] = useState({
    senhaAtual: '',
    novaSenha: '',
    confirmarSenha: ''
  });

  // Filtrar usuários da instituição ativa (exceto SuperAdmin)
  const usuariosDaInstituicao = (usuarios || []).filter(u => 
    u.instituicaoId === instituicaoAtiva && u.perfil !== 'SuperAdmin'
  );

  const isAdminDaEscola = (
    (usuarioLogado?.tipo === 'master' || usuarioLogado?.perfil === 'Admin' || usuarioLogado?.perfil === 'AdminEscola') &&
    usuarioLogado?.perfil !== 'SuperAdmin'
  );

  // Contar usuários master (sempre pelo menos 1 se o usuário logado é master)
  const totalMasters = isAdminDaEscola ? Math.max(1, usuariosDaInstituicao.filter(u => u.tipo === 'master').length) : 0;
  
  // Total de usuários (incluindo o logado se não estiver na lista)
  const totalUsuarios = usuariosDaInstituicao.some(u => u.id === usuarioLogado?.id) 
    ? usuariosDaInstituicao.length 
    : usuariosDaInstituicao.length + 1;

  // Limite de 5 usuários por instituição (1 master + 4 usuários)
  const limiteAtingido = totalUsuarios >= 5;

  const handleOpen = () => {
    setFormData({
      nome: '',
      login: '',
      senha: '',
      email: '',
      cargo: '',
      observacoes: '',
      permissoes: PERMISSOES_DISPONIVEIS.map(item => item.path)
    });
    setEditando(false);
    setUsuarioEditando(null);
    setMostrarSenha(false);
    setDialogOpen(true);
  };

  const handleEdit = (usuario) => {
    setFormData({
      nome: usuario.nome,
      login: usuario.login,
      senha: '', // Não mostra senha por segurança
      email: usuario.email || '',
      cargo: usuario.cargo || '',
      observacoes: usuario.observacoes || '',
      permissoes: Array.isArray(usuario.permissoes) && usuario.permissoes.length > 0
        ? usuario.permissoes
        : PERMISSOES_DISPONIVEIS.map(item => item.path)
    });
    setEditando(true);
    setUsuarioEditando(usuario);
    setMostrarSenha(false);
    setDialogOpen(true);
  };

  const handleClose = () => {
    setDialogOpen(false);
    setEditando(false);
    setUsuarioEditando(null);
    setMostrarSenha(false);
  };

  const abrirDialogSenha = (usuario) => {
    setUsuarioSenhaAlvo(usuario);
    setSenhaFormData({ senhaAtual: '', novaSenha: '', confirmarSenha: '' });
    setMostrarSenhaAtual(false);
    setMostrarNovaSenha(false);
    setMostrarConfirmarSenha(false);
    setDialogSenhaOpen(true);
  };

  const fecharDialogSenha = () => {
    setDialogSenhaOpen(false);
    setUsuarioSenhaAlvo(null);
    setSenhaFormData({ senhaAtual: '', novaSenha: '', confirmarSenha: '' });
  };

  const handleSalvarSenha = () => {
    if (!usuarioSenhaAlvo) return;

    const alterandoPropriaSenha = usuarioSenhaAlvo.id === usuarioLogado?.id;

    if (alterandoPropriaSenha && !senhaFormData.senhaAtual) {
      alert('Informe sua senha atual para alterar a própria senha.');
      return;
    }

    if (alterandoPropriaSenha && senhaFormData.senhaAtual !== usuarioLogado?.senha) {
      alert('Senha atual inválida.');
      return;
    }

    const erroSenhaForte = validarSenhaForte(senhaFormData.novaSenha);
    if (erroSenhaForte) {
      alert(erroSenhaForte);
      return;
    }

    if (senhaFormData.novaSenha !== senhaFormData.confirmarSenha) {
      alert('A confirmação de senha não confere.');
      return;
    }

    editarUsuario(usuarioSenhaAlvo.id, {
      ...usuarioSenhaAlvo,
      senha: senhaFormData.novaSenha
    });

    alert(`Senha de "${usuarioSenhaAlvo.nome}" atualizada com sucesso.`);
    fecharDialogSenha();
  };

  const togglePermissao = (path) => {
    setFormData(prev => {
      const permissoesAtuais = prev.permissoes || [];
      const jaSelecionada = permissoesAtuais.includes(path);

      return {
        ...prev,
        permissoes: jaSelecionada
          ? permissoesAtuais.filter(item => item !== path)
          : [...permissoesAtuais, path]
      };
    });
  };

  const handleSubmit = () => {
    if (!formData.nome || !formData.login) {
      alert('Nome e login são obrigatórios');
      return;
    }

    if (!editando && limiteAtingido) {
      alert(`Limite de usuários atingido (${totalUsuarios}/5). Exclua um usuário para cadastrar outro.`);
      return;
    }

    if (!editando && !formData.senha) {
      alert('Senha é obrigatória para novos usuários');
      return;
    }

    if (!editando || formData.senha) {
      const erroSenhaForte = validarSenhaForte(formData.senha);
      if (erroSenhaForte) {
        alert(erroSenhaForte);
        return;
      }
    }

    if (!Array.isArray(formData.permissoes) || formData.permissoes.length === 0) {
      alert('Selecione pelo menos uma permissão de acesso para o usuário');
      return;
    }

    // Verificar se login já existe
    const loginExiste = usuarios.some(u => 
      u.login.toLowerCase() === formData.login.toLowerCase() && 
      u.id !== usuarioEditando?.id
    );

    if (loginExiste) {
      alert('Este login já está em uso. Escolha outro.');
      return;
    }

    if (editando) {
      const dadosAtualizados = {
        ...usuarioEditando,
        nome: formData.nome,
        login: formData.login,
        email: formData.email,
        cargo: formData.cargo,
        observacoes: formData.observacoes,
        permissoes: formData.permissoes
      };

      // Só atualiza senha se foi preenchida
      if (formData.senha) {
        dadosAtualizados.senha = formData.senha;
      }

      editarUsuario(usuarioEditando.id, dadosAtualizados);
    } else {
      const novoUsuario = {
        ...formData,
        instituicaoId: instituicaoAtiva,
        perfil: 'Usuario',
        tipo: 'comum',
        ativo: true,
        permissoes: formData.permissoes,
        dataCriacao: new Date().toISOString(),
        criadoPor: usuarioLogado.id
      };

      adicionarUsuario(novoUsuario);
    }

    handleClose();
  };

  const handleDelete = (usuario) => {
    if (usuario.tipo === 'master') {
      alert('Não é possível excluir o usuário master!');
      return;
    }

    if (window.confirm(`Deseja realmente excluir o usuário "${usuario.nome}"?`)) {
      excluirUsuario(usuario.id);
    }
  };

  if (!isAdminDaEscola) {
    return (
      <Layout title="Gerenciar Usuários">
        <Alert severity="error">
          Acesso negado. Somente o administrador da escola pode criar e gerenciar login/senha de usuários.
        </Alert>
      </Layout>
    );
