                </Avatar>
                <Box>
                  <Typography variant="h4">{totalUsuarios}</Typography>
                  <Typography color="text.secondary">Total de Usuários</Typography>
                </Box>
              </Box>
            </CardContent>
          </Card>
        </Grid>
        
        <Grid item xs={12} sm={4}>
          <Card>
            <CardContent>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
