            <TextField
              label="Login *"
              fullWidth
              value={formData.login}
              onChange={(e) => setFormData({ ...formData, login: e.target.value })}
              helperText="Nome de usuário para fazer login no sistema"
            />
            
            <TextField
              label={editando ? "Nova Senha (deixe em branco para manter)" : "Senha *"}
