        </DialogActions>
      </Dialog>

      <Dialog open={dialogSenhaOpen} onClose={fecharDialogSenha} maxWidth="xs" fullWidth>
        <DialogTitle>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
