        <DialogContent>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 1 }}>
            <Alert severity="info">
              Alterando senha de: <strong>{usuarioSenhaAlvo?.nome || '-'}</strong>
            </Alert>

            {usuarioSenhaAlvo?.id === usuarioLogado?.id && (
              <TextField
                label="Senha Atual"
                fullWidth
                type={mostrarSenhaAtual ? 'text' : 'password'}
                value={senhaFormData.senhaAtual}
                onChange={(e) => setSenhaFormData({ ...senhaFormData, senhaAtual: e.target.value })}
                InputProps={{
                  endAdornment: (
                    <InputAdornment position="end">
                      <IconButton edge="end" onClick={() => setMostrarSenhaAtual(prev => !prev)}>
                        {mostrarSenhaAtual ? <VisibilityOff /> : <Visibility />}
                      </IconButton>
                    </InputAdornment>
                  )
                }}
              />
            )}

            <TextField
              label="Nova Senha"
              fullWidth
              type={mostrarNovaSenha ? 'text' : 'password'}
              value={senhaFormData.novaSenha}
              onChange={(e) => setSenhaFormData({ ...senhaFormData, novaSenha: e.target.value })}
              helperText="8+ caracteres, com maiúscula, minúscula, número e especial"
              InputProps={{
                endAdornment: (
                  <InputAdornment position="end">
                    <IconButton edge="end" onClick={() => setMostrarNovaSenha(prev => !prev)}>
                      {mostrarNovaSenha ? <VisibilityOff /> : <Visibility />}
                    </IconButton>
                  </InputAdornment>
                )
              }}
            />

            <TextField
              label="Confirmar Nova Senha"
              fullWidth
              type={mostrarConfirmarSenha ? 'text' : 'password'}
              value={senhaFormData.confirmarSenha}
              onChange={(e) => setSenhaFormData({ ...senhaFormData, confirmarSenha: e.target.value })}
              InputProps={{
                endAdornment: (
                  <InputAdornment position="end">
                    <IconButton edge="end" onClick={() => setMostrarConfirmarSenha(prev => !prev)}>
                      {mostrarConfirmarSenha ? <VisibilityOff /> : <Visibility />}
                    </IconButton>
                  </InputAdornment>
                )
              }}
            />
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={fecharDialogSenha}>Cancelar</Button>
          <Button variant="contained" onClick={handleSalvarSenha} startIcon={<VpnKey />}>
            Salvar Nova Senha
          </Button>
        </DialogActions>
      </Dialog>
    </Layout>
  );
}

import React, { useMemo, useState } from 'react';
import Layout from '../components/Layout';
import {
  Box,
  Button,
  Card,
  CardContent,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  Chip,
  Typography,
  MenuItem,
  Tooltip
} from '@mui/material';
import { Add, Edit, Delete, DeleteForever, Search, Description, ToggleOn, ToggleOff, UploadFile } from '@mui/icons-material';
import { useData } from '../context/DataContext';
import TermoEmprestimo from '../components/TermoEmprestimo';

const normalizarTexto = (valor) => String(valor || '')
  .trim()
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[º°]/g, 'o')
  .replace(/[ª]/g, 'a')
  .replace(/[^a-z0-9\s-]/g, ' ')
  .replace(/\s+/g, ' ');

const compactarTexto = (valor) => normalizarTexto(valor).replace(/[^a-z0-9]/g, '');

const tokenizarTexto = (...valores) => {
  const texto = normalizarTexto(valores.filter(Boolean).join(' '));
  if (!texto) return [];
  return texto.split(/[^a-z0-9]+/).filter(Boolean);
};

const extrairNumeroSerie = (valor) => {
  const texto = normalizarTexto(valor);
  if (!texto) return '';

  const match = texto.match(/(\d{1,2})\s*(?:a|o)?\s*(?:serie|ano)?/);
  return match ? match[1] : '';
};

const extrairSalaTurma = (valor) => {
  const texto = normalizarTexto(valor).toUpperCase();
  if (!texto) return '';

  const padraoIB = texto.match(/\b[IA]\s*-\s*([A-Z])\b/);
  if (padraoIB) {
    return padraoIB[1];
  }

  const inicio = texto.match(/^([A-Z])\b/);
  if (inicio) {
    return inicio[1];
  }

  const final = texto.match(/\b([A-Z])\b$/);
  if (final) {
    return final[1];
  }

  return '';
};

const extrairCursoAcademico = (...valores) => {
  const tokens = tokenizarTexto(...valores);
  if (tokens.length === 0) return '';

  const tokenSet = new Set(tokens);
  const textoCompacto = tokens.join('');

  if (tokens.some((token) => token.includes('farm'))) return 'farm';
  if (tokens.some((token) => token.includes('mark')) || tokenSet.has('dig')) return 'mark';
  if (tokens.some((token) => token.includes('emp'))) return 'emp';
  if (tokens.some((token) => token.includes('prop')) || tokens.some((token) => token.includes('admi'))) return 'prop';

  const temDs = tokenSet.has('ds')
    || (tokenSet.has('d') && tokenSet.has('s'))
    || tokens.some((token) => token.includes('des'))
    || tokens.some((token) => token === 'sis');

  if (temDs || textoCompacto.includes('dessis')) return 'ds';
  if (tokenSet.has('int')) return 'int';

  return '';
};
const somenteDigitos = (valor) => String(valor || '').replace(/\D/g, '');

const extrairSerieETurma = (valor) => {
  const texto = String(valor || '').replace(/[–—]/g, '-').replace(/\s+/g, ' ').trim();
  if (!texto) {
    return { serie: '', turma: '' };
  }

  const partes = texto.split('-').map((item) => item.trim()).filter(Boolean);
  if (partes.length >= 2) {
    return {
      serie: partes.slice(0, -1).join(' - ').trim(),
      turma: partes[partes.length - 1].trim()
    };
  }

  return { serie: texto, turma: '' };
};

const parseLinhaImportacao = (linha) => {
  const conteudo = String(linha || '').replace(/^\uFEFF/, '').trim();
  if (!conteudo) return null;

  const linhaNormalizada = normalizarTexto(conteudo);
  if (
    linhaNormalizada.startsWith('nome') ||
    linhaNormalizada.startsWith('cpf') ||
    linhaNormalizada.includes('nome	cpf')
  ) {
    return null;
  }

  const separador = conteudo.includes('\t')
    ? '\t'
    : conteudo.includes(';')
      ? ';'
      : conteudo.includes(',')
        ? ','
        : null;

  if (!separador) {
    return null;
  }

  const partes = conteudo.split(separador).map((item) => String(item || '').trim());
  if (partes.length < 3) {
    return null;
  }

  const possuiIndice = /^\d+$/.test(partes[0] || '');
  const deslocamento = possuiIndice ? 1 : 0;
  const colunasUteis = partes.length - deslocamento;

  if (colunasUteis < 3) {
    return null;
  }

  const nome = partes[deslocamento] || '';
  const cpf = partes[deslocamento + 1] || '';
  const matricula = partes[deslocamento + 4] || '';

  let serie = '';
  let turma = '';

  if (colunasUteis >= 4) {
    serie = partes[deslocamento + 2] || '';
    turma = partes[deslocamento + 3] || '';
  } else {
    const extraido = extrairSerieETurma(partes[deslocamento + 2]);
    serie = extraido.serie;
    turma = extraido.turma;
  }

  return {
    nome,
    cpf,
    serie,
    turma,
    matricula
  };
};

function LeitoresPage() {
  const {
    clientes,
    adicionarCliente,
    adicionarClientesEmLote,
    atualizarCliente,
    removerCliente,
    removerTodosClientes,
    removerClientesPorTurma,
    emprestimos,
    seriesAcademicas,
    turmasAcademicas
  } = useData();
  const [open, setOpen] = useState(false);
  const [importOpen, setImportOpen] = useState(false);
  const [excluirTurmaOpen, setExcluirTurmaOpen] = useState(false);
  const [turmaParaExclusao, setTurmaParaExclusao] = useState('');
  const [textoImportacao, setTextoImportacao] = useState('');
  const [editando, setEditando] = useState(null);
  const [busca, setBusca] = useState('');
  
  // Estados para termo de empréstimo
  const [termoOpen, setTermoOpen] = useState(false);
  const [tipoTermo, setTipoTermo] = useState('branco');
  
  const [formData, setFormData] = useState({
    nome: '',
    cpf: '',
    telefone: '',
    email: '',
    endereco: '',
    tipo: 'Aluno',
    categoria: '',
    serie: '',
    serieId: '',
    turma: '',
    turmaId: '',
    matricula: '',
    ativo: true
  });

  const tiposCliente = ['Aluno', 'Professor', 'Funcionário', 'Visitante'];

  const getPerfilLeitor = (cliente) => {
    const tipo = normalizarTexto(cliente?.tipo);
    const categoria = normalizarTexto(cliente?.categoria);
    const possuiVinculoAcademico = Boolean(
      String(cliente?.turmaId || '').trim()
      || String(cliente?.serieId || '').trim()
      || normalizarTexto(cliente?.turma || cliente?.nomeTurma)
      || normalizarTexto(cliente?.serie || cliente?.nomeSerie)
    );

    if (tipo === 'aluno' || categoria === 'estudante' || (tipo === 'leitor' && possuiVinculoAcademico)) {
      return 'estudante';
    }

    if (tipo.includes('professor')) {
      return 'professor';
    }

    if (
      tipo.includes('funcion')
      || tipo.includes('bibliotec')
      || tipo.includes('coorden')
      || tipo.includes('diretor')
      || tipo.includes('gestor')
      || tipo.includes('servidor')
      || tipo.includes('admin')
      || categoria.includes('funcion')
      || categoria.includes('servidor')
    ) {
      return 'funcionario';
    }

    return 'comunidade';
  };

  const clientesVisiveis = useMemo(
    () => clientes.filter((cliente) => !cliente?.excluido),
    [clientes]
  );

  const resumoLeitores = useMemo(() => {
    const acumulado = {
      turmas: turmasAcademicas.length,
      total: clientesVisiveis.length,
      estudantes: 0,
      professores: 0,
      funcionarios: 0,
      comunidade: 0
    };

    clientesVisiveis.forEach((cliente) => {
      const perfil = getPerfilLeitor(cliente);
      if (perfil === 'estudante') acumulado.estudantes += 1;
      else if (perfil === 'professor') acumulado.professores += 1;
      else if (perfil === 'funcionario') acumulado.funcionarios += 1;
      else acumulado.comunidade += 1;
    });

    return acumulado;
  }, [clientesVisiveis, turmasAcademicas]);

  const localizarSeriePorNome = (nomeSerie) => {
    const nomeNormalizado = normalizarTexto(nomeSerie);
    if (!nomeNormalizado) return null;

    const nomeCompacto = compactarTexto(nomeSerie);
    const numeroSerie = extrairNumeroSerie(nomeSerie);

    const correspondenciaExata = seriesAcademicas.find((serie) => normalizarTexto(serie.nomeSerie) === nomeNormalizado);
    if (correspondenciaExata) return correspondenciaExata;

    if (nomeCompacto) {
      const correspondenciaCompacta = seriesAcademicas.find((serie) => {
        const serieCompacta = compactarTexto(serie.nomeSerie);
        return (
          serieCompacta === nomeCompacto
          || serieCompacta.includes(nomeCompacto)
          || nomeCompacto.includes(serieCompacta)
        );
      });

      if (correspondenciaCompacta) {
        return correspondenciaCompacta;
      }
    }

    if (numeroSerie) {
      const correspondenciasPorNumero = seriesAcademicas.filter(
        (serie) => extrairNumeroSerie(serie.nomeSerie) === numeroSerie
      );

      if (correspondenciasPorNumero.length === 1) {
        return correspondenciasPorNumero[0];
      }
    }

    return null;
  };

  const localizarTurmaPorNome = (nomeTurma, serieId = '', nomeSerie = '') => {
    const turmaNormalizada = normalizarTexto(nomeTurma);
    if (!turmaNormalizada) return null;

    const turmaCompacta = compactarTexto(nomeTurma);
    const serieIdNormalizada = String(serieId || '').trim();
    const serieInformada = localizarSeriePorNome(nomeSerie);
    const serieIdResolvida = serieIdNormalizada || (serieInformada ? String(serieInformada.id) : '');
    const serieTextoReferencia = String(nomeSerie || serieInformada?.nomeSerie || '').trim();
    const nomeSerieNormalizado = normalizarTexto(serieTextoReferencia);
    const nomeSerieCompacto = compactarTexto(serieTextoReferencia);
    const numeroSerieReferencia = extrairNumeroSerie(serieTextoReferencia);
    const salaReferencia = extrairSalaTurma(nomeTurma);
    const cursoReferencia = extrairCursoAcademico(nomeTurma, serieTextoReferencia);

    const candidatosSerie = turmasAcademicas.filter((turma) => {
      if (serieIdResolvida) {
        return String(turma.serieId || '') === serieIdResolvida;
      }

      if (!nomeSerieNormalizado && !numeroSerieReferencia) {
        return true;
      }

      const nomeSerieTurma = normalizarTexto(turma.nomeSerie);
      const nomeSerieTurmaCompacto = compactarTexto(turma.nomeSerie);
      const numeroSerieTurma = extrairNumeroSerie(turma.nomeSerie);

      return (
        (!nomeSerieNormalizado || nomeSerieTurma === nomeSerieNormalizado)
        || (nomeSerieCompacto && nomeSerieTurmaCompacto === nomeSerieCompacto)
        || (nomeSerieCompacto && nomeSerieTurmaCompacto.includes(nomeSerieCompacto))
        || (nomeSerieCompacto && nomeSerieCompacto.includes(nomeSerieTurmaCompacto))
        || (numeroSerieReferencia && numeroSerieTurma && numeroSerieReferencia === numeroSerieTurma)
      );
    });

    const candidatos = candidatosSerie.length > 0 ? candidatosSerie : turmasAcademicas;

    const correspondenciaExata = candidatos.find(
      (turma) => normalizarTexto(turma.nomeTurma) === turmaNormalizada
    );
    if (correspondenciaExata) {
      return correspondenciaExata;
    }

    if (turmaCompacta) {
      const correspondenciaCompacta = candidatos.find((turma) => {
        const nomeTurmaCompacto = compactarTexto(turma.nomeTurma);
        return (
          nomeTurmaCompacto === turmaCompacta
          || nomeTurmaCompacto.includes(turmaCompacta)
          || turmaCompacta.includes(nomeTurmaCompacto)
        );
      });

      if (correspondenciaCompacta) {
        return correspondenciaCompacta;
      }
    }

    if (!salaReferencia && !cursoReferencia) {
      return null;
    }

    const candidatosAssinatura = candidatos.filter((turma) => {
      const salaTurma = extrairSalaTurma(turma.nomeTurma);
      const cursoTurma = extrairCursoAcademico(turma.nomeTurma, turma.nomeSerie);
      const numeroSerieTurma = extrairNumeroSerie(turma.nomeSerie);
      const possuiEixoComparavel = (salaReferencia && salaTurma) || (cursoReferencia && cursoTurma);

      if (!possuiEixoComparavel) {
        return false;
      }

      const salaCompativel = !salaReferencia || !salaTurma || salaReferencia === salaTurma;
      const cursoCompativel = !cursoReferencia || !cursoTurma || cursoReferencia === cursoTurma;
      const serieCompativel = !numeroSerieReferencia || !numeroSerieTurma || numeroSerieReferencia === numeroSerieTurma;

      return salaCompativel && cursoCompativel && serieCompativel;
    });

    if (candidatosAssinatura.length === 1) {
      return candidatosAssinatura[0];
    }

    if (cursoReferencia) {
      const candidatosPorCurso = candidatosAssinatura.filter(
        (turma) => extrairCursoAcademico(turma.nomeTurma, turma.nomeSerie) === cursoReferencia
      );

      if (candidatosPorCurso.length === 1) {
        return candidatosPorCurso[0];
      }
    }

    return null;
  };

  const handleOpen = (cliente = null) => {
    if (cliente) {
      setEditando(cliente.id);
      setFormData({
        ...cliente,
        serieId: cliente.serieId ? String(cliente.serieId) : '',
        turmaId: cliente.turmaId ? String(cliente.turmaId) : ''
      });
    } else {
      setEditando(null);
      setFormData({
        nome: '',
        cpf: '',
        telefone: '',
        email: '',
        endereco: '',
        tipo: 'Aluno',
        categoria: '',
        serie: '',
        serieId: '',
        turma: '',
        turmaId: '',
        matricula: '',
        ativo: true
      });
    }
    setOpen(true);
  };

  const handleClose = () => {
    setOpen(false);
    setEditando(null);
  };

  const abrirCadastroRapido = (tipo) => {
    setEditando(null);
    setFormData({
      nome: '',
      cpf: '',
      telefone: '',
      email: '',
      endereco: '',
      tipo,
      categoria: tipo === 'Aluno' ? 'Estudante' : '',
      serie: '',
      serieId: '',
      turma: '',
      turmaId: '',
      matricula: '',
      ativo: true
    });
    setOpen(true);
  };

  const handleSubmit = () => {
    const dadosParaSalvar = { ...formData };

    // Gerar código automático se for novo leitor
    if (!editando) {
      const numeroSequencial = (clientes.length + 1).toString().padStart(6, '0');
      const codigoLeitor = `LEIT${numeroSequencial}`;
      dadosParaSalvar.codigoIdentificacao = codigoLeitor;
    }

    if (dadosParaSalvar.tipo === 'Aluno') {
      const serieEncontrada = dadosParaSalvar.serieId
        ? (
          seriesAcademicas.find((serie) => String(serie.id) === String(dadosParaSalvar.serieId))
          || localizarSeriePorNome(dadosParaSalvar.serie)
        )
        : localizarSeriePorNome(dadosParaSalvar.serie);

      if (serieEncontrada) {
        dadosParaSalvar.serieId = String(serieEncontrada.id);
        dadosParaSalvar.serie = serieEncontrada.nomeSerie;
      } else {
        dadosParaSalvar.serieId = '';
      }

      const turmaEncontrada = dadosParaSalvar.turmaId
        ? (
          turmasAcademicas.find((turma) => String(turma.id) === String(dadosParaSalvar.turmaId))
          || localizarTurmaPorNome(dadosParaSalvar.turma, dadosParaSalvar.serieId, dadosParaSalvar.serie)
        )
        : localizarTurmaPorNome(dadosParaSalvar.turma, dadosParaSalvar.serieId, dadosParaSalvar.serie);

      if (turmaEncontrada) {
        dadosParaSalvar.turmaId = String(turmaEncontrada.id);
        dadosParaSalvar.turma = turmaEncontrada.nomeTurma;

        if (!dadosParaSalvar.serieId && turmaEncontrada.serieId) {
          dadosParaSalvar.serieId = String(turmaEncontrada.serieId);
          dadosParaSalvar.serie = turmaEncontrada.nomeSerie || dadosParaSalvar.serie;
        }
      } else {
        dadosParaSalvar.turmaId = '';
      }
    } else {
      dadosParaSalvar.serie = '';
      dadosParaSalvar.serieId = '';
      dadosParaSalvar.turma = '';
      dadosParaSalvar.turmaId = '';
    }
    
    if (editando) {
      atualizarCliente(editando, dadosParaSalvar);
    } else {
      adicionarCliente(dadosParaSalvar);
    }
    handleClose();
  };

  const isEmprestimoAtivo = (status) => {
    const statusNormalizado = String(status || '').toLowerCase();
    return statusNormalizado === 'ativo' || statusNormalizado === 'emprestado';
  };

  const possuiEmprestimoAtivo = (clienteId) => {
    const idNormalizado = String(clienteId);
    return emprestimos.some((e) => {
      const clienteIdEmprestimo = e.clienteId ?? e.leitorId;
      return (
        clienteIdEmprestimo !== undefined &&
        clienteIdEmprestimo !== null &&
        String(clienteIdEmprestimo) === idNormalizado &&
        isEmprestimoAtivo(e.status)
      );
    });
  };

  const possuiHistoricoEmprestimos = (clienteId) => {
    const idNormalizado = String(clienteId);
    return emprestimos.some((e) => {
      const clienteIdEmprestimo = e.clienteId ?? e.leitorId;
      return clienteIdEmprestimo !== undefined && clienteIdEmprestimo !== null && String(clienteIdEmprestimo) === idNormalizado;
    });
  };

  const clientePertenceTurma = (cliente, turma) => {
    const turmaId = String(turma?.id || '').trim();
    const clienteTurmaId = String(cliente?.turmaId || '').trim();

    if (turmaId && clienteTurmaId && turmaId === clienteTurmaId) {
      return true;
    }

    const nomeTurmaAlvo = normalizarTexto(turma?.nomeTurma);
    const nomeTurmaCliente = normalizarTexto(cliente?.turma || cliente?.nomeTurma);

    if (!nomeTurmaAlvo || !nomeTurmaCliente || nomeTurmaAlvo !== nomeTurmaCliente) {
      return false;
    }

    const nomeSerieAlvo = normalizarTexto(turma?.nomeSerie);
    const nomeSerieCliente = normalizarTexto(cliente?.serie || cliente?.nomeSerie);

    return !nomeSerieAlvo || !nomeSerieCliente || nomeSerieAlvo === nomeSerieCliente;
  };

  const turmasParaExclusao = useMemo(() => {
    return [...turmasAcademicas]
      .map((turma) => {
        const leitoresDaTurma = clientesVisiveis.filter((cliente) => clientePertenceTurma(cliente, turma));
        const totalLeitores = leitoresDaTurma.length;
        const elegiveisExclusao = leitoresDaTurma.filter((cliente) => !possuiHistoricoEmprestimos(cliente.id)).length;

        return {
          ...turma,
          totalLeitores,
          elegiveisExclusao,
          preservadosHistorico: Math.max(totalLeitores - elegiveisExclusao, 0)
        };
      })
      .filter((turma) => turma.totalLeitores > 0)
      .sort((a, b) => {
        const serieA = String(a.nomeSerie || '');
        const serieB = String(b.nomeSerie || '');
        if (serieA !== serieB) return serieA.localeCompare(serieB, 'pt-BR');
        return String(a.nomeTurma || '').localeCompare(String(b.nomeTurma || ''), 'pt-BR');
      });
  }, [clientesVisiveis, turmasAcademicas, emprestimos]);

  const turmaSelecionadaExclusao = useMemo(() => {
    return turmasParaExclusao.find((turma) => String(turma.id) === String(turmaParaExclusao)) || null;
  }, [turmasParaExclusao, turmaParaExclusao]);

  const handleToggleStatus = (cliente) => {
    const novoStatus = !cliente.ativo;
    const acao = novoStatus ? 'ativar' : 'inativar';

    if (!novoStatus && possuiEmprestimoAtivo(cliente.id)) {
      const confirmar = window.confirm(
        'Este leitor possui empréstimo(s) ativo(s).\n\n' +
        'A inativação não apaga dados e apenas evita novos empréstimos para este cadastro.\n\n' +
        'Deseja continuar?'
      );

      if (!confirmar) {
        return;
      }
    } else if (!window.confirm(`Deseja realmente ${acao} este leitor?`)) {
      return;
    }

    atualizarCliente(cliente.id, { ativo: novoStatus });
  };

  const handleDelete = async (id) => {
    const idNormalizado = String(id);
    const leitor = clientesVisiveis.find((c) => String(c.id) === idNormalizado);
    const nomeLeitor = leitor?.nome || leitor?.nomeCompleto || 'este leitor';

    const emprestimoAtivo = possuiEmprestimoAtivo(id);

    if (emprestimoAtivo) {
      alert(
        `Não é possível excluir "${nomeLeitor}"!\n\n` +
        'O leitor possui livro(s) emprestado(s).\n' +
        'Primeiro realize a devolução de todos os livros emprestados.'
      );
      return;
    }

    if (possuiHistoricoEmprestimos(id)) {
      const confirmarExclusao = window.confirm(
        `Tem certeza que deseja excluir "${nomeLeitor}"?\n\n` +
        'Este leitor possui histórico de empréstimos vinculado ao cadastro.\n' +
        'Ao excluir, o leitor sairá da listagem normal, mas o histórico da biblioteca será preservado.\n\n' +
        'Deseja continuar com a exclusão?'
      );

      if (!confirmarExclusao) {
        return;
      }
      await removerCliente(id);
      return;
    }

    if (window.confirm(`Tem certeza que deseja excluir "${nomeLeitor}"?\n\nEsta ação não pode ser desfeita.`)) {
      await removerCliente(id);
    }
  };

  const handleDeleteByTurma = async () => {
    if (!turmaSelecionadaExclusao) {
      alert('Selecione uma turma para continuar.');
      return;
    }

    const mensagem =
      `Tem certeza que deseja EXCLUIR leitores da turma ${turmaSelecionadaExclusao.nomeSerie || '-'} - ${turmaSelecionadaExclusao.nomeTurma}?\n\n` +
      `Total na turma: ${turmaSelecionadaExclusao.totalLeitores}\n` +
      `Sem histórico (serão excluídos): ${turmaSelecionadaExclusao.elegiveisExclusao}\n` +
      `Com histórico (serão preservados): ${turmaSelecionadaExclusao.preservadosHistorico}\n\n` +
      `Esta ação não pode ser desfeita.`;

    if (!window.confirm(mensagem)) return;
    if (!window.confirm('Confirme novamente: excluir os leitores sem histórico da turma selecionada?')) return;

    const resultado = await removerClientesPorTurma({
      id: turmaSelecionadaExclusao.id,
      nomeTurma: turmaSelecionadaExclusao.nomeTurma,
      nomeSerie: turmaSelecionadaExclusao.nomeSerie
    });

    const removidos = Number(resultado?.removidos || 0);
    const preservadosHistorico = Number(resultado?.preservadosHistorico || 0);
    const falhas = Number(resultado?.falhas || 0);

    if (falhas > 0) {
      alert(
        `Concluído com ressalvas.\n\n` +
        `Excluídos: ${removidos}\n` +
        `Preservados por histórico: ${preservadosHistorico}\n` +
        `Falhas na nuvem: ${falhas}`
      );
    } else {
      alert(
        `Concluído.\n\n` +
        `Excluídos: ${removidos}\n` +
        `Preservados por histórico: ${preservadosHistorico}`
      );
    }

    setExcluirTurmaOpen(false);
    setTurmaParaExclusao('');
  };

  const handleDeleteAll = async () => {
    const totalSemHistorico = clientesVisiveis.filter((c) => {
      return !possuiHistoricoEmprestimos(c.id);
    }).length;

    const totalComHistorico = clientesVisiveis.length - totalSemHistorico;

    const mensagem =
      `Tem certeza que deseja EXCLUIR TODOS os leitores?

` +
      `Total de leitores: ${clientesVisiveis.length}
` +
      `Sem histórico (serão excluídos): ${totalSemHistorico}
` +
      `Com histórico (serão preservados): ${totalComHistorico}

` +
      `Esta ação não pode ser desfeita!`;

    if (!window.confirm(mensagem)) return;
    if (!window.confirm('Confirme novamente: excluir TODOS os leitores sem histórico de empréstimo?')) return;

    const resultado = await removerTodosClientes();
    if (resultado?.falhas > 0) {
      alert(
        `Concluído com ressalvas.\n\n` +
        `Excluídos: ${resultado.removidos}\n` +
        `Falhas na nuvem: ${resultado.falhas}`
      );
      return;
    }

    alert(`Concluído. ${resultado.removidos} leitor(es) excluído(s).`);
  };

  const handleImportarEmLote = () => {
    const linhas = String(textoImportacao || '')
      .replace(/\u0000/g, '')
      .split(/\r\n|\n|\r/)
      .map((linha) => linha.trim())
      .filter(Boolean);

    if (linhas.length === 0) {
      alert('Cole a lista de alunos antes de importar.');
      return;
    }

    const registrosProcessados = linhas.map((linha) => parseLinhaImportacao(linha));
    const registros = registrosProcessados.filter(Boolean);

    if (registros.length === 0) {
      alert('Formato inválido. Use linhas como: Nome;CPF;Série;Turma;Matrícula');
      return;
    }

    let ignoradosFormato = registrosProcessados.length - registros.length;

    const loteParaAdicionar = registros.reduce((acumulador, registro) => {
      const nome = String(registro.nome || '').trim();
      const cpf = String(registro.cpf || '').trim();
      const cpfDigitos = somenteDigitos(cpf);

      if (!nome || !cpf || cpfDigitos.length !== 11) {
        ignoradosFormato += 1;
        return acumulador;
      }

      const serieEncontrada = localizarSeriePorNome(registro.serie);
      const turmaEncontrada = localizarTurmaPorNome(
        registro.turma,
        serieEncontrada ? String(serieEncontrada.id) : '',
        registro.serie
      );

      acumulador.push({
        nome,
        cpf,
        telefone: '',
        email: '',
        endereco: '',
        tipo: 'Aluno',
        serie: serieEncontrada?.nomeSerie || String(registro.serie || '').trim(),
        serieId: serieEncontrada ? String(serieEncontrada.id) : '',
        turma: turmaEncontrada?.nomeTurma || String(registro.turma || '').trim(),
        turmaId: turmaEncontrada ? String(turmaEncontrada.id) : '',
        matricula: String(registro.matricula || '').trim(),
        ativo: true
      });

      return acumulador;
    }, []);

    const resultadoLote = adicionarClientesEmLote(loteParaAdicionar);
    const inseridos = Number(resultadoLote?.inseridos || 0);
    const ignoradosContexto = Number(resultadoLote?.ignorados || 0);
    const ignorados = ignoradosFormato + ignoradosContexto;

    const ignoradosPorLimite = Array.isArray(resultadoLote?.detalhesIgnorados)
      ? resultadoLote.detalhesIgnorados.filter((item) => String(item?.motivo || '').includes('limite')).length
      : 0;

    const resumoLimite = ignoradosPorLimite > 0
      ? `\nIgnorados por limite da conta: ${ignoradosPorLimite}`
      : '';

    alert(
      `Importação concluída.\n\n` +
      `Inseridos: ${inseridos}\n` +
      `Ignorados: ${ignorados}` +
      resumoLimite
    );

    setTextoImportacao('');
    setImportOpen(false);
  };

  const clientesFiltrados = clientesVisiveis.filter((cliente) => {
    const buscaNormalizada = busca.toLowerCase();
    return (
      String(cliente?.nome || '').toLowerCase().includes(buscaNormalizada)
      || String(cliente?.cpf || '').includes(busca)
      || String(cliente?.matricula || '').includes(busca)
      || String(cliente?.turma || '').toLowerCase().includes(buscaNormalizada)
      || String(cliente?.serie || '').toLowerCase().includes(buscaNormalizada)
    );
  });

  const turmasCadastradas = useMemo(() => {
    const serieSelecionadaId = String(formData.serieId || '');
    const serieSelecionadaNome = normalizarTexto(formData.serie);
    const nomesTurma = new Set();

    turmasAcademicas.forEach((turma) => {
      const mesmaSeriePorId = serieSelecionadaId
        ? String(turma.serieId || '') === serieSelecionadaId
        : true;
      const mesmaSeriePorNome = !serieSelecionadaId && serieSelecionadaNome
        ? normalizarTexto(turma.nomeSerie) === serieSelecionadaNome
        : true;

      if (mesmaSeriePorId && mesmaSeriePorNome) {
        nomesTurma.add(String(turma.nomeTurma || '').trim());
      }
    });

    clientesVisiveis
      .filter((cliente) => String(cliente.tipo || '').toLowerCase() === 'aluno')
      .forEach((cliente) => {
        const mesmaSerie = serieSelecionadaNome
          ? normalizarTexto(cliente.serie) === serieSelecionadaNome
          : true;

        if (mesmaSerie) {
          nomesTurma.add(String(cliente.turma || '').trim());
        }
      });

    return Array.from(nomesTurma)
      .filter(Boolean)
      .sort((a, b) => a.localeCompare(b, 'pt-BR'));
  }, [clientesVisiveis, turmasAcademicas, formData.serie, formData.serieId]);

  const seriesCadastradas = useMemo(() => {
    const nomesSeries = new Set(
      seriesAcademicas
        .map((serie) => String(serie.nomeSerie || '').trim())
        .filter(Boolean)
    );

    clientesVisiveis
      .filter((cliente) => String(cliente.tipo || '').toLowerCase() === 'aluno')
      .forEach((cliente) => {
        nomesSeries.add(String(cliente.serie || '').trim());
      });

    return Array.from(nomesSeries)
      .filter(Boolean)
      .sort((a, b) => a.localeCompare(b, 'pt-BR'));
  }, [clientesVisiveis, seriesAcademicas]);

  return (
    <Layout title="Leitores">
      <Box
        sx={{
          mb: 2,
          display: 'grid',
          gridTemplateColumns: {
            xs: '1fr 1fr',
            md: 'repeat(3, minmax(180px, 1fr))',
            lg: 'repeat(6, minmax(170px, 1fr))'
          },
          gap: 1.5
        }}
      >
        <Card variant="outlined">
          <CardContent sx={{ py: 1.5 }}>
            <Typography variant="caption" color="text.secondary">Turmas</Typography>
            <Typography variant="h5" fontWeight={700}>{resumoLeitores.turmas}</Typography>
            <Typography variant="body2" color="text.secondary">cadastradas</Typography>
          </CardContent>
        </Card>

        <Card variant="outlined">
          <CardContent sx={{ py: 1.5 }}>
            <Typography variant="caption" color="text.secondary">Estudantes</Typography>
            <Typography variant="h5" fontWeight={700}>{resumoLeitores.estudantes}</Typography>
            <Typography variant="body2" color="text.secondary">leitores cadastrados</Typography>
          </CardContent>
        </Card>

        <Card variant="outlined">
          <CardContent sx={{ py: 1.5 }}>
            <Typography variant="caption" color="text.secondary">Professores</Typography>
            <Typography variant="h5" fontWeight={700}>{resumoLeitores.professores}</Typography>
            <Typography variant="body2" color="text.secondary">leitores cadastrados</Typography>
          </CardContent>
        </Card>

        <Card variant="outlined">
          <CardContent sx={{ py: 1.5 }}>
            <Typography variant="caption" color="text.secondary">Funcionários</Typography>
            <Typography variant="h5" fontWeight={700}>{resumoLeitores.funcionarios}</Typography>
            <Typography variant="body2" color="text.secondary">leitores cadastrados</Typography>
          </CardContent>
        </Card>

        <Card variant="outlined">
          <CardContent sx={{ py: 1.5 }}>
            <Typography variant="caption" color="text.secondary">Comunidade</Typography>
            <Typography variant="h5" fontWeight={700}>{resumoLeitores.comunidade}</Typography>
            <Typography variant="body2" color="text.secondary">leitores cadastrados</Typography>
          </CardContent>
        </Card>

        <Card variant="outlined" sx={{ borderColor: 'secondary.main', bgcolor: 'secondary.50' }}>
          <CardContent sx={{ py: 1.5 }}>
            <Typography variant="caption" color="text.secondary">Total</Typography>
            <Typography variant="h5" fontWeight={700}>{resumoLeitores.total}</Typography>
            <Typography variant="body2" color="text.secondary">leitores cadastrados</Typography>
          </CardContent>
        </Card>
      </Box>

      <Paper variant="outlined" sx={{ p: 1.5, mb: 2 }}>
        <Typography variant="subtitle2" fontWeight={700} sx={{ mb: 1 }}>
          Iniciação Rápida
        </Typography>
        <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
          <Button size="small" variant="contained" onClick={() => abrirCadastroRapido('Aluno')}>
            Novo Estudante
          </Button>
          <Button size="small" variant="outlined" onClick={() => abrirCadastroRapido('Professor')}>
            Novo Professor
          </Button>
          <Button size="small" variant="outlined" onClick={() => abrirCadastroRapido('Funcionário')}>
            Novo Funcionário
          </Button>
          <Button size="small" variant="outlined" onClick={() => abrirCadastroRapido('Visitante')}>
            Nova Comunidade
          </Button>
          <Button size="small" variant="text" startIcon={<UploadFile />} onClick={() => setImportOpen(true)}>
            Importar em lote
          </Button>
        </Box>
      </Paper>

      <Box sx={{ mb: 2, display: 'flex', gap: 2, flexWrap: 'wrap', alignItems: 'center' }}>
        <TextField
          placeholder="Buscar por nome, CPF ou matrícula..."
          variant="outlined"
          size="small"
          fullWidth
          value={busca}
          onChange={(e) => setBusca(e.target.value)}
          InputProps={{
            startAdornment: <Search sx={{ mr: 1, color: 'text.secondary' }} />
          }}
          sx={{ flexGrow: 1, minWidth: '200px' }}
        />
        <Button
          variant="outlined"
          startIcon={<Description />}
          onClick={() => {
            setTipoTermo('branco');
            setTermoOpen(true);
          }}
          size="small"
          color="secondary"
        >
          Termo em Branco
        </Button>
        <Button
          variant="outlined"
          color="warning"
          startIcon={<Delete />}
          onClick={() => {
            setTurmaParaExclusao('');
            setExcluirTurmaOpen(true);
          }}
          disabled={turmasParaExclusao.length === 0}
        >
          Excluir por Turma
        </Button>
        <Button
          variant="outlined"
          color="error"
          startIcon={<DeleteForever />}
          onClick={handleDeleteAll}
        >
          Excluir Todos
        </Button>
      </Box>

      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Código</TableCell>
              <TableCell>Nome</TableCell>
              <TableCell>CPF</TableCell>
              <TableCell>Tipo</TableCell>
              <TableCell>Categoria</TableCell>
              <TableCell>Matrícula</TableCell>
              <TableCell>Série</TableCell>
              <TableCell>Turma</TableCell>
              <TableCell>Status</TableCell>
              <TableCell>Ações</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {clientesFiltrados.length === 0 ? (
              <TableRow>
                <TableCell colSpan={10} align="center">
                  <Typography color="text.secondary">
                    Nenhum leitor cadastrado
                  </Typography>
                </TableCell>
              </TableRow>
            ) : (
              clientesFiltrados.map((cliente) => (
                <TableRow key={cliente.id}>
                  <TableCell>
                    <Chip 
                      label={cliente.codigoIdentificacao || 'N/A'} 
                      size="small" 
                      color="secondary"
                      variant="outlined"
                    />
                  </TableCell>
                  <TableCell>{cliente.nome}</TableCell>
                  <TableCell>{cliente.cpf}</TableCell>
                  <TableCell>
                    <Chip label={cliente.tipo} size="small" />
                  </TableCell>
                  <TableCell>{cliente.categoria || '-'}</TableCell>
                  <TableCell>{cliente.matricula || '-'}</TableCell>
                  <TableCell>{cliente.serie || '-'}</TableCell>
                  <TableCell>{cliente.turma || '-'}</TableCell>
                  <TableCell>
                    <Chip 
                      label={cliente.ativo ? 'Ativo' : 'Inativo'} 
                      size="small" 
                      color={cliente.ativo ? 'success' : 'default'} 
                    />
                  </TableCell>
                  <TableCell>
                    <IconButton onClick={() => handleOpen(cliente)} size="small">
                      <Edit />
                    </IconButton>
                    <Tooltip title={cliente.ativo ? 'Inativar leitor' : 'Ativar leitor'}>
                      <IconButton
                        onClick={() => handleToggleStatus(cliente)}
                        size="small"
                        color={cliente.ativo ? 'warning' : 'success'}
                      >
                        {cliente.ativo ? <ToggleOff /> : <ToggleOn />}
                      </IconButton>
                    </Tooltip>
                    <IconButton onClick={() => handleDelete(cliente.id)} size="small" color="error">
                      <Delete />
                    </IconButton>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </TableContainer>

      <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
        <DialogTitle>{editando ? 'Editar Leitor' : 'Novo Leitor'}</DialogTitle>
        <DialogContent>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 1 }}>
            <TextField
              label="Nome Completo"
              fullWidth
              required
              value={formData.nome}
              onChange={(e) => setFormData({ ...formData, nome: e.target.value })}
            />
            <TextField
              label="CPF"
              fullWidth
              required
              value={formData.cpf}
              onChange={(e) => setFormData({ ...formData, cpf: e.target.value })}
            />
            <TextField
              label="Telefone"
              fullWidth
              value={formData.telefone}
              onChange={(e) => setFormData({ ...formData, telefone: e.target.value })}
            />
            <TextField
              label="Email"
              fullWidth
              type="email"
              value={formData.email}
              onChange={(e) => setFormData({ ...formData, email: e.target.value })}
            />
            <TextField
              label="Endereço"
              fullWidth
              value={formData.endereco}
              onChange={(e) => setFormData({ ...formData, endereco: e.target.value })}
            />
            <TextField
              label="Tipo"
              fullWidth
              select
              required
              value={formData.tipo}
              onChange={(e) => setFormData({ ...formData, tipo: e.target.value })}
            >
              {tiposCliente.map((tipo) => (
                <MenuItem key={tipo} value={tipo}>{tipo}</MenuItem>
              ))}
            </TextField>
            <TextField
              label="Categoria"
              fullWidth
              select
              value={formData.categoria || ''}
              onChange={(e) => setFormData({ ...formData, categoria: e.target.value })}
            >
              <MenuItem value="">— Não informado —</MenuItem>
              {['Estudante', 'Professor', 'Funcionário', 'Comunidade'].map((cat) => (
                <MenuItem key={cat} value={cat}>{cat}</MenuItem>
              ))}
            </TextField>
            {formData.tipo === 'Aluno' && (
              <>
                <TextField
                  label="Matrícula"
                  fullWidth
                  value={formData.matricula}
                  onChange={(e) => setFormData({ ...formData, matricula: e.target.value })}
                />
                <TextField
                  label="Série/Ano"
                  fullWidth
                  value={formData.serie}
                  onChange={(e) => {
                    const valorSerie = e.target.value;
                    const serieEncontrada = localizarSeriePorNome(valorSerie);

                    setFormData((prev) => {
                      const proximo = {
                        ...prev,
                        serie: valorSerie,
                        serieId: serieEncontrada ? String(serieEncontrada.id) : ''
                      };

                      if (prev.turmaId) {
                        const turmaAtual = turmasAcademicas.find(
                          (turma) => String(turma.id) === String(prev.turmaId)
                        );

                        if (turmaAtual && proximo.serieId && String(turmaAtual.serieId || '') !== proximo.serieId) {
                          proximo.turma = '';
                          proximo.turmaId = '';
                        }
                      }

                      return proximo;
                    });
                  }}
                  inputProps={{ list: 'lista-series-cadastradas' }}
                  placeholder="Ex: 6º Ano, 1ª Série, EJA Módulo I"
                />
                <TextField
                  label="Turma"
                  fullWidth
                  value={formData.turma}
                  onChange={(e) => {
                    const valorTurma = e.target.value;

                    setFormData((prev) => {
                      const turmaEncontrada = localizarTurmaPorNome(valorTurma, prev.serieId, prev.serie);

                      if (!turmaEncontrada) {
                        return {
                          ...prev,
                          turma: valorTurma,
                          turmaId: ''
                        };
                      }

                      return {
                        ...prev,
                        turma: turmaEncontrada.nomeTurma || valorTurma,
                        turmaId: String(turmaEncontrada.id),
                        serie: turmaEncontrada.nomeSerie || prev.serie,
                        serieId: turmaEncontrada.serieId ? String(turmaEncontrada.serieId) : prev.serieId
                      };
                    });
                  }}
                  inputProps={{ list: 'lista-turmas-cadastradas' }}
                  placeholder="Ex: A, B, C, Integral"
                />
                <datalist id="lista-series-cadastradas">
                  {seriesCadastradas.map((serie) => (
                    <option key={serie} value={serie} />
                  ))}
                </datalist>
                <datalist id="lista-turmas-cadastradas">
                  {turmasCadastradas.map((turma) => (
                    <option key={turma} value={turma} />
                  ))}
                </datalist>
              </>
            )}
            <TextField
              label="Status"
              fullWidth
              select
              value={formData.ativo}
              onChange={(e) => setFormData({ ...formData, ativo: e.target.value === 'true' })}
            >
              <MenuItem value={true}>Ativo</MenuItem>
              <MenuItem value={false}>Inativo</MenuItem>
            </TextField>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClose}>Cancelar</Button>
          <Button onClick={handleSubmit} variant="contained">
            {editando ? 'Salvar' : 'Adicionar'}
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog open={excluirTurmaOpen} onClose={() => setExcluirTurmaOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Excluir Leitores por Turma</DialogTitle>
        <DialogContent>
          <Typography variant="body2" color="text.secondary" sx={{ mt: 1, mb: 2 }}>
            Selecione a turma. O sistema exclui somente leitores sem histórico de empréstimos e preserva os demais.
          </Typography>

          <TextField
            select
            fullWidth
            label="Turma"
            value={turmaParaExclusao}
            onChange={(e) => setTurmaParaExclusao(e.target.value)}
          >
            {turmasParaExclusao.length === 0 ? (
              <MenuItem value="" disabled>
                Nenhuma turma com leitores cadastrados
              </MenuItem>
            ) : (
              turmasParaExclusao.map((turma) => (
                <MenuItem key={turma.id} value={String(turma.id)}>
                  {turma.nomeSerie || '-'} - {turma.nomeTurma} ({turma.totalLeitores} leitor(es))
                </MenuItem>
              ))
            )}
          </TextField>

          {turmaSelecionadaExclusao && (
            <Box sx={{ mt: 2 }}>
              <Typography variant="body2">
                Total na turma: <strong>{turmaSelecionadaExclusao.totalLeitores}</strong>
              </Typography>
              <Typography variant="body2">
                Serão excluídos: <strong>{turmaSelecionadaExclusao.elegiveisExclusao}</strong>
              </Typography>
              <Typography variant="body2">
                Serão preservados por histórico: <strong>{turmaSelecionadaExclusao.preservadosHistorico}</strong>
              </Typography>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setExcluirTurmaOpen(false)}>Cancelar</Button>
          <Button
            variant="contained"
            color="error"
            onClick={handleDeleteByTurma}
            disabled={!turmaSelecionadaExclusao}
          >
            Excluir da Turma
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog open={importOpen} onClose={() => setImportOpen(false)} maxWidth="md" fullWidth>
        <DialogTitle>Importar Alunos em Lote</DialogTitle>
        <DialogContent>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
            Cole uma linha por aluno no formato:
          </Typography>
          <Typography variant="body2" sx={{ mb: 2 }}>
            Nome;CPF;Série;Turma;Matrícula
          </Typography>
          <Typography variant="caption" color="text.secondary" sx={{ mb: 1, display: 'block' }}>
            Também aceita colunas separadas por TAB (copiar/colar de planilha).
          </Typography>
          <TextField
            multiline
            minRows={12}
            fullWidth
            placeholder={'Exemplo:\nMaria da Silva;123.456.789-10;9º ANO;I-A;MAT001'}
            value={textoImportacao}
            onChange={(e) => setTextoImportacao(e.target.value)}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setImportOpen(false)}>Cancelar</Button>
          <Button variant="contained" onClick={handleImportarEmLote}>
            Importar
          </Button>
        </DialogActions>
      </Dialog>

      {/* Dialog do Termo de Empréstimo */}
      <TermoEmprestimo
        open={termoOpen}
        onClose={() => setTermoOpen(false)}
        dados={null}
        tipo={tipoTermo}
      />
    </Layout>
  );
}

export default LeitoresPage;

import React, { useState, useEffect } from 'react';
import { useData } from '../context/DataContext';
import {
  Container,
  Paper,
  Typography,
  Box,
  Button,
  Alert,
  Grid,
  Card,
  CardContent,
  Divider,
  LinearProgress,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  Chip
} from '@mui/material';
import WarningIcon from '@mui/icons-material/Warning';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import DeleteIcon from '@mui/icons-material/Delete';
import BackupIcon from '@mui/icons-material/Backup';
import RestoreIcon from '@mui/icons-material/Restore';
import SchoolIcon from '@mui/icons-material/School';

export default function LimparDuplicatasPage() {
  const { instituicoes } = useData();
  const [stats, setStats] = useState(null);
  const [backupFeito, setBackupFeito] = useState(false);
  const [limpezaConcluida, setLimpezaConcluida] = useState(false);
  const [processando, setProcessando] = useState(false);

  useEffect(() => {
    analisarDados();
  }, [instituicoes]);

  const analisarDados = () => {
    const total = instituicoes.length;
    const comPagamento = instituicoes.filter(i => i.pagamentoConfirmado === true).length;
    const pendentes = instituicoes.filter(i => i.status === 'pendente').length;
    
    // Detectar duplicatas por CNPJ
    const cnpjMap = {};
    instituicoes.forEach(inst => {
      if (!cnpjMap[inst.cnpj]) cnpjMap[inst.cnpj] = [];
      cnpjMap[inst.cnpj].push(inst);
    });
    
    let duplicatas = 0;
    Object.values(cnpjMap).forEach(insts => {
      if (insts.length > 1) duplicatas += (insts.length - 1);
    });

    setStats({
      total,
      comPagamento,
      pendentes,
      duplicatas,
      aposLimpeza: Math.max(comPagamento, 1)
    });
  };

  const fazerBackup = () => {
    setProcessando(true);
    try {
      const dadosAtuais = localStorage.getItem('cei_data');
      const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
      const backupKey = `cei_data_backup_${timestamp}`;
      
      localStorage.setItem(backupKey, dadosAtuais);
      localStorage.setItem('cei_data_ultimo_backup', backupKey);
      
      setBackupFeito(true);
      setProcessando(false);
      
      return true;
    } catch (error) {
      console.error('Erro ao fazer backup:', error);
      alert('Erro ao fazer backup! Operação cancelada.');
      setProcessando(false);
      return false;
    }
  };

  const restaurarBackup = () => {
    if (!window.confirm('Deseja restaurar o último backup?')) return;

    try {
      const ultimoBackup = localStorage.getItem('cei_data_ultimo_backup');
      if (!ultimoBackup) {
        alert('Nenhum backup encontrado!');
        return;
      }

      const dadosBackup = localStorage.getItem(ultimoBackup);
      if (!dadosBackup) {
        alert('Backup não encontrado!');
        return;
      }

      localStorage.setItem('cei_data', dadosBackup);
      alert('Backup restaurado com sucesso! Recarregando...');
      window.location.reload();
    } catch (error) {
      console.error('Erro ao restaurar backup:', error);
      alert('Erro ao restaurar backup!');
    }
  };

  const limparDuplicatas = () => {
    if (!backupFeito) {
      alert('Por favor, faça o backup primeiro!');
      return;
    }

    if (!window.confirm(`⚠️ CONFIRMAÇÃO FINAL\n\nSerão mantidas apenas ${stats.aposLimpeza} instituição(ões) válida(s).\n\n${stats.duplicatas} duplicatas serão removidas.\n\nDeseja continuar?`)) {
      return;
    }

    setProcessando(true);

    try {
      const dadosStr = localStorage.getItem('cei_data');
      const dados = JSON.parse(dadosStr);

      // Manter apenas instituições com pagamento confirmado
      let instituicoesValidas = dados.instituicoes.filter(i => i.pagamentoConfirmado === true);
      
      // Se não houver nenhuma, manter a primeira
      if (instituicoesValidas.length === 0) {
        instituicoesValidas = [dados.instituicoes[0]];
      } else {
        // Manter apenas a primeira válida (remover duplicatas)
        const cnpjSet = new Set();
        instituicoesValidas = instituicoesValidas.filter(inst => {
          if (!cnpjSet.has(inst.cnpj)) {
            cnpjSet.add(inst.cnpj);
            return true;
          }
          return false;
        });
      }

      // IDs válidos
      const idsValidos = instituicoesValidas.map(i => i.id);

      // Limpar usuários (manter SuperAdmin e usuários das instituições válidas)
      dados.usuarios = dados.usuarios.filter(u => 
        u.perfil === 'SuperAdmin' || idsValidos.includes(u.instituicaoId)
      );

      // Limpar dados relacionados às instituições removidas
      dados.livros = (dados.livros || []).filter(l => idsValidos.includes(l.instituicaoId));
      dados.clientes = (dados.clientes || []).filter(c => idsValidos.includes(c.instituicaoId));
      dados.emprestimos = (dados.emprestimos || []).filter(e => idsValidos.includes(e.instituicaoId));
      dados.patrimonio = (dados.patrimonio || []).filter(p => idsValidos.includes(p.instituicaoId));

      // Atualizar instituições
      dados.instituicoes = instituicoesValidas;

      // Salvar
      localStorage.setItem('cei_data', JSON.stringify(dados));

      setLimpezaConcluida(true);
      setProcessando(false);

      setTimeout(() => {
        if (window.confirm('Limpeza concluída com sucesso!\n\nDeseja recarregar o sistema agora?')) {
          window.location.reload();
        }
      }, 1000);

    } catch (error) {
      console.error('Erro ao limpar duplicatas:', error);
      alert('Erro ao limpar duplicatas! Use "Restaurar Backup" para recuperar os dados.');
      setProcessando(false);
    }
  };

  if (!stats) {
    return (
      <Container>
        <Box sx={{ mt: 4 }}>
          <LinearProgress />
          <Typography sx={{ mt: 2, textAlign: 'center' }}>
            Analisando dados...
          </Typography>
        </Box>
      </Container>
    );
  }

  return (
    <Container maxWidth="lg" sx={{ py: 4 }}>
      <Paper elevation={3} sx={{ p: 4 }}>
        {/* Cabeçalho */}
        <Box sx={{ mb: 3 }}>
          <Typography variant="h4" gutterBottom>
            🧹 Limpeza de Duplicatas
          </Typography>
          <Typography variant="body2" color="text.secondary">
            Ferramenta segura para remover instituições duplicadas
          </Typography>
        </Box>

        {/* Estatísticas */}
        <Grid container spacing={3} sx={{ mb: 3 }}>
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ bgcolor: 'error.light' }}>
              <CardContent>
                <Typography variant="h4" color="white">
                  {stats.total}
                </Typography>
                <Typography variant="body2" color="white">
                  Total de Instituições
                </Typography>
              </CardContent>
            </Card>
          </Grid>
          
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ bgcolor: 'warning.main' }}>
              <CardContent>
                <Typography variant="h4" color="white">
                  {stats.duplicatas}
                </Typography>
                <Typography variant="body2" color="white">
                  Duplicatas Detectadas
                </Typography>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ bgcolor: 'info.main' }}>
              <CardContent>
                <Typography variant="h4" color="white">
                  {stats.comPagamento}
                </Typography>
                <Typography variant="body2" color="white">
                  Com Pagamento Confirmado
                </Typography>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ bgcolor: 'success.main' }}>
              <CardContent>
                <Typography variant="h4" color="white">
                  {stats.aposLimpeza}
                </Typography>
                <Typography variant="body2" color="white">
                  Após Limpeza
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        </Grid>

        <Divider sx={{ my: 3 }} />

        {/* Alertas */}
        {!limpezaConcluida && stats.total > 10 && (
          <Alert severity="warning" sx={{ mb: 3 }} icon={<WarningIcon />}>
            <Typography variant="body1" gutterBottom>
              <strong>Atenção: Quantidade anormal de instituições detectada!</strong>
            </Typography>
            <Typography variant="body2">
              Foram encontradas <strong>{stats.total}</strong> instituições cadastradas, sendo <strong>{stats.duplicatas}</strong> duplicatas.
              Esta ferramenta irá manter apenas as instituições com pagamento confirmado.
            </Typography>
          </Alert>
        )}

        {limpezaConcluida && (
          <Alert severity="success" sx={{ mb: 3 }} icon={<CheckCircleIcon />}>
            <Typography variant="body1">
              <strong>✅ Limpeza concluída com sucesso!</strong>
            </Typography>
            <Typography variant="body2">
              As duplicatas foram removidas. Recarregue a página para ver as alterações.
            </Typography>
          </Alert>
        )}

        {/* Instituições Válidas */}
        <Card variant="outlined" sx={{ mb: 3 }}>
          <CardContent>
            <Typography variant="h6" gutterBottom color="primary">
              <SchoolIcon sx={{ verticalAlign: 'middle', mr: 1 }} />
              Instituições que serão mantidas
            </Typography>
            <Divider sx={{ my: 2 }} />
            <List>
              {instituicoes
                .filter(i => i.pagamentoConfirmado === true)
                .slice(0, 5)
                .map((inst, index) => (
                  <ListItem key={index}>
                    <ListItemIcon>
                      <CheckCircleIcon color="success" />
                    </ListItemIcon>
                    <ListItemText
                      primary={inst.nomeInstituicao}
                      secondary={`CNPJ: ${inst.cnpj} | Email: ${inst.email}`}
                    />
                    <Chip label="Pago" color="success" size="small" />
                  </ListItem>
                ))}
              {stats.comPagamento === 0 && (
                <ListItem>
                  <ListItemIcon>
                    <CheckCircleIcon color="info" />
                  </ListItemIcon>
                  <ListItemText
                    primary={instituicoes[0]?.nomeInstituicao || 'Primeira instituição'}
                    secondary="Será mantida por padrão (nenhuma com pagamento confirmado)"
                  />
                  <Chip label="Padrão" color="info" size="small" />
                </ListItem>
              )}
            </List>
          </CardContent>
        </Card>

        {/* Botões de Ação */}
        {processando && <LinearProgress sx={{ mb: 2 }} />}

        <Grid container spacing={2}>
          <Grid item xs={12} sm={6}>
            <Button
              fullWidth
              variant="contained"
              color="primary"
              size="large"
              startIcon={<BackupIcon />}
              onClick={fazerBackup}
              disabled={backupFeito || processando || limpezaConcluida}
            >
              {backupFeito ? '✓ Backup Realizado' : '1. Fazer Backup'}
            </Button>
          </Grid>

          <Grid item xs={12} sm={6}>
            <Button
              fullWidth
              variant="contained"
              color="error"
              size="large"
              startIcon={<DeleteIcon />}
              onClick={limparDuplicatas}
              disabled={!backupFeito || processando || limpezaConcluida}
            >
              2. Limpar Duplicatas
            </Button>
          </Grid>

          <Grid item xs={12}>
            <Button
              fullWidth
              variant="outlined"
              color="secondary"
              size="large"
              startIcon={<RestoreIcon />}
              onClick={restaurarBackup}
              disabled={processando || !backupFeito}
            >
              Restaurar Último Backup
            </Button>
          </Grid>
        </Grid>

        {/* Instruções */}
        <Box sx={{ mt: 3 }}>
          <Alert severity="info">
            <Typography variant="body2" gutterBottom>
              <strong>📋 Como usar:</strong>
            </Typography>
            <Typography variant="body2" component="div">
              1️⃣ Clique em <strong>"Fazer Backup"</strong> para salvar seus dados atuais<br />
              2️⃣ Clique em <strong>"Limpar Duplicatas"</strong> para remover as duplicatas<br />
              3️⃣ Se algo der errado, use <strong>"Restaurar Backup"</strong> para voltar ao estado anterior<br />
              <br />
              <strong>✅ Totalmente seguro!</strong> Seu backup fica salvo no navegador.
            </Typography>
          </Alert>
        </Box>
      </Paper>
    </Container>
  );
}

import React, { useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import Layout from '../components/Layout';
import BarcodeScannerDialog from '../components/BarcodeScannerDialog';
import MobileBarcodeScanner from '../components/MobileBarcodeScanner';
import TermoDoacao from '../components/TermoDoacao';
import CameraCapture from '../components/CameraCapture';
import {
  Box,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  Chip,
  Typography,
  Avatar,
  Card,
  CardMedia,
  Tooltip,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Alert,
  Radio,
  RadioGroup,
  FormControlLabel,
  FormLabel
} from '@mui/material';
import { Add, Edit, Delete, Search, PhotoCamera, Upload, Close, QrCodeScanner, GetApp, Description, PrintOutlined, Label, WarningAmber, LibraryAdd, AddCircleOutline } from '@mui/icons-material';
import { useData } from '../context/DataContext';
import TermoEmprestimo from '../components/TermoEmprestimo';

function LivrosPage() {
  const navigate = useNavigate();
  const { livros, emprestimos, adicionarLivro, atualizarLivro, removerLivro, darBaixaLivro, usuarioLogado } = useData();
  const [open, setOpen] = useState(false);
  const [editando, setEditando] = useState(null);
  const [busca, setBusca] = useState('');
  const [scannerOpen, setScannerOpen] = useState(false);
  const [mobileScannerOpen, setMobileScannerOpen] = useState(false);
  const [baixaOpen, setBaixaOpen] = useState(false);
  const [livroParaBaixa, setLivroParaBaixa] = useState(null);
  const [termoOpen, setTermoOpen] = useState(false);
  const [dadosTermo, setDadosTermo] = useState(null);
  const [cameraOpen, setCameraOpen] = useState(false);
  const [duplicataDialog, setDuplicataDialog] = useState({ open: false, livroExistente: null });
  const fileInputRef = useRef(null);
  
  // Estados para termo de empréstimo
  const [termoEmprestimoOpen, setTermoEmprestimoOpen] = useState(false);
  const [tipoTermoEmprestimo, setTipoTermoEmprestimo] = useState('branco');
  
  const [dadosBaixa, setDadosBaixa] = useState({
    motivo: 'Doação',
    donatarioNome: '',
    donatarioCpf: '',
    donatarioEndereco: '',
    donatarioTelefone: '',
    observacoes: ''
  });
  
  // Categorias predefinidas para livros
  const categoriasLivros = [
    'Ficção',
    'Não-ficção',
    'Romance',
    'Aventura',
    'Fantasia',
    'Suspense',
    'Terror',
    'Biografia',
    'História',
    'Ciência',
    'Tecnologia',
    'Autoajuda',
    'Infantil',
    'Juvenil',
    'Didático',
    'Paradidático',
    'Livro do Professor',
    'Poesia',
    'Drama',
    'Comédia',
    'Filosofia',
    'Religião',
    'Artes',
    'Culinária',
    'Outros'
  ];
  
  const [formData, setFormData] = useState({
    titulo: '',
    autor: '',
    isbn: '',
    editora: '',
    anoPublicacao: '',
    edicao: '',
    cidadeEdicao: '',
    categoria: '',
    quantidade: 1,
    localizacao: '',
    fotoUrl: '',
    tipo: 'Paradidático', // Didático, Paradidático ou Livro do Professor
    anoVigencia: '' // Apenas para livros didáticos
  });

  const handleOpen = (livro = null) => {
    if (livro) {
      setEditando(livro.id);
      setFormData(livro);
    } else {
      setEditando(null);
      setFormData({
        titulo: '',
        autor: '',
        isbn: '',
        editora: '',
        anoPublicacao: '',
        edicao: '',
        cidadeEdicao: '',
        categoria: '',
        quantidade: 1,
        localizacao: '',
        fotoUrl: '',
        tipo: 'Paradidático',
        anoVigencia: ''
      });
    }
    setOpen(true);
  };

  const handleBookFound = (dadosLivro) => {
    console.log('📖 Preenchendo formulário com dados do livro:', dadosLivro);
    
    setFormData({
      ...formData,
      titulo: dadosLivro.titulo || formData.titulo,
      autor: dadosLivro.autor || formData.autor,
      isbn: dadosLivro.isbn || formData.isbn,
      editora: dadosLivro.editora || formData.editora,
      anoPublicacao: dadosLivro.anoPublicacao || formData.anoPublicacao,
      edicao: dadosLivro.edicao || formData.edicao || '1',
      cidadeEdicao: dadosLivro.cidadeEdicao || formData.cidadeEdicao,
      categoria: dadosLivro.categoria || formData.categoria,
      idioma: dadosLivro.idioma || formData.idioma || 'Português',
      numeroPaginas: dadosLivro.numeroPaginas || formData.numeroPaginas,
      descricao: dadosLivro.descricao || formData.descricao,
      fotoUrl: dadosLivro.imagemUrl || dadosLivro.fotoUrl || dadosLivro.foto || formData.fotoUrl
    });
    
    console.log('✅ Formulário preenchido!');
    setOpen(true);
  };

  const handleFileUpload = (event) => {
    const file = event.target.files[0];
    if (file) {
      // Verificar se é imagem
      if (!file.type.startsWith('image/')) {
        alert('Por favor, selecione apenas arquivos de imagem');
        return;
      }
      
      // Verificar tamanho (máximo 2MB)
      if (file.size > 2 * 1024 * 1024) {
        alert('A imagem deve ter no máximo 2MB');
        return;
      }
      
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({ ...formData, fotoUrl: reader.result });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleCameraCapture = (imageData) => {
    setFormData({ ...formData, fotoUrl: imageData });
    setCameraOpen(false);
  };

  const handleRemoverFoto = () => {
    setFormData({ ...formData, fotoUrl: '' });
  };

  const handleClose = () => {
    setOpen(false);
    setEditando(null);
  };

  const handleSubmit = () => {
    if (!editando) {
      const livroExistente = livros.find(l =>
        !l.baixa && (
          (formData.isbn && formData.isbn.trim() && l.isbn === formData.isbn.trim()) ||
          (l.titulo.toLowerCase().trim() === formData.titulo.toLowerCase().trim() &&
           l.autor.toLowerCase().trim() === formData.autor.toLowerCase().trim())
        )
      );

      if (livroExistente) {
        setDuplicataDialog({ open: true, livroExistente });
        return;
      }

      // Gerar código automático se for novo livro
      const numeroSequencial = (livros.length + 1).toString().padStart(6, '0');
      formData.codigoIdentificacao = `LIV${numeroSequencial}`;
    }

    if (editando) {
      atualizarLivro(editando, formData);
    } else {
      adicionarLivro(formData);
    }
    handleClose();
  };

  const handleDuplicataAdicionarExemplar = () => {
    const { livroExistente } = duplicataDialog;
    const novaQuantidade = parseInt(livroExistente.quantidade || 1) + parseInt(formData.quantidade || 1);
    atualizarLivro(livroExistente.id, { ...livroExistente, quantidade: novaQuantidade });
    setDuplicataDialog({ open: false, livroExistente: null });
    handleClose();
  };

  const handleDuplicataNovoCadastro = () => {
    const numeroSequencial = (livros.length + 1).toString().padStart(6, '0');
    formData.codigoIdentificacao = `LIV${numeroSequencial}`;
    adicionarLivro(formData);
    setDuplicataDialog({ open: false, livroExistente: null });
    handleClose();
  };

  const handleDelete = (id) => {
    if (window.confirm('Deseja realmente remover este livro?')) {
      removerLivro(id);
    }
  };

  const handleAbrirBaixa = (livro) => {
    setLivroParaBaixa(livro);
    setDadosBaixa({
      motivo: 'Doação',
      donatarioNome: '',
      donatarioCpf: '',
      donatarioEndereco: '',
      donatarioTelefone: '',
      observacoes: ''
    });
    setBaixaOpen(true);
  };

  const handleConfirmarBaixa = () => {
    if (dadosBaixa.motivo === 'Doação' && (!dadosBaixa.donatarioNome || !dadosBaixa.donatarioCpf)) {
      alert('Por favor, preencha os dados do donatário');
      return;
    }

    const detalhes = {
      donatario: dadosBaixa.donatarioNome,
      cpfDonatario: dadosBaixa.donatarioCpf,
      enderecoDonatario: dadosBaixa.donatarioEndereco,
      telefoneDonatario: dadosBaixa.donatarioTelefone,
      observacoes: dadosBaixa.observacoes
    };

    const livroComBaixa = darBaixaLivro(livroParaBaixa.id, dadosBaixa.motivo, detalhes);

    if (dadosBaixa.motivo === 'Doação' && livroComBaixa) {
      // Preparar dados para o termo
      setDadosTermo({
        livro: livroComBaixa,
        doador: {
          nome: usuarioLogado?.nome || 'Instituição de Ensino',
          cpf: usuarioLogado?.cpf || '',
          endereco: usuarioLogado?.endereco || '',
          telefone: usuarioLogado?.telefone || '',
          cidade: usuarioLogado?.cidade || ''
        },
        donatario: {
          nome: dadosBaixa.donatarioNome,
          cpf: dadosBaixa.donatarioCpf,
          endereco: dadosBaixa.donatarioEndereco,
          telefone: dadosBaixa.donatarioTelefone
        }
      });
      setTermoOpen(true);
    }

    setBaixaOpen(false);
    setLivroParaBaixa(null);
  };

  const livrosFiltrados = livros.filter(livro =>
    livro.titulo.toLowerCase().includes(busca.toLowerCase()) ||
    livro.autor.toLowerCase().includes(busca.toLowerCase()) ||
    livro.isbn.includes(busca)
  );

  const isEmprestimoAtivo = (status) => {
    const statusNormalizado = String(status || '').toLowerCase();
    return statusNormalizado === 'ativo' || statusNormalizado === 'emprestado';
  };

  const calcularLivrosDisponiveis = (livro) => {
    if (livro.baixa) return 0;

    const quantidadeTotal = Number(livro.quantidade) || 0;
    const livroIdNormalizado = String(livro.id);

    const emprestimosAtivos = emprestimos.filter((emp) =>
      String(emp.livroId) === livroIdNormalizado && isEmprestimoAtivo(emp.status)
    ).length;

    return Math.max(quantidadeTotal - emprestimosAtivos, 0);
  };

  return (
    <Layout title="Livros">
      <Box sx={{ mb: 2, display: 'flex', gap: 2, flexWrap: 'wrap' }}>
        <TextField
          placeholder="Buscar por título, autor ou ISBN..."
          variant="outlined"
          size="small"
          fullWidth
          value={busca}
          onChange={(e) => setBusca(e.target.value)}
          InputProps={{
            startAdornment: <Search sx={{ mr: 1, color: 'text.secondary' }} />
          }}
          sx={{ flexGrow: 1, minWidth: '200px' }}
        />
        <Button
          variant="outlined"
          startIcon={<Label />}
          onClick={() => navigate('/etiquetas')}
          size="small"
          color="secondary"
          sx={{ display: { xs: 'none', sm: 'flex' } }}
        >
          Etiquetas
        </Button>
        <Button
          variant="outlined"
          startIcon={<Description />}
          onClick={() => {
            setTipoTermoEmprestimo('branco');
            setTermoEmprestimoOpen(true);
          }}
          size="small"
          color="secondary"
          sx={{ display: { xs: 'none', sm: 'flex' } }}
        >
          Termo
        </Button>
        <Button
          variant="outlined"
          startIcon={<QrCodeScanner />}
          onClick={() => {
            // Detectar se é mobile
            const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent) || window.innerWidth < 768;
            if (isMobile) {
              setMobileScannerOpen(true);
            } else {
              setScannerOpen(true);
            }
          }}
          sx={{ minWidth: '120px', display: { xs: 'none', sm: 'flex' } }}
          size="small"
        >
          ISBN
        </Button>
        <Button
          variant="outlined"
          startIcon={<QrCodeScanner />}
          onClick={() => setMobileScannerOpen(true)}
          sx={{ display: { xs: 'flex', sm: 'none' } }}
          size="small"
        >
          Escanear
        </Button>
        <Button
          variant="contained"
          startIcon={<Add />}
          onClick={() => handleOpen()}
        >
          Novo Livro
        </Button>
      </Box>

      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Código</TableCell>
              <TableCell>Foto</TableCell>
              <TableCell>Título</TableCell>
              <TableCell>Autor</TableCell>
              <TableCell>ISBN</TableCell>
              <TableCell>Tipo</TableCell>
              <TableCell>Categoria</TableCell>
              <TableCell>Quantidade</TableCell>
              <TableCell>Livros Disponíveis</TableCell>
              <TableCell>Status</TableCell>
              <TableCell>Ações</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {livrosFiltrados.length === 0 ? (
              <TableRow>
                <TableCell colSpan={11} align="center">
                  <Typography color="text.secondary">
                    Nenhum livro cadastrado
                  </Typography>
                </TableCell>
              </TableRow>
            ) : (
              livrosFiltrados.map((livro) => (
                <TableRow key={livro.id} sx={{ bgcolor: livro.baixa ? '#f5f5f5' : 'inherit' }}>
                  <TableCell>
                    <Chip 
                      label={livro.codigoIdentificacao || 'N/A'} 
                      size="small" 
                      color="primary"
                      variant="outlined"
                    />
                  </TableCell>
                  <TableCell>
                    <Avatar
                      src={livro.fotoUrl}
                      alt={livro.titulo}
                      variant="rounded"
                      sx={{ width: 56, height: 56 }}
                      imgProps={{ style: { objectFit: 'contain' } }}
                    >
                      {!livro.fotoUrl && livro.titulo.charAt(0)}
                    </Avatar>
                  </TableCell>
                  <TableCell>{livro.titulo}</TableCell>
                  <TableCell>{livro.autor}</TableCell>
                  <TableCell>{livro.isbn}</TableCell>
                  <TableCell>
                    <Chip 
                      label={livro.tipo || 'Paradidático'} 
                      size="small" 
                      color={livro.tipo === 'Didático' ? 'primary' : livro.tipo === 'Livro do Professor' ? 'secondary' : 'default'}
                    />
                  </TableCell>
                  <TableCell>
                    <Chip label={livro.categoria} size="small" />
                  </TableCell>
                  <TableCell>{livro.quantidade}</TableCell>
                  <TableCell>{calcularLivrosDisponiveis(livro)}</TableCell>
                  <TableCell>
                    {livro.baixa ? (
                      <Chip 
                        label={`Baixa: ${livro.baixa.motivo}`}
                        size="small"
                        color="warning"
                      />
                    ) : (
                      <Chip label="Ativo" size="small" color="success" />
                    )}
                  </TableCell>
                  <TableCell>
                    {!livro.baixa && (
                      <>
                        <IconButton onClick={() => handleOpen(livro)} size="small">
                          <Edit />
                        </IconButton>
                        <Tooltip title="Dar Baixa">
                          <IconButton onClick={() => handleAbrirBaixa(livro)} size="small" color="warning">
                            <GetApp />
                          </IconButton>
                        </Tooltip>
                      </>
                    )}
                    <IconButton onClick={() => handleDelete(livro.id)} size="small" color="error">
                      <Delete />
                    </IconButton>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </TableContainer>

      <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
        <DialogTitle>{editando ? 'Editar Livro' : 'Novo Livro'}</DialogTitle>
        <DialogContent>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 1 }}>
            <TextField
              label="Título"
              fullWidth
              required
              value={formData.titulo}
              onChange={(e) => setFormData({ ...formData, titulo: e.target.value })}
            />
            <TextField
              label="Autor"
              fullWidth
              required
              value={formData.autor}
              onChange={(e) => setFormData({ ...formData, autor: e.target.value })}
            />
            <TextField
              label="ISBN"
              fullWidth
              value={formData.isbn}
              onChange={(e) => setFormData({ ...formData, isbn: e.target.value })}
            />
            <TextField
              label="Editora"
              fullWidth
              value={formData.editora}
              onChange={(e) => setFormData({ ...formData, editora: e.target.value })}
            />
            <TextField
              label="Ano de Publicação"
              fullWidth
              type="number"
              value={formData.anoPublicacao}
              onChange={(e) => setFormData({ ...formData, anoPublicacao: e.target.value })}
            />
            <TextField
              label="Edição"
              fullWidth
              placeholder="Ex: 1ª edição, 2ª edição, etc."
              value={formData.edicao}
              onChange={(e) => setFormData({ ...formData, edicao: e.target.value })}
            />
            <TextField
              label="Cidade de Edição"
              fullWidth
              placeholder="Ex: São Paulo, Rio de Janeiro, etc."
              value={formData.cidadeEdicao}
              onChange={(e) => setFormData({ ...formData, cidadeEdicao: e.target.value })}
            />
            <FormControl fullWidth>
              <InputLabel>Categoria</InputLabel>
              <Select
                value={formData.categoria}
                label="Categoria"
                onChange={(e) => setFormData({ ...formData, categoria: e.target.value })}
              >
                <MenuItem value="">
                  <em>Selecione uma categoria</em>
                </MenuItem>
                {categoriasLivros.map((cat) => (
                  <MenuItem key={cat} value={cat}>
                    {cat}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
            <FormControl fullWidth>
              <InputLabel>Tipo de Livro *</InputLabel>
              <Select
                value={formData.tipo}
                label="Tipo de Livro *"
                onChange={(e) => setFormData({
                  ...formData,
                  tipo: e.target.value,
                  anoVigencia: e.target.value === 'Didático' ? formData.anoVigencia : ''
                })}
              >
                <MenuItem value="Didático">Didático</MenuItem>
                <MenuItem value="Paradidático">Paradidático</MenuItem>
                <MenuItem value="Livro do Professor">Livro do Professor</MenuItem>
              </Select>
            </FormControl>
            {formData.tipo === 'Didático' && (
              <TextField
                label="Ano de Vigência"
                fullWidth
                type="number"
                placeholder="Ex: 2026"
                helperText="Ano até quando o livro será utilizado"
                value={formData.anoVigencia}
                onChange={(e) => setFormData({ ...formData, anoVigencia: e.target.value })}
              />
            )}
            <TextField
              label="Quantidade"
              fullWidth
              type="number"
              required
              value={formData.quantidade}
              onChange={(e) => setFormData({ ...formData, quantidade: parseInt(e.target.value) })}
            />
            <TextField
              label="Localização"
              fullWidth
              value={formData.localizacao}
              onChange={(e) => setFormData({ ...formData, localizacao: e.target.value })}
            />
            
            {/* Seção de Foto */}
            <Box sx={{ mt: 2 }}>
              <Typography variant="subtitle2" gutterBottom>
                Foto do Livro
              </Typography>
              
              {formData.fotoUrl ? (
                <Card sx={{ maxWidth: 300, position: 'relative', mx: 'auto' }}>
                  <CardMedia
                    component="img"
                    height="200"
                    image={formData.fotoUrl}
                    alt="Foto do livro"
                    sx={{ objectFit: 'contain' }}
                  />
                  <IconButton
                    sx={{ position: 'absolute', top: 8, right: 8, bgcolor: 'background.paper' }}
                    size="small"
                    onClick={handleRemoverFoto}
                  >
                    <Close />
                  </IconButton>
                </Card>
              ) : (
                <Box sx={{ display: 'flex', gap: 1, justifyContent: 'center' }}>
                  <input
                    type="file"
                    ref={fileInputRef}
                    accept="image/*"
                    style={{ display: 'none' }}
                    onChange={handleFileUpload}
                  />
                  <Button
                    variant="outlined"
                    startIcon={<Upload />}
                    onClick={() => fileInputRef.current?.click()}
                  >
                    Upload
                  </Button>
                  
                  <Button
                    variant="outlined"
                    startIcon={<PhotoCamera />}
                    onClick={() => setCameraOpen(true)}
                  >
                    Câmera
                  </Button>
                </Box>
              )}
              <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1, textAlign: 'center' }}>
                Formatos aceitos: JPG, PNG. Tamanho máximo: 2MB
              </Typography>
            </Box>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClose}>Cancelar</Button>
          <Button 
            onClick={handleSubmit} 
            variant="contained"
            disabled={!formData.titulo || !formData.autor}
          >
            {editando ? 'Salvar' : 'Adicionar'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Dialog de Livro Duplicado */}
      <Dialog
        open={duplicataDialog.open}
        onClose={() => setDuplicataDialog({ open: false, livroExistente: null })}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <WarningAmber color="warning" />
          Livro Já Cadastrado
        </DialogTitle>
        <DialogContent>
          <Alert severity="warning" sx={{ mb: 2 }}>
            <strong>"{ formData.titulo }"</strong> já existe no acervo.
            {duplicataDialog.livroExistente?.isbn && (
              <> ISBN: <strong>{duplicataDialog.livroExistente.isbn}</strong></>  
            )}
          </Alert>
          <Box sx={{ bgcolor: 'grey.50', borderRadius: 1, p: 2, mb: 2 }}>
            <Typography variant="body2" color="text.secondary" gutterBottom>Cadastro existente:</Typography>
            <Typography variant="body1" fontWeight={700}>{duplicataDialog.livroExistente?.titulo}</Typography>
            <Typography variant="body2">{duplicataDialog.livroExistente?.autor}</Typography>
            <Typography variant="body2">Código: <strong>{duplicataDialog.livroExistente?.codigoIdentificacao}</strong></Typography>
            <Typography variant="body2">Exemplares atuais: <strong>{duplicataDialog.livroExistente?.quantidade}</strong></Typography>
          </Box>
          <Typography variant="body2" color="text.secondary">
            O que deseja fazer com <strong>{formData.quantidade} novo(s) exemplar(es)</strong>?
          </Typography>
        </DialogContent>
        <DialogActions sx={{ flexDirection: 'column', gap: 1, px: 3, pb: 3, alignItems: 'stretch' }}>
          <Button
            variant="contained"
            color="primary"
            startIcon={<AddCircleOutline />}
            onClick={handleDuplicataAdicionarExemplar}
            fullWidth
          >
            Adicionar ao cadastro existente
            <Typography variant="caption" component="span" sx={{ ml: 1, opacity: 0.85 }}>
              (total: {parseInt(duplicataDialog.livroExistente?.quantidade || 1) + parseInt(formData.quantidade || 1)} exemplares)
            </Typography>
          </Button>
          <Button
            variant="outlined"
            color="secondary"
            startIcon={<LibraryAdd />}
            onClick={handleDuplicataNovoCadastro}
            fullWidth
          >
            Cadastrar como novo título separado
            <Typography variant="caption" component="span" sx={{ ml: 1, opacity: 0.75 }}>
              (novo código + etiqueta)
            </Typography>
          </Button>
          <Button
            variant="text"
            color="inherit"
            onClick={() => setDuplicataDialog({ open: false, livroExistente: null })}
            fullWidth
          >
            Cancelar
          </Button>
        </DialogActions>
      </Dialog>

      <BarcodeScannerDialog
        open={scannerOpen}
        onClose={() => setScannerOpen(false)}
        onBookFound={handleBookFound}
      />

      {/* Scanner Mobile Otimizado */}
      <MobileBarcodeScanner
        open={mobileScannerOpen}
        onClose={() => setMobileScannerOpen(false)}
        onBookFound={handleBookFound}
      />

      {/* Modal de Baixa */}
      <Dialog open={baixaOpen} onClose={() => setBaixaOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Dar Baixa no Livro</DialogTitle>
        <DialogContent>
          <Alert severity="info" sx={{ mb: 2 }}>
            <strong>Livro:</strong> {livroParaBaixa?.titulo}<br />
            <strong>Autor:</strong> {livroParaBaixa?.autor}
          </Alert>

          <FormControl component="fieldset" sx={{ mb: 3 }}>
            <FormLabel component="legend">Motivo da Baixa</FormLabel>
            <RadioGroup
              value={dadosBaixa.motivo}
              onChange={(e) => setDadosBaixa({ ...dadosBaixa, motivo: e.target.value })}
            >
              <FormControlLabel value="Doação" control={<Radio />} label="Doação" />
              <FormControlLabel value="Término de Vigência" control={<Radio />} label="Término de Vigência" />
            </RadioGroup>
          </FormControl>

          {dadosBaixa.motivo === 'Doação' && (
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
              <Typography variant="subtitle2" color="primary">Dados do Donatário</Typography>
              <TextField
                label="Nome Completo *"
                fullWidth
                value={dadosBaixa.donatarioNome}
                onChange={(e) => setDadosBaixa({ ...dadosBaixa, donatarioNome: e.target.value })}
              />
              <TextField
                label="CPF/CNPJ *"
                fullWidth
                value={dadosBaixa.donatarioCpf}
                onChange={(e) => setDadosBaixa({ ...dadosBaixa, donatarioCpf: e.target.value })}
              />
              <TextField
                label="Endereço"
                fullWidth
                value={dadosBaixa.donatarioEndereco}
                onChange={(e) => setDadosBaixa({ ...dadosBaixa, donatarioEndereco: e.target.value })}
              />
              <TextField
                label="Telefone"
                fullWidth
                value={dadosBaixa.donatarioTelefone}
                onChange={(e) => setDadosBaixa({ ...dadosBaixa, donatarioTelefone: e.target.value })}
              />
            </Box>
          )}

          <TextField
            label="Observações"
            fullWidth
            multiline
            rows={3}
            sx={{ mt: 2 }}
            value={dadosBaixa.observacoes}
            onChange={(e) => setDadosBaixa({ ...dadosBaixa, observacoes: e.target.value })}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setBaixaOpen(false)}>Cancelar</Button>
          <Button onClick={handleConfirmarBaixa} variant="contained" color="warning">
            Confirmar Baixa
          </Button>
        </DialogActions>
      </Dialog>

      {/* Termo de Doação */}
      {dadosTermo && (
        <TermoDoacao 
          open={termoOpen}
          onClose={() => {
            setTermoOpen(false);
            setDadosTermo(null);
          }}
          livro={dadosTermo.livro}
          doador={dadosTermo.doador}
          donatario={dadosTermo.donatario}
        />
      )}

      {/* Dialog de Captura de Câmera */}
      <CameraCapture
        open={cameraOpen}
        onClose={() => setCameraOpen(false)}
        onCapture={handleCameraCapture}
        title="Tirar Foto do Livro"
      />

      {/* Dialog do Termo de Empréstimo */}
      <TermoEmprestimo
        open={termoEmprestimoOpen}
        onClose={() => setTermoEmprestimoOpen(false)}
        dados={null}
        tipo={tipoTermoEmprestimo}
      />
    </Layout>
  );
}

