const CREDENCIAIS_DEMO = {
  login: 'demo',
  senha: '[VALOR_CONFIDENCIAL_REMOVIDO]'
};

const DEMO_DEVICE_ID_KEY = 'cei_demo_device_id';
const DEMO_CONTACT_KEY = 'cei_demo_contact';

const formatarIdentificadorDemo = (deviceId) => {
  if (!deviceId) return 'Será gerado ao clicar em Usar demo';

  const partes = deviceId.split('-');
  const base = (partes[partes.length - 1] || deviceId).slice(0, 6).toUpperCase();
  return `DEMO-${base}`;
};

export default function LoginPage() {
  const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:3001';
  const identificadorDemo = formatarIdentificadorDemo(localStorage.getItem(DEMO_DEVICE_ID_KEY));
  const [login, setLogin] = useState('');
  const [senha, setSenha] = useState('');
  const [erro, setErro] = useState('');
  const [mostrarSenha, setMostrarSenha] = useState(false);
  const [dialogRecuperacao, setDialogRecuperacao] = useState(false);
  const [emailRecuperacao, setEmailRecuperacao] = useState('');
  const [novaSenha, setNovaSenha] = useState('');
  const [confirmarNovaSenha, setConfirmarNovaSenha] = useState('');
  const [erroRecuperacao, setErroRecuperacao] = useState('');
  const [sucessoRecuperacao, setSucessoRecuperacao] = useState('');
  const [mostrarNovaSenha, setMostrarNovaSenha] = useState(false);
  const [etapaRecuperacao, setEtapaRecuperacao] = useState(1); // 1: email, 2: nova senha
  const [dialogTourVideo, setDialogTourVideo] = useState(false);
  const [videoSelecionado, setVideoSelecionado] = useState(DEMO_VIDEOS[0]);
  const [dialogCadastroDemo, setDialogCadastroDemo] = useState(false);
  const [erroCadastroDemo, setErroCadastroDemo] = useState('');
  const [cadastroDemo, setCadastroDemo] = useState({
    nomeResponsavel: '',
    telefoneCelular: '',
    email: '',
    cidade: '',
    estado: ''
  });
  const { login: fazerLogin, recuperarSenha, usuarioLogado } = useData();
  const navigate = useNavigate();
  const location = useLocation();

  // Se usuário já está logado, redirecionar
  useEffect(() => {
    if (usuarioLogado) {
      const from = location.state?.from?.pathname || '/';
      console.log('👤 Usuário já logado, redirecionando para:', from);
      navigate(from, { replace: true });
    }
  }, [usuarioLogado, navigate, location]);

  useEffect(() => {
    if (!dialogTourVideo) return;

    const intervalo = setInterval(() => {
      setVideoSelecionado((atual) => {
        const idxAtual = DEMO_VIDEOS.findIndex((item) => item.id === atual.id);
        const proximoIndice = idxAtual >= DEMO_VIDEOS.length - 1 ? 0 : idxAtual + 1;
        return DEMO_VIDEOS[proximoIndice];
      });
    }, 7000);

    return () => clearInterval(intervalo);
  }, [dialogTourVideo]);

  useEffect(() => {
    try {
      const contatoSalvo = localStorage.getItem(DEMO_CONTACT_KEY);
      if (!contatoSalvo) return;

      const dados = JSON.parse(contatoSalvo);
      setCadastroDemo((prev) => ({
        ...prev,
        nomeResponsavel: String(dados?.nomeResponsavel || ''),
        telefoneCelular: String(dados?.telefoneCelular || ''),
        email: String(dados?.email || ''),
        cidade: String(dados?.cidade || ''),
        estado: String(dados?.estado || '').toUpperCase().slice(0, 2)
      }));
    } catch (error) {
      console.warn('Não foi possível carregar cadastro demo salvo:', error);
    }
  }, []);

  const aplicarMascaraTelefone = (valor) => {
    const numeros = String(valor || '').replace(/\D/g, '').slice(0, 11);
    if (numeros.length <= 10) {
      return numeros
        .replace(/^(\d{2})(\d)/, '($1) $2')
        .replace(/(\d{4})(\d)/, '$1-$2');
    }
    return numeros
      .replace(/^(\d{2})(\d)/, '($1) $2')
      .replace(/(\d{5})(\d)/, '$1-$2');
  };

  const validarEmail = (email) => {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return re.test(String(email || '').trim());
  };

  const validarCadastroDemoObrigatorio = (dados) => {
    const nomeResponsavel = String(dados?.nomeResponsavel || '').trim();
    const telefoneCelular = String(dados?.telefoneCelular || '').trim();
    const email = String(dados?.email || '').trim();
    const cidade = String(dados?.cidade || '').trim();
    const estado = String(dados?.estado || '').trim().toUpperCase();

    if (!nomeResponsavel) return { ok: false, mensagem: 'Informe o nome do responsável pelo cadastro.' };
    if (!telefoneCelular) return { ok: false, mensagem: 'Informe o telefone celular para contato.' };

    const telefoneNumeros = telefoneCelular.replace(/\D/g, '');
    if (telefoneNumeros.length < 10) {
      return { ok: false, mensagem: 'Telefone celular inválido. Use DDD + número.' };
    }

    if (!email) return { ok: false, mensagem: 'Informe o e-mail para contato.' };
    if (!validarEmail(email)) return { ok: false, mensagem: 'E-mail inválido.' };
    if (!cidade) return { ok: false, mensagem: 'Informe a cidade.' };
    if (!estado) return { ok: false, mensagem: 'Informe o estado (UF).' };
    if (estado.length < 2) return { ok: false, mensagem: 'Estado inválido. Use a UF com 2 letras.' };

    return { ok: true };
  };

  const normalizarCadastroDemo = (dados) => {
    return {
      nomeResponsavel: String(dados?.nomeResponsavel || '').trim(),
      telefoneCelular: aplicarMascaraTelefone(dados?.telefoneCelular || dados?.telefone || ''),
      email: String(dados?.email || '').trim().toLowerCase(),
      cidade: String(dados?.cidade || '').trim(),
      estado: String(dados?.estado || '').trim().toUpperCase().slice(0, 2)
    };
  };

  const obterDemoDeviceId = () => {
    const existente = localStorage.getItem(DEMO_DEVICE_ID_KEY);
    if (existente) return existente;

    const novo = `demo-${Date.now()}-${Math.random().toString(36).slice(2, 12)}`;
    localStorage.setItem(DEMO_DEVICE_ID_KEY, novo);
    return novo;
  };

  const registrarLeadDemoNoBackend = (dadosCadastroDemo, origemEvento = 'login_demo') => {
    const dadosNormalizados = normalizarCadastroDemo(dadosCadastroDemo);
    const validacao = validarCadastroDemoObrigatorio(dadosNormalizados);
    if (!validacao.ok) {
      return;
    }

    const dedupeKey = `cei_demo_lead_last_sent:${dadosNormalizados.email}`;
    const ultimoEnvio = Number(localStorage.getItem(dedupeKey) || 0);
    if (Number.isFinite(ultimoEnvio) && (Date.now() - ultimoEnvio) < (15 * 60 * 1000)) {
      return;
    }

    const payload = {
      ...dadosNormalizados,
      capturadoEm: new Date().toISOString(),
      origemEvento,
      demoDeviceId: obterDemoDeviceId(),
      origem: window.location.origin
    };

    fetch(`${API_URL}/api/demo-leads`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(payload)
    })
      .then(() => {
        localStorage.setItem(dedupeKey, String(Date.now()));
      })
      .catch((error) => {
        console.error('Erro ao registrar lead demo no backend:', error);
      });
  };

  const processarLogin = (usuario, senhaUsuario, opcoes = {}) => {
    const isDemoLogin = Boolean(opcoes?.isDemoLogin);
    const dadosDemo = opcoes?.dadosDemo || null;

    if (fazerLogin(usuario, senhaUsuario)) {
      if (isDemoLogin && dadosDemo) {
        registrarLeadDemoNoBackend(dadosDemo, opcoes?.origemEvento || 'login_demo');
      }

      try {
        fetch(`${API_URL}/api/notify-access`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            usuario,
            perfil: 'Autenticado',
            instituicao: 'Login CEI',
            origem: window.location.origin,
            isDemoLogin,
            demoLead: isDemoLogin ? normalizarCadastroDemo(dadosDemo) : null
          })
        }).catch((error) => {
          console.error('Erro ao notificar acesso no backend:', error);
        });
      } catch (error) {
        console.error('Erro ao iniciar notificação de acesso:', error);
      }

      const from = location.state?.from?.pathname || '/';
      console.log('✅ Login realizado, redirecionando para:', from);
      navigate(from, { replace: true });
      return;
    }

    setErro('Login ou senha inválidos');
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setErro('');

    const loginNormalizado = String(login || '').trim().toLowerCase();
    const senhaNormalizada = String(senha || '').trim();
    const ehLoginDemo = loginNormalizado === CREDENCIAIS_DEMO.login && senhaNormalizada === CREDENCIAIS_DEMO.senha;
    const dadosDemoNormalizados = normalizarCadastroDemo(cadastroDemo);

    if (ehLoginDemo) {
      const validacao = validarCadastroDemoObrigatorio(dadosDemoNormalizados);
      if (!validacao.ok) {
        setErroCadastroDemo(validacao.mensagem);
        setDialogCadastroDemo(true);
        return;
      }
    }

    processarLogin(login, senha, {
      isDemoLogin: ehLoginDemo,
      dadosDemo: ehLoginDemo ? dadosDemoNormalizados : null,
      origemEvento: 'login_demo'
    });
  };

  const handleUsarCredenciaisDemo = () => {
    setLogin(CREDENCIAIS_DEMO.login);
    setSenha(CREDENCIAIS_DEMO.senha);
    setErro('');

    const dadosDemoNormalizados = normalizarCadastroDemo(cadastroDemo);
    const validacao = validarCadastroDemoObrigatorio(dadosDemoNormalizados);
    if (!validacao.ok) {
      setErroCadastroDemo(validacao.mensagem);
      setDialogCadastroDemo(true);
      return;
    }

    processarLogin(CREDENCIAIS_DEMO.login, CREDENCIAIS_DEMO.senha, {
      isDemoLogin: true,
      dadosDemo: dadosDemoNormalizados,
      origemEvento: 'login_demo'
    });
  };

  const handleConfirmarCadastroDemo = () => {
    const dadosNormalizados = normalizarCadastroDemo(cadastroDemo);

    const validacao = validarCadastroDemoObrigatorio(dadosNormalizados);
    if (!validacao.ok) {
      setErroCadastroDemo(validacao.mensagem);
      return;
    }

    try {
      localStorage.setItem(DEMO_CONTACT_KEY, JSON.stringify({
        ...dadosNormalizados,
        capturadoEm: new Date().toISOString()
      }));
    } catch (error) {
      console.warn('Não foi possível salvar os dados do cadastro demo:', error);
    }

    setCadastroDemo(dadosNormalizados);
    setErroCadastroDemo('');
    setDialogCadastroDemo(false);
    setLogin(CREDENCIAIS_DEMO.login);
    setSenha(CREDENCIAIS_DEMO.senha);
    processarLogin(CREDENCIAIS_DEMO.login, CREDENCIAIS_DEMO.senha, {
      isDemoLogin: true,
      dadosDemo: dadosNormalizados,
      origemEvento: 'cadastro_demo'
    });
  };

  const handleAbrirRecuperacao = () => {
    setDialogRecuperacao(true);
    setEmailRecuperacao('');
    setNovaSenha('');
    setConfirmarNovaSenha('');
    setErroRecuperacao('');
    setSucessoRecuperacao('');
    setEtapaRecuperacao(1);
  };

  const handleFecharRecuperacao = () => {
    setDialogRecuperacao(false);
    setEmailRecuperacao('');
    setNovaSenha('');
    setConfirmarNovaSenha('');
    setErroRecuperacao('');
    setSucessoRecuperacao('');
    setEtapaRecuperacao(1);
  };

  const handleVerificarEmail = () => {
    setErroRecuperacao('');
    
    if (!emailRecuperacao.trim()) {
      setErroRecuperacao('Por favor, informe o email cadastrado');
      return;
    }

    // Verificar se o email existe
    const resultado = recuperarSenha(emailRecuperacao);
    
    if (resultado.sucesso) {
      setEtapaRecuperacao(2);
      setSucessoRecuperacao(`Email encontrado! Escola: ${resultado.escola}`);
    } else {
      setErroRecuperacao(resultado.mensagem);
    }
  };

  const handleRedefinirSenha = () => {
    setErroRecuperacao('');
    
    if (!novaSenha || !confirmarNovaSenha) {
      setErroRecuperacao('Por favor, preencha todos os campos');
      return;
    }

    if (novaSenha.length < 8) {
      setErroRecuperacao('A senha deve ter no mínimo 8 caracteres');
      return;
    }

    if (!/[A-Z]/.test(novaSenha)) {
      setErroRecuperacao('A senha deve conter pelo menos 1 letra maiúscula');
      return;
    }

    if (!/[a-z]/.test(novaSenha)) {
      setErroRecuperacao('A senha deve conter pelo menos 1 letra minúscula');
      return;
    }

    if (!/[0-9]/.test(novaSenha)) {
      setErroRecuperacao('A senha deve conter pelo menos 1 número');
      return;
    }

    if (!/[^A-Za-z0-9]/.test(novaSenha)) {
      setErroRecuperacao('A senha deve conter pelo menos 1 caractere especial');
      return;
    }

    if (novaSenha !== confirmarNovaSenha) {
      setErroRecuperacao('As senhas não coincidem');
      return;
    }

    // Redefinir a senha
    const resultado = recuperarSenha(emailRecuperacao, novaSenha);
    
    if (resultado.sucesso) {
      setSucessoRecuperacao('Senha redefinida com sucesso! Você já pode fazer login.');
      setTimeout(() => {
        handleFecharRecuperacao();
      }, 2000);
    } else {
      setErroRecuperacao(resultado.mensagem);
    }
  };

  const fadeIn = keyframes`
    from {
      opacity: 0;
      transform: translateY(30px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  `;

  const float = keyframes`
    0%, 100% {
      transform: translateY(0px);
    }
    50% {
      transform: translateY(-10px);
    }
  `;

  return (
    <Box
      sx={{
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
        position: 'relative',
        overflow: 'hidden',
        '&::before': {
          content: '""',
          position: 'absolute',
          width: '500px',
          height: '500px',
          background: 'rgba(255, 255, 255, 0.1)',
          borderRadius: '50%',
          top: '-250px',
          right: '-250px',
        },
        '&::after': {
          content: '""',
          position: 'absolute',
          width: '400px',
          height: '400px',
          background: 'rgba(255, 255, 255, 0.05)',
          borderRadius: '50%',
          bottom: '-200px',
          left: '-200px',
        }
      }}
    >
      <Container maxWidth="sm">
        <Paper 
          elevation={24}
          sx={{ 
            p: 5,
            borderRadius: 4,
            background: 'rgba(255, 255, 255, 0.95)',
            backdropFilter: 'blur(20px)',
            animation: `${fadeIn} 0.8s ease-out`,
            position: 'relative',
            zIndex: 1,
          }}
        >
          <Box sx={{ textAlign: 'center', mb: 4 }}>
            <Box
              sx={{
                display: 'inline-block',
                p: 2,
                borderRadius: '50%',
                background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                mb: 2,
                animation: `${float} 3s ease-in-out infinite`,
                boxShadow: '0 10px 40px rgba(102, 126, 234, 0.4)',
              }}
            >
              <SchoolIcon sx={{ fontSize: 60, color: 'white' }} />
            </Box>
            <Typography 
              variant="h3" 
              fontWeight="bold" 
              gutterBottom
              sx={{
                background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                WebkitBackgroundClip: 'text',
                WebkitTextFillColor: 'transparent',
                backgroundClip: 'text',
              }}
            >
              CEI
            </Typography>
            <Typography variant="h6" color="text.secondary" fontWeight="500">
              Controle Escolar Inteligente - Gerenciamento de Biblioteca
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
              Bem-vindo! Faça login para continuar
            </Typography>
          </Box>

          <Alert severity="info" sx={{ mb: 2 }}>
            <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 0.5 }}>
              ACESSO DEMONSTRAÇÃO
            </Typography>
            <Typography variant="body2" sx={{ fontWeight: 700 }}>
              Login: {CREDENCIAIS_DEMO.login} | Senha: {CREDENCIAIS_DEMO.senha}
            </Typography>
            <Typography variant="caption" display="block" sx={{ mt: 0.5 }}>
              Teste por 30 dias com até 20 livros, 20 leitores e movimentação completa de empréstimos/devoluções.
            </Typography>
            <Typography variant="caption" display="block" sx={{ mt: 0.5, fontWeight: 700 }}>
              Sessão demo deste dispositivo: cada cliente usa um perfil de demonstração próprio.
            </Typography>
            <Typography variant="caption" display="block" sx={{ mt: 0.5 }}>
              Identificador da sessão demo: {identificadorDemo}
            </Typography>
            <Box sx={{ mt: 1.2, display: 'flex', justifyContent: 'flex-end' }}>
              <Button size="small" variant="outlined" onClick={handleUsarCredenciaisDemo}>
                Usar demo
              </Button>
            </Box>
          </Alert>

          {erro && (
            <Alert severity="error" sx={{ mb: 2 }}>
              {erro}
            </Alert>
          )}

          <form onSubmit={handleSubmit}>
            <TextField
              label="Login"
              fullWidth
              margin="normal"
              value={login}
              onChange={(e) => setLogin(e.target.value)}
              required
              autoComplete="username"
              sx={{
                '& .MuiOutlinedInput-root': {
                  borderRadius: 2,
                  transition: 'all 0.3s',
                  '&:hover': {
                    transform: 'translateY(-2px)',
                    boxShadow: '0 4px 12px rgba(102, 126, 234, 0.2)',
                  },
                  '&.Mui-focused': {
                    boxShadow: '0 4px 12px rgba(102, 126, 234, 0.3)',
                  }
                }
              }}
            />
            <TextField
              label="Senha"
              type={mostrarSenha ? 'text' : 'password'}
              fullWidth
              margin="normal"
              value={senha}
              onChange={(e) => setSenha(e.target.value)}
              required
              autoComplete="current-password"
              sx={{
                '& .MuiOutlinedInput-root': {
                  borderRadius: 2,
                  transition: 'all 0.3s',
                  '&:hover': {
                    transform: 'translateY(-2px)',
                    boxShadow: '0 4px 12px rgba(102, 126, 234, 0.2)',
                  },
                  '&.Mui-focused': {
                    boxShadow: '0 4px 12px rgba(102, 126, 234, 0.3)',
                  }
                }
              }}
              InputProps={{
                endAdornment: (
                  <InputAdornment position="end">
                    <IconButton
                      aria-label="alternar visibilidade da senha"
                      onClick={() => setMostrarSenha(!mostrarSenha)}
                      onMouseDown={(e) => e.preventDefault()}
                      edge="end"
                      sx={{
                        color: 'primary.main',
                        '&:hover': {
                          background: 'rgba(102, 126, 234, 0.1)',
                        }
                      }}
                    >
                      {mostrarSenha ? <VisibilityOff /> : <Visibility />}
                    </IconButton>
                  </InputAdornment>
                )
              }}
            />
            
            <Box sx={{ textAlign: 'right', mt: 1, mb: 2 }}>
              <Link
                component="button"
                type="button"
                variant="body2"
                onClick={handleAbrirRecuperacao}
                sx={{
                  color: 'primary.main',
                  fontWeight: 500,
                  textDecoration: 'none',
                  cursor: 'pointer',
                  transition: 'all 0.2s',
                  '&:hover': {
                    textDecoration: 'underline',
                    color: 'primary.dark',
                  }
                }}
              >
                Esqueceu a senha?
              </Link>
            </Box>

            <Button
              type="submit"
              variant="contained"
              fullWidth
              size="large"
              startIcon={<LoginIcon />}
              sx={{ 
                mt: 3,
                py: 1.5,
                borderRadius: 2,
                fontSize: '1.1rem',
                fontWeight: 'bold',
                background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                boxShadow: '0 8px 24px rgba(102, 126, 234, 0.4)',
                transition: 'all 0.3s',
                '&:hover': {
                  transform: 'translateY(-3px)',
                  boxShadow: '0 12px 32px rgba(102, 126, 234, 0.5)',
                  background: 'linear-gradient(135deg, #764ba2 0%, #667eea 100%)',
                }
              }}
            >
              Entrar no Sistema
            </Button>
          </form>

          <Box sx={{ mt: 3, textAlign: 'center' }}>
            <Typography variant="body2" color="text.secondary" gutterBottom sx={{ mb: 2 }}>
              Sua instituição ainda não está cadastrada?
            </Typography>
            <Button
              variant="outlined"
              fullWidth
              startIcon={<PersonAddIcon />}
              onClick={() => navigate('/termos-de-uso')}
              sx={{
                borderRadius: 2,
                py: 1,
                borderWidth: 2,
                fontWeight: 600,
                borderColor: 'primary.main',
                color: 'primary.main',
                transition: 'all 0.3s',
                '&:hover': {
                  borderWidth: 2,
                  borderColor: 'primary.dark',
                  background: 'rgba(102, 126, 234, 0.05)',
                  transform: 'translateY(-2px)',
                  boxShadow: '0 4px 12px rgba(102, 126, 234, 0.2)',
                }
              }}
            >
              Cadastrar Nova Instituição
            </Button>

            <Button
              variant="contained"
              fullWidth
              startIcon={<SmartDisplayIcon />}
              onClick={() => setDialogTourVideo(true)}
              sx={{
                mt: 1.5,
                borderRadius: 2,
                py: 1,
                fontWeight: 700,
                background: 'linear-gradient(135deg, #00c6ff 0%, #0072ff 100%)',
                boxShadow: '0 8px 24px rgba(0, 114, 255, 0.35)',
                transition: 'all 0.3s',
                '&:hover': {
                  transform: 'translateY(-2px)',
                  boxShadow: '0 12px 28px rgba(0, 114, 255, 0.45)',
                  background: 'linear-gradient(135deg, #0072ff 0%, #00c6ff 100%)',
                }
              }}
            >
              Ver Tour em Vídeo do Sistema
            </Button>
          </Box>

          {/* Instalar PWA */}
          <InstallPWA />
          
          {/* Marca Registrada */}
          <Box sx={{ mt: 4, pt: 3, borderTop: '2px solid', borderColor: 'divider', textAlign: 'center' }}>
            <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 0.5 }}>
              © {new Date().getFullYear()} CEI - Sistema desenvolvido por
            </Typography>
            <Typography 
              variant="caption" 
              display="block" 
              fontWeight="bold"
              sx={{
                background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                WebkitBackgroundClip: 'text',
                WebkitTextFillColor: 'transparent',
                backgroundClip: 'text',
                fontSize: '0.9rem',
              }}
            >
              Wander Pires Silva Coelho ®
            </Typography>
            <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 0.5 }}>
              Todos os direitos reservados
            </Typography>
          </Box>
        </Paper>

        {/* Dialog de Recuperação de Senha */}
        <Dialog
          open={dialogCadastroDemo}
          onClose={() => setDialogCadastroDemo(false)}
          maxWidth="sm"
          fullWidth
          PaperProps={{
            sx: {
              borderRadius: 3,
              p: 1
            }
          }}
        >
          <DialogTitle sx={{ pb: 1 }}>
            Cadastro Obrigatório para Acesso Demo
          </DialogTitle>
          <DialogContent>
            <Alert severity="info" sx={{ mb: 2 }}>
              Para usar a demonstração, informe seus dados de contato. Eles aparecerão no painel do Super Administrador para retorno comercial.
            </Alert>

            {erroCadastroDemo && (
              <Alert severity="error" sx={{ mb: 2 }} onClose={() => setErroCadastroDemo('')}>
                {erroCadastroDemo}
              </Alert>
            )}

            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 1 }}>
              <TextField
                label="Nome do Responsável pelo Cadastro *"
                fullWidth
                required
                value={cadastroDemo.nomeResponsavel}
                onChange={(e) => setCadastroDemo((prev) => ({ ...prev, nomeResponsavel: e.target.value }))}
                placeholder="Ex: Maria Silva"
              />
              <TextField
                label="Telefone Celular *"
                fullWidth
                required
                value={cadastroDemo.telefoneCelular}
                onChange={(e) => setCadastroDemo((prev) => ({
                  ...prev,
                  telefoneCelular: aplicarMascaraTelefone(e.target.value)
                }))}
                placeholder="(99) 9 9999-9999"
                inputProps={{ maxLength: 16 }}
              />
              <TextField
                label="E-mail *"
                type="email"
                fullWidth
                required
                value={cadastroDemo.email}
                onChange={(e) => setCadastroDemo((prev) => ({ ...prev, email: e.target.value }))}
                placeholder="contato@escola.com.br"
              />
              <Box sx={{ display: 'flex', gap: 2 }}>
                <TextField
                  label="Cidade *"
                  fullWidth
                  required
                  value={cadastroDemo.cidade}
                  onChange={(e) => setCadastroDemo((prev) => ({ ...prev, cidade: e.target.value }))}
                />
                <TextField
                  label="Estado (UF) *"
                  fullWidth
                  required
                  value={cadastroDemo.estado}
                  onChange={(e) => setCadastroDemo((prev) => ({
                    ...prev,
                    estado: String(e.target.value || '').toUpperCase().slice(0, 2)
                  }))}
                  placeholder="PI"
                  inputProps={{ maxLength: 2 }}
                />
              </Box>
            </Box>
          </DialogContent>
          <DialogActions sx={{ px: 3, pb: 2 }}>
            <Button onClick={() => setDialogCadastroDemo(false)}>
              Cancelar
            </Button>
            <Button variant="contained" onClick={handleConfirmarCadastroDemo}>
              Salvar e Entrar no Demo
            </Button>
          </DialogActions>
        </Dialog>

        <Dialog 
          open={dialogRecuperacao} 
          onClose={handleFecharRecuperacao}
          maxWidth="sm"
          fullWidth
          PaperProps={{
            sx: {
              borderRadius: 3,
              p: 2
            }
          }}
        >
          <DialogTitle sx={{ 
            display: 'flex', 
            alignItems: 'center', 
            gap: 1,
            pb: 1 
          }}>
            <LockResetIcon sx={{ color: 'primary.main', fontSize: 30 }} />
            <Typography variant="h5" fontWeight="bold">
              Recuperar Senha
            </Typography>
          </DialogTitle>

          <DialogContent sx={{ pt: 2 }}>
            {etapaRecuperacao === 1 ? (
              // Etapa 1: Verificar email
              <>
                <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
                  Digite o email cadastrado da sua instituição para recuperar a senha.
                </Typography>

                {erroRecuperacao && (
                  <Alert severity="error" sx={{ mb: 2 }}>
                    {erroRecuperacao}
                  </Alert>
                )}

                <TextField
                  label="Email da Instituição"
                  type="email"
                  fullWidth
                  value={emailRecuperacao}
                  onChange={(e) => setEmailRecuperacao(e.target.value)}
                  placeholder="email@escola.com.br"
                  autoFocus
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <EmailIcon color="primary" />
                      </InputAdornment>
                    )
                  }}
                  sx={{
                    '& .MuiOutlinedInput-root': {
                      borderRadius: 2,
                    }
                  }}
                />
              </>
            ) : (
              // Etapa 2: Redefinir senha
              <>
                <Alert severity="success" sx={{ mb: 2 }}>
                  {sucessoRecuperacao}
                </Alert>

                <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
                  Agora defina uma nova senha de acesso.
                </Typography>

                {erroRecuperacao && (
                  <Alert severity="error" sx={{ mb: 2 }}>
                    {erroRecuperacao}
                  </Alert>
                )}

                <TextField
                  label="Nova Senha"
                  type={mostrarNovaSenha ? 'text' : 'password'}
                  fullWidth
                  value={novaSenha}
                  onChange={(e) => setNovaSenha(e.target.value)}
                  placeholder="Mínimo 6 caracteres"
                  autoFocus
                  sx={{ mb: 2 }}
                  InputProps={{
                    endAdornment: (
                      <InputAdornment position="end">
                        <IconButton
                          onClick={() => setMostrarNovaSenha(!mostrarNovaSenha)}
                          edge="end"
                        >
                          {mostrarNovaSenha ? <VisibilityOff /> : <Visibility />}
                        </IconButton>
                      </InputAdornment>
                    )
                  }}
                />

                <TextField
                  label="Confirmar Nova Senha"
                  type={mostrarNovaSenha ? 'text' : 'password'}
                  fullWidth
                  value={confirmarNovaSenha}
                  onChange={(e) => setConfirmarNovaSenha(e.target.value)}
                  placeholder="Digite a senha novamente"
                />
              </>
            )}
          </DialogContent>

          <DialogActions sx={{ px: 3, pb: 2 }}>
            <Button 
              onClick={handleFecharRecuperacao}
              sx={{ borderRadius: 2 }}
            >
              Cancelar
            </Button>
            {etapaRecuperacao === 1 ? (
              <Button 
                variant="contained"
                onClick={handleVerificarEmail}
                disabled={!emailRecuperacao.trim()}
                sx={{ 
                  borderRadius: 2,
                  px: 3,
                  background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                }}
              >
                Verificar Email
              </Button>
            ) : (
              <Button 
                variant="contained"
                onClick={handleRedefinirSenha}
                disabled={!novaSenha || !confirmarNovaSenha}
                sx={{ 
                  borderRadius: 2,
                  px: 3,
                  background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                }}
              >
                Redefinir Senha
              </Button>
            )}
          </DialogActions>
        </Dialog>

        <Dialog
          open={dialogTourVideo}
          onClose={() => setDialogTourVideo(false)}
          maxWidth="lg"
          fullWidth
          PaperProps={{
            sx: {
              borderRadius: 3,
              overflow: 'hidden'
            }
          }}
        >
          <DialogTitle
            sx={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              background: 'linear-gradient(135deg, #0f2027 0%, #203a43 50%, #2c5364 100%)',
              color: 'white'
            }}
          >
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              <AutoAwesomeIcon />
              <Typography variant="h6" fontWeight="bold">
                CEI Experience - Tour Completo de Funcionalidades
              </Typography>
            </Box>
            <IconButton onClick={() => setDialogTourVideo(false)} sx={{ color: 'white' }}>
              <CloseIcon />
            </IconButton>
          </DialogTitle>

          <DialogContent sx={{ p: 0 }}>
            <Box sx={{ p: 2, bgcolor: '#f6f9ff' }}>
              <Box
                sx={{
                  borderRadius: 2,
                  overflow: 'hidden',
                  boxShadow: '0 12px 30px rgba(0,0,0,0.2)',
                  bgcolor: 'black',
                  minHeight: 300,
                  background: videoSelecionado.gradiente,
                  color: 'white',
                  position: 'relative'
                }}
              >
                <Box sx={{ p: { xs: 2, md: 3 }, display: 'flex', flexDirection: 'column', gap: 2 }}>
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
                    {(() => {
                      const IconComp = videoSelecionado.icon;
                      return <IconComp sx={{ fontSize: 36 }} />;
                    })()}
                    <Typography variant="h5" fontWeight="bold">Demonstração Inteligente CEI</Typography>
                  </Box>

                  <Box
                    sx={{
                      display: 'grid',
                      gridTemplateColumns: { xs: '1fr', md: '1fr 1fr' },
                      gap: 2
                    }}
                  >
                    <Box sx={{ p: 2, borderRadius: 2, bgcolor: 'rgba(255,255,255,0.12)', backdropFilter: 'blur(6px)' }}>
                      <Typography variant="caption" sx={{ opacity: 0.85 }}>Performance</Typography>
                      <Typography variant="h6" fontWeight="bold">{videoSelecionado.metricA}</Typography>
                    </Box>
                    <Box sx={{ p: 2, borderRadius: 2, bgcolor: 'rgba(255,255,255,0.12)', backdropFilter: 'blur(6px)' }}>
                      <Typography variant="caption" sx={{ opacity: 0.85 }}>Tecnologia</Typography>
                      <Typography variant="h6" fontWeight="bold">{videoSelecionado.metricB}</Typography>
                    </Box>
                  </Box>

                  <Box sx={{ p: 2, borderRadius: 2, bgcolor: 'rgba(0,0,0,0.25)' }}>
                    {videoSelecionado.destaque.map((item) => (
                      <Typography key={item} variant="body2" sx={{ mb: 0.8 }}>
                        • {item}
                      </Typography>
                    ))}
                  </Box>

                  <Box sx={{ display: 'flex', gap: 1 }}>
                    {[1, 2, 3].map((bar) => (
                      <Box
                        key={bar}
                        sx={{
                          height: 8,
                          flex: 1,
                          borderRadius: 99,
                          bgcolor: 'rgba(255,255,255,0.25)',
                          overflow: 'hidden'
                        }}
                      >
                        <Box
                          sx={{
                            height: '100%',
                            width: `${65 + bar * 10}%`,
                            borderRadius: 99,
                            bgcolor: '#7cf3ff',
                            boxShadow: '0 0 12px rgba(124,243,255,0.9)',
                            transition: 'all 0.8s ease'
                          }}
                        />
                      </Box>
                    ))}
                  </Box>
                </Box>
              </Box>

              <Box sx={{ mt: 1.5, mb: 2 }}>
                <Typography variant="h6" fontWeight="bold" color="primary.main">
                  {videoSelecionado.titulo}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  {videoSelecionado.descricao}
                </Typography>
              </Box>

              <Box
                sx={{
                  display: 'grid',
                  gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr', md: '1fr 1fr 1fr' },
                  gap: 1.2
                }}
              >
                {DEMO_VIDEOS.map((video) => (
                  <Button
                    key={video.id}
                    variant={videoSelecionado.id === video.id ? 'contained' : 'outlined'}
                    startIcon={<SmartDisplayIcon />}
                    onClick={() => {
                      setVideoSelecionado(video);
                    }}
                    sx={{
                      justifyContent: 'flex-start',
                      textTransform: 'none',
                      borderRadius: 2,
                      py: 1,
                      px: 1.5,
                      fontWeight: 600
                    }}
                  >
                    {video.titulo}
                  </Button>
                ))}
              </Box>
            </Box>
          </DialogContent>

          <DialogActions sx={{ px: 3, py: 1.5, bgcolor: '#f6f9ff' }}>
            <Button
              variant="contained"
              onClick={() => {
                setDialogTourVideo(false);
                navigate('/termos-de-uso');
              }}
              startIcon={<PersonAddIcon />}
              sx={{ borderRadius: 2, fontWeight: 700 }}
            >
              Quero Adquirir o Sistema
            </Button>
          </DialogActions>
        </Dialog>
      </Container>
    </Box>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import Layout from '../components/Layout';
import { useData } from '../context/DataContext';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Dialog,
  DialogContent,
  DialogActions,
  DialogTitle,
  Divider,
  FormControl,
  Grid,
  IconButton,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography
} from '@mui/material';
import {
  Add,
  AssignmentTurnedIn,
  Print,
  Receipt,
  Refresh,
  Visibility
} from '@mui/icons-material';
import { imprimirEscopo } from '../utils/printUtils';

const DEFAULT_PREFEITURA_CURIMATA = {
  razaoSocial: '',
  cnpj: '',
  endereco: '',
  cep: '',
  municipio: '',
  uf: '',
  telefone: '',
  email: ''
};

const DEFAULT_PRESTADOR = {
  razaoSocial: '',
  nomeFantasia: 'CEI - Controle Escolar Inteligente',
  tipoDocumento: 'CPF',
  documento: '',
  inscricaoMunicipal: '',
  endereco: '',
  cep: '',
  municipio: '',
  uf: '',
  telefone: '',
  email: ''
};

const FORM_DEFAULT = {
  instituicaoClienteId: '',
  serie: 'A1',
  competencia: new Date().toISOString().slice(0, 7),
  codigoServico: '1.05',
  naturezaOperacao: 'Prestação de serviço de licenciamento de software',
  descricaoServico: 'Licença mensal do sistema CEI - Controle Escolar Inteligente',
  valorServico: 0,
  aliquotaISS: 2,
  observacoes: ''
};

const STORAGE_PRESTADOR = 'cei_nf_prestador_config';
const STORAGE_PREFEITURA = 'cei_nf_prefeitura_config';

function somenteDigitos(value) {
  return (value || '').replace(/\D/g, '');
}

function formatarValor(value) {
  return Number(value || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}

function formatarCompetencia(competencia) {
  if (!competencia || competencia.length !== 7) return '-';
  const [ano, mes] = competencia.split('-');
  return `${mes}/${ano}`;
}

function gerarChaveControle(numero, instituicaoId) {
  const base = `${numero}-${instituicaoId}-${Date.now()}`;
  const encoded = btoa(unescape(encodeURIComponent(base))).replace(/=+$/g, '');
  return encoded.slice(0, 20).toUpperCase();
}

function validarDocumento(documento, tipoDocumento) {
  const digits = somenteDigitos(documento);
  if (tipoDocumento === 'CPF') return digits.length === 11;
  if (tipoDocumento === 'CNPJ') return digits.length === 14;
  return false;
}

function aplicarMascaraDocumento(value, tipoDocumento) {
  const digits = somenteDigitos(value);

  if (tipoDocumento === 'CPF') {
    const cpf = digits.slice(0, 11);
    if (cpf.length <= 3) return cpf;
    if (cpf.length <= 6) return `${cpf.slice(0, 3)}.${cpf.slice(3)}`;
    if (cpf.length <= 9) return `${cpf.slice(0, 3)}.${cpf.slice(3, 6)}.${cpf.slice(6)}`;
    return `${cpf.slice(0, 3)}.${cpf.slice(3, 6)}.${cpf.slice(6, 9)}-${cpf.slice(9, 11)}`;
  }

  const cnpj = digits.slice(0, 14);
  if (cnpj.length <= 2) return cnpj;
  if (cnpj.length <= 5) return `${cnpj.slice(0, 2)}.${cnpj.slice(2)}`;
  if (cnpj.length <= 8) return `${cnpj.slice(0, 2)}.${cnpj.slice(2, 5)}.${cnpj.slice(5)}`;
  if (cnpj.length <= 12) return `${cnpj.slice(0, 2)}.${cnpj.slice(2, 5)}.${cnpj.slice(5, 8)}/${cnpj.slice(8)}`;
  return `${cnpj.slice(0, 2)}.${cnpj.slice(2, 5)}.${cnpj.slice(5, 8)}/${cnpj.slice(8, 12)}-${cnpj.slice(12, 14)}`;
}

function aplicarMascaraCEP(value) {
  const digits = somenteDigitos(value).slice(0, 8);
  if (digits.length <= 5) return digits;
  return `${digits.slice(0, 5)}-${digits.slice(5)}`;
}

function aplicarMascaraTelefone(value) {
  const digits = somenteDigitos(value).slice(0, 11);
  if (digits.length <= 2) return digits;
  if (digits.length <= 6) return `(${digits.slice(0, 2)}) ${digits.slice(2)}`;
  if (digits.length <= 10) return `(${digits.slice(0, 2)}) ${digits.slice(2, 6)}-${digits.slice(6)}`;
  return `(${digits.slice(0, 2)}) ${digits.slice(2, 7)}-${digits.slice(7)}`;
}

function isCepIncompleto(value) {
  const digits = somenteDigitos(value);
  return digits.length > 0 && digits.length < 8;
}

function isTelefoneIncompleto(value) {
  const digits = somenteDigitos(value);
  return digits.length > 0 && digits.length !== 10 && digits.length !== 11;
}

function isDocumentoIncompleto(value, tipoDocumento) {
  const digits = somenteDigitos(value);
  if (digits.length === 0) return false;
  if (tipoDocumento === 'CPF') return digits.length < 11;
  if (tipoDocumento === 'CNPJ') return digits.length < 14;
  return false;
}

export default function NotaFiscalPage() {
  const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:3001';
  const TEST_EMAIL_TOKEN = process.env.REACT_APP_TEST_EMAIL_TOKEN || '';

  const { 
    usuarioLogado, 
    instituicoes,
    notasFiscais, 
    adicionarNotaFiscal
  } = useData();
  
  const [open, setOpen] = useState(false);
  const [visualizarOpen, setVisualizarOpen] = useState(false);
  const [notaSelecionada, setNotaSelecionada] = useState(null);
  const [prestador, setPrestador] = useState(DEFAULT_PRESTADOR);
  const [prefeituraBeneficiada, setPrefeituraBeneficiada] = useState(DEFAULT_PREFEITURA_CURIMATA);
  const [erroFormulario, setErroFormulario] = useState('');
  const [openTesteEmail, setOpenTesteEmail] = useState(false);
  const [enviandoTesteEmail, setEnviandoTesteEmail] = useState(false);
  const [feedbackTesteEmail, setFeedbackTesteEmail] = useState({ tipo: '', mensagem: '' });
  const [testeEmailData, setTesteEmailData] = useState({
    compradorEmail: '',
    compradorNome: '',
    instituicaoNome: '',
    planoNome: 'Plano 1 Ano (365 dias)',
    valor: 970
  });
  
  const [formData, setFormData] = useState(FORM_DEFAULT);

  const instituicoesTomadoras = useMemo(
    () => instituicoes.filter((inst) => inst.id !== 0),
    [instituicoes]
  );

  useEffect(() => {
    try {
      const prestadorSalvo = localStorage.getItem(STORAGE_PRESTADOR);
      if (prestadorSalvo) {
        const parsedPrestador = JSON.parse(prestadorSalvo);
        const documentoMigrado = parsedPrestador.documento || parsedPrestador.cnpj || '';
        const tipoMigrado = parsedPrestador.tipoDocumento || (somenteDigitos(documentoMigrado).length === 11 ? 'CPF' : 'CNPJ');
        setPrestador({
          ...DEFAULT_PRESTADOR,
          ...parsedPrestador,
          tipoDocumento: tipoMigrado,
          documento: documentoMigrado
        });
      }
      const prefeituraSalva = localStorage.getItem(STORAGE_PREFEITURA);
      if (prefeituraSalva) {
        setPrefeituraBeneficiada({ ...DEFAULT_PREFEITURA_CURIMATA, ...JSON.parse(prefeituraSalva) });
      }
    } catch (error) {
      console.error('Erro ao carregar configurações fiscais:', error);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_PRESTADOR, JSON.stringify(prestador));
  }, [prestador]);

  useEffect(() => {
    localStorage.setItem(STORAGE_PREFEITURA, JSON.stringify(prefeituraBeneficiada));
  }, [prefeituraBeneficiada]);

  const valorISS = (formData.valorServico * formData.aliquotaISS) / 100;
  const valorLiquido = formData.valorServico - valorISS;

  const emissaoBloqueada =
    !formData.instituicaoClienteId ||
    !formData.competencia ||
    !formData.descricaoServico?.trim() ||
    !formData.valorServico ||
    formData.valorServico <= 0 ||
    !prestador.razaoSocial?.trim() ||
    !validarDocumento(prestador.documento, prestador.tipoDocumento) ||
    isDocumentoIncompleto(prestador.documento, prestador.tipoDocumento) ||
    isCepIncompleto(prestador.cep) ||
    isTelefoneIncompleto(prestador.telefone) ||
    isCepIncompleto(prefeituraBeneficiada.cep) ||
    isTelefoneIncompleto(prefeituraBeneficiada.telefone);

  const handleOpen = () => {
    setFormData(FORM_DEFAULT);
    setErroFormulario('');
    setOpen(true);
  };

  const handleClose = () => {
    setOpen(false);
  };

  const validarFormulario = () => {
    if (!formData.instituicaoClienteId) return 'Selecione a instituição tomadora.';
    if (!formData.descricaoServico?.trim()) return 'Informe a descrição do serviço.';
    if (!formData.valorServico || formData.valorServico <= 0) return 'Informe um valor de serviço válido.';
    if (!formData.competencia) return 'Informe a competência da nota.';
    if (!prestador.razaoSocial?.trim()) return 'Informe a razão social do prestador.';
    if (!validarDocumento(prestador.documento, prestador.tipoDocumento)) {
      return `Informe um ${prestador.tipoDocumento} válido do prestador.`;
    }
    if (!prefeituraBeneficiada.razaoSocial?.trim()) return 'Informe o órgão/município beneficiado.';
    return '';
  };

  const handleSubmit = () => {
    const erro = validarFormulario();
    if (erro) {
      setErroFormulario(erro);
      return;
    }

    const instituicaoCliente = instituicoes.find(i => i.id === formData.instituicaoClienteId);
    
    if (!instituicaoCliente) {
      setErroFormulario('Instituição tomadora não encontrada.');
      return;
    }

    const proximoNumero = notasFiscais.length > 0 ? Math.max(...notasFiscais.map((n) => n.numero || 0)) + 1 : 1;

    const nota = {
      ...formData,
      serie: formData.serie || 'A1',
      status: 'emitida',
      chaveControle: gerarChaveControle(proximoNumero, instituicaoCliente.id),
      clienteNome: instituicaoCliente.nomeInstituicao,
      clienteCnpj: instituicaoCliente.cnpj || 'Não informado',
      clienteEndereco: instituicaoCliente.endereco || 'Não informado',
      clienteCidade: instituicaoCliente.cidade,
      clienteEstado: instituicaoCliente.estado,
      clienteCep: instituicaoCliente.cep || '',
      valorISS,
      valorLiquido,
      instituicaoId: formData.instituicaoClienteId,
      prestadorNome: prestador.razaoSocial,
      prestadorNomeFantasia: prestador.nomeFantasia,
      prestadorDocumentoTipo: prestador.tipoDocumento,
      prestadorDocumento: prestador.documento,
      prestadorCnpj: prestador.tipoDocumento === 'CNPJ' ? prestador.documento : '',
      prestadorInscricaoMunicipal: prestador.inscricaoMunicipal,
      prestadorEndereco: prestador.endereco,
      prestadorCep: prestador.cep,
      prestadorCidade: prestador.municipio,
      prestadorEstado: prestador.uf,
      prestadorTelefone: prestador.telefone,
      prestadorEmail: prestador.email,
      beneficiarioRazaoSocial: prefeituraBeneficiada.razaoSocial,
      beneficiarioCnpj: prefeituraBeneficiada.cnpj,
      beneficiarioEndereco: prefeituraBeneficiada.endereco,
      beneficiarioCep: prefeituraBeneficiada.cep,
      beneficiarioCidade: prefeituraBeneficiada.municipio,
      beneficiarioEstado: prefeituraBeneficiada.uf,
      beneficiarioTelefone: prefeituraBeneficiada.telefone,
      beneficiarioEmail: prefeituraBeneficiada.email
    };

    adicionarNotaFiscal(nota);
    setErroFormulario('');
    handleClose();
  };

  const handleVisualizar = (nota) => {
    setNotaSelecionada(nota);
    setVisualizarOpen(true);
  };

  const handleImprimir = (nota) => {
    setNotaSelecionada(nota);
    setVisualizarOpen(true);
    setTimeout(() => imprimirEscopo(), 300);
  };

  const abrirTesteEmail = () => {
    const instituicaoBase = instituicoesTomadoras[0];
    setTesteEmailData({
      compradorEmail: instituicaoBase?.email || '',
      compradorNome: instituicaoBase?.nomeResponsavel || '',
      instituicaoNome: instituicaoBase?.nomeInstituicao || '',
      planoNome: instituicaoBase?.plano || 'Plano 1 Ano (365 dias)',
      valor: instituicaoBase?.valorMensal || 970
    });
    setFeedbackTesteEmail({ tipo: '', mensagem: '' });
    setOpenTesteEmail(true);
  };

  const enviarTesteEmail = async () => {
    if (!testeEmailData.compradorEmail?.trim()) {
      setFeedbackTesteEmail({ tipo: 'error', mensagem: 'Informe o e-mail do comprador para o teste.' });
      return;
    }

    setEnviandoTesteEmail(true);
    setFeedbackTesteEmail({ tipo: '', mensagem: '' });

    try {
      const headers = {
        'Content-Type': 'application/json'
      };

      if (TEST_EMAIL_TOKEN) {
        headers['x-test-token'] = TEST_EMAIL_TOKEN;
      }

      const response = await fetch(`${API_URL}/api/test-email`, {
        method: 'POST',
        headers,
        body: JSON.stringify(testeEmailData)
      });

      const result = await response.json();

      if (!response.ok || !result.success) {
        throw new Error(result.error || 'Falha no envio de e-mail de teste.');
      }

      const destinatarios = Array.isArray(result.recipients) ? result.recipients.join(', ') : 'comprador + proprietário';
      setFeedbackTesteEmail({
        tipo: 'success',
        mensagem: `Teste enviado com sucesso para: ${destinatarios}`
      });
    } catch (error) {
      setFeedbackTesteEmail({ tipo: 'error', mensagem: error.message || 'Erro ao enviar teste de e-mail.' });
    } finally {
      setEnviandoTesteEmail(false);
    }
  };

  const notasFiltradas = notasFiscais;

  const totalEmitido = notasFiltradas.reduce((acc, n) => acc + n.valorServico, 0);
  const totalISS = notasFiltradas.reduce((acc, n) => acc + n.valorISS, 0);

  if (usuarioLogado?.perfil !== 'SuperAdmin') {
    return (
      <Layout title="Notas Fiscais de Serviço (ISS)">
        <Alert severity="error">Acesso negado. Apenas o Super Administrador pode emitir e visualizar notas fiscais.</Alert>
      </Layout>
    );
  }

  return (
    <Layout title="Notas Fiscais de Serviço (ISS)">
      <Box sx={{ mb: 3, display: 'flex', gap: 1, flexWrap: 'wrap' }} className="no-print">
        <Button
          variant="contained"
          startIcon={<Add />}
          onClick={handleOpen}
        >
          Emitir Nova Nota Fiscal
        </Button>
        <Button
          variant="outlined"
          startIcon={<Receipt />}
          onClick={abrirTesteEmail}
        >
          Testar E-mails
        </Button>
      </Box>

      {feedbackTesteEmail.mensagem && (
        <Alert severity={feedbackTesteEmail.tipo || 'info'} sx={{ mb: 2 }} className="no-print">
          {feedbackTesteEmail.mensagem}
        </Alert>
      )}

      {/* Cards de Resumo */}
      <Grid container spacing={3} sx={{ mb: 3 }}>
        <Grid item xs={12} sm={4}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                Total Emitido
              </Typography>
              <Typography variant="h4">
                R$ {totalEmitido.toFixed(2)}
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={4}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                Total ISS Retido
              </Typography>
              <Typography variant="h4">
                R$ {totalISS.toFixed(2)}
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={4}>
          <Card>
            <CardContent>
              <Typography color="textSecondary" gutterBottom>
                Notas Emitidas
              </Typography>
              <Typography variant="h4">
                {notasFiltradas.length}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Tabela de Notas */}
      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Número</TableCell>
              <TableCell>Série</TableCell>
              <TableCell>Data</TableCell>
              <TableCell>Tomador</TableCell>
              <TableCell>Competência</TableCell>
              <TableCell>Valor Serviço</TableCell>
              <TableCell>ISS</TableCell>
              <TableCell>Valor Líquido</TableCell>
              <TableCell>Status</TableCell>
              <TableCell>Ações</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {notasFiltradas.length === 0 ? (
              <TableRow>
                <TableCell colSpan={10} align="center">
                  <Typography color="text.secondary">
                    Nenhuma nota fiscal emitida
                  </Typography>
                </TableCell>
              </TableRow>
            ) : (
              notasFiltradas.map((nota) => (
                <TableRow key={nota.id}>
                  <TableCell>
                    <Chip label={`NF ${nota.numero}`} color="primary" size="small" />
                  </TableCell>
                  <TableCell>{nota.serie || 'A1'}</TableCell>
                  <TableCell>
                    {new Date(nota.dataEmissao).toLocaleDateString('pt-BR')}
                  </TableCell>
                  <TableCell>{nota.clienteNome}</TableCell>
                  <TableCell>{formatarCompetencia(nota.competencia)}</TableCell>
                  <TableCell>R$ {nota.valorServico.toFixed(2)}</TableCell>
                  <TableCell>{formatarValor(nota.valorISS)}</TableCell>
                  <TableCell>R$ {nota.valorLiquido.toFixed(2)}</TableCell>
                  <TableCell>
                    <Chip
                      label={nota.status || 'emitida'}
                      size="small"
                      color={(nota.status || 'emitida') === 'emitida' ? 'success' : 'default'}
                      icon={<AssignmentTurnedIn />}
                    />
                  </TableCell>
                  <TableCell>
                    <IconButton 
                      size="small" 
                      onClick={() => handleVisualizar(nota)}
                      title="Visualizar"
                    >
                      <Visibility />
                    </IconButton>
                    <IconButton 
                      size="small" 
                      onClick={() => handleImprimir(nota)}
                      title="Imprimir"
                    >
                      <Print />
                    </IconButton>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </TableContainer>

      {/* Modal de Emissão */}
      <Dialog open={open} onClose={handleClose} maxWidth="md" fullWidth>
        <DialogTitle>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <Receipt />
            Emitir Nota Fiscal de Serviço (ISS)
          </Box>
        </DialogTitle>
        <DialogContent>
          {erroFormulario && <Alert severity="warning" sx={{ mt: 2 }}>{erroFormulario}</Alert>}

          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 2 }}>
            <Typography variant="subtitle2" color="primary">
              Dados do Prestador
            </Typography>
            <Grid container spacing={2}>
              <Grid item xs={12} sm={8}>
                <TextField
                  label="Razão Social *"
                  fullWidth
                  value={prestador.razaoSocial}
                  onChange={(e) => setPrestador({ ...prestador, razaoSocial: e.target.value })}
                />
              </Grid>
              <Grid item xs={12} sm={2}>
                <FormControl fullWidth>
                  <InputLabel>Tipo</InputLabel>
                  <Select
                    value={prestador.tipoDocumento}
                    label="Tipo"
                    onChange={(e) => {
                      const novoTipo = e.target.value;
                      setPrestador({
                        ...prestador,
                        tipoDocumento: novoTipo,
                        documento: aplicarMascaraDocumento(prestador.documento, novoTipo)
                      });
                    }}
                  >
                    <MenuItem value="CPF">CPF</MenuItem>
                    <MenuItem value="CNPJ">CNPJ</MenuItem>
                  </Select>
                </FormControl>
              </Grid>
              <Grid item xs={12} sm={2}>
                <TextField
                  label={`${prestador.tipoDocumento} *`}
                  fullWidth
                  value={prestador.documento}
                  onChange={(e) => {
                    const valorFormatado = aplicarMascaraDocumento(e.target.value, prestador.tipoDocumento);
                    setPrestador({ ...prestador, documento: valorFormatado });
                  }}
                  error={isDocumentoIncompleto(prestador.documento, prestador.tipoDocumento)}
                  helperText={
                    isDocumentoIncompleto(prestador.documento, prestador.tipoDocumento)
                      ? `${prestador.tipoDocumento} incompleto.`
                      : prestador.tipoDocumento === 'CPF'
                        ? 'Formato: 000.000.000-00'
                        : 'Formato: 00.000.000/0000-00'
                  }
                />
              </Grid>
              <Grid item xs={12} sm={6}>
                <TextField
                  label="Nome Fantasia"
                  fullWidth
                  value={prestador.nomeFantasia}
                  onChange={(e) => setPrestador({ ...prestador, nomeFantasia: e.target.value })}
                />
              </Grid>
              <Grid item xs={12} sm={6}>
                <TextField
                  label="Inscrição Municipal"
                  fullWidth
                  value={prestador.inscricaoMunicipal}
                  onChange={(e) => setPrestador({ ...prestador, inscricaoMunicipal: e.target.value })}
                />
              </Grid>
              <Grid item xs={12} sm={8}>
                <TextField
                  label="Endereço"
                  fullWidth
                  value={prestador.endereco}
                  onChange={(e) => setPrestador({ ...prestador, endereco: e.target.value })}
                />
              </Grid>
              <Grid item xs={12} sm={4}>
                <TextField
                  label="CEP"
                  fullWidth
                  value={prestador.cep}
                  onChange={(e) => setPrestador({ ...prestador, cep: aplicarMascaraCEP(e.target.value) })}
                  error={isCepIncompleto(prestador.cep)}
                  helperText={isCepIncompleto(prestador.cep) ? 'CEP incompleto. Use 8 dígitos.' : 'Formato: 00000-000'}
                />
              </Grid>
              <Grid item xs={12} sm={6}>
                <TextField
                  label="Município"
                  fullWidth
                  value={prestador.municipio}
                  onChange={(e) => setPrestador({ ...prestador, municipio: e.target.value })}
                />
              </Grid>
              <Grid item xs={12} sm={2}>
                <TextField
                  label="UF"
                  fullWidth
                  value={prestador.uf}
                  onChange={(e) => setPrestador({ ...prestador, uf: e.target.value.toUpperCase() })}
                />
              </Grid>
              <Grid item xs={12} sm={4}>
                <TextField
                  label="Telefone"
                  fullWidth
                  value={prestador.telefone}
                  onChange={(e) => setPrestador({ ...prestador, telefone: aplicarMascaraTelefone(e.target.value) })}
                  error={isTelefoneIncompleto(prestador.telefone)}
                  helperText={isTelefoneIncompleto(prestador.telefone) ? 'Telefone incompleto. Use DDD + número.' : 'Formato: (00) 0000-0000 ou (00) 00000-0000'}
                />
              </Grid>
            </Grid>

            <Divider />

            <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 1 }}>
              <Typography variant="subtitle2" color="primary">
                Município/Órgão Beneficiado
              </Typography>
              <Button
                variant="outlined"
                size="small"
                startIcon={<Refresh />}
                onClick={() => setPrefeituraBeneficiada(DEFAULT_PREFEITURA_CURIMATA)}
              >
                Restaurar Curimatá-PI
              </Button>
            </Box>

            <Grid container spacing={2}>
              <Grid item xs={12} sm={8}>
                <TextField
                  label="Órgão Beneficiado *"
                  fullWidth
                  value={prefeituraBeneficiada.razaoSocial}
                  onChange={(e) => setPrefeituraBeneficiada({ ...prefeituraBeneficiada, razaoSocial: e.target.value })}
                />
              </Grid>
              <Grid item xs={12} sm={4}>
                <TextField
                  label="CNPJ"
                  fullWidth
                  value={prefeituraBeneficiada.cnpj}
                  onChange={(e) => setPrefeituraBeneficiada({ ...prefeituraBeneficiada, cnpj: e.target.value })}
                />
              </Grid>
              <Grid item xs={12} sm={8}>
                <TextField
                  label="Endereço"
                  fullWidth
                  value={prefeituraBeneficiada.endereco}
                  onChange={(e) => setPrefeituraBeneficiada({ ...prefeituraBeneficiada, endereco: e.target.value })}
                />
              </Grid>
              <Grid item xs={12} sm={4}>
                <TextField
                  label="CEP"
                  fullWidth
                  value={prefeituraBeneficiada.cep}
                  onChange={(e) => setPrefeituraBeneficiada({ ...prefeituraBeneficiada, cep: aplicarMascaraCEP(e.target.value) })}
                  error={isCepIncompleto(prefeituraBeneficiada.cep)}
                  helperText={isCepIncompleto(prefeituraBeneficiada.cep) ? 'CEP incompleto. Use 8 dígitos.' : 'Formato: 00000-000'}
                />
              </Grid>
              <Grid item xs={12} sm={6}>
                <TextField
                  label="Município"
                  fullWidth
                  value={prefeituraBeneficiada.municipio}
                  onChange={(e) => setPrefeituraBeneficiada({ ...prefeituraBeneficiada, municipio: e.target.value })}
                />
              </Grid>
              <Grid item xs={12} sm={2}>
                <TextField
                  label="UF"
                  fullWidth
                  value={prefeituraBeneficiada.uf}
                  onChange={(e) => setPrefeituraBeneficiada({ ...prefeituraBeneficiada, uf: e.target.value.toUpperCase() })}
                />
              </Grid>
              <Grid item xs={12} sm={4}>
                <TextField
                  label="Telefone"
                  fullWidth
                  value={prefeituraBeneficiada.telefone}
                  onChange={(e) => setPrefeituraBeneficiada({ ...prefeituraBeneficiada, telefone: aplicarMascaraTelefone(e.target.value) })}
                  error={isTelefoneIncompleto(prefeituraBeneficiada.telefone)}
                  helperText={isTelefoneIncompleto(prefeituraBeneficiada.telefone) ? 'Telefone incompleto. Use DDD + número.' : 'Formato: (00) 0000-0000 ou (00) 00000-0000'}
                />
              </Grid>
            </Grid>

            <Divider />

            <Typography variant="subtitle2" color="primary">Dados do Tomador (Escola)</Typography>
            <FormControl fullWidth>
              <InputLabel>Selecione a Escola *</InputLabel>
              <Select
                value={formData.instituicaoClienteId}
                label="Selecione a Escola *"
                onChange={(e) => setFormData({ ...formData, instituicaoClienteId: e.target.value })}
              >
                {instituicoesTomadoras.map((inst) => (
                  <MenuItem key={inst.id} value={inst.id}>
                    {inst.nomeInstituicao} - {inst.cidade}/{inst.estado}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>

            <Divider />

            <Typography variant="subtitle2" color="primary">Dados do Serviço</Typography>
            <Grid container spacing={2}>
              <Grid item xs={12} sm={4}>
                <TextField
                  label="Série"
                  fullWidth
                  value={formData.serie}
                  onChange={(e) => setFormData({ ...formData, serie: e.target.value })}
                />
              </Grid>
              <Grid item xs={12} sm={4}>
                <TextField
                  label="Competência (AAAA-MM) *"
                  fullWidth
                  type="month"
                  value={formData.competencia}
                  onChange={(e) => setFormData({ ...formData, competencia: e.target.value })}
                  InputLabelProps={{ shrink: true }}
                />
              </Grid>
              <Grid item xs={12} sm={4}>
                <TextField
                  label="Código do Serviço"
                  fullWidth
                  value={formData.codigoServico}
                  onChange={(e) => setFormData({ ...formData, codigoServico: e.target.value })}
                />
              </Grid>
            </Grid>

            <TextField
              label="Natureza da Operação"
              fullWidth
              value={formData.naturezaOperacao}
              onChange={(e) => setFormData({ ...formData, naturezaOperacao: e.target.value })}
            />

            <TextField
              label="Descrição do Serviço *"
              fullWidth
              multiline
              rows={3}
              value={formData.descricaoServico}
              onChange={(e) => setFormData({ ...formData, descricaoServico: e.target.value })}
              placeholder="Ex: Licença mensal do sistema CEI - Controle Escolar Inteligente - Plano Premium"
            />

            <Grid container spacing={2}>
              <Grid item xs={12} sm={6}>
                <TextField
                  label="Valor do Serviço (R$) *"
                  fullWidth
                  type="number"
                  value={formData.valorServico}
                  onChange={(e) => setFormData({ ...formData, valorServico: parseFloat(e.target.value) || 0 })}
                  inputProps={{ step: 0.01, min: 0 }}
                />
              </Grid>
              <Grid item xs={12} sm={6}>
                <TextField
                  label="Alíquota ISS (%)"
                  fullWidth
                  type="number"
                  value={formData.aliquotaISS}
                  onChange={(e) => setFormData({ ...formData, aliquotaISS: parseFloat(e.target.value) || 0 })}
                  inputProps={{ step: 0.1, min: 0, max: 100 }}
                  helperText="Defina conforme regra municipal"
                />
              </Grid>
            </Grid>

            {formData.valorServico > 0 && (
              <Box sx={{ p: 2, bgcolor: '#e3f2fd', borderRadius: 1 }}>
                <Typography><strong>Valor do Serviço:</strong> {formatarValor(formData.valorServico)}</Typography>
                <Typography><strong>ISS ({formData.aliquotaISS}%):</strong> {formatarValor(valorISS)}</Typography>
                <Typography variant="h6" color="primary">
                  <strong>Valor Líquido:</strong> {formatarValor(valorLiquido)}
                </Typography>
              </Box>
            )}

            <TextField
              label="Observações"
              fullWidth
              multiline
              rows={2}
              value={formData.observacoes}
              onChange={(e) => setFormData({ ...formData, observacoes: e.target.value })}
            />
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClose}>Cancelar</Button>
          <Button 
            variant="contained" 
            onClick={handleSubmit}
            startIcon={<Receipt />}
            disabled={emissaoBloqueada}
          >
            Emitir Nota Fiscal
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog open={openTesteEmail} onClose={() => setOpenTesteEmail(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Testar envio de e-mails</DialogTitle>
        <DialogContent>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 1 }}>
            <Alert severity="info">
              Este teste envia confirmação para o e-mail informado e para o e-mail do proprietário configurado no backend.
            </Alert>
            <TextField
              label="E-mail do comprador *"
              type="email"
              fullWidth
              value={testeEmailData.compradorEmail}
              onChange={(e) => setTesteEmailData({ ...testeEmailData, compradorEmail: e.target.value })}
            />
            <TextField
              label="Nome do comprador"
              fullWidth
              value={testeEmailData.compradorNome}
              onChange={(e) => setTesteEmailData({ ...testeEmailData, compradorNome: e.target.value })}
            />
            <TextField
              label="Instituição"
              fullWidth
              value={testeEmailData.instituicaoNome}
              onChange={(e) => setTesteEmailData({ ...testeEmailData, instituicaoNome: e.target.value })}
            />
            <TextField
              label="Plano"
              fullWidth
              value={testeEmailData.planoNome}
              onChange={(e) => setTesteEmailData({ ...testeEmailData, planoNome: e.target.value })}
            />
            <TextField
              label="Valor (R$)"
              type="number"
              fullWidth
              value={testeEmailData.valor}
              onChange={(e) => setTesteEmailData({ ...testeEmailData, valor: parseFloat(e.target.value) || 0 })}
              inputProps={{ step: 0.01, min: 0 }}
            />
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenTesteEmail(false)}>Fechar</Button>
          <Button variant="contained" onClick={enviarTesteEmail} disabled={enviandoTesteEmail}>
            {enviandoTesteEmail ? 'Enviando...' : 'Enviar teste'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Modal de Visualização/Impressão */}
      {notaSelecionada && (
        <Dialog 
          open={visualizarOpen} 
          onClose={() => setVisualizarOpen(false)} 
          maxWidth="md" 
          fullWidth
        >
          <DialogTitle>
            <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }} className="no-print">
              <span>Nota Fiscal de Serviço Nº {notaSelecionada.numero}</span>
              <Button startIcon={<Print />} onClick={() => imprimirEscopo()} variant="outlined">
                Imprimir
              </Button>
            </Box>
          </DialogTitle>
          <DialogContent>
            <Box
              className="print-scope"
              sx={{
                p: 4,
                fontFamily: 'Arial, sans-serif',
                '@media print': {
                  p: 6
                }
              }}
            >
              <Typography variant="h4" align="center" gutterBottom sx={{ fontWeight: 'bold' }}>
                NOTA FISCAL DE SERVIÇO
              </Typography>
              <Typography variant="h6" align="center" color="primary" gutterBottom>
                Nº {notaSelecionada.numero}
              </Typography>
              
              <Divider sx={{ my: 2 }} />

              <Typography variant="caption" color="text.secondary">
                Data de Emissão: {new Date(notaSelecionada.dataEmissao).toLocaleDateString('pt-BR')}
              </Typography>
              <Typography variant="caption" color="text.secondary" display="block">
                Competência: {formatarCompetencia(notaSelecionada.competencia)} | Série: {notaSelecionada.serie || 'A1'}
              </Typography>
              <Typography variant="caption" color="text.secondary" display="block">
                Chave de Controle: {notaSelecionada.chaveControle}
              </Typography>

              <Box sx={{ mt: 3 }}>
                <Typography variant="h6" gutterBottom>PRESTADOR DO SERVIÇO</Typography>
                <Box sx={{ p: 2, border: '1px solid #ccc', borderRadius: 1 }}>
                  <Typography><strong>Razão Social:</strong> {notaSelecionada.prestadorNome}</Typography>
                  {notaSelecionada.prestadorNomeFantasia && <Typography><strong>Nome Fantasia:</strong> {notaSelecionada.prestadorNomeFantasia}</Typography>}
                  <Typography><strong>{notaSelecionada.prestadorDocumentoTipo || 'CNPJ'}:</strong> {notaSelecionada.prestadorDocumento || notaSelecionada.prestadorCnpj || '-'}</Typography>
                  {notaSelecionada.prestadorInscricaoMunicipal && <Typography><strong>Inscrição Municipal:</strong> {notaSelecionada.prestadorInscricaoMunicipal}</Typography>}
                  <Typography><strong>Endereço:</strong> {notaSelecionada.prestadorEndereco || '-'}</Typography>
                  <Typography><strong>Município:</strong> {notaSelecionada.prestadorCidade || '-'} - {notaSelecionada.prestadorEstado || '-'}</Typography>
                  {notaSelecionada.prestadorCep && <Typography><strong>CEP:</strong> {notaSelecionada.prestadorCep}</Typography>}
                  {notaSelecionada.prestadorTelefone && <Typography><strong>Telefone:</strong> {notaSelecionada.prestadorTelefone}</Typography>}
                  {notaSelecionada.prestadorEmail && <Typography><strong>E-mail:</strong> {notaSelecionada.prestadorEmail}</Typography>}
                </Box>
              </Box>

              <Box sx={{ mt: 3 }}>
                <Typography variant="h6" gutterBottom>ÓRGÃO BENEFICIADO / MUNICÍPIO</Typography>
                <Box sx={{ p: 2, border: '1px solid #ccc', borderRadius: 1 }}>
                  <Typography><strong>Órgão:</strong> {notaSelecionada.beneficiarioRazaoSocial || '-'}</Typography>
                  <Typography><strong>CNPJ:</strong> {notaSelecionada.beneficiarioCnpj || '-'}</Typography>
                  <Typography><strong>Endereço:</strong> {notaSelecionada.beneficiarioEndereco || '-'}</Typography>
                  <Typography><strong>Município/UF:</strong> {(notaSelecionada.beneficiarioCidade || '-')} - {(notaSelecionada.beneficiarioEstado || '-')}</Typography>
                  {notaSelecionada.beneficiarioCep && <Typography><strong>CEP:</strong> {notaSelecionada.beneficiarioCep}</Typography>}
                  {notaSelecionada.beneficiarioTelefone && <Typography><strong>Telefone:</strong> {notaSelecionada.beneficiarioTelefone}</Typography>}
                  {notaSelecionada.beneficiarioEmail && <Typography><strong>E-mail:</strong> {notaSelecionada.beneficiarioEmail}</Typography>}
                </Box>
              </Box>

              <Box sx={{ mt: 3 }}>
                <Typography variant="h6" gutterBottom>TOMADOR DO SERVIÇO</Typography>
                <Box sx={{ p: 2, border: '1px solid #ccc', borderRadius: 1 }}>
                  <Typography><strong>Razão Social:</strong> {notaSelecionada.clienteNome}</Typography>
                  <Typography><strong>CNPJ:</strong> {notaSelecionada.clienteCnpj || '-'}</Typography>
                  <Typography><strong>Endereço:</strong> {notaSelecionada.clienteEndereco || '-'}</Typography>
                  <Typography><strong>Município/UF:</strong> {(notaSelecionada.clienteCidade || '-')} - {(notaSelecionada.clienteEstado || '-')}</Typography>
                  {notaSelecionada.clienteCep && <Typography><strong>CEP:</strong> {notaSelecionada.clienteCep}</Typography>}
                </Box>
              </Box>

              <Box sx={{ mt: 3 }}>
                <Typography variant="h6" gutterBottom>DISCRIMINAÇÃO DO SERVIÇO</Typography>
                <Box sx={{ p: 2, border: '1px solid #ccc', borderRadius: 1, minHeight: 100 }}>
                  <Typography><strong>Natureza:</strong> {notaSelecionada.naturezaOperacao || '-'}</Typography>
                  <Typography><strong>Código do Serviço:</strong> {notaSelecionada.codigoServico || '-'}</Typography>
                  <Typography>{notaSelecionada.descricaoServico}</Typography>
                </Box>
              </Box>

              <Box sx={{ mt: 3 }}>
                <Typography variant="h6" gutterBottom>VALORES</Typography>
                <TableContainer component={Paper} variant="outlined">
                  <Table size="small">
                    <TableBody>
                      <TableRow>
                        <TableCell><strong>Valor Total do Serviço</strong></TableCell>
                        <TableCell align="right">{formatarValor(notaSelecionada.valorServico)}</TableCell>
                      </TableRow>
                      <TableRow>
                        <TableCell><strong>(-) ISS ({notaSelecionada.aliquotaISS}%)</strong></TableCell>
                        <TableCell align="right">{formatarValor(notaSelecionada.valorISS)}</TableCell>
                      </TableRow>
                      <TableRow>
                        <TableCell><strong>Valor Líquido da Nota</strong></TableCell>
                        <TableCell align="right">
                          <Typography variant="h6" color="primary">
                            {formatarValor(notaSelecionada.valorLiquido)}
                          </Typography>
                        </TableCell>
                      </TableRow>
                    </TableBody>
                  </Table>
                </TableContainer>
              </Box>

              {notaSelecionada.observacoes && (
                <Box sx={{ mt: 3 }}>
                  <Typography variant="h6" gutterBottom>OBSERVAÇÕES</Typography>
                  <Box sx={{ p: 2, border: '1px solid #ccc', borderRadius: 1 }}>
                    <Typography>{notaSelecionada.observacoes}</Typography>
                  </Box>
                </Box>
              )}

              <Box sx={{ mt: 4, p: 2, bgcolor: '#f5f5f5', borderRadius: 1 }}>
                <Typography variant="caption" color="text.secondary">
                  Documento gerado eletronicamente pelo CEI - Controle Escolar Inteligente para gestão administrativa.
                  Para validade fiscal plena, confirme o fluxo oficial de NFS-e do município competente.
                </Typography>
              </Box>
            </Box>
          </DialogContent>
          <DialogActions className="no-print">
            <Button onClick={() => setVisualizarOpen(false)}>Fechar</Button>
          </DialogActions>
        </Dialog>
      )}
    </Layout>
  );
}

import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import {
  Container,
  Paper,
  Typography,
  Box,
  Button,
  Grid,
  Alert,
  Tabs,
  Tab,
  TextField,
  Card,
  CardContent,
  Divider,
  CircularProgress,
  InputAdornment,
  IconButton
} from '@mui/material';
import SchoolIcon from '@mui/icons-material/School';
import PaymentIcon from '@mui/icons-material/Payment';
import PixIcon from '@mui/icons-material/QrCode2';
import CreditCardIcon from '@mui/icons-material/CreditCard';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';
import LockIcon from '@mui/icons-material/Lock';

export default function PagamentoPage() {
  const navigate = useNavigate();
  const location = useLocation();
  const { dadosCadastro, planoSelecionado } = location.state || {};
  
  const [abaAtiva, setAbaAtiva] = useState(0);
  const [processando, setProcessando] = useState(false);
  const [sucesso, setSucesso] = useState(false);
  const [erro, setErro] = useState('');
  
  // Estados PIX
  const [pixQRCode, setPixQRCode] = useState('');
  const [pixCopiaECola, setPixCopiaECola] = useState('');
  const [pixGerado, setPixGerado] = useState(false);
  const [verificandoPagamento, setVerificandoPagamento] = useState(false);
  const [copiado, setCopiado] = useState(false);
  
  // Estados Cartão de Crédito
  const [dadosCartao, setDadosCartao] = useState({
    numero: '',
    nome: '',
    validade: '',
    cvv: '',
    parcelas: 1
  });

  useEffect(() => {
    // Redirecionar se não houver dados de cadastro
    if (!dadosCadastro || !planoSelecionado) {
      navigate('/cadastro-escola');
    }
  }, [dadosCadastro, planoSelecionado, navigate]);

  if (!dadosCadastro || !planoSelecionado) {
    return null;
  }

  const valorTotal = planoSelecionado.valor;
  const valorPorDia = (valorTotal / planoSelecionado.dias).toFixed(2);

  // URL da API (altere quando fizer deploy do backend)
  const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:3001';
  const MERCADOPAGO_PUBLIC_KEY = process.env.REACT_APP_MERCADOPAGO_PUBLIC_KEY || 'APP_USR-7c4ec711-2b61-41f4-93fd-c4a2c8b10672';

  // Gerar PIX
  const gerarPix = async () => {
    setProcessando(true);
    setErro('');
    
    try {
      const response = await fetch(`${API_URL}/api/create-pix-payment`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          amount: valorTotal,
          email: dadosCadastro.email,
          cpf: dadosCadastro.cpfResponsavel.replace(/\D/g, ''),
          nome: dadosCadastro.nomeResponsavel,
          instituicaoId: `INST-${Date.now()}`,
          plano: planoSelecionado.nome
        })
      });

      const data = await response.json();

      if (data.success && data.payment) {
        // QR Code real do Mercado Pago
        setPixQRCode(`data:image/png;base64,${data.payment.qr_code_base64}`);
        setPixCopiaECola(data.payment.qr_code);
        setPixGerado(true);
        
        console.log('✅ PIX gerado com sucesso!');
        console.log('ID do pagamento:', data.payment.id);
        
        // Iniciar verificação do pagamento
        iniciarVerificacaoPagamento(data.payment.id, {
          metodoPagamento: 'pix'
        });
      } else {
        setErro(data.error || 'Erro ao gerar PIX. Tente novamente.');
      }
    } catch (error) {
      console.error('Erro ao gerar PIX:', error);
      setErro('Erro ao conectar com o servidor. Verifique se o backend está rodando.');
    } finally {
      setProcessando(false);
    }
  };

  // Verificar pagamento PIX
  const iniciarVerificacaoPagamento = (paymentId, options = {}) => {
    const { metodoPagamento = 'pix', parcelas = null } = options;
    setVerificandoPagamento(true);
    
    // Verificar a cada 5 segundos
    const intervalo = setInterval(async () => {
      try {
        const response = await fetch(`${API_URL}/api/check-payment/${paymentId}`);
        const data = await response.json();
        
        if (data.success && data.status === 'approved') {
          clearInterval(intervalo);
          setVerificandoPagamento(false);
          setSucesso(true);
          
          console.log('✅ Pagamento aprovado!');
          
          // Redirecionar para página de sucesso
          setTimeout(() => {
            navigate('/pagamento-sucesso', { 
              state: { 
                dadosCadastro, 
                planoSelecionado,
                metodoPagamento,
                parcelas,
                transacaoId: paymentId,
                status: 'approved'
              } 
            });
          }, 2000);
        }
      } catch (error) {
        console.error('Erro ao verificar pagamento:', error);
      }
    }, 5000);

    // Parar verificação após 10 minutos
    setTimeout(() => {
      clearInterval(intervalo);
      setVerificandoPagamento(false);
    }, 600000);
  };

  // Copiar código PIX
  const copiarCodigoPix = () => {
    navigator.clipboard.writeText(pixCopiaECola);
    setCopiado(true);
    setTimeout(() => setCopiado(false), 2000);
  };

  // Processar pagamento com cartão
  const processarPagamentoCartao = async () => {
    setErro('');
    
    console.log('🔍 Validando dados do cartão...');
    
    // Validações
    if (!dadosCartao.numero || dadosCartao.numero.replace(/\s/g, '').length < 16) {
      setErro('Número do cartão inválido (mínimo 16 dígitos)');
      return;
    }
    
    if (!dadosCartao.nome.trim()) {
      setErro('Nome no cartão é obrigatório');
      return;
    }
    
    if (!dadosCartao.validade || dadosCartao.validade.length < 5) {
      setErro('Validade do cartão inválida (formato MM/AA)');
      return;
    }
    
    if (!dadosCartao.cvv || dadosCartao.cvv.length < 3) {
      setErro('CVV inválido (mínimo 3 dígitos)');
      return;
    }
    
    console.log('✅ Validações básicas OK');
    setProcessando(true);
    
    try {
      // Verificar se o SDK do Mercado Pago está carregado
      if (!window.MercadoPago) {
        throw new Error('SDK do Mercado Pago não carregado. Recarregue a página.');
      }

      console.log('✅ SDK do Mercado Pago carregado');

      // Inicializar Mercado Pago
      const mp = new window.MercadoPago(MERCADOPAGO_PUBLIC_KEY);
      
      console.log('✅ MercadoPago inicializado com chave:', MERCADOPAGO_PUBLIC_KEY.substring(0, 15) + '...');
      
      // Separar mês e ano da validade
      const [mes, ano] = dadosCartao.validade.split('/');
      
      console.log('📅 Validade:', { mes, ano: '20' + ano });
      
      // Criar objeto cardForm para tokenizar
      const cardData = {
        cardNumber: dadosCartao.numero.replace(/\s/g, ''),
        cardholderName: dadosCartao.nome.toUpperCase(),
        cardExpirationMonth: mes.padStart(2, '0'),
        cardExpirationYear: '20' + ano,
        securityCode: dadosCartao.cvv,
        identificationType: 'CPF',
        identificationNumber: dadosCadastro.cpfResponsavel.replace(/\D/g, '')
      };

      console.log('🔄 Criando token do cartão...');
      console.log('Dados do cartão (sem número/CVV):', {
        cardholderName: cardData.cardholderName,
        cardExpirationMonth: cardData.cardExpirationMonth,
        cardExpirationYear: cardData.cardExpirationYear,
        identificationType: cardData.identificationType,
        identificationNumber: cardData.identificationNumber
      });

      // Criar token do cartão
      const response = await mp.createCardToken(cardData);
      
      console.log('📦 Resposta do createCardToken:', response);
      
      if (!response || !response.id) {
        throw new Error('Falha ao criar token do cartão. Verifique os dados e tente novamente.');
      }

      console.log('✅ Token do cartão criado:', response.id);

      // Enviar pagamento para o backend
      console.log('📤 Enviando para backend:', `${API_URL}/api/create-card-payment`);
      
      const paymentResponse = await fetch(`${API_URL}/api/create-card-payment`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          cardToken: response.id,
          amount: valorTotal,
          installments: parseInt(dadosCartao.parcelas),
          email: dadosCadastro.email,
          nome: dadosCadastro.nomeResponsavel,
          cpf: dadosCadastro.cpfResponsavel.replace(/\D/g, ''),
          instituicaoId: `INST-${Date.now()}`,
          plano: planoSelecionado.nome
        })
      });

      if (!paymentResponse.ok) {
        throw new Error(`Erro HTTP: ${paymentResponse.status}`);
      }

      const data = await paymentResponse.json();

      console.log('📥 Resposta do backend:', data);

      if (data.success && data.payment.status === 'approved') {
        setSucesso(true);
        console.log('✅ Pagamento processado:', data.payment.status);
        
        // Redirecionar para página de sucesso
        setTimeout(() => {
          navigate('/pagamento-sucesso', { 
            state: { 
              dadosCadastro, 
              planoSelecionado,
              metodoPagamento: 'cartao',
              parcelas: dadosCartao.parcelas,
              transacaoId: data.payment.id,
              status: 'approved'
            } 
          });
        }, 2000);
      } else if (data.success && data.payment.status === 'pending') {
        console.log('⏳ Pagamento pendente. Aguardando confirmação da operadora...');
        setSucesso(true);
        iniciarVerificacaoPagamento(data.payment.id, {
          metodoPagamento: 'cartao',
          parcelas: dadosCartao.parcelas
        });
      } else {
        // Pagamento rejeitado ou erro
        const mensagemErro = data.error || data.payment?.status_detail || 'Pagamento recusado. Verifique os dados do cartão.';
        console.error('❌ Pagamento recusado:', mensagemErro);
        setErro(mensagemErro);
      }
    } catch (error) {
      console.error('❌ Erro ao processar cartão:', error);
      let mensagemErro = 'Erro ao processar pagamento. ';
      
      if (error.message.includes('Failed to fetch') || error.message.includes('NetworkError')) {
        mensagemErro += 'Verifique sua conexão ou se o backend está rodando.';
      } else if (error.message.includes('token')) {
        mensagemErro += 'Erro ao validar dados do cartão.';
      } else {
        mensagemErro += error.message;
      }
      
      setErro(mensagemErro);
    } finally {
      setProcessando(false);
    }
  };

  // Máscaras de input
  const aplicarMascaraCartao = (valor) => {
    valor = valor.replace(/\D/g, '');
    valor = valor.replace(/(\d{4})(\d)/, '$1 $2');
    valor = valor.replace(/(\d{4})(\d)/, '$1 $2');
    valor = valor.replace(/(\d{4})(\d)/, '$1 $2');
    return valor.substring(0, 19);
  };

  const aplicarMascaraValidade = (valor) => {
    valor = valor.replace(/\D/g, '');
    valor = valor.replace(/(\d{2})(\d)/, '$1/$2');
    return valor.substring(0, 5);
  };

  const aplicarMascaraCVV = (valor) => {
    return valor.replace(/\D/g, '').substring(0, 4);
  };

  const handleChangeCartao = (campo, valor) => {
    if (campo === 'numero') {
      valor = aplicarMascaraCartao(valor);
    } else if (campo === 'validade') {
      valor = aplicarMascaraValidade(valor);
    } else if (campo === 'cvv') {
      valor = aplicarMascaraCVV(valor);
    } else if (campo === 'nome') {
      valor = valor.toUpperCase();
    }
    
    setDadosCartao({ ...dadosCartao, [campo]: valor });
  };

  // Calcular opções de parcelamento
  const opcoesParcelamento = [];
  for (let i = 1; i <= 12; i++) {
    const valorParcela = (valorTotal / i).toFixed(2);
    opcoesParcelamento.push({
      numero: i,
      valor: valorParcela,
      label: i === 1 
        ? `À vista - R$ ${valorTotal.toFixed(2)}` 
        : `${i}x de R$ ${valorParcela} ${i > 3 ? '(com juros)' : 'sem juros'}`
    });
  }

  if (sucesso) {
    return (
      <Container maxWidth="sm">
        <Box sx={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', py: 4 }}>
          <Paper elevation={3} sx={{ p: 4, width: '100%', textAlign: 'center' }}>
            <CheckCircleIcon sx={{ fontSize: 80, color: 'success.main', mb: 2 }} />
            <Typography variant="h4" gutterBottom color="success.main">
              Pagamento Processado!
            </Typography>
            <Typography variant="body1" color="text.secondary" sx={{ mb: 3 }}>
              Aguardando confirmação da operadora...
            </Typography>
            <CircularProgress />
          </Paper>
        </Box>
      </Container>
    );
  }

  return (
    <Container maxWidth="md">
      <Box sx={{ minHeight: '100vh', py: 4 }}>
        <Paper elevation={3} sx={{ p: 4 }}>
          {/* Cabeçalho */}
          <Box sx={{ textAlign: 'center', mb: 3 }}>
            <SchoolIcon sx={{ fontSize: 60, color: 'primary.main', mb: 2 }} />
            <Typography variant="h4" gutterBottom>
              Finalizar Pagamento
            </Typography>
            <Typography variant="subtitle1" color="text.secondary">
              Sistema CEI - Controle Escolar Inteligente - Gerenciamento de Biblioteca
            </Typography>
          </Box>

          {/* Resumo do Pedido */}
          <Card variant="outlined" sx={{ mb: 3, bgcolor: 'grey.50' }}>
            <CardContent>
              <Typography variant="h6" gutterBottom color="primary">
                📋 Resumo do Pedido
              </Typography>
              <Divider sx={{ my: 2 }} />
              <Grid container spacing={2}>
                <Grid item xs={12}>
                  <Typography variant="body2">
                    <strong>Instituição:</strong> {dadosCadastro.nomeInstituicao}
                  </Typography>
                </Grid>
                <Grid item xs={12}>
                  <Typography variant="body2">
                    <strong>Plano:</strong> {planoSelecionado.nome}
                  </Typography>
                </Grid>
                <Grid item xs={12} sm={6}>
                  <Typography variant="body2">
                    <strong>Duração:</strong> {planoSelecionado.dias} dias
                  </Typography>
                </Grid>
                <Grid item xs={12} sm={6}>
                  <Typography variant="body2">
                    <strong>Valor por dia:</strong> R$ {valorPorDia}
                  </Typography>
                </Grid>
                <Grid item xs={12}>
                  <Divider sx={{ my: 1 }} />
                  <Typography variant="h6" color="primary" sx={{ textAlign: 'right' }}>
                    Total: R$ {valorTotal.toFixed(2)}
                  </Typography>
                </Grid>
              </Grid>
            </CardContent>
          </Card>

          {/* Métodos de Pagamento */}
          <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 3 }}>
            <Tabs value={abaAtiva} onChange={(e, newValue) => setAbaAtiva(newValue)}>
              <Tab 
                icon={<PixIcon />} 
                label="PIX" 
                iconPosition="start"
              />
              <Tab 
                icon={<CreditCardIcon />} 
                label="Cartão de Crédito" 
                iconPosition="start"
              />
            </Tabs>
          </Box>

          {erro && (
            <Alert severity="error" sx={{ mb: 2 }} onClose={() => setErro('')}>
              {erro}
            </Alert>
          )}

          {/* Aba PIX */}
          {abaAtiva === 0 && (
            <Box>
              <Alert severity="info" sx={{ mb: 3 }}>
                <Typography variant="body2">
                  <strong>Pagamento via PIX</strong><br />
                  Aprovação instantânea após a confirmação do pagamento
                </Typography>
              </Alert>

              {!pixGerado ? (
                <Box sx={{ textAlign: 'center', py: 4 }}>
                  <PixIcon sx={{ fontSize: 80, color: 'primary.main', mb: 2 }} />
                  <Typography variant="body1" sx={{ mb: 3 }}>
                    Clique no botão abaixo para gerar o código PIX
                  </Typography>
                  <Button
                    variant="contained"
                    size="large"
                    startIcon={<PaymentIcon />}
                    onClick={gerarPix}
                    disabled={processando}
                  >
                    {processando ? 'Gerando PIX...' : 'Gerar Código PIX'}
                  </Button>
                </Box>
              ) : (
                <Box>
                  <Grid container spacing={3}>
                    {/* QR Code */}
                    <Grid item xs={12} md={6}>
                      <Card variant="outlined">
                        <CardContent sx={{ textAlign: 'center' }}>
                          <Typography variant="subtitle1" gutterBottom>
                            <strong>Escaneie o QR Code</strong>
                          </Typography>
                          <Box sx={{ 
                            width: 200, 
                            height: 200, 
                            bgcolor: 'white', 
                            display: 'flex', 
                            alignItems: 'center', 
                            justifyContent: 'center',
                            mx: 'auto',
                            my: 2,
                            border: 2,
                            borderColor: 'primary.main',
                            borderRadius: 2,
                            overflow: 'hidden'
                          }}>
                            {pixQRCode ? (
                              <img 
                                src={pixQRCode} 
                                alt="QR Code PIX" 
                                style={{ width: '100%', height: '100%', objectFit: 'contain' }}
                              />
                            ) : (
                              <PixIcon sx={{ fontSize: 100, color: 'primary.main' }} />
                            )}
                          </Box>
                          <Typography variant="caption" color="text.secondary">
                            Abra o aplicativo do seu banco e escaneie o código
                          </Typography>
                        </CardContent>
                      </Card>
                    </Grid>

                    {/* Copia e Cola */}
                    <Grid item xs={12} md={6}>
                      <Card variant="outlined">
                        <CardContent>
                          <Typography variant="subtitle1" gutterBottom>
                            <strong>Ou use o código PIX:</strong>
                          </Typography>
                          <TextField
                            fullWidth
                            multiline
                            rows={4}
                            value={pixCopiaECola}
                            InputProps={{
                              readOnly: true,
                              endAdornment: (
                                <InputAdornment position="end">
                                  <IconButton onClick={copiarCodigoPix}>
                                    <ContentCopyIcon />
                                  </IconButton>
                                </InputAdornment>
                              ),
                            }}
                            sx={{ mb: 2 }}
                          />
                          <Button
                            fullWidth
                            variant="contained"
                            startIcon={<ContentCopyIcon />}
                            onClick={copiarCodigoPix}
                          >
                            {copiado ? 'Código Copiado!' : 'Copiar Código'}
                          </Button>
                          
                          {verificandoPagamento && (
                            <Box sx={{ mt: 3, textAlign: 'center' }}>
                              <CircularProgress size={24} sx={{ mb: 1 }} />
                              <Typography variant="caption" display="block" color="text.secondary">
                                Aguardando confirmação do pagamento...
                              </Typography>
                            </Box>
                          )}
                        </CardContent>
                      </Card>
                    </Grid>

                    {/* Instruções */}
                    <Grid item xs={12}>
                      <Alert severity="warning">
                        <Typography variant="body2" gutterBottom>
                          <strong>Como pagar:</strong>
                        </Typography>
                        <Typography variant="body2" component="div">
                          1. Abra o aplicativo do seu banco<br />
                          2. Escolha pagar via PIX<br />
                          3. Escaneie o QR Code ou cole o código<br />
                          4. Confirme o pagamento<br />
                          5. Pronto! Seu acesso será liberado automaticamente
                        </Typography>
                      </Alert>
                    </Grid>
                  </Grid>

                  <Box sx={{ mt: 3, textAlign: 'center' }}>
                    <Button
                      variant="outlined"
                      onClick={() => setPixGerado(false)}
                    >
                      Gerar Novo Código
                    </Button>
                  </Box>
                </Box>
              )}
            </Box>
          )}

          {/* Aba Cartão */}
          {abaAtiva === 1 && (
            <Box>
              <Alert severity="info" sx={{ mb: 3 }}>
                <Typography variant="body2">
                  <strong>Pagamento via Cartão de Crédito</strong><br />
                  Parcelamento em até 12x • Aprovação em até 2 minutos
                </Typography>
              </Alert>

              <Grid container spacing={2}>
                <Grid item xs={12}>
                  <TextField
                    label="Número do Cartão"
                    fullWidth
                    required
                    value={dadosCartao.numero}
                    onChange={(e) => handleChangeCartao('numero', e.target.value)}
                    placeholder="0000 0000 0000 0000"
                    InputProps={{
                      startAdornment: (
                        <InputAdornment position="start">
                          <CreditCardIcon />
                        </InputAdornment>
                      ),
                    }}
                  />
                </Grid>

                <Grid item xs={12}>
                  <TextField
                    label="Nome no Cartão"
                    fullWidth
                    required
                    value={dadosCartao.nome}
                    onChange={(e) => handleChangeCartao('nome', e.target.value)}
                    placeholder="NOME COMO ESTÁ NO CARTÃO"
                  />
                </Grid>

                <Grid item xs={12} sm={6}>
                  <TextField
                    label="Validade"
                    fullWidth
                    required
                    value={dadosCartao.validade}
                    onChange={(e) => handleChangeCartao('validade', e.target.value)}
                    placeholder="MM/AA"
                  />
                </Grid>

                <Grid item xs={12} sm={6}>
                  <TextField
                    label="CVV"
                    fullWidth
                    required
                    value={dadosCartao.cvv}
                    onChange={(e) => handleChangeCartao('cvv', e.target.value)}
                    placeholder="123"
                    type="password"
                    autoComplete="cc-csc"
                    InputProps={{
                      startAdornment: (
                        <InputAdornment position="start">
                          <LockIcon />
                        </InputAdornment>
                      ),
                    }}
                  />
                </Grid>

                <Grid item xs={12}>
                  <TextField
                    select
                    label="Parcelamento"
                    fullWidth
                    required
                    value={dadosCartao.parcelas}
                    onChange={(e) => handleChangeCartao('parcelas', e.target.value)}
                    SelectProps={{
                      native: true,
                    }}
                  >
                    {opcoesParcelamento.map((opcao) => (
                      <option key={opcao.numero} value={opcao.numero}>
                        {opcao.label}
                      </option>
                    ))}
                  </TextField>
                </Grid>

                <Grid item xs={12}>
                  <Alert severity="success">
                    <Typography variant="body2">
                      <LockIcon sx={{ fontSize: 16, verticalAlign: 'middle', mr: 1 }} />
                      Pagamento 100% seguro e criptografado
                    </Typography>
                  </Alert>
                </Grid>

                <Grid item xs={12}>
                  <Button
                    fullWidth
                    variant="contained"
                    size="large"
                    onClick={processarPagamentoCartao}
                    disabled={processando}
                    startIcon={processando ? <CircularProgress size={20} /> : <PaymentIcon />}
                  >
                    {processando ? 'Processando...' : `Pagar R$ ${valorTotal.toFixed(2)}`}
                  </Button>
                </Grid>
              </Grid>
            </Box>
          )}

          {/* Rodapé */}
          <Box sx={{ mt: 4, pt: 3, borderTop: 1, borderColor: 'divider' }}>
            <Alert severity="info" icon={<LockIcon />}>
              <Typography variant="caption">
                Seus dados estão protegidos com criptografia de ponta a ponta. 
                Não armazenamos dados sensíveis do cartão.
              </Typography>
            </Alert>
            
            <Box sx={{ textAlign: 'center', mt: 3 }}>
              <Button
                variant="text"
                onClick={() => navigate('/cadastro-escola')}
              >
                ← Voltar para o cadastro
              </Button>
            </Box>
          </Box>

          {/* Marca Registrada */}
          <Box sx={{ mt: 3, pt: 2, borderTop: 1, borderColor: 'divider', textAlign: 'center' }}>
            <Typography variant="caption" color="text.secondary" display="block">
              © {new Date().getFullYear()} CEI - Sistema desenvolvido por
            </Typography>
            <Typography variant="caption" color="primary" display="block" fontWeight="bold">
              Wander Pires Silva Coelho ®
            </Typography>
          </Box>
        </Paper>
      </Box>
    </Container>
  );
}

import React, { useState } from 'react';
import Layout from '../components/Layout';
import {
  Box,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  Chip,
  Typography,
  MenuItem
} from '@mui/material';
import { Add, Edit, Delete, Search } from '@mui/icons-material';
import { useData } from '../context/DataContext';

function PatrimonioPage() {
  const { patrimonio, adicionarPatrimonio, atualizarPatrimonio, removerPatrimonio } = useData();
  const [open, setOpen] = useState(false);
  const [editando, setEditando] = useState(null);
  const [busca, setBusca] = useState('');
  const [formData, setFormData] = useState({
    numeroPatrimonio: '',
    descricao: '',
    categoria: '',
    marca: '',
    modelo: '',
    dataAquisicao: '',
    valorAquisicao: '',
    estado: 'Bom',
    localizacao: '',
    observacoes: ''
  });

  const estadosDisponiveis = ['Novo', 'Bom', 'Regular', 'Ruim', 'Descartado'];
  const categoriasDisponiveis = ['Eletrônico', 'Mobiliário', 'Equipamento', 'Material', 'Outro'];

  const handleOpen = (bem = null) => {
    if (bem) {
      setEditando(bem.id);
      setFormData(bem);
    } else {
      setEditando(null);
      setFormData({
        numeroPatrimonio: '',
        descricao: '',
        categoria: '',
        marca: '',
        modelo: '',
        dataAquisicao: '',
        valorAquisicao: '',
        estado: 'Bom',
        localizacao: '',
        observacoes: ''
      });
    }
    setOpen(true);
  };

  const handleClose = () => {
    setOpen(false);
    setEditando(null);
  };

  const handleSubmit = () => {
    if (editando) {
      atualizarPatrimonio(editando, formData);
    } else {
      adicionarPatrimonio(formData);
    }
    handleClose();
  };

  const handleDelete = (id) => {
    if (window.confirm('Deseja realmente remover este bem do patrimônio?')) {
      removerPatrimonio(id);
    }
  };

  const patrimonioFiltrado = patrimonio.filter(bem =>
    bem.descricao.toLowerCase().includes(busca.toLowerCase()) ||
    bem.numeroPatrimonio.includes(busca) ||
    bem.categoria.toLowerCase().includes(busca.toLowerCase())
  );

  const getEstadoColor = (estado) => {
    const cores = {
      'Novo': 'success',
      'Bom': 'primary',
      'Regular': 'warning',
      'Ruim': 'error',
      'Descartado': 'default'
    };
    return cores[estado] || 'default';
  };

  return (
    <Layout title="Patrimônio">
      <Box sx={{ mb: 2, display: 'flex', gap: 2 }}>
        <TextField
          placeholder="Buscar por descrição, número ou categoria..."
          variant="outlined"
          size="small"
          fullWidth
          value={busca}
          onChange={(e) => setBusca(e.target.value)}
          InputProps={{
            startAdornment: <Search sx={{ mr: 1, color: 'text.secondary' }} />
          }}
        />
        <Button
          variant="contained"
          startIcon={<Add />}
          onClick={() => handleOpen()}
        >
          Novo Bem
        </Button>
      </Box>

      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Nº Patrimônio</TableCell>
              <TableCell>Descrição</TableCell>
              <TableCell>Categoria</TableCell>
              <TableCell>Estado</TableCell>
              <TableCell>Localização</TableCell>
              <TableCell>Ações</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {patrimonioFiltrado.length === 0 ? (
              <TableRow>
                <TableCell colSpan={6} align="center">
                  <Typography color="text.secondary">
                    Nenhum bem cadastrado no patrimônio
                  </Typography>
                </TableCell>
              </TableRow>
            ) : (
              patrimonioFiltrado.map((bem) => (
                <TableRow key={bem.id}>
                  <TableCell>{bem.numeroPatrimonio}</TableCell>
                  <TableCell>{bem.descricao}</TableCell>
                  <TableCell>
                    <Chip label={bem.categoria} size="small" />
                  </TableCell>
                  <TableCell>
                    <Chip 
                      label={bem.estado} 
                      size="small" 
                      color={getEstadoColor(bem.estado)} 
                    />
                  </TableCell>
                  <TableCell>{bem.localizacao}</TableCell>
                  <TableCell>
                    <IconButton onClick={() => handleOpen(bem)} size="small">
                      <Edit />
                    </IconButton>
                    <IconButton onClick={() => handleDelete(bem.id)} size="small" color="error">
                      <Delete />
                    </IconButton>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </TableContainer>

      <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
        <DialogTitle>{editando ? 'Editar Bem' : 'Novo Bem'}</DialogTitle>
        <DialogContent>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 1 }}>
            <TextField
              label="Número do Patrimônio"
              fullWidth
              required
              value={formData.numeroPatrimonio}
              onChange={(e) => setFormData({ ...formData, numeroPatrimonio: e.target.value })}
            />
            <TextField
              label="Descrição"
              fullWidth
              required
              value={formData.descricao}
              onChange={(e) => setFormData({ ...formData, descricao: e.target.value })}
            />
            <TextField
              label="Categoria"
              fullWidth
              select
              required
              value={formData.categoria}
              onChange={(e) => setFormData({ ...formData, categoria: e.target.value })}
            >
              {categoriasDisponiveis.map((cat) => (
                <MenuItem key={cat} value={cat}>{cat}</MenuItem>
              ))}
            </TextField>
            <TextField
              label="Marca"
              fullWidth
              value={formData.marca}
              onChange={(e) => setFormData({ ...formData, marca: e.target.value })}
            />
            <TextField
              label="Modelo"
              fullWidth
              value={formData.modelo}
              onChange={(e) => setFormData({ ...formData, modelo: e.target.value })}
            />
            <TextField
              label="Data de Aquisição"
              fullWidth
              type="date"
              InputLabelProps={{ shrink: true }}
              value={formData.dataAquisicao}
              onChange={(e) => setFormData({ ...formData, dataAquisicao: e.target.value })}
            />
            <TextField
              label="Valor de Aquisição"
              fullWidth
              type="number"
              value={formData.valorAquisicao}
              onChange={(e) => setFormData({ ...formData, valorAquisicao: e.target.value })}
            />
            <TextField
              label="Estado"
              fullWidth
              select
              required
              value={formData.estado}
              onChange={(e) => setFormData({ ...formData, estado: e.target.value })}
            >
              {estadosDisponiveis.map((estado) => (
                <MenuItem key={estado} value={estado}>{estado}</MenuItem>
              ))}
            </TextField>
            <TextField
              label="Localização"
              fullWidth
              value={formData.localizacao}
              onChange={(e) => setFormData({ ...formData, localizacao: e.target.value })}
            />
            <TextField
              label="Observações"
              fullWidth
              multiline
              rows={3}
              value={formData.observacoes}
              onChange={(e) => setFormData({ ...formData, observacoes: e.target.value })}
            />
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClose}>Cancelar</Button>
          <Button onClick={handleSubmit} variant="contained">
            {editando ? 'Salvar' : 'Adicionar'}
          </Button>
        </DialogActions>
      </Dialog>
    </Layout>
  );
}

export default PatrimonioPage;

import React, { useMemo, useRef, useState } from 'react';
import Layout from '../components/Layout';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Button,
  TextField,
