const normalizarTexto = (valor) => {
  return String(valor || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ');
};

const escapeHtml = (valor) => String(valor ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const montarTabelaHtmlImpressao = (colunas, dados) => {
  if (!dados || dados.length === 0) {
    return '<p class="vazio">Nenhum dado disponível.</p>';
  }

  const cabecalho = colunas.map((col) => `<th>${escapeHtml(col)}</th>`).join('');
  const linhas = dados.map((row) => {
    const celulas = Object.entries(row)
      .filter(([key]) => !key.startsWith('_'))
      .map(([, valor]) => `<td>${escapeHtml(valor)}</td>`)
      .join('');
    return `<tr>${celulas}</tr>`;
  }).join('');

  return `<table class="dados"><thead><tr>${cabecalho}</tr></thead><tbody>${linhas}</tbody></table>`;
};

const buildLegacyTurmaKey = (serieNome, turmaNome) => {
  return `legacy:${normalizarTexto(serieNome)}|${normalizarTexto(turmaNome)}`;
};

const isAlunoRelatorio = (cliente) => {
  const tipoNormalizado = normalizarTexto(cliente?.tipo);
  const categoriaNormalizada = normalizarTexto(cliente?.categoria);

  const possuiVinculoAcademico =
    String(cliente?.turmaId || '').trim().length > 0
    || String(cliente?.serieId || '').trim().length > 0
    || normalizarTexto(cliente?.turma).length > 0
    || normalizarTexto(cliente?.nomeTurma).length > 0
    || normalizarTexto(cliente?.serie).length > 0
    || normalizarTexto(cliente?.nomeSerie).length > 0;

  const perfisNaoAluno = [
    'professor',
    'funcionario',
    'funcionario administrativo',
    'bibliotecario',
    'coordenador',
    'diretor',
    'gestor',
    'servidor',
    'admin',
    'administrador',
    'comunidade'
  ];

  if (tipoNormalizado === 'aluno' || categoriaNormalizada === 'estudante') {
    return true;
  }

  if (tipoNormalizado === 'leitor') {
    return possuiVinculoAcademico;
  }

  if (possuiVinculoAcademico) {
    return !perfisNaoAluno.includes(tipoNormalizado) && !perfisNaoAluno.includes(categoriaNormalizada);
  }

  return false;
};

const isClienteAtivoRelatorio = (cliente) => cliente?.ativo !== false;

const obterCategoriaLeitorRelatorio = (cliente) => {
  const tipoNormalizado = normalizarTexto(cliente?.tipo);
  const categoriaNormalizada = normalizarTexto(cliente?.categoria);

  if (isAlunoRelatorio(cliente)) {
    return 'Estudante';
  }

  if (categoriaNormalizada === 'professor' || tipoNormalizado === 'professor') {
    return 'Professor';
  }

  if (categoriaNormalizada === 'comunidade' || tipoNormalizado === 'comunidade') {
    return 'Comunidade';
  }

  const perfisFuncionais = new Set([
    'funcionario',
    'funcionario administrativo',
    'bibliotecario',
    'coordenador',
    'diretor',
    'gestor',
    'servidor',
    'admin',
    'administrador'
  ]);

  if (perfisFuncionais.has(categoriaNormalizada) || perfisFuncionais.has(tipoNormalizado)) {
    return 'Funcionário';
  }

  return String(cliente?.categoria || cliente?.tipo || 'Sem categoria').trim() || 'Sem categoria';
};

const obterChaveTurmaEmprestimo = (emprestimo) => {
  const turmaId = String(emprestimo?.turmaId || '').trim();
  if (turmaId) {
    return turmaId;
  }

  const turmaNome = String(emprestimo?.turmaNome || '').trim();
  if (!turmaNome) {
    return '';
  }

  const serieNome = String(
    emprestimo?.dadosTermoEmprestimo?.leitorSerie || emprestimo?.serieNome || ''
  ).trim();

  return buildLegacyTurmaKey(serieNome, turmaNome);
};

const obterInfoTurmaAluno = (aluno, turmasAcademicasMap) => {
  const turmaId = String(aluno?.turmaId || '');

  if (turmaId && turmasAcademicasMap.has(turmaId)) {
    const turma = turmasAcademicasMap.get(turmaId);
    const nomeTurma = String(turma?.nomeTurma || '').trim() || 'N/A';
    const nomeSerie = String(turma?.nomeSerie || '').trim() || 'N/A';

    return {
      key: turmaId,
      nomeTurma,
      nomeSerie,
      label: nomeSerie !== 'N/A' ? `${nomeSerie} - ${nomeTurma}` : nomeTurma
    };
  }

  const nomeTurmaLegacy = String(aluno?.turma || '').trim();
  if (!nomeTurmaLegacy) {
    return {
      key: '',
      nomeTurma: '',
      nomeSerie: '',
      label: ''
    };
  }

  const nomeSerieLegacy = String(aluno?.serie || '').trim();

  return {
    key: buildLegacyTurmaKey(nomeSerieLegacy, nomeTurmaLegacy),
    nomeTurma: nomeTurmaLegacy,
    nomeSerie: nomeSerieLegacy || 'N/A',
    label: nomeSerieLegacy ? `${nomeSerieLegacy} - ${nomeTurmaLegacy}` : nomeTurmaLegacy
  };
};

function RelatoriosPage() {
  const { 
    livros, 
    patrimonio, 
    clientes, 
    emprestimos, 
    instituicoes,
    turmasAcademicas,
    usuarioLogado,
    instituicaoAtiva,
    atualizarInstituicao,
    removerEmprestimo
  } = useData();

  const [tipoRelatorio, setTipoRelatorio] = useState('livros-cadastrados');
  const [dialogConfig, setDialogConfig] = useState(false);
  const [detalheEmprestimos, setDetalheEmprestimos] = useState(null);
  const [confirmarExclusao, setConfirmarExclusao] = useState(null);
  const [configCabecalho, setConfigCabecalho] = useState({
    titulo: '',
    subtitulo: '',
    logoUrl: ''
  });
  const logoInputRef = useRef(null);
  // Guarda para qual instituição já inicializamos o cabeçalho,
  // evitando que o sync periódico apague o que o usuário digitou.
  const cabecalhoInitForRef = useRef(null);

  // Carregar configuração salva da instituição — somente uma vez por instituição ativa
  React.useEffect(() => {
    if (cabecalhoInitForRef.current === instituicaoAtiva) return;
    const instituicao = instituicoes.find(i => i.id === instituicaoAtiva);
    if (!instituicao) return;
    cabecalhoInitForRef.current = instituicaoAtiva;
    if (instituicao.configRelatorios) {
      const logoFallback = instituicao.configRelatorios.logoUrl || instituicao.logoCabecalho || instituicao.logoEscola || '';
      setConfigCabecalho({ ...instituicao.configRelatorios, logoUrl: logoFallback });
    } else {
      setConfigCabecalho({
        titulo: instituicao.nomeInstituicao || '',
        subtitulo: `${instituicao.cidade || ''}, ${instituicao.estado || ''}`,
        logoUrl: instituicao.logoCabecalho || instituicao.logoEscola || instituicao.logoUrl || ''
      });
    }
  }, [instituicaoAtiva, instituicoes]);

  const isEmprestimoAtivo = (status) => {
    const statusNormalizado = String(status || '').toLowerCase();
    return statusNormalizado === 'ativo' || statusNormalizado === 'emprestado';
  };

  const livrosDidaticosAtivos = useMemo(() => {
    return livros.filter((livro) => livro.tipo === 'Didático' && !livro.baixa);
  }, [livros]);

  const livroDidaticoMap = useMemo(() => {
    const map = new Map();
    livrosDidaticosAtivos.forEach((livro) => map.set(String(livro.id), livro));
    return map;
  }, [livrosDidaticosAtivos]);

  const turmasAcademicasMap = useMemo(() => {
    const map = new Map();
    turmasAcademicas.forEach((turma) => {
      map.set(String(turma.id), turma);
    });
    return map;
  }, [turmasAcademicas]);

  const alunosComTurma = useMemo(() => {
    return clientes
      .filter((cliente) => isAlunoRelatorio(cliente))
      .filter((cliente) => {
        const infoTurma = obterInfoTurmaAluno(cliente, turmasAcademicasMap);
        return infoTurma.key.length > 0;
      });
  }, [clientes, turmasAcademicasMap]);

  const getClienteByEmprestimo = (emprestimo) => {
    const clienteId = String(emprestimo?.clienteId ?? emprestimo?.leitorId ?? '').trim();
    if (!clienteId) {
      return null;
    }

    return clientes.find((cliente) => String(cliente.id) === clienteId) || null;
  };

  const getNomeClienteEmprestimo = (emprestimo, clienteAtual = null) => {
    const cliente = clienteAtual || getClienteByEmprestimo(emprestimo);
    return (
      cliente?.nome
      || emprestimo?.clienteNome
      || emprestimo?.leitorNome
      || emprestimo?.dadosTermoEmprestimo?.leitorNome
      || 'Leitor removido'
    );
  };

  const getTelefoneClienteEmprestimo = (emprestimo, clienteAtual = null) => {
    const cliente = clienteAtual || getClienteByEmprestimo(emprestimo);
    return cliente?.telefone || emprestimo?.dadosTermoEmprestimo?.leitorTelefone || 'N/A';
  };

  const getCpfClienteEmprestimo = (emprestimo, clienteAtual = null) => {
    const cliente = clienteAtual || getClienteByEmprestimo(emprestimo);
    return cliente?.cpf || emprestimo?.dadosTermoEmprestimo?.leitorCPF || 'N/A';
  };

  const getTurmaClienteEmprestimo = (emprestimo, clienteAtual = null) => {
    const cliente = clienteAtual || getClienteByEmprestimo(emprestimo);

    if (cliente) {
      const infoTurma = obterInfoTurmaAluno(cliente, turmasAcademicasMap);
      if (infoTurma.label) {
        return infoTurma.label;
      }
    }

    const serieHistorica = String(
      emprestimo?.dadosTermoEmprestimo?.leitorSerie || emprestimo?.serieNome || ''
    ).trim();
    const turmaHistorica = String(
      emprestimo?.dadosTermoEmprestimo?.leitorTurma || emprestimo?.turmaNome || ''
    ).trim();
    const partes = [serieHistorica, turmaHistorica].filter((valor) => valor && valor !== 'N/A');

    return partes.join(' - ') || 'N/A';
  };

  // Funções de geração de relatórios
  const getRelatorioLivrosCadastrados = () => {
    return {
      titulo: 'Livros Cadastrados',
      colunas: ['Título', 'Autor', 'ISBN', 'Categoria', 'Quantidade', 'Emprestados', 'Disponíveis', 'Próx. Disponibilidade', 'Localização'],
      dados: livros.map(l => {
        const livroIdNormalizado = String(l.id);
        const emprestimosAtivos = emprestimos.filter((emp) =>
          String(emp.livroId) === livroIdNormalizado && isEmprestimoAtivo(emp.status)
        );
        const emprestadosCount = emprestimosAtivos.length;
        const quantidadeTotal = Number(l.quantidade) || 0;
        const disponiveisCount = Math.max(quantidadeTotal - emprestadosCount, 0);

        // Próxima data de disponibilidade (menor dataDevolucao dos ativos)
        let proxDisponibilidade = '-';
        if (emprestadosCount > 0 && disponiveisCount === 0) {
          const datas = emprestimosAtivos
            .map(e => e.dataDevolucao || e.dataDevolucaoPrevista)
            .filter(Boolean)
            .map(d => new Date(d))
            .filter(d => !isNaN(d.getTime()))
            .sort((a, b) => a - b);
          if (datas.length > 0) {
            proxDisponibilidade = datas[0].toLocaleDateString('pt-BR');
          }
        }

        return {
          titulo: l.titulo,
          autor: l.autor,
          isbn: l.isbn || 'N/A',
          categoria: l.categoria || 'Sem categoria',
          quantidade: quantidadeTotal,
          emprestados: emprestadosCount,
          disponiveis: disponiveisCount,
          proxDisponibilidade,
          localizacao: l.localizacao || 'N/A',
          _livroId: l.id,
          _emprestimosAtivos: emprestimosAtivos
        };
      }),
      resumo: {
        total: livros.length,
        totalExemplares: livros.reduce((sum, l) => sum + (l.quantidade || 0), 0),
        emprestados: emprestimos.filter(e => isEmprestimoAtivo(e.status)).length,
        disponiveis: livros.reduce((sum, l) => sum + (l.quantidade || 0), 0) - emprestimos.filter(e => isEmprestimoAtivo(e.status)).length
      },
      renderCustom: true
    };
  };

  const getRelatorioLivrosEmprestados = () => {
    const emprestimosPorLivro = emprestimos
      .filter(e => e.status === 'ativo')
      .reduce((acc, emp) => {
        const livro = livros.find(l => l.id === emp.livroId);
        const cliente = getClienteByEmprestimo(emp);
        
        if (livro) {
          acc.push({
            titulo: livro.titulo,
            autor: livro.autor,
            cliente: getNomeClienteEmprestimo(emp, cliente),
            cpf: getCpfClienteEmprestimo(emp, cliente),
            serieTurma: getTurmaClienteEmprestimo(emp, cliente),
            dataEmprestimo: new Date(emp.dataEmprestimo).toLocaleDateString('pt-BR'),
            dataDevolucao: new Date(emp.dataDevolucao).toLocaleDateString('pt-BR'),
            diasRestantes: Math.ceil((new Date(emp.dataDevolucao) - new Date()) / (1000 * 60 * 60 * 24)),
            _emprestimoId: emp.id
          });
        }
        return acc;
      }, []);

    return {
      titulo: 'Livros Emprestados (Ativos)',
      colunas: ['Livro', 'Autor', 'Cliente', 'CPF', 'Série/Turma', 'Data Empréstimo', 'Prazo Devolução', 'Dias Restantes'],
      dados: emprestimosPorLivro,
      resumo: {
        total: emprestimosPorLivro.length
      },
      permiteExcluir: true
    };
  };

  const getRelatorioPessoasCadastradas = () => {
    return {
      titulo: 'Pessoas Cadastradas',
      colunas: ['Nome', 'Tipo', 'CPF', 'Email', 'Telefone', 'Status'],
      dados: clientes.map(c => ({
        nome: c.nome,
        tipo: c.tipo || 'N/A',
        cpf: c.cpf || 'N/A',
        email: c.email || 'N/A',
        telefone: c.telefone || 'N/A',
        status: isClienteAtivoRelatorio(c) ? 'Ativo' : 'Inativo'
      })),
      resumo: {
        total: clientes.length,
        ativos: clientes.filter(isClienteAtivoRelatorio).length,
        inativos: clientes.filter((c) => !isClienteAtivoRelatorio(c)).length
      }
    };
  };

  const getRelatorioPessoasComEmprestimos = () => {
    const clientesComEmprestimos = clientes
      .filter(c => emprestimos.some(e => e.clienteId === c.id && e.status === 'ativo'))
      .map(c => {
        const emprestimosDaPessoa = emprestimos.filter(e => e.clienteId === c.id && e.status === 'ativo');
        const livrosEmprestados = emprestimosDaPessoa.map(e => {
          const livro = livros.find(l => l.id === e.livroId);
          return livro?.titulo || 'Livro não encontrado';
        }).join(', ');
        const infoTurma = obterInfoTurmaAluno(c, turmasAcademicasMap);

        return {
          nome: c.nome,
          tipo: c.tipo || 'N/A',
          cpf: c.cpf || 'N/A',
          serieTurma: infoTurma.label || 'N/A',
          telefone: c.telefone || 'N/A',
          quantidadeLivros: emprestimosDaPessoa.length,
          livros: livrosEmprestados
        };
      });

    return {
      titulo: 'Pessoas com Livros Emprestados',
      colunas: ['Nome', 'Tipo', 'CPF', 'Série/Turma', 'Telefone', 'Qtd Livros', 'Títulos Emprestados'],
      dados: clientesComEmprestimos,
      resumo: {
        total: clientesComEmprestimos.length
      }
    };
  };

  const getRelatorioDevolucoesPendentes = () => {
    const hoje = new Date();
    const devolucoesPendentes = emprestimos
      .filter(e => e.status === 'ativo')
      .map(e => {
        const cliente = getClienteByEmprestimo(e);
        const livro = livros.find(l => l.id === e.livroId);
        const dataDevolucao = new Date(e.dataDevolucao);
        const diasAtraso = Math.floor((hoje - dataDevolucao) / (1000 * 60 * 60 * 24));
        const situacao = diasAtraso > 0 ? 'Atrasado' : 'No Prazo';

        return {
          cliente: getNomeClienteEmprestimo(e, cliente),
          cpf: getCpfClienteEmprestimo(e, cliente),
          serieTurma: getTurmaClienteEmprestimo(e, cliente),
          livro: livro?.titulo || 'N/A',
          telefone: getTelefoneClienteEmprestimo(e, cliente),
          dataEmprestimo: new Date(e.dataEmprestimo).toLocaleDateString('pt-BR'),
          dataDevolucao: dataDevolucao.toLocaleDateString('pt-BR'),
          diasAtraso: diasAtraso > 0 ? diasAtraso : 0,
          situacao,
          _emprestimoId: e.id
        };
      })
      .sort((a, b) => b.diasAtraso - a.diasAtraso);

    return {
      titulo: 'Devoluções Pendentes',
      colunas: ['Cliente', 'CPF', 'Série/Turma', 'Livro', 'Telefone', 'Data Empréstimo', 'Prazo', 'Dias Atraso', 'Situação'],
      dados: devolucoesPendentes,
      resumo: {
        total: devolucoesPendentes.length,
        atrasados: devolucoesPendentes.filter(d => d.situacao === 'Atrasado').length,
        noPrazo: devolucoesPendentes.filter(d => d.situacao === 'No Prazo').length
      },
      permiteExcluir: true
    };
  };

  const getRelatorioRankingLeitores = () => {
    const rankingMap = new Map();

    emprestimos.forEach((emprestimo) => {
      const clienteId = String(emprestimo?.clienteId ?? emprestimo?.leitorId ?? '').trim();
      if (!clienteId) {
        return;
      }

      const cliente = getClienteByEmprestimo(emprestimo);
      const nome = getNomeClienteEmprestimo(emprestimo, cliente);
      const telefone = getTelefoneClienteEmprestimo(emprestimo, cliente);
      const turma = getTurmaClienteEmprestimo(emprestimo, cliente);
      const existente = rankingMap.get(clienteId) || {
        posicao: 0,
        nome,
        tipo: cliente?.tipo || 'Leitor',
        turma,
        totalLivrosEmprestados: 0,
        livrosAtivos: 0,
        livrosDevolvidos: 0,
        telefone
      };

      existente.totalLivrosEmprestados += 1;

      if (isEmprestimoAtivo(emprestimo.status)) {
        existente.livrosAtivos += 1;
      } else {
        existente.livrosDevolvidos += 1;
      }

      if ((!existente.nome || existente.nome === 'Leitor removido') && nome) {
        existente.nome = nome;
      }
      if ((!existente.telefone || existente.telefone === 'N/A') && telefone) {
        existente.telefone = telefone;
      }
      if ((!existente.turma || existente.turma === 'N/A') && turma) {
        existente.turma = turma;
      }
      if (cliente?.tipo && existente.tipo === 'Leitor') {
        existente.tipo = cliente.tipo;
      }

      rankingMap.set(clienteId, existente);
    });

    const rankingPorEmprestimos = Array.from(rankingMap.values())
      .filter((r) => r.totalLivrosEmprestados > 0)
      .sort((a, b) => b.totalLivrosEmprestados - a.totalLivrosEmprestados)
      .map((r, index) => ({ ...r, posicao: index + 1 }));

    return {
      titulo: 'Ranking de Leitores',
      colunas: ['Posição', 'Nome', 'Tipo', 'Turma', 'Total Emprestados', 'Ativos', 'Devolvidos', 'Telefone'],
      dados: rankingPorEmprestimos,
      resumo: {
        totalLeitores: rankingPorEmprestimos.length,
        totalEmprestimos: rankingPorEmprestimos.reduce((sum, r) => sum + r.totalLivrosEmprestados, 0),
        mediaEmprestimosPorLeitor: rankingPorEmprestimos.length > 0 
          ? (rankingPorEmprestimos.reduce((sum, r) => sum + r.totalLivrosEmprestados, 0) / rankingPorEmprestimos.length).toFixed(1)
          : 0
      }
    };
  };

  const getRelatorioDidaticosPorTurma = () => {
    const gruposTurma = new Map();
    const emprestimosDidaticosAtivosGlobais = emprestimos.filter((emp) => {
      return isEmprestimoAtivo(emp.status) && livroDidaticoMap.has(String(emp.livroId || ''));
    });
    const ativosGlobaisPorLivro = new Map();

    emprestimosDidaticosAtivosGlobais.forEach((emp) => {
      const livroId = String(emp.livroId || '');
      ativosGlobaisPorLivro.set(livroId, (ativosGlobaisPorLivro.get(livroId) || 0) + 1);
    });

    alunosComTurma.forEach((aluno) => {
      const infoTurma = obterInfoTurmaAluno(aluno, turmasAcademicasMap);
      if (!infoTurma.key) return;

      if (!gruposTurma.has(infoTurma.key)) {
        gruposTurma.set(infoTurma.key, {
          key: infoTurma.key,
          serie: infoTurma.nomeSerie || 'N/A',
          turma: infoTurma.nomeTurma || 'N/A',
          alunos: []
        });
      }

      gruposTurma.get(infoTurma.key).alunos.push(aluno);
    });

    const dados = Array.from(gruposTurma.values())
      .sort((a, b) => {
        const serieCompare = String(a.serie).localeCompare(String(b.serie), 'pt-BR');
        if (serieCompare !== 0) return serieCompare;
        return String(a.turma).localeCompare(String(b.turma), 'pt-BR');
      })
      .map((grupo) => {
      const alunosDaTurma = grupo.alunos;
      const alunoIds = new Set(alunosDaTurma.map((aluno) => String(aluno.id)));

      const emprestimosDidaticosAtivos = emprestimos.filter((emp) => {
        const clienteId = emp.clienteId ?? emp.leitorId;
        const livroId = String(emp.livroId || '');
        const chaveTurmaEmprestimo = obterChaveTurmaEmprestimo(emp);
        const pertencePelaTurmaEmprestimo = chaveTurmaEmprestimo && chaveTurmaEmprestimo === String(grupo.key || '');
        return (
          (
            (clienteId !== undefined && clienteId !== null && alunoIds.has(String(clienteId)))
            || pertencePelaTurmaEmprestimo
          ) &&
          isEmprestimoAtivo(emp.status) &&
          livroDidaticoMap.has(livroId)
        );
      });

      const titulosDistintosEntregues = new Set(
        emprestimosDidaticosAtivos.map((emp) => String(emp.livroId || ''))
      ).size;
      const emprestimosPorLivroNaTurma = new Map();

      emprestimosDidaticosAtivos.forEach((emp) => {
        const livroId = String(emp.livroId || '');
        emprestimosPorLivroNaTurma.set(livroId, (emprestimosPorLivroNaTurma.get(livroId) || 0) + 1);
      });

      const totalAlunos = alunosDaTurma.length;
      const totalTitulosDidaticos = livrosDidaticosAtivos.length;
      const coberturaEsperada = totalAlunos * totalTitulosDidaticos;
      const coberturaAtual = emprestimosDidaticosAtivos.length;
      const pendencias = Math.max(coberturaEsperada - coberturaAtual, 0);
      const estoqueRestante = livrosDidaticosAtivos.reduce((sum, livro) => {
        const livroId = String(livro.id);
        const totalLivro = Number(livro.quantidade) || 0;
        const ativosGlobais = ativosGlobaisPorLivro.get(livroId) || 0;
        const estoqueGlobalDisponivel = Math.max(totalLivro - ativosGlobais, 0);
        const emprestadosNaTurma = emprestimosPorLivroNaTurma.get(livroId) || 0;
        const faltantesNaTurma = Math.max(totalAlunos - emprestadosNaTurma, 0);

        return sum + Math.min(estoqueGlobalDisponivel, faltantesNaTurma);
      }, 0);
      const percentualCobertura = coberturaEsperada > 0
        ? `${((coberturaAtual / coberturaEsperada) * 100).toFixed(1)}%`
        : '0%';

      return {
        serie: grupo.serie,
        turma: grupo.turma,
        alunos: totalAlunos,
        titulosDidaticos: totalTitulosDidaticos,
        titulosEntregues: titulosDistintosEntregues,
        quantidadeEmprestada: coberturaAtual,
        estoqueRestante,
        pendencias,
        cobertura: percentualCobertura
      };
    });

    return {
      titulo: 'Didáticos por Turma',
      colunas: ['Série', 'Turma', 'Alunos', 'Títulos Didáticos', 'Títulos Entregues', 'Quantidade Emprestada', 'Estoque Restante', 'Pendências', 'Cobertura'],
      dados,
      resumo: {
        turmas: dados.length,
        alunos: dados.reduce((sum, item) => sum + item.alunos, 0),
        quantidadeEmprestada: dados.reduce((sum, item) => sum + item.quantidadeEmprestada, 0),
        estoqueRestante: dados.reduce((sum, item) => sum + item.estoqueRestante, 0),
        pendencias: dados.reduce((sum, item) => sum + item.pendencias, 0)
      }
    };
  };

  const getRelatorioPendenciasDidaticasPorAluno = () => {
    const didaticos = livrosDidaticosAtivos;

    const dados = alunosComTurma
      .map((aluno) => {
        const emprestimosAtivosAluno = emprestimos.filter((emp) => {
          const clienteId = emp.clienteId ?? emp.leitorId;
          return (
            clienteId !== undefined &&
            clienteId !== null &&
            String(clienteId) === String(aluno.id) &&
            isEmprestimoAtivo(emp.status) &&
            livroDidaticoMap.has(String(emp.livroId || ''))
          );
        });

        const livrosAtivosIds = new Set(
          emprestimosAtivosAluno.map((emp) => String(emp.livroId || ''))
        );

        const titulosPendentes = didaticos
          .filter((livro) => !livrosAtivosIds.has(String(livro.id)))
          .map((livro) => livro.titulo);

        const infoTurma = obterInfoTurmaAluno(aluno, turmasAcademicasMap);

        return {
          nome: aluno.nome,
          serie: infoTurma.nomeSerie || 'N/A',
          turma: infoTurma.nomeTurma || 'N/A',
          matricula: aluno.matricula || 'N/A',
          totalDidaticos: didaticos.length,
          comEmprestimo: livrosAtivosIds.size,
          pendentes: titulosPendentes.length,
          titulosPendentes: titulosPendentes.join(', ') || 'Nenhum'
        };
      })
      .filter((item) => item.pendentes > 0)
      .sort((a, b) => {
        const serieCompare = String(a.serie).localeCompare(String(b.serie), 'pt-BR');
        if (serieCompare !== 0) return serieCompare;
        const turmaCompare = String(a.turma).localeCompare(String(b.turma), 'pt-BR');
        if (turmaCompare !== 0) return turmaCompare;
        return String(a.nome).localeCompare(String(b.nome), 'pt-BR');
      });

    return {
      titulo: 'Pendências Didáticas por Aluno',
      colunas: ['Aluno', 'Série', 'Turma', 'Matrícula', 'Total Didáticos', 'Com Empréstimo', 'Pendências', 'Títulos Pendentes'],
      dados,
      resumo: {
        alunosComPendencia: dados.length,
        pendenciasTotais: dados.reduce((sum, item) => sum + item.pendentes, 0)
      }
    };
  };

  const getRelatorioEscolasCadastradas = () => {
    if (usuarioLogado?.perfil !== 'SuperAdmin') return null;

    return {
      titulo: 'Escolas Cadastradas',
      colunas: ['Nome', 'CNPJ', 'Cidade/Estado', 'Status', 'Licença', 'Data Cadastro'],
      dados: instituicoes.map(i => ({
        nome: i.nomeInstituicao,
        cnpj: i.cnpj,
        localizacao: `${i.cidade}/${i.estado}`,
        status: i.status === 'ativo' ? 'Ativo' : i.status === 'bloqueado' ? 'Bloqueado' : 'Pendente',
        licenca: i.licenca,
        dataCadastro: new Date(i.dataCadastro).toLocaleDateString('pt-BR')
      })),
      resumo: {
        total: instituicoes.length,
        ativas: instituicoes.filter(i => i.status === 'ativo').length,
        bloqueadas: instituicoes.filter(i => i.status === 'bloqueado').length,
        pendentes: instituicoes.filter(i => i.status === 'pendente').length
      }
    };
  };

  const getRelatorioEscolasInadimplentes = () => {
    if (usuarioLogado?.perfil !== 'SuperAdmin') return null;

    const inadimplentes = instituicoes.filter(i => 
      i.status !== 'pendente' && 
      (i.statusFinanceiro === 'atrasado' || i.statusFinanceiro === 'bloqueado_financeiro')
    ).map(i => ({
      nome: i.nomeInstituicao,
      responsavel: i.nomeResponsavel,
      telefone: i.telefoneContato,
      email: i.emailContato,
      valorMensal: `R$ ${(i.valorMensal || 97).toFixed(2)}`,
      ultimoPagamento: i.ultimoPagamento 
        ? new Date(i.ultimoPagamento).toLocaleDateString('pt-BR')
        : 'Nenhum',
      situacao: i.statusFinanceiro === 'bloqueado_financeiro' ? 'Bloqueado' : 'Atrasado'
    }));

    return {
      titulo: 'Escolas Inadimplentes',
      colunas: ['Nome', 'Responsável', 'Telefone', 'Email', 'Valor Mensal', 'Último Pagamento', 'Situação'],
      dados: inadimplentes,
      resumo: {
        total: inadimplentes.length,
        bloqueadas: inadimplentes.filter(i => i.situacao === 'Bloqueado').length
      }
    };
  };

  const getRelatorioEscolasAdimplentes = () => {
    if (usuarioLogado?.perfil !== 'SuperAdmin') return null;

    const adimplentes = instituicoes.filter(i => 
      i.status === 'ativo' && 
      i.statusFinanceiro === 'em_dia'
    ).map(i => ({
      nome: i.nomeInstituicao,
      responsavel: i.nomeResponsavel,
      telefone: i.telefoneContato,
      valorMensal: `R$ ${(i.valorMensal || 97).toFixed(2)}`,
      ultimoPagamento: i.ultimoPagamento 
        ? new Date(i.ultimoPagamento).toLocaleDateString('pt-BR')
        : 'N/A',
      dataExpiracao: i.dataExpiracao 
        ? new Date(i.dataExpiracao).toLocaleDateString('pt-BR')
        : 'N/A'
    }));

    return {
      titulo: 'Escolas Adimplentes',
      colunas: ['Nome', 'Responsável', 'Telefone', 'Valor Mensal', 'Último Pagamento', 'Licença Válida Até'],
      dados: adimplentes,
      resumo: {
        total: adimplentes.length,
        receitaMensal: adimplentes.reduce((sum, i) => {
          const valor = parseFloat(i.valorMensal.replace('R$ ', '').replace(',', '.'));
          return sum + valor;
        }, 0)
      }
    };
  };

  const getRelatorioPatrimonio = () => {
    return {
      titulo: 'Patrimônio Cadastrado',
      colunas: ['Descrição', 'Código', 'Categoria', 'Localização', 'Estado', 'Valor Aquisição'],
      dados: patrimonio.map(p => ({
        descricao: p.descricao,
        codigo: p.codigoPatrimonio,
        categoria: p.categoria || 'N/A',
        localizacao: p.localizacao || 'N/A',
        estado: p.estado || 'N/A',
        valor: `R$ ${parseFloat(p.valorAquisicao || 0).toFixed(2)}`
      })),
      resumo: {
        total: patrimonio.length,
        valorTotal: patrimonio.reduce((sum, p) => sum + parseFloat(p.valorAquisicao || 0), 0)
      }
    };
  };

  const getRelatorioEmprestimosHistorico = () => {
    return {
      titulo: 'Histórico de Empréstimos',
      colunas: ['Cliente', 'CPF', 'Série/Turma', 'Livro', 'Data Empréstimo', 'Data Devolução', 'Data Retorno', 'Status'],
      dados: emprestimos.map(e => {
        const cliente = getClienteByEmprestimo(e);
        const livro = livros.find(l => l.id === e.livroId);
        
        return {
          cliente: getNomeClienteEmprestimo(e, cliente),
          cpf: getCpfClienteEmprestimo(e, cliente),
          serieTurma: getTurmaClienteEmprestimo(e, cliente),
          livro: livro?.titulo || 'N/A',
          dataEmprestimo: new Date(e.dataEmprestimo).toLocaleDateString('pt-BR'),
          dataDevolucao: new Date(e.dataDevolucao).toLocaleDateString('pt-BR'),
          dataRetorno: e.dataRetorno ? new Date(e.dataRetorno).toLocaleDateString('pt-BR') : 'Não devolvido',
          status: e.status === 'ativo' ? 'Ativo' : 'Devolvido',
          _emprestimoId: e.id
        };
      }),
      resumo: {
        total: emprestimos.length,
        ativos: emprestimos.filter(e => e.status === 'ativo').length,
        devolvidos: emprestimos.filter(e => e.status === 'devolvido').length
      },
      permiteExcluir: true
    };
  };

  const getRelatorioLeitoresCadastrados = () => {
    const categoriasOrdem = ['Estudante', 'Professor', 'Funcionário', 'Comunidade'];

    const leitoresNormalizados = clientes.map((cliente) => ({
      ...cliente,
      ativoRelatorio: isClienteAtivoRelatorio(cliente),
      categoriaRelatorio: obterCategoriaLeitorRelatorio(cliente)
    }));

    const todosOrdenados = [...leitoresNormalizados].sort((a, b) => {
      const catA = categoriasOrdem.indexOf(a.categoriaRelatorio || '');
      const catB = categoriasOrdem.indexOf(b.categoriaRelatorio || '');
      const iA = catA >= 0 ? catA : 99;
      const iB = catB >= 0 ? catB : 99;
      if (iA !== iB) return iA - iB;
      const serieComp = String(a.serie || '').localeCompare(String(b.serie || ''), 'pt-BR');
      if (serieComp !== 0) return serieComp;
      const infoA = obterInfoTurmaAluno(a, turmasAcademicasMap);
      const infoB = obterInfoTurmaAluno(b, turmasAcademicasMap);
      const turmaComp = String(infoA.label || '').localeCompare(String(infoB.label || ''), 'pt-BR');
      if (turmaComp !== 0) return turmaComp;
      return String(a.nome || '').localeCompare(String(b.nome || ''), 'pt-BR');
    });

    // Build section map
    const secaoMap = new Map();
    todosOrdenados.forEach((c) => {
      const cat = c.categoriaRelatorio || 'Sem categoria';
      if (!secaoMap.has(cat)) secaoMap.set(cat, []);
      secaoMap.get(cat).push(c);
    });

    const categoriasPresentes = [
      ...categoriasOrdem.filter(c => secaoMap.has(c)),
      ...Array.from(secaoMap.keys()).filter(c => !categoriasOrdem.includes(c))
    ];

    const secoes = categoriasPresentes.map((cat) => {
      const leitores = secaoMap.get(cat) || [];

      if (cat === 'Estudante') {
        const turmaMap = new Map();
        leitores.forEach((l) => {
          const info = obterInfoTurmaAluno(l, turmasAcademicasMap);
          const turmaKey = info.label || 'Sem turma';
          if (!turmaMap.has(turmaKey)) turmaMap.set(turmaKey, []);
          turmaMap.get(turmaKey).push(l);
        });

        const subsecoes = Array.from(turmaMap.entries())
          .sort(([a], [b]) => a.localeCompare(b, 'pt-BR'))
          .map(([turmaLabel, alunos]) => ({
            titulo: turmaLabel,
            colunas: ['Nº', 'Nome', 'Matrícula', 'Série', 'Turma'],
            dados: alunos.map((a, i) => {
              const info = obterInfoTurmaAluno(a, turmasAcademicasMap);
              return {
                num: i + 1,
                nome: a.nome,
                matricula: a.matricula || '-',
                serie: info.nomeSerie !== 'N/A' ? info.nomeSerie : (a.serie || '-'),
                turma: info.nomeTurma !== 'N/A' ? info.nomeTurma : (a.turma || '-')
              };
            })
          }));

        return { titulo: `Estudantes (${leitores.length})`, subsecoes };
      }

      return {
        titulo: `${cat} (${leitores.length})`,
        colunas: ['Nº', 'Nome', 'Tipo', 'Telefone'],
        dados: leitores.map((l, i) => ({
          num: i + 1,
          nome: l.nome,
          tipo: l.tipo || '-',
          telefone: l.telefone || '-'
        }))
      };
    });

    const dados = todosOrdenados.map((c, i) => {
      const info = obterInfoTurmaAluno(c, turmasAcademicasMap);
      return {
        num: i + 1,
        nome: c.nome,
        categoria: c.categoriaRelatorio || '-',
        tipo: c.tipo || '-',
        matricula: c.matricula || '-',
        serieTurma: info.label || '-'
      };
    });

    const resumo = leitoresNormalizados.reduce((acc, cliente) => {
      acc.total += 1;

      if (cliente.ativoRelatorio) {
        acc.ativos += 1;
      }

      if (cliente.categoriaRelatorio === 'Estudante') acc.estudantes += 1;
      if (cliente.categoriaRelatorio === 'Professor') acc.professores += 1;
      if (cliente.categoriaRelatorio === 'Funcionário') acc.funcionarios += 1;
      if (cliente.categoriaRelatorio === 'Comunidade') acc.comunidade += 1;

      return acc;
    }, {
      total: 0,
      ativos: 0,
      estudantes: 0,
      professores: 0,
      funcionarios: 0,
      comunidade: 0
    });

    return {
      titulo: 'Leitores Cadastrados',
      colunas: ['Nº', 'Nome', 'Categoria', 'Tipo', 'Matrícula', 'Série/Turma'],
      dados,
      secoes,
      resumo
    };
  };

  const tiposRelatorio = [
    { value: 'livros-cadastrados', label: 'Livros Cadastrados' },
    { value: 'livros-emprestados', label: 'Livros Emprestados' },
    { value: 'leitores-cadastrados', label: 'Leitores Cadastrados' },
    { value: 'pessoas-cadastradas', label: 'Pessoas Cadastradas' },
    { value: 'pessoas-com-emprestimos', label: 'Pessoas com Livros Emprestados' },
    { value: 'devolucoes-pendentes', label: 'Devoluções Pendentes' },
    { value: 'ranking-leitores', label: 'Ranking de Leitores' },
    { value: 'didaticos-por-turma', label: 'Didáticos por Turma' },
    { value: 'pendencias-didaticas-aluno', label: 'Pendências Didáticas por Aluno' },
    { value: 'patrimonio', label: 'Patrimônio' },
    { value: 'emprestimos-historico', label: 'Histórico de Empréstimos' },
  ];

  if (usuarioLogado?.perfil === 'SuperAdmin') {
    tiposRelatorio.push(
      { value: 'escolas-cadastradas', label: 'Escolas Cadastradas' },
      { value: 'escolas-inadimplentes', label: 'Escolas Inadimplentes' },
      { value: 'escolas-adimplentes', label: 'Escolas Adimplentes' }
    );
  }

  const getRelatorioAtual = () => {
    switch (tipoRelatorio) {
      case 'livros-cadastrados': return getRelatorioLivrosCadastrados();
      case 'livros-emprestados': return getRelatorioLivrosEmprestados();
      case 'leitores-cadastrados': return getRelatorioLeitoresCadastrados();
      case 'pessoas-cadastradas': return getRelatorioPessoasCadastradas();
      case 'pessoas-com-emprestimos': return getRelatorioPessoasComEmprestimos();
      case 'devolucoes-pendentes': return getRelatorioDevolucoesPendentes();
      case 'ranking-leitores': return getRelatorioRankingLeitores();
      case 'didaticos-por-turma': return getRelatorioDidaticosPorTurma();
      case 'pendencias-didaticas-aluno': return getRelatorioPendenciasDidaticasPorAluno();
      case 'patrimonio': return getRelatorioPatrimonio();
      case 'emprestimos-historico': return getRelatorioEmprestimosHistorico();
      case 'escolas-cadastradas': return getRelatorioEscolasCadastradas();
      case 'escolas-inadimplentes': return getRelatorioEscolasInadimplentes();
      case 'escolas-adimplentes': return getRelatorioEscolasAdimplentes();
      default: return null;
    }
  };

  const relatorio = getRelatorioAtual();

  const handleSalvarConfiguracao = () => {
    if (instituicaoAtiva) {
      atualizarInstituicao(instituicaoAtiva, {
        configRelatorios: configCabecalho,
        logoUrl: configCabecalho.logoUrl
      });
    }
    setDialogConfig(false);
  };

  const handleUploadLogo = (event) => {
    const file = event.target.files[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        alert('Selecione apenas arquivos de imagem');
        return;
      }
      if (file.size > 1 * 1024 * 1024) {
        alert('A imagem deve ter no máximo 1MB');
        return;
      }

      const reader = new FileReader();
      reader.onloadend = () => {
        setConfigCabecalho({ ...configCabecalho, logoUrl: reader.result });
      };
      reader.readAsDataURL(file);
    }
  };

  const gerarHtmlImpressao = () => {
    const instituicao = instituicoes.find(i => i.id === instituicaoAtiva);
    const tituloEntidade = configCabecalho.titulo || instituicao?.nomeInstituicao || 'Sistema de Controle Escolar Inteligente';
    const subtituloEntidade = configCabecalho.subtitulo
      || [instituicao?.cidade, instituicao?.estado].filter(Boolean).join(', ');
    const contatoEntidade = [
      instituicao?.cnpj ? `CNPJ: ${escapeHtml(instituicao.cnpj)}` : '',
      instituicao?.telefoneContato ? `Tel.: ${escapeHtml(instituicao.telefoneContato)}` : '',
      instituicao?.emailContato ? escapeHtml(instituicao.emailContato) : ''
    ].filter(Boolean).join(' &bull; ');
    const logoHtml = configCabecalho.logoUrl
      ? `<img src="${configCabecalho.logoUrl}" alt="Logo" />`
      : '';

    const resumoHtml = relatorio.resumo
      ? `<div class="resumo">${Object.entries(relatorio.resumo).map(([key, value]) => {
          const label = key.replace(/([A-Z])/g, ' $1').trim();
          const valorFormatado = typeof value === 'number' && key.toLowerCase().includes('receita')
            ? `R$ ${value.toFixed(2)}`
            : value;
          return `<div><span>${escapeHtml(label)}</span><b>${escapeHtml(valorFormatado)}</b></div>`;
        }).join('')}</div>`
      : '';

    let corpoHtml;
    if (relatorio.secoes) {
      corpoHtml = relatorio.secoes.map((secao) => {
        const conteudo = secao.subsecoes
          ? secao.subsecoes.map((sub) =>
              `<h4 class="subsecao">${escapeHtml(sub.titulo)} — ${sub.dados.length} registro(s)</h4>${montarTabelaHtmlImpressao(sub.colunas, sub.dados)}`
            ).join('')
          : montarTabelaHtmlImpressao(secao.colunas, secao.dados);
        return `<h3 class="secao">${escapeHtml(secao.titulo)}</h3>${conteudo}`;
      }).join('');
    } else {
      corpoHtml = montarTabelaHtmlImpressao(relatorio.colunas, relatorio.dados);
    }

    return `<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="utf-8" />
<title>${escapeHtml(relatorio.titulo)} - ${escapeHtml(tituloEntidade)}</title>
<style>
  @page { size: A4; margin: 1.2cm; }
  body { font-family: Arial, Helvetica, sans-serif; color: #222; margin: 0; }
  table.folha { width: 100%; border-collapse: collapse; }
  .timbrado { text-align: center; border-bottom: 3px double #1565c0; padding-bottom: 8px; margin-bottom: 10px; }
  .timbrado img { height: 70px; object-fit: contain; }
  .timbrado h1 { margin: 4px 0 0; font-size: 18px; color: #1565c0; }
  .timbrado p { margin: 2px 0 0; font-size: 12px; color: #555; }
  h2.titulo-relatorio { font-size: 15px; margin: 10px 0 2px; }
  p.gerado { font-size: 10px; color: #777; margin: 0 0 8px; }
  .resumo { display: flex; flex-wrap: wrap; gap: 6px; margin: 8px 0 12px; }
  .resumo div { border: 1px solid #ddd; border-radius: 4px; padding: 4px 10px; font-size: 10px; background: #f7f7f7; text-transform: capitalize; }
  .resumo b { display: block; font-size: 13px; }
  table.dados { width: 100%; border-collapse: collapse; margin-bottom: 12px; }
  table.dados thead { display: table-header-group; }
  table.dados th { background: #1565c0; color: #fff; font-size: 10.5px; padding: 5px 6px; text-align: left; border: 1px solid #1565c0; }
  table.dados td { font-size: 10.5px; padding: 4px 6px; border: 1px solid #ccc; vertical-align: top; }
  table.dados tbody tr:nth-child(even) td { background: #f3f6fb; }
  table.dados tr { page-break-inside: avoid; }
  h3.secao { background: #1565c0; color: #fff; font-size: 12px; padding: 4px 8px; margin: 12px 0 4px; border-radius: 3px; }
  h4.subsecao { background: #e3eaf5; font-size: 11px; padding: 3px 8px; margin: 8px 0 4px; }
  p.vazio { font-size: 11px; color: #777; }
  .rodape { margin-top: 14px; font-size: 10px; color: #666; text-align: right; border-top: 1px solid #ccc; padding-top: 4px; }
</style>
</head>
<body>
<table class="folha">
  <thead>
    <tr><td>
      <div class="timbrado">
        ${logoHtml}
        <h1>${escapeHtml(tituloEntidade)}</h1>
        ${subtituloEntidade ? `<p>${escapeHtml(subtituloEntidade)}</p>` : ''}
        ${contatoEntidade ? `<p>${contatoEntidade}</p>` : ''}
      </div>
    </td></tr>
  </thead>
  <tbody>
    <tr><td>
      <h2 class="titulo-relatorio">${escapeHtml(relatorio.titulo)}</h2>
      <p class="gerado">Gerado em: ${new Date().toLocaleString('pt-BR')}</p>
      ${resumoHtml}
      ${corpoHtml}
      <p class="rodape">Total de registros: ${relatorio.dados.length}</p>
    </td></tr>
  </tbody>
</table>
</body>
</html>`;
  };

  const handleImprimir = () => {
    if (!relatorio) return;

    const win = window.open('', '_blank');
    if (!win) {
      // Popup bloqueado: cai para a impressão da própria página
      imprimirEscopo();
      return;
    }

    win.document.write(gerarHtmlImpressao());
    win.document.close();
    win.focus();
    setTimeout(() => win.print(), 400);
  };

  const handleDownloadPDF = () => {
    handleImprimir(); // Na janela de impressão, escolher "Salvar como PDF"
  };

  const handleDownloadExcel = () => {
    if (!relatorio) return;

    // Criar CSV (compatível com Excel)
    const headers = relatorio.colunas.join(',');
    const rows = relatorio.dados.map(row =>
      Object.entries(row)
        .filter(([key]) => !key.startsWith('_'))
        .map(([, val]) => `"${String(val ?? '').replace(/"/g, '""')}"`)
        .join(',')
    ).join('\n');
    
    const csv = `${headers}\n${rows}`;
    const blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `${relatorio.titulo.replace(/\s+/g, '_')}_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  if (!relatorio) {
    return (
      <Layout title="Relatórios">
        <Alert severity="info">Selecione um tipo de relatório</Alert>
      </Layout>
    );
  }

  return (
    <Layout title="Relatórios">
      <Box sx={{ mb: 3 }} className="print-actions no-print">
        <Grid container spacing={2} alignItems="center">
          <Grid item xs={12} md={6}>
            <TextField
              select
              fullWidth
              label="Tipo de Relatório"
              value={tipoRelatorio}
              onChange={(e) => setTipoRelatorio(e.target.value)}
            >
              {tiposRelatorio.map((tipo) => (
                <MenuItem key={tipo.value} value={tipo.value}>
                  {tipo.label}
                </MenuItem>
              ))}
            </TextField>
          </Grid>
          
          <Grid item xs={12} md={6}>
            <Box display="flex" gap={1} justifyContent="flex-end">
              <Button
                variant="outlined"
                startIcon={<Settings />}
                onClick={() => setDialogConfig(true)}
              >
                Configurar Cabeçalho
              </Button>
              <Button
                variant="outlined"
                startIcon={<Print />}
                onClick={handleImprimir}
              >
                Imprimir
              </Button>
              <Button
                variant="outlined"
                startIcon={<PictureAsPdf />}
                onClick={handleDownloadPDF}
              >
                PDF
              </Button>
              <Button
                variant="outlined"
                startIcon={<TableChart />}
                onClick={handleDownloadExcel}
              >
                Excel
              </Button>
            </Box>
          </Grid>
        </Grid>
      </Box>

      {/* Área de Impressão */}
      <Box className="print-scope">
        <Card>
          <CardContent>
            {/* Cabeçalho Personalizado */}
            <Box sx={{ mb: 3, textAlign: 'center', borderBottom: 2, borderColor: 'primary.main', pb: 2 }}>
              {configCabecalho.logoUrl && (
                <Avatar
                  src={configCabecalho.logoUrl}
                  alt="Logo"
                  sx={{ width: 80, height: 80, mx: 'auto', mb: 2 }}
                  variant="square"
                />
              )}
              <Typography variant="h5" fontWeight="bold" color="primary">
                {configCabecalho.titulo || 'Sistema de Controle Escolar Inteligente'}
              </Typography>
              {configCabecalho.subtitulo && (
                <Typography variant="subtitle1" color="textSecondary">
                  {configCabecalho.subtitulo}
                </Typography>
              )}
            </Box>

            {/* Título do Relatório */}
            <Typography variant="h6" gutterBottom fontWeight="bold">
              {relatorio.titulo}
            </Typography>
            <Typography variant="caption" color="textSecondary" gutterBottom display="block">
              Gerado em: {new Date().toLocaleString('pt-BR')}
            </Typography>

            <Divider sx={{ my: 2 }} />

            {/* Resumo */}
            {relatorio.resumo && (
              <Box sx={{ mb: 3 }}>
                <Typography variant="subtitle2" fontWeight="bold" gutterBottom>
                  Resumo:
                </Typography>
                <Grid container spacing={2}>
                  {Object.entries(relatorio.resumo).map(([key, value]) => (
                    <Grid item xs={6} sm={3} key={key}>
                      <Paper elevation={0} sx={{ p: 2, bgcolor: 'grey.50' }}>
                        <Typography variant="caption" color="textSecondary" textTransform="capitalize">
                          {key.replace(/([A-Z])/g, ' $1').trim()}
                        </Typography>
                        <Typography variant="h6" fontWeight="bold">
                          {typeof value === 'number' && key.includes('receita') 
                            ? `R$ ${value.toFixed(2)}` 
                            : value}
                        </Typography>
                      </Paper>
                    </Grid>
                  ))}
                </Grid>
              </Box>
            )}

            {/* Tabela de Dados */}
            {relatorio.renderCustom && tipoRelatorio === 'livros-cadastrados' ? (
              <TableContainer component={Paper} variant="outlined">
                <Table size="small">
                  <TableHead>
                    <TableRow sx={{ bgcolor: 'primary.main' }}>
                      {relatorio.colunas.map((col) => (
                        <TableCell key={col} sx={{ color: 'white', fontWeight: 'bold' }}>
                          {col}
                        </TableCell>
                      ))}
                      <TableCell sx={{ color: 'white', fontWeight: 'bold' }}>Detalhes</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {relatorio.dados.length === 0 ? (
                      <TableRow>
                        <TableCell colSpan={relatorio.colunas.length + 1} align="center">
                          <Typography color="textSecondary">Nenhum dado disponível</Typography>
                        </TableCell>
                      </TableRow>
                    ) : (
                      relatorio.dados.map((row, index) => (
                        <TableRow key={index} hover>
                          <TableCell>{row.titulo}</TableCell>
                          <TableCell>{row.autor}</TableCell>
                          <TableCell>{row.isbn}</TableCell>
                          <TableCell>{row.categoria}</TableCell>
                          <TableCell>{row.quantidade}</TableCell>
                          <TableCell>
                            <Chip label={row.emprestados} size="small" color={row.emprestados > 0 ? 'warning' : 'default'} />
                          </TableCell>
                          <TableCell>
                            <Chip label={row.disponiveis} size="small" color={row.disponiveis > 0 ? 'success' : 'error'} />
                          </TableCell>
                          <TableCell>{row.proxDisponibilidade}</TableCell>
                          <TableCell>{row.localizacao}</TableCell>
                          <TableCell>
                            {row.emprestados > 0 ? (
                              <Tooltip title="Ver quem está com o livro">
                                <IconButton
                                  size="small"
                                  color="info"
                                  onClick={() => setDetalheEmprestimos({
                                    titulo: row.titulo,
                                    emprestimos: row._emprestimosAtivos.map(emp => {
                                      const cliente = getClienteByEmprestimo(emp);
                                      return {
                                        leitor: getNomeClienteEmprestimo(emp, cliente),
                                        telefone: getTelefoneClienteEmprestimo(emp, cliente),
                                        turma: getTurmaClienteEmprestimo(emp, cliente),
                                        dataEmprestimo: new Date(emp.dataEmprestimo).toLocaleDateString('pt-BR'),
                                        dataDevolucao: new Date(emp.dataDevolucao).toLocaleDateString('pt-BR')
                                      };
                                    })
                                  })}
                                >
                                  <Visibility fontSize="small" />
                                </IconButton>
                              </Tooltip>
                            ) : '-'}
                          </TableCell>
                        </TableRow>
                      ))
                    )}
                  </TableBody>
                </Table>
              </TableContainer>
            ) : relatorio.secoes ? (
              relatorio.secoes.map((secao, sIdx) => (
                <Box key={sIdx} sx={{ mb: 3 }}>
                  <Typography
                    variant="subtitle1"
                    fontWeight="bold"
                    sx={{ bgcolor: 'primary.main', color: 'white', p: 1, mb: 1, borderRadius: 1 }}
                  >
                    {secao.titulo}
                  </Typography>
                  {secao.subsecoes ? (
                    secao.subsecoes.map((sub, ssIdx) => (
                      <Box key={ssIdx} sx={{ mb: 2 }}>
                        <Typography
                          variant="subtitle2"
                          sx={{ bgcolor: 'grey.200', p: 0.5, px: 1, mb: 0.5, borderRadius: 0.5 }}
                        >
                          {sub.titulo} — {sub.dados.length} aluno(s)
                        </Typography>
                        <TableContainer component={Paper} variant="outlined">
                          <Table size="small">
                            <TableHead>
                              <TableRow sx={{ bgcolor: 'grey.100' }}>
                                {sub.colunas.map((col) => (
                                  <TableCell key={col} sx={{ fontWeight: 'bold' }}>{col}</TableCell>
                                ))}
                              </TableRow>
                            </TableHead>
                            <TableBody>
                              {sub.dados.map((row, i) => (
                                <TableRow key={i} hover>
                                  {Object.values(row).map((val, vi) => (
                                    <TableCell key={vi}>{val}</TableCell>
                                  ))}
                                </TableRow>
                              ))}
                            </TableBody>
                          </Table>
                        </TableContainer>
                      </Box>
                    ))
                  ) : (
                    <TableContainer component={Paper} variant="outlined">
                      <Table size="small">
                        <TableHead>
                          <TableRow sx={{ bgcolor: 'grey.100' }}>
                            {secao.colunas.map((col) => (
                              <TableCell key={col} sx={{ fontWeight: 'bold' }}>{col}</TableCell>
                            ))}
                          </TableRow>
                        </TableHead>
                        <TableBody>
                          {secao.dados.map((row, i) => (
                            <TableRow key={i} hover>
                              {Object.entries(row).filter(([key]) => !key.startsWith('_')).map(([key, val], vi) => (
                                <TableCell key={vi}>{val}</TableCell>
                              ))}
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </TableContainer>
                  )}
                </Box>
              ))
            ) : (
              <TableContainer component={Paper} variant="outlined">
                <Table size="small">
                  <TableHead>
                    <TableRow sx={{ bgcolor: 'primary.main' }}>
                      {relatorio.colunas.map((col) => (
                        <TableCell key={col} sx={{ color: 'white', fontWeight: 'bold' }}>
                          {col}
                        </TableCell>
                      ))}
                      {relatorio.permiteExcluir && (
                        <TableCell sx={{ color: 'white', fontWeight: 'bold', width: 60 }}>Ação</TableCell>
                      )}
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {relatorio.dados.length === 0 ? (
                      <TableRow>
                        <TableCell colSpan={relatorio.colunas.length + (relatorio.permiteExcluir ? 1 : 0)} align="center">
                          <Typography color="textSecondary">
                            Nenhum dado disponível
                          </Typography>
                        </TableCell>
                      </TableRow>
                    ) : (
                      relatorio.dados.map((row, index) => (
                        <TableRow key={index} hover>
                          {Object.entries(row).filter(([key]) => !key.startsWith('_')).map(([key, value], i) => (
                            <TableCell key={i}>{value}</TableCell>
                          ))}
                          {relatorio.permiteExcluir && row._emprestimoId && (
                            <TableCell>
                              <Tooltip title="Excluir empréstimo">
                                <IconButton
                                  size="small"
                                  color="error"
                                  onClick={() => setConfirmarExclusao(row)}
                                >
                                  <Delete fontSize="small" />
                                </IconButton>
                              </Tooltip>
                            </TableCell>
                          )}
                        </TableRow>
                      ))
                    )}
                  </TableBody>
                </Table>
              </TableContainer>
            )}

            <Box sx={{ mt: 3, textAlign: 'right' }}>
              <Typography variant="caption" color="textSecondary">
                Total de registros: {relatorio.dados.length}
              </Typography>
            </Box>
          </CardContent>
        </Card>
      </Box>

      {/* Dialog Configuração */}
      <Dialog open={dialogConfig} onClose={() => setDialogConfig(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Configurar Cabeçalho dos Relatórios</DialogTitle>
        <DialogContent>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 1 }}>
            <TextField
              label="Título"
              fullWidth
              value={configCabecalho.titulo}
              onChange={(e) => setConfigCabecalho({ ...configCabecalho, titulo: e.target.value })}
              placeholder="Nome da instituição"
            />
            
            <TextField
              label="Subtítulo"
              fullWidth
              value={configCabecalho.subtitulo}
              onChange={(e) => setConfigCabecalho({ ...configCabecalho, subtitulo: e.target.value })}
              placeholder="Endereço, cidade, etc."
            />

            <Box>
              <Typography variant="subtitle2" gutterBottom>
                Logo/Emblema
              </Typography>
              
              {configCabecalho.logoUrl ? (
                <Box sx={{ textAlign: 'center', mb: 2 }}>
                  <Avatar
                    src={configCabecalho.logoUrl}
                    alt="Logo"
                    sx={{ width: 100, height: 100, mx: 'auto', mb: 1 }}
                    variant="square"
                  />
                  <Button
                    size="small"
                    color="error"
                    onClick={() => setConfigCabecalho({ ...configCabecalho, logoUrl: '' })}
                  >
                    Remover Logo
                  </Button>
                </Box>
              ) : (
                <>
                  <input
                    type="file"
                    ref={logoInputRef}
                    accept="image/*"
                    style={{ display: 'none' }}
                    onChange={handleUploadLogo}
                  />
                  <Button
                    variant="outlined"
                    startIcon={<ImageIcon />}
                    onClick={() => logoInputRef.current?.click()}
                    fullWidth
                  >
                    Selecionar Logo
                  </Button>
                  <Typography variant="caption" color="textSecondary" display="block" sx={{ mt: 1 }}>
                    Tamanho máximo: 1MB. Formatos: JPG, PNG
                  </Typography>
                </>
              )}
            </Box>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDialogConfig(false)}>Cancelar</Button>
          <Button onClick={handleSalvarConfiguracao} variant="contained">
            Salvar Configuração
          </Button>
        </DialogActions>
      </Dialog>

      {/* Dialog Detalhe Empréstimos do Livro */}
      <Dialog open={!!detalheEmprestimos} onClose={() => setDetalheEmprestimos(null)} maxWidth="md" fullWidth>
        <DialogTitle>
          📖 Empréstimos Ativos — {detalheEmprestimos?.titulo}
        </DialogTitle>
        <DialogContent>
          <TableContainer component={Paper} variant="outlined" sx={{ mt: 1 }}>
            <Table size="small">
              <TableHead>
                <TableRow sx={{ bgcolor: 'primary.main' }}>
                  <TableCell sx={{ color: 'white', fontWeight: 'bold' }}>Leitor</TableCell>
                  <TableCell sx={{ color: 'white', fontWeight: 'bold' }}>Telefone</TableCell>
                  <TableCell sx={{ color: 'white', fontWeight: 'bold' }}>Turma</TableCell>
                  <TableCell sx={{ color: 'white', fontWeight: 'bold' }}>Data Empréstimo</TableCell>
                  <TableCell sx={{ color: 'white', fontWeight: 'bold' }}>Prazo Devolução</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {(detalheEmprestimos?.emprestimos || []).map((emp, i) => (
                  <TableRow key={i} hover>
                    <TableCell><strong>{emp.leitor}</strong></TableCell>
                    <TableCell>{emp.telefone}</TableCell>
                    <TableCell>{emp.turma}</TableCell>
                    <TableCell>{emp.dataEmprestimo}</TableCell>
                    <TableCell>{emp.dataDevolucao}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
          <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
            Total: {detalheEmprestimos?.emprestimos?.length || 0} empréstimo(s) ativo(s)
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDetalheEmprestimos(null)}>Fechar</Button>
          <Button
            variant="outlined"
            startIcon={<Print />}
            onClick={() => {
              const d = detalheEmprestimos;
              if (!d) return;
              const win = window.open('', '_blank');
              if (!win) return;
              win.document.write(`<html><head><title>Empréstimos - ${d.titulo}</title>
                <style>body{font-family:Arial,sans-serif;padding:20px}table{width:100%;border-collapse:collapse;margin-top:10px}
                th,td{border:1px solid #ccc;padding:6px 10px;text-align:left;font-size:13px}
                th{background:#1976d2;color:white}tr:nth-child(even){background:#f5f5f5}</style></head>
                <body><h2>📖 ${d.titulo}</h2><p>Empréstimos ativos — ${new Date().toLocaleString('pt-BR')}</p>
                <table><thead><tr><th>Leitor</th><th>Telefone</th><th>Turma</th><th>Data Empréstimo</th><th>Prazo Devolução</th></tr></thead>
                <tbody>${d.emprestimos.map(e => `<tr><td>${e.leitor}</td><td>${e.telefone}</td><td>${e.turma}</td><td>${e.dataEmprestimo}</td><td>${e.dataDevolucao}</td></tr>`).join('')}
                </tbody></table><p>Total: ${d.emprestimos.length} empréstimo(s)</p></body></html>`);
              win.document.close();
              win.print();
            }}
          >
            Imprimir
          </Button>
        </DialogActions>
      </Dialog>

      {/* Dialog Confirmação Exclusão de Empréstimo */}
      <Dialog open={!!confirmarExclusao} onClose={() => setConfirmarExclusao(null)} maxWidth="xs" fullWidth>
        <DialogTitle sx={{ color: 'error.main' }}>Confirmar Exclusão</DialogTitle>
        <DialogContent>
          <Typography>
            Deseja realmente excluir este empréstimo?
          </Typography>
          {confirmarExclusao && (
            <Box sx={{ mt: 1, p: 1.5, bgcolor: 'grey.50', borderRadius: 1 }}>
              <Typography variant="body2"><strong>Cliente:</strong> {confirmarExclusao.cliente}</Typography>
              <Typography variant="body2"><strong>Livro:</strong> {confirmarExclusao.livro || confirmarExclusao.titulo || 'N/A'}</Typography>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setConfirmarExclusao(null)}>Cancelar</Button>
          <Button
            variant="contained"
            color="error"
            startIcon={<Delete />}
            onClick={() => {
              if (confirmarExclusao?._emprestimoId) {
                removerEmprestimo(confirmarExclusao._emprestimoId);
              }
              setConfirmarExclusao(null);
            }}
          >
            Excluir
          </Button>
        </DialogActions>
      </Dialog>

    </Layout>
  );
}

export default RelatoriosPage;

import React, { useState } from 'react';
import Layout from '../components/Layout';
import { useData } from '../context/DataContext';
import {
  Box,
  Card,
  CardContent,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Typography,
  Chip,
  Alert,
  Grid,
  Avatar,
  Button,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  TextField
} from '@mui/material';
import {
  Timeline,
  Person,
  Book,
  SwapHoriz,
  Edit,
  Delete,
  Add,
  AssignmentReturn,
  Login,
  Logout,
  Visibility,
  Print
} from '@mui/icons-material';
import { imprimirEscopo } from '../utils/printUtils';

export default function RelatorioUsuariosPage() {
  const { 
    usuarioLogado, 
    instituicaoAtiva,
    usuarios,
    logAtividades
  } = useData();

  const [filtroUsuario, setFiltroUsuario] = useState('todos');
  const [filtroAcao, setFiltroAcao] = useState('todas');
  const [dataInicio, setDataInicio] = useState('');
  const [dataFim, setDataFim] = useState('');

  const handleImprimir = () => {
    imprimirEscopo();
  };

  // Verificar se é usuário master
  const isMaster = usuarioLogado?.tipo === 'master' || usuarioLogado?.perfil === 'Admin';

  // Filtrar usuários e logs da instituição ativa
  const usuariosDaInstituicao = (usuarios || []).filter(u => 
    u.instituicaoId === instituicaoAtiva && u.perfil !== 'SuperAdmin'
  );

  const logsFiltrados = (logAtividades || [])
    .filter(log => log.instituicaoId === instituicaoAtiva)
    .filter(log => filtroUsuario === 'todos' || log.usuarioId === parseInt(filtroUsuario))
    .filter(log => filtroAcao === 'todas' || log.acao === filtroAcao)
    .filter(log => {
      if (!dataInicio && !dataFim) return true;
      const dataLog = new Date(log.dataHora);
      const inicio = dataInicio ? new Date(dataInicio) : null;
      const fim = dataFim ? new Date(dataFim) : null;
      
      if (inicio && dataLog < inicio) return false;
      if (fim && dataLog > fim) return false;
      return true;
    })
    .sort((a, b) => new Date(b.dataHora) - new Date(a.dataHora));

  const getUsuarioNome = (usuarioId) => {
    const usuario = usuarios.find(u => u.id === usuarioId);
    return usuario ? usuario.nome : 'Usuário Desconhecido';
  };

  const getIconeAcao = (acao) => {
    switch (acao) {
      case 'acesso': return <Visibility sx={{ fontSize: 20 }} />;
      case 'login': return <Login sx={{ fontSize: 20 }} />;
      case 'logout': return <Logout sx={{ fontSize: 20 }} />;
      case 'adicionar': return <Add sx={{ fontSize: 20 }} />;
      case 'editar': return <Edit sx={{ fontSize: 20 }} />;
      case 'excluir': return <Delete sx={{ fontSize: 20 }} />;
      case 'emprestimo': return <SwapHoriz sx={{ fontSize: 20 }} />;
      case 'devolucao': return <AssignmentReturn sx={{ fontSize: 20 }} />;
      default: return <Timeline sx={{ fontSize: 20 }} />;
    }
  };

  const getCorAcao = (acao) => {
    switch (acao) {
      case 'acesso': return 'secondary';
      case 'login': return 'success';
      case 'logout': return 'default';
      case 'adicionar': return 'success';
      case 'editar': return 'info';
      case 'excluir': return 'error';
      case 'emprestimo': return 'warning';
      case 'devolucao': return 'primary';
      default: return 'default';
    }
  };

  // Estatísticas por usuário
  const estatisticasPorUsuario = usuariosDaInstituicao.map(usuario => {
    const logsUsuario = (logAtividades || []).filter(log => 
      log.usuarioId === usuario.id && log.instituicaoId === instituicaoAtiva
    );
    
    return {
      usuario: usuario.nome,
      total: logsUsuario.length,
      acessos: logsUsuario.filter(l => l.acao === 'acesso').length,
      logins: logsUsuario.filter(l => l.acao === 'login').length,
      adicoes: logsUsuario.filter(l => l.acao === 'adicionar').length,
      edicoes: logsUsuario.filter(l => l.acao === 'editar').length,
      exclusoes: logsUsuario.filter(l => l.acao === 'excluir').length,
      emprestimos: logsUsuario.filter(l => l.acao === 'emprestimo').length,
      devolucoes: logsUsuario.filter(l => l.acao === 'devolucao').length,
    };
  });

  if (!isMaster) {
    return (
      <Layout title="Relatório de Atividades">
        <Alert severity="error">
          Acesso negado. Apenas o usuário master pode visualizar este relatório.
        </Alert>
      </Layout>
    );
  }

  return (
    <Layout title="Relatório de Atividades dos Usuários">
      <Box sx={{ mb: 2 }} className="print-actions no-print">
        <Button variant="outlined" startIcon={<Print />} onClick={handleImprimir}>
          Imprimir Relatório
        </Button>
      </Box>

      <Box className="print-scope">
      <Typography className="print-only" variant="h6" fontWeight="bold" sx={{ mb: 1 }}>
        Relatório de Atividades dos Usuários
      </Typography>
      <Typography className="print-only" variant="body2" sx={{ mb: 2 }}>
        Emitido em: {new Date().toLocaleString('pt-BR')}
      </Typography>

      <Box sx={{ mb: 3 }}>
        <Alert severity="info">
          <Typography variant="body2">
            <strong>📊 Relatório de Movimentação:</strong> Visualize todas as ações realizadas pelos usuários do sistema.
          </Typography>
        </Alert>
      </Box>

      {/* Estatísticas por Usuário */}
      <Card sx={{ mb: 3 }} className="no-print">
        <CardContent>
          <Typography variant="h6" gutterBottom sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <Person /> Estatísticas por Usuário
          </Typography>
          <TableContainer>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Usuário</TableCell>
                  <TableCell align="center">Total</TableCell>
                  <TableCell align="center">Acessos</TableCell>
                  <TableCell align="center">Logins</TableCell>
                  <TableCell align="center">Adições</TableCell>
                  <TableCell align="center">Edições</TableCell>
                  <TableCell align="center">Exclusões</TableCell>
                  <TableCell align="center">Empréstimos</TableCell>
                  <TableCell align="center">Devoluções</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {estatisticasPorUsuario.map((stat, index) => (
                  <TableRow key={index}>
                    <TableCell>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <Avatar sx={{ width: 24, height: 24, fontSize: 12 }}>
                          {stat.usuario.charAt(0)}
                        </Avatar>
                        {stat.usuario}
                      </Box>
                    </TableCell>
                    <TableCell align="center"><Chip label={stat.total} size="small" /></TableCell>
                    <TableCell align="center"><Chip label={stat.acessos} size="small" color="secondary" /></TableCell>
                    <TableCell align="center"><Chip label={stat.logins} size="small" color="success" /></TableCell>
                    <TableCell align="center"><Chip label={stat.adicoes} size="small" color="success" /></TableCell>
                    <TableCell align="center"><Chip label={stat.edicoes} size="small" color="info" /></TableCell>
                    <TableCell align="center"><Chip label={stat.exclusoes} size="small" color="error" /></TableCell>
                    <TableCell align="center"><Chip label={stat.emprestimos} size="small" color="warning" /></TableCell>
                    <TableCell align="center"><Chip label={stat.devolucoes} size="small" color="primary" /></TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </CardContent>
      </Card>

      {/* Filtros */}
      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Typography variant="h6" gutterBottom>
            🔍 Filtros
          </Typography>
          <Grid container spacing={2}>
            <Grid item xs={12} sm={3}>
              <FormControl fullWidth>
                <InputLabel>Usuário</InputLabel>
                <Select
                  value={filtroUsuario}
                  label="Usuário"
                  onChange={(e) => setFiltroUsuario(e.target.value)}
                >
                  <MenuItem value="todos">Todos os Usuários</MenuItem>
                  {usuariosDaInstituicao.map(usuario => (
                    <MenuItem key={usuario.id} value={usuario.id}>
                      {usuario.nome}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            
            <Grid item xs={12} sm={3}>
              <FormControl fullWidth>
                <InputLabel>Ação</InputLabel>
                <Select
                  value={filtroAcao}
                  label="Ação"
                  onChange={(e) => setFiltroAcao(e.target.value)}
                >
                  <MenuItem value="todas">Todas as Ações</MenuItem>
                  <MenuItem value="adicionar">Adições</MenuItem>
                  <MenuItem value="editar">Edições</MenuItem>
                  <MenuItem value="excluir">Exclusões</MenuItem>
                  <MenuItem value="acesso">Acessos</MenuItem>
                  <MenuItem value="login">Logins</MenuItem>
                  <MenuItem value="logout">Logouts</MenuItem>
                  <MenuItem value="emprestimo">Empréstimos</MenuItem>
                  <MenuItem value="devolucao">Devoluções</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            
            <Grid item xs={12} sm={3}>
              <TextField
                label="Data Início"
                type="date"
                fullWidth
                InputLabelProps={{ shrink: true }}
                value={dataInicio}
                onChange={(e) => setDataInicio(e.target.value)}
              />
            </Grid>
            
            <Grid item xs={12} sm={3}>
              <TextField
                label="Data Fim"
                type="date"
                fullWidth
                InputLabelProps={{ shrink: true }}
                value={dataFim}
                onChange={(e) => setDataFim(e.target.value)}
              />
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      {/* Log de Atividades */}
      <Card>
        <CardContent>
          <Typography variant="h6" gutterBottom sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <Timeline /> Histórico de Atividades ({logsFiltrados.length})
          </Typography>
          
          <TableContainer component={Paper} sx={{ maxHeight: 600 }}>
            <Table stickyHeader>
              <TableHead>
                <TableRow>
                  <TableCell>Data/Hora</TableCell>
                  <TableCell>Usuário</TableCell>
                  <TableCell>Ação</TableCell>
                  <TableCell>Módulo</TableCell>
                  <TableCell>Descrição</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {logsFiltrados.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={5} align="center">
                      <Typography color="text.secondary">
                        Nenhuma atividade registrada
                      </Typography>
                    </TableCell>
                  </TableRow>
                ) : (
                  logsFiltrados.map((log) => (
                    <TableRow key={log.id} hover>
                      <TableCell>
                        <Typography variant="body2">
                          {new Date(log.dataHora).toLocaleString('pt-BR')}
                        </Typography>
                      </TableCell>
                      <TableCell>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                          <Avatar sx={{ width: 28, height: 28, fontSize: 12 }}>
                            {getUsuarioNome(log.usuarioId).charAt(0)}
                          </Avatar>
                          {getUsuarioNome(log.usuarioId)}
                        </Box>
                      </TableCell>
                      <TableCell>
                        <Chip 
                          label={log.acao} 
                          size="small" 
                          color={getCorAcao(log.acao)}
                          icon={getIconeAcao(log.acao)}
                        />
                      </TableCell>
                      <TableCell>
                        <Chip label={log.modulo} size="small" variant="outlined" />
                      </TableCell>
                      <TableCell>
                        <Typography variant="body2">{log.descricao}</Typography>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </TableContainer>
        </CardContent>
      </Card>
      </Box>
    </Layout>
  );
}

import React, { useMemo, useState } from 'react';
import Layout from '../components/Layout';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Divider,
  FormControl,
  Grid,
  IconButton,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography
} from '@mui/material';
import { Add, Clear, Delete, Edit, Groups, School } from '@mui/icons-material';
import { useData } from '../context/DataContext';

export default function SeriesTurmasPage() {
  const {
    seriesAcademicas,
    turmasAcademicas,
    clientes,
    adicionarSerieAcademica,
    atualizarSerieAcademica,
    adicionarTurmaAcademica,
    atualizarTurmaAcademica,
    removerTurmaAcademica
  } = useData();

  const [serieEmEdicao, setSerieEmEdicao] = useState(null);
  const [turmaEmEdicao, setTurmaEmEdicao] = useState(null);

  const [serieForm, setSerieForm] = useState({
    nomeSerie: '',
    anoLetivo: String(new Date().getFullYear()),
    descricao: ''
  });

  const [turmaForm, setTurmaForm] = useState({
    nomeTurma: '',
    serieId: '',
    anoLetivo: String(new Date().getFullYear()),
    turno: ''
  });

  const seriesOrdenadas = useMemo(() => {
    return [...seriesAcademicas].sort((a, b) => {
      const anoA = String(a.anoLetivo || '');
      const anoB = String(b.anoLetivo || '');
      if (anoA !== anoB) return anoB.localeCompare(anoA, 'pt-BR');
      return String(a.nomeSerie || '').localeCompare(String(b.nomeSerie || ''), 'pt-BR');
    });
  }, [seriesAcademicas]);

  const turmasOrdenadas = useMemo(() => {
    return [...turmasAcademicas].sort((a, b) => {
      const serieA = String(a.nomeSerie || '');
      const serieB = String(b.nomeSerie || '');
      if (serieA !== serieB) return serieA.localeCompare(serieB, 'pt-BR');
      return String(a.nomeTurma || '').localeCompare(String(b.nomeTurma || ''), 'pt-BR');
    });
  }, [turmasAcademicas]);

  const normalizarTexto = (valor) => String(valor || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[º°]/g, 'o')
    .replace(/[ª]/g, 'a')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, ' ')
    .replace(/\s+/g, ' ');

  const turmasAcademicasMap = useMemo(() => {
    const map = new Map();
    turmasAcademicas.forEach((turma) => {
      map.set(String(turma.id), turma);
    });
    return map;
  }, [turmasAcademicas]);

  const compactarTexto = (valor) => normalizarTexto(valor).replace(/[^a-z0-9]/g, '');

  const tokenizarTexto = (...valores) => {
    const texto = normalizarTexto(valores.filter(Boolean).join(' '));
    if (!texto) return [];
    return texto.split(/[^a-z0-9]+/).filter(Boolean);
  };

  const extrairNumeroSerie = (valor) => {
    const texto = normalizarTexto(valor);
    if (!texto) return '';

    const match = texto.match(/(\d{1,2})\s*(?:a|o)?\s*(?:serie|ano)?/);
    return match ? match[1] : '';
  };

  const extrairSalaTurma = (valor) => {
    const texto = normalizarTexto(valor).toUpperCase();
    if (!texto) return '';

    const padraoIB = texto.match(/\b[IA]\s*-\s*([A-Z])\b/);
    if (padraoIB) {
      return padraoIB[1];
    }

    const inicio = texto.match(/^([A-Z])\b/);
    if (inicio) {
      return inicio[1];
    }

    const final = texto.match(/\b([A-Z])\b$/);
    if (final) {
      return final[1];
    }

    return '';
  };

  const extrairCursoAcademico = (...valores) => {
    const tokens = tokenizarTexto(...valores);
    if (tokens.length === 0) return '';

    const tokenSet = new Set(tokens);
    const textoCompacto = tokens.join('');

    if (tokens.some((token) => token.includes('farm'))) return 'farm';
    if (tokens.some((token) => token.includes('mark')) || tokenSet.has('dig')) return 'mark';
    if (tokens.some((token) => token.includes('emp'))) return 'emp';
    if (tokens.some((token) => token.includes('prop')) || tokens.some((token) => token.includes('admi'))) return 'prop';

    const temDs = tokenSet.has('ds')
      || (tokenSet.has('d') && tokenSet.has('s'))
      || tokens.some((token) => token.includes('des'))
      || tokens.some((token) => token === 'sis');

    if (temDs || textoCompacto.includes('dessis')) return 'ds';
    if (tokenSet.has('int')) return 'int';

    return '';
  };

  const isAlunoCliente = (cliente) => {
    if (cliente?.excluido) {
      return false;
    }

    const tipoNormalizado = normalizarTexto(cliente?.tipo);
    const categoriaNormalizada = normalizarTexto(cliente?.categoria);

    const possuiVinculoAcademico =
      String(cliente?.turmaId || '').trim().length > 0
      || String(cliente?.serieId || '').trim().length > 0
      || normalizarTexto(cliente?.turma).length > 0
      || normalizarTexto(cliente?.nomeTurma).length > 0
      || normalizarTexto(cliente?.serie).length > 0
      || normalizarTexto(cliente?.nomeSerie).length > 0;

    const perfisNaoAluno = [
      'professor',
      'funcionario',
      'funcionario administrativo',
      'bibliotecario',
      'coordenador',
      'diretor',
      'gestor',
      'servidor',
      'admin',
      'administrador',
      'comunidade'
    ];

    if (tipoNormalizado === 'aluno' || categoriaNormalizada === 'estudante') {
      return true;
    }

    if (tipoNormalizado === 'leitor') {
      return possuiVinculoAcademico;
    }

    if (possuiVinculoAcademico) {
      return !perfisNaoAluno.includes(tipoNormalizado) && !perfisNaoAluno.includes(categoriaNormalizada);
    }

    return false;
  };

  const resolverTurmaAssociadaAoLeitor = (cliente) => {
    const clienteTurmaId = String(cliente?.turmaId || '').trim();
    if (clienteTurmaId && turmasAcademicasMap.has(clienteTurmaId)) {
      return turmasAcademicasMap.get(clienteTurmaId);
    }

    const clienteTurmaBruta = String(cliente?.turma || cliente?.nomeTurma || '').trim();
    if (!clienteTurmaBruta) {
      return null;
    }

    const clienteSerieBruta = String(cliente?.serie || cliente?.nomeSerie || '').trim();
    const clienteTurmaNormalizada = normalizarTexto(clienteTurmaBruta);
    const clienteTurmaCompacta = compactarTexto(clienteTurmaBruta);
    const clienteSerieNormalizada = normalizarTexto(clienteSerieBruta);
    const clienteSerieCompacta = compactarTexto(clienteSerieBruta);
    const numeroSerieCliente = extrairNumeroSerie(clienteSerieBruta);
    const salaCliente = extrairSalaTurma(clienteTurmaBruta);
    const cursoCliente = extrairCursoAcademico(clienteTurmaBruta, clienteSerieBruta);

    const candidatas = turmasOrdenadas.filter((turma) => {
      const turmaNomeNormalizada = normalizarTexto(turma.nomeTurma);
      const turmaNomeCompacta = compactarTexto(turma.nomeTurma);
      const serieTurmaNormalizada = normalizarTexto(turma.nomeSerie);
      const serieTurmaCompacta = compactarTexto(turma.nomeSerie);
      const numeroSerieTurma = extrairNumeroSerie(turma.nomeSerie);
      const salaTurma = extrairSalaTurma(turma.nomeTurma);
      const cursoTurma = extrairCursoAcademico(turma.nomeTurma, turma.nomeSerie);

      const porNome =
        clienteTurmaNormalizada === turmaNomeNormalizada
        || (clienteTurmaCompacta && clienteTurmaCompacta === turmaNomeCompacta)
        || (clienteTurmaCompacta && turmaNomeCompacta.includes(clienteTurmaCompacta))
        || (clienteTurmaCompacta && clienteTurmaCompacta.includes(turmaNomeCompacta));

      const porAssinatura =
        Boolean(salaCliente)
        && Boolean(salaTurma)
        && salaCliente === salaTurma
        && (!cursoCliente || !cursoTurma || cursoCliente === cursoTurma);

      if (!porNome && !porAssinatura) {
        return false;
      }

      const serieCompativel =
        !clienteSerieNormalizada
        || !serieTurmaNormalizada
        || clienteSerieNormalizada === serieTurmaNormalizada
        || (clienteSerieCompacta && clienteSerieCompacta === serieTurmaCompacta)
        || (clienteSerieCompacta && serieTurmaCompacta.includes(clienteSerieCompacta))
        || (clienteSerieCompacta && clienteSerieCompacta.includes(serieTurmaCompacta))
        || (numeroSerieCliente && numeroSerieTurma && numeroSerieCliente === numeroSerieTurma);

      return serieCompativel;
    });

    if (candidatas.length === 0) {
      return null;
    }

    if (candidatas.length === 1) {
      return candidatas[0];
    }

    const melhorMatch = candidatas.find((turma) => {
      return (
        normalizarTexto(turma.nomeTurma) === clienteTurmaNormalizada
        && (!clienteSerieNormalizada || normalizarTexto(turma.nomeSerie) === clienteSerieNormalizada)
      );
    });

    return melhorMatch || candidatas[0];
  };

  const contagemLeitoresPorTurma = useMemo(() => {
    const mapa = new Map();
    turmasOrdenadas.forEach((turma) => {
      mapa.set(String(turma.id), 0);
    });

    clientes.forEach((cliente) => {
      if (!isAlunoCliente(cliente)) {
        return;
      }

      const turmaAssociada = resolverTurmaAssociadaAoLeitor(cliente);
      if (!turmaAssociada) {
        return;
      }

      const turmaId = String(turmaAssociada.id);
      mapa.set(turmaId, (mapa.get(turmaId) || 0) + 1);
    });

    return mapa;
  }, [clientes, turmasOrdenadas, turmasAcademicasMap]);

  const contadores = useMemo(() => {
    const seriesBase = (turmasAcademicas.length > 0 ? turmasAcademicas : seriesAcademicas)
      .map((item) => item?.nomeSerie)
      .map((nomeSerie) => normalizarTexto(nomeSerie))
      .filter(Boolean);

    const alunosComTurma = Array.from(contagemLeitoresPorTurma.values()).reduce((total, valor) => total + valor, 0);

    return {
      series: new Set(seriesBase).size,
      turmas: turmasAcademicas.length,
      alunosComTurma
    };
  }, [seriesAcademicas, turmasAcademicas, contagemLeitoresPorTurma]);

  const getTotalAlunosDaTurma = (turma) => {
    return contagemLeitoresPorTurma.get(String(turma?.id || '')) || 0;
  };

  const limparSerieForm = () => {
    setSerieEmEdicao(null);
    setSerieForm({
      nomeSerie: '',
      anoLetivo: String(new Date().getFullYear()),
      descricao: ''
    });
  };

  const limparTurmaForm = () => {
    setTurmaEmEdicao(null);
    setTurmaForm({
      nomeTurma: '',
      serieId: '',
      anoLetivo: String(new Date().getFullYear()),
      turno: ''
    });
  };

  const salvarSerieTurma = () => {
    if (turmaEmEdicao) {
      if (!turmaForm.nomeTurma.trim()) {
        alert('Informe o nome da turma.');
        return;
      }

      if (!turmaForm.serieId) {
        alert('Selecione a série da turma.');
        return;
      }

      const serieSelecionada = seriesAcademicas.find((serie) => String(serie.id) === String(turmaForm.serieId));
      if (!serieSelecionada) {
        alert('Série vinculada não encontrada.');
        return;
      }

      atualizarTurmaAcademica(turmaEmEdicao, {
        ...turmaForm,
        serieId: String(turmaForm.serieId),
        anoLetivo: String(turmaForm.anoLetivo || '').trim() || String(serieSelecionada.anoLetivo || '').trim()
      });
      limparTurmaForm();
      return;
    }

    if (serieEmEdicao) {
      if (!serieForm.nomeSerie.trim()) {
        alert('Informe o nome da série.');
        return;
      }

      atualizarSerieAcademica(serieEmEdicao, serieForm);
      limparSerieForm();
      return;
    }

    const deveSalvarSerie = Boolean(serieEmEdicao || serieForm.nomeSerie.trim());
    const deveSalvarTurma = Boolean(
      turmaEmEdicao || turmaForm.nomeTurma.trim() || turmaForm.serieId || turmaForm.turno.trim()
    );

    if (!deveSalvarSerie && !deveSalvarTurma) {
      alert('Preencha os dados da série ou da turma.');
      return;
    }

    const nomeSerieNormalizado = String(serieForm.nomeSerie || '').trim().toLowerCase();
    const anoSerieNormalizado = String(serieForm.anoLetivo || '').trim();

    const serieExistentePorNomeAno = nomeSerieNormalizado
      ? seriesAcademicas.find((serie) => {
        return (
          String(serie.nomeSerie || '').trim().toLowerCase() === nomeSerieNormalizado
          && String(serie.anoLetivo || '').trim() === anoSerieNormalizado
        );
      })
      : null;

    let serieIdVinculada = turmaForm.serieId ? String(turmaForm.serieId) : '';
    let anoLetivoDaSerie = String(serieForm.anoLetivo || '').trim();
    let serieFallback = null;

    if (deveSalvarSerie) {
      if (!serieForm.nomeSerie.trim()) {
        alert('Informe o nome da série.');
        return;
      }

      if (serieEmEdicao) {
        atualizarSerieAcademica(serieEmEdicao, serieForm);
        serieIdVinculada = serieIdVinculada || String(serieEmEdicao);
      } else if (serieExistentePorNomeAno) {
        if (!deveSalvarTurma) {
          alert('Já existe uma série com esse nome e ano letivo.');
          return;
        }

        serieIdVinculada = serieIdVinculada || String(serieExistentePorNomeAno.id);
        anoLetivoDaSerie = String(serieExistentePorNomeAno.anoLetivo || '').trim() || anoLetivoDaSerie;
      } else {
        const novaSerie = adicionarSerieAcademica(serieForm);
        if (!novaSerie) return;
        serieIdVinculada = serieIdVinculada || String(novaSerie.id);
        anoLetivoDaSerie = String(novaSerie.anoLetivo || '').trim() || anoLetivoDaSerie;
        serieFallback = novaSerie;
      }
    }

    if (!serieIdVinculada && serieExistentePorNomeAno) {
      serieIdVinculada = String(serieExistentePorNomeAno.id);
      anoLetivoDaSerie = String(serieExistentePorNomeAno.anoLetivo || '').trim() || anoLetivoDaSerie;
    }

    if (deveSalvarTurma) {
      if (!turmaForm.nomeTurma.trim()) {
        alert('Informe o nome da turma.');
        return;
      }

      if (!serieIdVinculada) {
        alert('Selecione a série da turma ou preencha Série/Ano válidos.');
        return;
      }

      const turmaPayload = {
        ...turmaForm,
        serieId: serieIdVinculada,
        anoLetivo: String(turmaForm.anoLetivo || '').trim() || anoLetivoDaSerie
      };

      if (serieFallback) {
        turmaPayload.serieFallback = serieFallback;
      }

      if (turmaEmEdicao) {
        atualizarTurmaAcademica(turmaEmEdicao, turmaPayload);
      } else {
        const novaTurma = adicionarTurmaAcademica(turmaPayload);
        if (!novaTurma) return;
      }
    }

    if (deveSalvarSerie) {
      limparSerieForm();
    }

    if (deveSalvarTurma) {
      limparTurmaForm();
    }
  };

  const limparFormulario = () => {
    limparSerieForm();
    limparTurmaForm();
  };

  const editarTurma = (turma) => {
    limparSerieForm();
    setTurmaEmEdicao(turma.id);
    setTurmaForm({
      nomeTurma: turma.nomeTurma || '',
      serieId: String(turma.serieId || ''),
      anoLetivo: turma.anoLetivo || String(new Date().getFullYear()),
      turno: turma.turno || ''
    });
  };

  return (
    <Layout title="Séries e Turmas">
      <Grid container spacing={2} sx={{ mb: 2 }}>
        <Grid item xs={12} sm={4}>
          <Card>
            <CardContent>
              <Typography variant="caption" color="text.secondary">Total de séries</Typography>
              <Typography variant="h5"><School sx={{ mr: 0.5, verticalAlign: 'middle' }} />{contadores.series}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={4}>
          <Card>
            <CardContent>
              <Typography variant="caption" color="text.secondary">Turmas cadastradas</Typography>
              <Typography variant="h5"><Groups sx={{ mr: 0.5, verticalAlign: 'middle' }} />{contadores.turmas}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={4}>
          <Card>
            <CardContent>
              <Typography variant="caption" color="text.secondary">Leitores/alunos alocados em turma</Typography>
              <Typography variant="h5">{contadores.alunosComTurma}</Typography>
