  return editorasBrasileiras.some(ed => 
    editora.toLowerCase().includes(ed.toLowerCase())
  );
};

export default {
  buscarLivroPorISBN,
  validarISBN,
  isbn13ParaIsbn10,
  isEditoraBrasileira
};

